window.jcdSort = jcdSort;
window.updateJobCostActual = updateJobCostActual;
window.renderJCDTable = renderJCDTable;

// conLoadJobs CO patch removed — consolidated into main function above

function commitJobStatusChange(newStatus) {
  const jobId = conCurrentJobId;
  const job = conJobs.find(j => j.id === jobId);
  if (!job || !jobId) return;
  if (job.status === newStatus) return;

  // Entry Information (lockbox code / access instructions) is required
  // before a job can move to Approved or Scheduled — a crew showing up
  // to a vacant property with no idea how to get in is exactly the
  // problem this exists to prevent. Required for every job, not just
  // ones flagged vacant.
  if ((newStatus === 'To Be Scheduled' || newStatus === 'Scheduled') && !(job.accessInfo && job.accessInfo.trim())) {
    alert('Entry Information is required before this job can move to "' + newStatus + '".\n\nGo to the "🔑 Entry Info" tab and fill in access/lockbox instructions first.');
    document.getElementById('detailStatusBadge').value = job.status || 'New Lead';
    return;
  }

  // Confirm on closing statuses — this is a meaningful, hard-to-undo action.
  if ((newStatus === 'Closed Completed' || newStatus === 'Closed Lost') &&
      !confirm('Mark this job as "' + newStatus + '"? This updates the job\'s status for everyone.')) {
    document.getElementById('detailStatusBadge').value = job.status || 'New Lead';
    return;
  }

  const prevStatus = job.status;
  job.status = newStatus; // optimistic local update
  document.getElementById('detailStatusBadge').value = newStatus;

  coll('jobs').doc(jobId).update({
    status: newStatus,
    statusDate: new Date().toISOString().split('T')[0],
    updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy: conCurrentUser ? conCurrentUser.email : 'unknown'
  }).then(() => {
    if (typeof conRenderBoard === 'function') conRenderBoard();
    if (typeof renderJobsBoard === 'function') renderJobsBoard();
  }).catch(err => {
    job.status = prevStatus; // revert on failure
    document.getElementById('detailStatusBadge').value = prevStatus || 'New Lead';
    alert('Could not update job status: ' + err.message);
  });
}
window.commitJobStatusChange = commitJobStatusChange;

// Shows a red dot on the Entry Info tab button itself when required
// info is missing, so it's visible at a glance without having to click
// into the tab to discover it's empty.
function updateEntryInfoTabWarning(job) {
  const btn = document.getElementById('entryInfoTabBtn');
  if (!btn) return;
  const filled = job && job.accessInfo && job.accessInfo.trim();
  btn.innerHTML = filled
    ? '🔑 Entry Info'
    : '🔑 Entry Info <span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:#ef5350;margin-left:3px"></span>';
}

function saveEntryInfo() {
  const jobId = conCurrentJobId;
  const job = conJobs.find(j => j.id === jobId);
  if (!job || !jobId || !conDb) return;

  const lockboxCode = document.getElementById('entryInfoLockbox')?.value.trim() || '';
  const alarmCode = document.getElementById('entryInfoAlarm')?.value.trim() || '';
  const accessInfo = document.getElementById('entryInfoInstructions')?.value.trim() || '';

  coll('jobs').doc(jobId).update({
    lockboxCode, alarmCode, accessInfo,
    updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy: conCurrentUser ? conCurrentUser.email : 'unknown'
  }).then(() => {
    job.lockboxCode = lockboxCode;
    job.alarmCode = alarmCode;
    job.accessInfo = accessInfo;
    document.getElementById('detailAccessInfo').textContent = accessInfo || '—';
    updateEntryInfoTabWarning(job);
    const msg = document.getElementById('entryInfoSavedMsg');
    if (msg) { msg.style.display = 'block'; setTimeout(() => msg.style.display = 'none', 3000); }
  }).catch(e => alert('Error saving Entry Information: ' + e.message));
}
window.saveEntryInfo = saveEntryInfo;

// Financials tab is locked to an exact, hardcoded email allowlist, not a
// role flag — Travis was explicit this needs to be airtight regardless
// of how roles get assigned/reassigned later. Originally just Travis;
// opened up to Jason on his explicit instruction ("only Jason and I have
// the financials") -- still a hard two-person allowlist, not tied to
// the 'Owner' role, so it stays exactly these two even if someone else
// is ever made an Owner for other reasons.
const FINANCIALS_TAB_ALLOWED_EMAILS = new Set([
  'travis@7pillarsgroup.org',
  'jason@7pillarsgroup.org',
]);
function canViewFinancialsTab() {
  return FINANCIALS_TAB_ALLOWED_EMAILS.has((conCurrentUser?.email || '').toLowerCase());
}

// Broader than canViewFinancialsTab() above (which is a hard, single-email
// lock on the COO-level Financials tab specifically). This governs the
// persistent job stat bar, the Dashboard's financial panel, and the Subs
// tab -- surfaces where Owner/PM/Office Manager/Accounting reasonably need
// visibility, but Field Technicians, Team Leads, Sales, and Marketing/
// Office Staff should not see cost, payment, or subcontractor-pay data.
function canViewJobMoney() {
  if (currentUserTeamData?.fullAccessOverride) return true;
  if (currentUserRole === 'Owner') return true;
  return hasPermission('costing') || hasPermission('invoicing') || hasPermission('subs');
}

// Change Orders: Travis wants creation (and, as implemented here, viewing --
// change orders carry $ deltas, same reasoning as the Subs tab) restricted
// to Team Lead's level (45) and above. Uses the existing numeric `level`
// field already on every role instead of hardcoding a role list, so this
// stays correct if roles are ever added or reordered.
function canCreateChangeOrders() {
  if (currentUserTeamData?.fullAccessOverride) return true;
  if (currentUserRole === 'Owner') return true;
  const role = KYTRAC_ROLES[currentUserRole];
  return !!role && role.level >= KYTRAC_ROLES['Team Lead'].level;
}

// Crew Map shows every clocked-in/out crew member's live GPS location --
// same sensitivity level as Change Orders (Team Lead's level and up), not
// something a Field Technician or Crew Member should see about their
// coworkers.
function canViewCrewMap() {
  if (currentUserTeamData?.fullAccessOverride) return true;
  if (currentUserRole === 'Owner') return true;
  const role = KYTRAC_ROLES[currentUserRole];
  return !!role && role.level >= KYTRAC_ROLES['Team Lead'].level;
}

// Field Technicians get an ALLOWLIST, not a blocklist -- only these tabs
// are visible on a job: Schedule, To-Dos, Notes, Daily Logs, Selections,
// Plans, Messages, Entry Info. Everything else (Dashboard, Estimate,
// Invoices, Change Orders, Specifications, Subs, Activity, Files,
// Financials, Reports, Retrospective) is hidden, per Travis's explicit
// list of what field-level work actually requires.
const FIELD_TECH_ALLOWED_TABS = ['phases', 'todos', 'jobnotes', 'logs', 'selections', 'plans', 'messages', 'entryinfo'];
function isFieldTechRestricted() {
  if (currentUserTeamData?.fullAccessOverride) return false;
  return currentUserRole === 'Field Technician';
}

function switchDetailTab(tab, btn) {
  // Hard block, checked BEFORE anything else renders — refuses even a
  // direct/forced switchDetailTab('financials') call (e.g. from the
  // browser console), not just hiding the button. Silently redirects
  // to Dashboard instead, no error message revealing the tab exists.
  if (tab === 'financials' && !canViewFinancialsTab()) {
    tab = 'dashboard';
    btn = document.querySelector('#jobDetailModal .con-subtab');
  }
  if (tab === 'subs' && !canViewJobMoney()) {
    tab = 'dashboard';
    btn = document.querySelector('#jobDetailModal .con-subtab');
  }
  if (tab === 'changeorders' && !canCreateChangeOrders()) {
    tab = 'dashboard';
    btn = document.querySelector('#jobDetailModal .con-subtab');
  }
  if (isFieldTechRestricted() && !FIELD_TECH_ALLOWED_TABS.includes(tab)) {
    tab = 'phases';
    btn = document.querySelector('#jobDetailModal .con-subtab[onclick*="\'phases\'"]') || document.querySelector('#jobDetailModal .con-subtab');
  }
  const allTabs = ['dashboard','financials','estimate','changeorders','subs','phases','logs','invoices','documents','activity','retrospective','todos','selections','specifications','plans','messages','reports','jobnotes','entryinfo'];
  allTabs.forEach(t => {
    const key = 'detail' + t.charAt(0).toUpperCase() + t.slice(1);
    const el = document.getElementById(key);
    if (el) el.style.display = t === tab ? 'block' : 'none';
  });
  // The big job-dashboard header (job number/status/name/contact/action
  // buttons) and the financial stat bar are genuinely useful on most
  // tabs, but on Estimate specifically they push the actual working
  // area (KPIs, Smart Add, the line-item tree) below the fold —
  // exactly the "I have to scroll past a dashboard to get to my
  // estimate" complaint. Hide both for Estimate only; every other tab
  // keeps them. Estimate gets its own compact header instead (job
  // number/name/status + a way back), populated from the same data
  // right below, so context isn't lost.
  const headerBlock = document.getElementById('jobDetailHeaderBlock');
  const finBar = document.getElementById('jobFinBar');
  const tabRow = document.getElementById('jobDetailTabRow');
  const isEstimate = tab === 'estimate';
  if (headerBlock) headerBlock.style.display = isEstimate ? 'none' : '';
  if (finBar) finBar.style.display = isEstimate ? 'none' : 'grid';
  // Tab row too — with the compact header's own "← Dashboard" button
  // providing a way back, the full 15-tab row is just clutter while
  // heads-down building an estimate. One click on "← Dashboard" (or
  // any nav action that lands back on another tab) restores it.
  if (tabRow) tabRow.style.display = isEstimate ? 'none' : '';
  if (isEstimate) {
    const setTxt = (id, srcId) => { const el = document.getElementById(id); const src = document.getElementById(srcId); if (el && src) el.textContent = src.textContent; };
    setTxt('estCompactJobNum', 'detailJobNum');
    setTxt('estCompactJobName', 'detailJobName');
    const statusEl = document.getElementById('estCompactStatus');
    const statusSrc = document.getElementById('detailStatusBadge');
    if (statusEl && statusSrc) statusEl.textContent = statusSrc.value;
  }
  document.querySelectorAll('#jobDetailModal .con-subtab').forEach(b => b.classList.remove('active'));
  if (btn) {
    btn.classList.add('active');
  } else {
    const btns = document.querySelectorAll('#jobDetailModal .con-subtab');
    if (btns[0]) btns[0].classList.add('active');
  }
  if (tab === 'estimate') {
    loadEstimate(conCurrentJobId);
    // Clicking into the Estimate tab means you're actually starting to
    // build one — auto-advance from New Lead/Appointment Set to
    // Building Estimate. Forward-only (never regresses a job already
    // further along), same helper used for the email->Submitted step.
    advanceJobStatusIfEarlier(conCurrentJobId, 'Building Estimate', 'Started building estimate');
  }
  if (tab === 'changeorders') renderCOList();
  if (tab === 'subs') { loadJobBidRequests(conCurrentJobId); renderSubList(); }
  if (tab === 'documents') { loadJobDocs(conCurrentJobId); loadJobPhotos(conCurrentJobId); }
  if (tab === 'phases') { renderJobGantt(conCurrentJobId); }
  if (tab === 'logs') renderLogList();
  if (tab === 'invoices') loadJobInvoices(conCurrentJobId);
  if (tab === 'activity') loadJobActivity(conCurrentJobId, 'full');
  if (tab === 'jobnotes') loadJobNotes(conCurrentJobId);
  if (tab === 'retrospective') loadRetrospective(conCurrentJobId);
  if (tab === 'financials') renderFinancialsHub(conCurrentJobId);
  if (tab === 'todos') renderJobTodos(conCurrentJobId);
  if (tab === 'selections') loadSelections(conCurrentJobId);
  if (tab === 'specifications') loadSpecifications(conCurrentJobId);
  if (tab === 'plans') loadPlans(conCurrentJobId);
  if (tab === 'messages') loadJobMessages(conCurrentJobId);
  if (tab === 'reports') renderJobReports(conCurrentJobId);
}

