let _fhInvoices = [];
let _fhBills = [];
let _fhMaterials = [];
let _fhSubPayments = [];
let _fhBillsLoadedFor = null;

function finhubToggle(bodyId, headEl) {
  const body = document.getElementById(bodyId);
  if (!body) return;
  const open = body.style.display !== 'none';
  body.style.display = open ? 'none' : 'block';
  const chev = headEl ? headEl.querySelector('.finhub-chev') : null;
  if (chev) chev.classList.toggle('closed', open);
}

const FH_INV_COLORS = { Paid:'#1dbb87', 'Partially Paid':'#f59e0b', Partial:'#f59e0b', Sent:'#4d8dff', Draft:'#8ea3c8', Overdue:'#ef5350' };
const FH_CO_COLORS  = { Approved:'#1dbb87', Pending:'#f59e0b', Rejected:'#ef5350', Void:'#8ea3c8' };
const FH_BILL_COLORS = { Paid:'#1dbb87', Partial:'#f97316', Unpaid:'#f59e0b', Overdue:'#ef5350' };

function fhBadge(txt, color) {
  return `<span class="finhub-badge" style="color:${color};background:${color}22">${esc(txt)}</span>`;
}
function fhMoney(n) { return '$' + Math.round(n||0).toLocaleString(); }

// Load bills tagged to this job across all vendors (bills live under vendors/{id}/bills with a jobId field)
function fhLoadJobBills(jobId, cb) {
  if (!conDb || !Array.isArray(allVendors) || !allVendors.length) { _fhBills = []; cb && cb(); return; }
  const bills = [];
  let pending = allVendors.length;
  allVendors.forEach(v => {
    coll('vendors').doc(v.id).collection('bills').where('jobId','==',jobId).get()
      .then(snap => { snap.forEach(d => bills.push({ id:d.id, vendorId:v.id, vendorName:v.name, ...d.data() })); })
      .catch(() => {})
      .finally(() => { if (--pending === 0) { _fhBills = bills; cb && cb(); } });
  });
}

function renderFinancialsHub(jobId) {
  const job = conJobs.find(j => j.id === jobId);
  if (!job) return;

  // Invoices (subcollection on job) — one-shot get
  coll('jobs').doc(jobId).collection('invoices').get()
    .then(snap => { _fhInvoices = []; snap.forEach(d => _fhInvoices.push({ id:d.id, ...d.data() })); fhRenderInvoices(); fhRenderTotals(job); })
    .catch(() => { _fhInvoices = []; fhRenderInvoices(); fhRenderTotals(job); });

  // Change orders already loaded into conCOs when job opened
  fhRenderCOs();

  // Bills across vendors
  fhRenderBillsLoading();
  fhLoadJobBills(jobId, () => { fhRenderBills(); fhRenderTotals(job); });

  // Materials purchases (direct, job-scoped, no vendor account)
  fhRenderMaterialsLoading();
  fhLoadJobMaterials(jobId, () => { fhRenderMaterials(); fhRenderTotals(job); });

  // Subcontractor payments (1099 flat-rate job pay)
  fhLoadJobSubPayments(jobId, () => { fhRenderSubPayments(); fhRenderTotals(job); });

  // Owner-only COO budget breakdown
  renderCOOBudgetBreakdown();
  renderLaborBudget();

  fhRenderEva();
}

// Fresh from Firestore, not the estGroups global — that's only
// populated once someone has actually clicked into the Estimate tab
// this session. Financials is exactly the tab where that might never
// have happened, and a wrong 50/50 fallback split looks like a real
// number, not an obviously-empty one, which makes it dangerous to get
// wrong silently.
// Parallelized — this used to await every group's items, then its
// subgroups, then every subgroup's items, then ITS sub-subgroups, one
// Firestore round trip at a time — the exact same sequential-cascade
// bug already found and fixed in loadEpicTree() earlier tonight, just
// never applied here. For a 106-task job this took 14.5 SECONDS
// (measured directly, not estimated) before the real Cost to Complete
// number ever appeared — which is why it looked "stuck on the old
// number" rather than "eventually correct but painfully slow." This
// single function feeds nearly every real-cost feature built tonight
// (COO Budget Breakdown, Labor Budget, Cost to Complete, the KPI
// dashboard), so this one fix speeds up all of them at once.
async function fetchEstimateCostSplitFresh(jobId) {
  let materials = 0, laborAndOther = 0;
  const addItem = data => {
    const price = (data.unitPrice || 0) * (data.qty || 1);
    if (data.costType === 'Materials') materials += price; else laborAndOther += price;
  };
  const jobRef = coll('jobs').doc(jobId);
  const groupsSnap = await jobRef.collection('estimateGroups').get();
  await Promise.all(groupsSnap.docs.map(async gDoc => {
    const gRef = gDoc.ref;
    const [directItems, subsSnap] = await Promise.all([
      gRef.collection('items').get(),
      gRef.collection('subgroups').get(),
    ]);
    directItems.forEach(d => addItem(d.data()));
    await Promise.all(subsSnap.docs.map(async sDoc => {
      const sRef = sDoc.ref;
      const [subItems, subsubSnap] = await Promise.all([
        sRef.collection('items').get(),
        sRef.collection('subgroups').get(),
      ]);
      subItems.forEach(d => addItem(d.data()));
      await Promise.all(subsubSnap.docs.map(ssDoc =>
        ssDoc.ref.collection('items').get().then(ssItems => ssItems.forEach(d => addItem(d.data())))
      ));
    }));
  }));
  return { materials, laborAndOther };
}

// Same parallelization applied — see fetchEstimateCostSplitFresh above
// for the full explanation. This is its twin (sums unitCost instead
// of unitPrice) and had the identical sequential-cascade bug.
async function fetchEstimateTrueCostSplit(jobId) {
  let materials = 0, laborAndOther = 0;
  const addItem = data => {
    const cost = (data.unitCost || 0) * (data.qty || 1);
    if (data.costType === 'Materials') materials += cost; else laborAndOther += cost;
  };
  const jobRef = coll('jobs').doc(jobId);
  const groupsSnap = await jobRef.collection('estimateGroups').get();
  await Promise.all(groupsSnap.docs.map(async gDoc => {
    const gRef = gDoc.ref;
    const [directItems, subsSnap] = await Promise.all([
      gRef.collection('items').get(),
      gRef.collection('subgroups').get(),
    ]);
    directItems.forEach(d => addItem(d.data()));
    await Promise.all(subsSnap.docs.map(async sDoc => {
      const sRef = sDoc.ref;
      const [subItems, subsubSnap] = await Promise.all([
        sRef.collection('items').get(),
        sRef.collection('subgroups').get(),
      ]);
      subItems.forEach(d => addItem(d.data()));
      await Promise.all(subsubSnap.docs.map(ssDoc =>
        ssDoc.ref.collection('items').get().then(ssItems => ssItems.forEach(d => addItem(d.data())))
      ));
    }));
  }));
  return { materials, laborAndOther };
}

function fhRenderInvoices() {
  const el = document.getElementById('fhInvSec');
  const cnt = document.getElementById('fhInvCount');
  const sum = document.getElementById('fhInvSum');
  if (!el) return;
  const invs = _fhInvoices.slice().sort((a,b) => (b.date||'').localeCompare(a.date||''));
  const total = invs.reduce((s,i)=>s+(i.total||0),0);
  const paid = invs.reduce((s,i)=>s+(i.amtPaid||0),0);
  if (cnt) cnt.textContent = invs.length;
  if (sum) sum.textContent = invs.length ? `${fhMoney(paid)} / ${fhMoney(total)} collected` : '';
  const today = new Date().toISOString().split('T')[0];
  if (!invs.length) { el.innerHTML = '<div class="finhub-empty">No invoices yet for this job.</div>'; return; }

  // The cost split is NEVER shown here, or anywhere in the JOBSMETRIX
  // UI, even Owner-gated — Travis was explicit that this is private
  // margin information and doesn't belong anywhere near the invoice
  // itself, even behind a role check. It's delivered as a PlannerXD
  // notification instead (sendInvoiceSplitToPlannerXD below), a
  // genuinely separate destination only the Owner's account receives.
  const canSend = currentUserRole === 'Owner';

  el.innerHTML = invs.map(inv => {
    const bal = (inv.total||0) - (inv.amtPaid||0);
    let status = inv.status || 'Draft';
    if (status !== 'Paid' && inv.dueDate && inv.dueDate < today) status = 'Overdue';
    const color = FH_INV_COLORS[status] || '#8ea3c8';
    return `<div class="finhub-line" onclick="openEditInvoice('${inv.jobId||conCurrentJobId}','${inv.id}')" style="cursor:pointer;flex-wrap:wrap">
      <div><div class="finhub-line-title">${esc(inv.number||'Draft')}</div><div class="finhub-line-sub">${esc(inv.type||'Invoice')} · ${inv.date||'—'}${inv.dueDate?` · due ${inv.dueDate}`:''}</div></div>
      <div class="finhub-line-amt">${fhMoney(inv.total)}</div>
      <div class="finhub-line-bal" style="color:${bal>0?'#fde68a':'#a3f2d2'}">${bal>0?fhMoney(bal)+' due':'paid'}</div>
      <div>${fhBadge(status,color)}</div>
      ${canSend && inv.total > 0 ? `<div style="flex-basis:100%" onclick="event.stopPropagation()"><button class="btn" style="padding:3px 8px;font-size:.7rem;margin-top:4px" onclick="sendInvoiceSplitToPlannerXD('${inv.id}')">📤 Send split to PlannerXD (private)</button></div>` : ''}
    </div>`;
  }).join('');
}

// Sends a private cost-split breakdown for ONE specific invoice to
// PlannerXD — never shown anywhere in JOBSMETRIX itself, even
// Owner-gated. Same pattern as generateCOOBudgetBreakdown but scoped
// to a single invoice amount instead of the whole job's estimate
// total, and delivered exclusively rather than also displayed inline.
async function sendInvoiceSplitToPlannerXD(invId) {
  if (currentUserRole !== 'Owner') { alert('Only the Owner can send this.'); return; }
  const jobId = conCurrentJobId;
  const job = conJobs.find(j => j.id === jobId);
  const inv = _fhInvoices.find(i => i.id === invId);
  if (!job || !inv || !inv.total) return;

  const btn = document.querySelector(`button[onclick="sendInvoiceSplitToPlannerXD('${invId}')"]`);
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }

  try {
    // Whole-job breakdown first (real cost, gross-margin-ratio
    // flexing — see computeCOOBudgetBreakdown), THEN scale every
    // bucket down by this invoice's share of total revenue. A 35%
    // deposit invoice gets 35% of every one of the six bucket dollar
    // amounts, not a separately-recomputed 35%-of-fixed-percentages —
    // this is what makes it agree exactly with the whole-job number
    // shown elsewhere on the Financials tab.
    const breakdown = await computeCOOBudgetBreakdown(job);
    const share = breakdown.revenue > 0 ? inv.total / breakdown.revenue : 0;
    const fmt = v => '$' + v.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
    const scale = v => Math.round(v * share * 100) / 100;

    const parts = {
      materials: scale(breakdown.materials),
      labor: scale(breakdown.labor),
      overhead: scale(breakdown.overhead),
      profit: scale(breakdown.profit),
      marketing: scale(breakdown.marketing),
      taxes: scale(breakdown.taxes),
    };

    const placeholderNote = breakdown.costSource && breakdown.costSource.startsWith('PLACEHOLDER')
      ? `\n\n⚠️ Labor cost is a placeholder (no real subcontractor payments/hours logged yet) — this split will change once real cost data exists.`
      : '';

    const body = `Invoice ${inv.number || ''} — ${fmt(inv.total)} (${(share*100).toFixed(1)}% of job)\n\n`
      + `Materials: ${fmt(parts.materials)}\n`
      + `Labor: ${fmt(parts.labor)}\n`
      + `Overhead: ${fmt(parts.overhead)}\n`
      + `Retained Earnings: ${fmt(parts.profit)}\n`
      + `Marketing: ${fmt(parts.marketing)}\n`
      + `Taxes (from Retained Earnings): ${fmt(parts.taxes)}`
      + placeholderNote;

    const settDoc = await coll('settings').doc('company').get();
    const ownerUid = settDoc?.exists ? settDoc.data().ownerUid : null;
    if (!ownerUid) {
      alert('Could not send — no PlannerXD account (ownerUid) is linked in Company Settings.');
      return;
    }
    await conDb.collection('plannerxd_notifications').doc(ownerUid).collection('items').add({
      type: 'invoice_split',
      title: 'Invoice Split — ' + (job.address || job.name || 'Job') + ' · ' + (inv.number || ''),
      body,
      jobId,
      invId,
      companyId: currentCompanyId,
      actionLabel: 'Open Job',
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      createdMs: Date.now(),
      read: false
    });
    alert('✅ Sent to PlannerXD.');
  } catch (e) {
    alert('Error: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '📤 Send split to PlannerXD (private)'; }
  }
}
window.sendInvoiceSplitToPlannerXD = sendInvoiceSplitToPlannerXD;

function fhRenderCOs() {
  const el = document.getElementById('fhCOSec');
  const cnt = document.getElementById('fhCOCount');
  const sum = document.getElementById('fhCOSum');
  if (!el) return;
  const cos = Array.isArray(conCOs) ? conCOs : [];
  const approved = cos.filter(c=>c.status==='Approved').reduce((s,c)=>s+Number(c.amount||0),0);
  const pending = cos.filter(c=>c.status==='Pending').reduce((s,c)=>s+Number(c.amount||0),0);
  if (cnt) cnt.textContent = cos.length;
  if (sum) sum.textContent = cos.length ? `+${fhMoney(approved)} approved${pending?` · ${fhMoney(pending)} pending`:''}` : '';
  if (!cos.length) { el.innerHTML = '<div class="finhub-empty">No change orders.</div>'; return; }
  el.innerHTML = cos.map(co => {
    const amt = Number(co.amount||0);
    const color = FH_CO_COLORS[co.status] || '#8ea3c8';
    return `<div class="finhub-line" onclick="switchDetailTab('changeorders',null)" style="cursor:pointer">
      <div><div class="finhub-line-title">${esc(co.title||'Untitled CO')}</div><div class="finhub-line-sub">${co.date||'—'}${co.days?` · +${co.days}d`:''}</div></div>
      <div class="finhub-line-amt" style="color:${amt>=0?'var(--amber)':'#ef5350'}">${amt>=0?'+':''}${fhMoney(Math.abs(amt))}</div>
      <div></div>
      <div>${fhBadge(co.status,color)}</div>
    </div>`;
  }).join('');
}

