// Opens the Materials Purchase modal, pre-scoped to the currently open
// job. Pass an expenseId to edit an existing entry.
function openAddMaterialsFromJob(expenseId) {
  const existing = expenseId ? _fhMaterials.find(m => m.id === expenseId) : null;
  document.getElementById('matExpenseId').value = expenseId || '';
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v || ''; };
  setVal('matPurchasedFrom', existing?.purchasedFrom);
  setVal('matDesc', existing?.desc);
  setVal('matAmount', existing?.amount);
  setVal('matDate', existing?.date || new Date().toISOString().split('T')[0]);
  // Auto-fill Notes with the job's address/number on a genuinely NEW
  // purchase, so Travis doesn't have to type this by hand every time
  // (real, direct request -- he was manually typing e.g. "7123 Beulah
  // Ave Job 2026 587" on every single materials purchase before this).
  // Never overwrites an existing purchase's real notes when editing.
  if (existing) {
    setVal('matNotes', existing.notes);
  } else {
    const job = conJobs.find(j => j.id === conCurrentJobId);
    const autoNote = job ? [job.address, job.jobNumber].filter(Boolean).join(' ') : '';
    setVal('matNotes', autoNote);
  }
  document.getElementById('matPaidBy').value = existing?.paidBy || 'Debit Card';
  document.getElementById('deleteMatBtn').style.display = existing ? 'inline-flex' : 'none';

  // "Who Purchased" dropdown — was free text, easy to typo/inconsistent
  // (Jason Hudson vs J Hudson vs jason). Populated from the same team
  // list used elsewhere, with an "Other" fallback for anyone not in
  // the system yet (a customer, a one-off helper, etc).
  const sel = document.getElementById('matPurchasedBy');
  const existingName = existing?.purchasedBy || '';
  const knownNames = (_lastTeamMemberList || []).map(m => m.name || m.email).filter(Boolean);
  const isKnown = knownNames.includes(existingName);
  sel.innerHTML = '<option value="">Select…</option>' +
    knownNames.map(n => `<option value="${esc(n)}" ${n===existingName?'selected':''}>${esc(n)}</option>`).join('') +
    `<option value="__other__" ${existingName && !isKnown ? 'selected' : ''}>Other…</option>`;
  document.getElementById('matPurchasedByOther').value = (existingName && !isKnown) ? existingName : '';
  document.getElementById('matPurchasedByOtherWrap').style.display = (existingName && !isKnown) ? '' : 'none';

  kOpen('addMaterialsModal');
}
window.openAddMaterialsFromJob = openAddMaterialsFromJob;

function onMatPurchasedBySelectChange() {
  const sel = document.getElementById('matPurchasedBy');
  const wrap = document.getElementById('matPurchasedByOtherWrap');
  if (wrap) wrap.style.display = sel.value === '__other__' ? '' : 'none';
}
window.onMatPurchasedBySelectChange = onMatPurchasedBySelectChange;

function saveMaterialsPurchase() {
  const jobId = conCurrentJobId;
  if (!jobId) { alert('No job open.'); return; }
  const purchasedFrom = document.getElementById('matPurchasedFrom')?.value.trim();
  const desc = document.getElementById('matDesc')?.value.trim();
  const amount = parseFloat(document.getElementById('matAmount')?.value) || 0;
  if (!purchasedFrom) { alert('Purchased From is required (e.g. Home Depot).'); return; }
  if (!desc) { alert('Description is required.'); return; }
  if (!amount) { alert('Amount is required.'); return; }
  const expenseId = document.getElementById('matExpenseId')?.value;
  const purchasedBySel = document.getElementById('matPurchasedBy')?.value || '';
  const purchasedBy = purchasedBySel === '__other__'
    ? (document.getElementById('matPurchasedByOther')?.value.trim() || '')
    : purchasedBySel;
  const data = {
    purchasedFrom, desc, amount,
    date: document.getElementById('matDate')?.value || new Date().toISOString().split('T')[0],
    paidBy: document.getElementById('matPaidBy')?.value || 'Debit Card',
    purchasedBy,
    notes: document.getElementById('matNotes')?.value.trim() || '',
    companyId: currentCompanyId,
    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
  };
  const col = coll('jobs').doc(jobId).collection('expenses');
  const promise = expenseId ? col.doc(expenseId).update(data)
    : col.add({ ...data, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
  promise.then(() => {
    kClose('addMaterialsModal');
    fhLoadJobMaterials(jobId, () => { fhRenderMaterials(); const j = conJobs.find(x=>x.id===jobId); if (j) { fhRenderTotals(j); refreshJobFinancials(j); } });
    if (!expenseId) {
      const amtStr = amount.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
      logInvoiceActivity(jobId, 'materials_purchase', `Materials purchase — ${purchasedFrom}: $${amtStr}`);
    }
  }).catch(e => alert('Error: ' + e.message));
}
window.saveMaterialsPurchase = saveMaterialsPurchase;

function deleteMaterialsPurchase() {
  const jobId = conCurrentJobId;
  const expenseId = document.getElementById('matExpenseId')?.value;
  if (!jobId || !expenseId || !confirm('Delete this materials purchase?')) return;
  coll('jobs').doc(jobId).collection('expenses').doc(expenseId).delete()
    .then(() => {
      kClose('addMaterialsModal');
      fhLoadJobMaterials(jobId, () => { fhRenderMaterials(); const j = conJobs.find(x=>x.id===jobId); if (j) { fhRenderTotals(j); refreshJobFinancials(j); } });
    }).catch(e => alert('Error: ' + e.message));
}
window.deleteMaterialsPurchase = deleteMaterialsPurchase;

// ── Subcontractor Payments (1099 flat-rate job pay) ──
// Mirrors the Materials Purchase pattern exactly — job-scoped, own
// Firestore subcollection with its own security rule, no formal
// vendor account required. This is the "what's actually owed" side of
// the flat-rate subcontractor model: clock-in/out hours for these
// people are informational only (Estimated vs Actual comparisons);
// this is the real dollar cost that hits the job.
function fhLoadJobSubPayments(jobId, cb) {
  if (!conDb) { _fhSubPayments = []; cb && cb(); return; }
  coll('jobs').doc(jobId).collection('subcontractorPayments').orderBy('date', 'desc').get()
    .then(snap => { _fhSubPayments = []; snap.forEach(d => _fhSubPayments.push({ id: d.id, ...d.data() })); cb && cb(); })
    .catch(() => { _fhSubPayments = []; cb && cb(); });
}

function fhRenderSubPayments() {
  const el = document.getElementById('fhSubPaySec');
  const cnt = document.getElementById('fhSubPayCount');
  const sum = document.getElementById('fhSubPaySum');
  if (!el) return;
  const items = _fhSubPayments;
  const total = items.reduce((s,p) => s + (p.amount||0), 0);
  if (cnt) cnt.textContent = items.length;
  if (sum) sum.textContent = items.length ? `${fhMoney(total)} total` : '';

  const paymentsHtml = !items.length
    ? '<div class="finhub-empty">No subcontractor payments logged for this job.</div>'
    : items.map(p => `
    <div class="finhub-line" onclick="openAddSubPayFromJob('${p.id}')" style="cursor:pointer">
      <div><div class="finhub-line-title">${esc(p.subName||'Subcontractor')}</div><div class="finhub-line-sub">${esc(p.desc||'')}${p.overrideReason ? ' · <span style="color:#f59e0b">⚠ override: '+esc(p.overrideReason)+'</span>' : ''}</div></div>
      <div class="finhub-line-amt">${fhMoney(p.amount)}</div>
      <div class="finhub-line-bal" style="color:${p.status==='Paid'?'#a3f2d2':'#fde68a'}">${esc(p.status||'Agreed')}</div>
      <div>${fhBadge('Subcontractor','#c084fc')}</div>
    </div>`).join('');

  el.innerHTML = `<div id="fhSubHoursSummary" style="padding:8px 0;font-size:.8rem;color:var(--muted);font-style:italic">Loading crew hours…</div>` + paymentsHtml;
  fhLoadSubcontractorHours(conCurrentJobId);
}

// The actual reason to have Domingo, Rosario, AND Francisco all
// clocking in individually (not just the crew lead): true man-hours
// for comparing against what the estimate assumed (e.g. "3-man crew,
// 8hrs, 10 days = 240 man-hours"). One person's clock only ever
// captures one person's presence — this sums everyone flagged
// Flat-Rate Subcontractor who logged time on this specific job.
function fhLoadSubcontractorHours(jobId) {
  const target = document.getElementById('fhSubHoursSummary');
  if (!target || !conDb || !jobId) return;
  coll('timeentries').where('jobId', '==', jobId).get()
    .then(snap => {
      const byPerson = {};
      let totalHours = 0;
      snap.forEach(d => {
        const t = d.data();
        if (!t.hours || !isFlatRateSubcontractor(t.userId, t.userEmail)) return;
        const name = t.userName || t.userEmail || 'Unknown';
        byPerson[name] = (byPerson[name] || 0) + t.hours;
        totalHours += t.hours;
      });
      const stillTarget = document.getElementById('fhSubHoursSummary');
      if (!stillTarget) return;
      if (!totalHours) {
        stillTarget.innerHTML = '<span style="font-style:italic">No crew clock-in hours logged yet for this job.</span>';
        return;
      }
      const breakdown = Object.entries(byPerson).map(([n,h]) => `${esc(n)}: ${h.toFixed(1)}h`).join(' · ');
      stillTarget.innerHTML = `<strong style="color:var(--text);font-style:normal">👷 ${totalHours.toFixed(1)} total crew man-hours logged</strong> — ${breakdown}`;
    })
    .catch(() => {
      const stillTarget = document.getElementById('fhSubHoursSummary');
      if (stillTarget) stillTarget.textContent = '';
    });
}

function openAddSubPayFromJob(payId) {
  const existing = payId ? _fhSubPayments.find(p => p.id === payId) : null;
  document.getElementById('subPayId').value = payId || '';
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v || ''; };

  const job = conJobs.find(j => j.id === conCurrentJobId);
  const jobLabelEl = document.getElementById('subPayJobLabel');
  if (jobLabelEl) jobLabelEl.textContent = job ? `For: ${job.address || job.name || 'this job'}` : '';

  // Populate the dropdown from Contractors (real, standing payees),
  // plus a manual "Other" option for a one-off sub who was never added
  // as a contractor at all.
  const sel = document.getElementById('subPaySelect');
  const existingSubKey = existing ? (existing.subKey || '') : '';
  sel.innerHTML = '<option value="">Select…</option>' +
    (allContractors || []).map(c => `<option value="${esc(c.id)}" ${existingSubKey===c.id?'selected':''}>${esc(c.name||'Unnamed')}</option>`).join('') +
    `<option value="__other__" ${existing && !existingSubKey ? 'selected' : ''}>Other (not a contractor)…</option>`;

  setVal('subPayOtherName', existing && !existingSubKey ? existing.subName : '');
  document.getElementById('subPayOtherWrap').style.display = (existing && !existingSubKey) ? '' : 'none';
  setVal('subPayDesc', existing?.desc);
  setVal('subPayAmount', existing?.amount);
  setVal('subPayDate', existing?.date || new Date().toISOString().split('T')[0]);
  setVal('subPayNotes', existing?.notes);
  document.getElementById('subPayStatus').value = existing?.status || 'Agreed';
  document.getElementById('deleteSubPayBtn').style.display = existing ? 'inline-flex' : 'none';

  // Reset override-tracking state. Editing an existing payment doesn't
  // re-trigger a suggestion unless the person actively re-picks a name
  // from the dropdown — we're not second-guessing an already-agreed
  // number just because they opened it to edit the notes.
  _subPaySuggestedAmount = existing?.suggestedAmount ?? null;
  setVal('subPayOverrideReason', existing?.overrideReason || '');
  document.getElementById('subPaySuggestedWrap').style.display = 'none';
  document.getElementById('subPayOverrideWrap').style.display = existing?.overrideReason ? '' : 'none';
  document.getElementById('subPayScheduleWrap').style.display = 'none';
  setVal('subPayJobTotal', '');

  kOpen('addSubPayModal');
}
window.openAddSubPayFromJob = openAddSubPayFromJob;

// Opens the Financials tab's shortcut with nothing pre-selected.
function openAddSubPayFromJobShortcut() { openAddSubPayFromJob(null); }
window.openAddSubPayFromJobShortcut = openAddSubPayFromJobShortcut;

// Tracks the last auto-calculated "suggested" amount (hours logged on
// THIS job × the contractor's burdenedRate, summed across every Team
// Member in its crewMemberEmails) so we can detect when the person
// types something different and require them to say why — the actual
// ask being "prepopulate it, but force an explanation for any manual
// override" rather than silently accepting either one.
let _subPaySuggestedAmount = null;

async function onSubPaySelectChange() {
  const sel = document.getElementById('subPaySelect');
  const wrap = document.getElementById('subPayOtherWrap');
  if (wrap) wrap.style.display = sel.value === '__other__' ? '' : 'none';

  const suggestedWrap = document.getElementById('subPaySuggestedWrap');
  const overrideWrap = document.getElementById('subPayOverrideWrap');
  const amountEl = document.getElementById('subPayAmount');

  if (!sel.value || sel.value === '__other__') {
    // No real contractor selected — nothing to suggest against, and
    // an "Other" one-off sub has no logged hours/rate to compute from.
    _subPaySuggestedAmount = null;
    if (suggestedWrap) suggestedWrap.style.display = 'none';
    if (overrideWrap) overrideWrap.style.display = 'none';
    document.getElementById('subPayScheduleWrap').style.display = 'none';
    return;
  }

  const contractor = (allContractors || []).find(c => c.id === sel.value);
  const jobId = conCurrentJobId;
  if (!contractor || !jobId || !conDb) return;

  showSubPayScheduleSection(contractor);

  if (suggestedWrap) { suggestedWrap.style.display = ''; suggestedWrap.textContent = 'Calculating amount owed from logged hours…'; }

  const crewEmails = (contractor.crewMemberEmails || []).map(e => (e||'').toLowerCase());
  if (!crewEmails.length) {
    _subPaySuggestedAmount = null;
    if (suggestedWrap) {
      suggestedWrap.style.display = '';
      suggestedWrap.textContent = contractor.name + ' has no crew members linked (edit it under Contractors) — enter the amount manually.';
    }
    return;
  }

  try {
    const teSnap = await coll('timeentries').where('jobId', '==', jobId).get();
    let hours = 0;
    teSnap.forEach(d => {
      const t = d.data();
      if (!t.hours) return;
      if (!crewEmails.includes((t.userEmail || '').toLowerCase())) return;
      hours += t.hours;
    });
    const rate = Number(contractor.burdenedRate) || 0;
    const suggested = Math.round(hours * rate * 100) / 100;

    if (!hours || !rate) {
      _subPaySuggestedAmount = null; // nothing real to compare overrides against
      if (suggestedWrap) {
        suggestedWrap.style.display = '';
        suggestedWrap.textContent = !hours
          ? 'No clock-in hours logged for ' + contractor.name + '\'s crew on this job yet — enter the amount manually.'
          : contractor.name + ' has no burdened rate set (Contractors) — enter the amount manually.';
      }
      // Real bug this closes: switching FROM a contractor that had a
      // valid suggested amount (which shows overrideWrap when the
      // typed amount differs) TO one with no hours/rate left
      // overrideWrap stuck visible with _subPaySuggestedAmount now
      // null — clicking Save then crashed on null.toFixed(2), silently,
      // with no alert and no save. onSubPayAmountInput() already
      // guards against this correctly; this branch needs the same
      // guard, since it changes _subPaySuggestedAmount without going
      // through that function.
      if (overrideWrap) overrideWrap.style.display = 'none';
      return;
    }

    _subPaySuggestedAmount = suggested;
    if (amountEl) amountEl.value = suggested;
    if (suggestedWrap) {
      suggestedWrap.style.display = '';
      suggestedWrap.textContent = `Suggested: ${hours.toFixed(1)} crew hrs × $${rate.toFixed(2)}/hr = $${suggested.toFixed(2)} (from logged hours on this job)`;
    }
    if (overrideWrap) overrideWrap.style.display = 'none'; // matches suggestion exactly right now
  } catch (e) {
    _subPaySuggestedAmount = null;
    if (suggestedWrap) { suggestedWrap.style.display = ''; suggestedWrap.textContent = 'Could not calculate suggested amount: ' + e.message; }
  }
}
window.onSubPaySelectChange = onSubPaySelectChange;

// Shows/hides the "apply this job's payment schedule" section, using
// the SAME resolveScheduleStages() the invoice picker already reads
// from — so a 50/50 job shows 50/50 stage buttons here too, never a
// second, separately-typed schedule that could drift from the real
// one on the Estimate tab.
function showSubPayScheduleSection(contractor) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const stages = resolveScheduleStages(job?.paymentSchedule);
  const wrap = document.getElementById('subPayScheduleWrap');
  if (!wrap) return;
  if (!stages.length) { wrap.style.display = 'none'; return; }

  wrap.style.display = '';
  const typeLabel = job?.paymentSchedule?.type || '—';
  document.getElementById('subPayScheduleType').textContent = typeLabel;

  const totalEl = document.getElementById('subPayJobTotal');
  const savedTotal = contractor.contractorJobTotals && contractor.contractorJobTotals[conCurrentJobId];
  if (totalEl) totalEl.value = savedTotal || '';

  renderSubPayScheduleButtons();
}

function renderSubPayScheduleButtons() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const stages = resolveScheduleStages(job?.paymentSchedule);
  const total = parseFloat(document.getElementById('subPayJobTotal')?.value) || 0;
  const btnWrap = document.getElementById('subPayScheduleButtons');
  if (!btnWrap) return;

  if (!total) {
    btnWrap.innerHTML = '<span class="small muted" style="font-style:italic">Enter the contractor\'s total for this job to see stage amounts.</span>';
    return;
  }

  btnWrap.innerHTML = stages.map((s, i) => {
    const amt = Math.round(total * s.pct / 100 * 100) / 100;
    return `<button type="button" class="btn" style="padding:6px 12px;font-size:.8rem" onclick="applySubPayScheduleStage(${amt},'${esc(s.label)}',${s.pct})">${esc(s.label)} (${s.pct}%) → $${amt.toFixed(2)}</button>`;
  }).join('');
}
window.renderSubPayScheduleButtons = renderSubPayScheduleButtons;

// Clicking a stage button fills the amount + description from the
// job's own schedule. If this differs from the hours×rate suggestion
// (or there's no hours suggestion at all), the override-reason field
// still appears per the usual rule — but pre-filled with a real,
// specific reason instead of leaving it blank to retype, since
// "matches the job's own payment schedule" is a genuinely different
// and equally legitimate basis for the number, not a shortcut around
// the requirement.
function applySubPayScheduleStage(amount, label, pct) {
  const amountEl = document.getElementById('subPayAmount');
  const descEl = document.getElementById('subPayDesc');
  if (amountEl) amountEl.value = amount;
  if (descEl && !descEl.value.trim()) descEl.value = label + ' (' + pct + '%)';
  onSubPayAmountInput();
  const overrideWrap = document.getElementById('subPayOverrideWrap');
  const reasonEl = document.getElementById('subPayOverrideReason');
  if (overrideWrap && overrideWrap.style.display !== 'none' && reasonEl && !reasonEl.value.trim()) {
    reasonEl.value = `Matches job's payment schedule — ${label} (${pct}%)`;
  }
}
window.applySubPayScheduleStage = applySubPayScheduleStage;

// Fires on every keystroke in the Amount field. If a real suggested
// amount exists and the typed value no longer matches it, the override
// reason field becomes visible AND required before saving.
function onSubPayAmountInput() {
  const overrideWrap = document.getElementById('subPayOverrideWrap');
  if (!overrideWrap) return;
  if (_subPaySuggestedAmount === null) { overrideWrap.style.display = 'none'; return; }
  const current = parseFloat(document.getElementById('subPayAmount')?.value) || 0;
  const differs = Math.abs(current - _subPaySuggestedAmount) > 0.005;
  overrideWrap.style.display = differs ? '' : 'none';
  if (!differs) { const r = document.getElementById('subPayOverrideReason'); if (r) r.value = ''; }
}
window.onSubPayAmountInput = onSubPayAmountInput;

function saveSubcontractorPayment() {
  const jobId = conCurrentJobId;
  if (!jobId) { alert('No job open.'); return; }
  const sel = document.getElementById('subPaySelect');
  const selVal = sel?.value || '';
  let subKey = '', subName = '';
  if (selVal === '__other__') {
    subName = document.getElementById('subPayOtherName')?.value.trim() || '';
  } else if (selVal) {
    const contractor = (allContractors || []).find(c => c.id === selVal);
    subKey = selVal;
    subName = contractor?.name || 'Contractor';
  }
  const desc = document.getElementById('subPayDesc')?.value.trim();
  const amount = parseFloat(document.getElementById('subPayAmount')?.value) || 0;
  if (!subName) { alert('Select a subcontractor or enter a name.'); return; }
  if (!desc) { alert('Scope/description is required.'); return; }
  if (!amount) { alert('Amount is required.'); return; }

  // If the amount was auto-suggested from logged hours × rate and the
  // person changed it, require them to say why before it saves — the
  // whole point of prepopulating is that a silent override defeats it.
  // Guards against _subPaySuggestedAmount being null here even though
  // overrideWrap is visible — a real, previously-reproducible state
  // (switching subcontractors mid-modal) that used to crash this
  // whole function silently on null.toFixed(2), with no alert and no
  // save. Root cause fixed above too; this is the belt-and-suspenders
  // so the save button can never go silent again this way.
  const overrideWrap = document.getElementById('subPayOverrideWrap');
  const overrideVisible = overrideWrap && overrideWrap.style.display !== 'none' && _subPaySuggestedAmount !== null;
  const overrideReason = document.getElementById('subPayOverrideReason')?.value.trim() || '';
  if (overrideVisible && !overrideReason) {
    alert('This amount differs from the suggested $' + _subPaySuggestedAmount.toFixed(2) + ' (hours × rate). Enter a reason for the override before saving.');
    return;
  }

  const payId = document.getElementById('subPayId')?.value;
  const data = {
    subKey, subName, desc, amount,
    date: document.getElementById('subPayDate')?.value || new Date().toISOString().split('T')[0],
    status: document.getElementById('subPayStatus')?.value || 'Agreed',
    notes: document.getElementById('subPayNotes')?.value.trim() || '',
    suggestedAmount: overrideVisible ? _subPaySuggestedAmount : null,
    overrideReason: overrideVisible ? overrideReason : '',
    companyId: currentCompanyId,
    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
  };
  const col = coll('jobs').doc(jobId).collection('subcontractorPayments');
  const promise = payId ? col.doc(payId).update(data)
    : col.add({ ...data, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
  promise.then(() => {
    // Remember the entered "contractor's total for this job" on the
    // contractor record itself (keyed by job), so reopening this modal
    // for the same job+contractor later has it prefilled instead of
    // needing retyping for every stage payment.
    const jobTotal = parseFloat(document.getElementById('subPayJobTotal')?.value) || 0;
    if (selVal && selVal !== '__other__' && jobTotal) {
      coll('contractors').doc(selVal).set(
        { contractorJobTotals: { [jobId]: jobTotal } },
        { merge: true }
      ).catch(() => {}); // non-critical — the payment itself already saved
    }
    kClose('addSubPayModal');
    fhLoadJobSubPayments(jobId, () => {
      fhRenderSubPayments();
      const j = conJobs.find(x=>x.id===jobId);
      if (j) { fhRenderTotals(j); refreshJobFinancials(j); }
    });
    if (!payId) {
      const amtStr = amount.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
      logInvoiceActivity(jobId, 'subcontractor_payment', `Subcontractor payment — ${subName}: $${amtStr}`);
    }
  }).catch(e => alert('Error: ' + e.message));
}
window.saveSubcontractorPayment = saveSubcontractorPayment;

function deleteSubcontractorPayment() {
  const jobId = conCurrentJobId;
  const payId = document.getElementById('subPayId')?.value;
  if (!jobId || !payId || !confirm('Delete this subcontractor payment?')) return;
  coll('jobs').doc(jobId).collection('subcontractorPayments').doc(payId).delete()
    .then(() => {
      kClose('addSubPayModal');
      fhLoadJobSubPayments(jobId, () => {
        fhRenderSubPayments();
        const j = conJobs.find(x=>x.id===jobId);
        if (j) { fhRenderTotals(j); refreshJobFinancials(j); }
      });
    }).catch(e => alert('Error: ' + e.message));
}
window.deleteSubcontractorPayment = deleteSubcontractorPayment;

function openVendorFromBill(vendorId, billId) {
  // Best-effort: jump to vendor detail if available, else no-op
  if (typeof openVendorDetail === 'function' && vendorId) { openVendorDetail(vendorId); }
}

function fhRenderEva() {
  const sum = document.getElementById('fhEvaSum');
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (sum && job) {
    const ec = job.estCost||0, ac = job.actualCost||0;
    sum.textContent = ac ? `${fhMoney(ac)} actual of ${fhMoney(ec)} est` : `${fhMoney(ec)} est`;
  }
}

function fhRenderTotals(job) {
  const contract = getJobValue(job);
  const approvedCO = (Array.isArray(conCOs)?conCOs:[]).filter(c=>c.status==='Approved').reduce((s,c)=>s+Number(c.amount||0),0);
  const contractTotal = contract + approvedCO;
  const invoiced = _fhInvoices.reduce((s,i)=>s+(i.total||0),0);
  const collected = _fhInvoices.reduce((s,i)=>s+(i.amtPaid||0),0);
  const owedUs = invoiced - collected;
  // "Owed to Us" only ever meant invoiced-but-not-collected — it was
  // never the full remaining contract value, but showing it alone (on
  // a job invoiced 50%) reads as "that's all we're owed." Not Yet
  // Invoiced makes the rest of the picture visible: collected +
  // owedUs + notYetInvoiced should always sum back to contractTotal.
  const notYetInvoiced = Math.max(0, contractTotal - invoiced);
  const billsTotal = _fhBills.reduce((s,b)=>s+(b.amount||0),0);
  const billsPaid = _fhBills.reduce((s,b)=>s+(b.amtPaid||0),0);
  const weOwe = billsTotal - billsPaid;
  // Materials purchases are always paid in full at time of purchase (no
  // partial/owed concept, unlike vendor bills) — pure money already out.
  const materialsTotal = _fhMaterials.reduce((s,m)=>s+(m.amount||0),0);
  // Subcontractor payments: only count 'Paid' status as actual cash
  // out here, matching the vendor-bill pattern (amtPaid, not amount) —
  // an 'Agreed' payment is a real committed cost but hasn't moved yet.
  const subPaymentsPaid = _fhSubPayments.filter(p=>p.status==='Paid').reduce((s,p)=>s+(p.amount||0),0);
  const net = collected - billsPaid - materialsTotal - subPaymentsPaid;

  const set = (id,v,color) => { const el=document.getElementById(id); if(el){ el.textContent=fhMoney(v); if(color)el.style.color=color; } };
  set('fhContract', contractTotal);
  set('fhInvoiced', invoiced);
  set('fhCollected', collected, '#a3f2d2');
  set('fhOwedUs', owedUs, owedUs>0?'#fde68a':'#a3f2d2');
  set('fhNotInvoiced', notYetInvoiced, '#8ea3c8');
  set('fhBills', billsTotal);
  set('fhBillsPaid', billsPaid, '#a3f2d2');
  set('fhMaterialsOut', materialsTotal, '#a3f2d2');
  set('fhSubPayOut', subPaymentsPaid, '#a3f2d2');
  set('fhWeOwe', weOwe, weOwe>0?'#fca5a5':'#a3f2d2');

  const netEl = document.getElementById('fhNet');
  if (netEl) { netEl.textContent = (net<0?'-':'')+fhMoney(Math.abs(net)); netEl.style.color = net>=0?'#a3f2d2':'#fca5a5'; }
  const netSub = document.getElementById('fhNetSub');
  if (netSub) netSub.textContent = `${fhMoney(owedUs)} still coming in · ${fhMoney(weOwe)} still going out`;

  // Materials / Labor / Company Profit -- now sourced entirely from
  // computeLockedBucketSplit(), the SAME real locked-formula engine that
  // drives the COO Budget Breakdown and the top stat bar (see
  // applyJobFinancialsDisplay). This used to be a THIRD, independently
  // invented calculation: materials backed the 15% markup OUT (wrong --
  // the locked formula keeps it in), and labor was a fabricated flat
  // $100/hr x 3-man x estimated-days guess that ignored the real signed
  // subcontractor payment ($27,360 Agreed on 707 Karon Drive) entirely.
  // Travis: "I want it done right" -- one formula, real data, same
  // number everywhere on this page instead of three different ones.
  if (conCurrentJobId) {
    computeLockedBucketSplit(job).then(split => {
      set('fhEstMaterials', split.materials);
      set('fhEstLabor', split.labor);

      const profit = split.retainedEarnings;
      const margin = split.revenue > 0 ? (profit / split.revenue * 100) : 0;
      const profitEl = document.getElementById('fhProfitVal');
      const profitColor = profit > 0 ? '#a3f2d2' : profit < 0 ? '#f87171' : '#f59e0b';
      if (profitEl) { profitEl.textContent = (profit<0?'-':'')+fhMoney(Math.abs(profit)); profitEl.style.color = profitColor; }
      const profitSub = document.getElementById('fhProfitSub');
      if (profitSub) profitSub.textContent = `${margin.toFixed(1)}% margin on ${fhMoney(split.revenue)} contract, after Overhead, Marketing, Flex, Taxes, and real Stripe fees — same number as the COO Budget Breakdown's Retained Earnings`;
    }).catch(() => {
      set('fhEstMaterials', 0);
      set('fhEstLabor', 0);
    });
  }
}



