function confirmArchiveJob() {
  if (!conCurrentJobId || !conDb) return;
  const reasonSel = document.getElementById('archiveJobReason').value;
  const otherText = document.getElementById('archiveJobOtherText').value.trim();
  const reason = (reasonSel === 'Other' && otherText) ? otherText : reasonSel;
  if (!reason) { alert('Please select a reason.'); return; }
  if (!confirm('Delete this job? It will be removed from your boards and lists.')) return;

  coll('jobs').doc(conCurrentJobId).update({
      archived: true,
      archivedReason: reason,
      archivedAt: firebase.firestore.FieldValue.serverTimestamp(),
      archivedBy: conCurrentUser ? conCurrentUser.email : 'unknown'
    })
    .then(() => {
      kClose('archiveJobModal');
      kClose('jobDetailModal');
      conCurrentJobId = null;
    })
    .catch(e => alert('Error deleting: ' + e.message));
}
window.confirmArchiveJob = confirmArchiveJob;

async function deleteCurrentJob() {
  if (!conCurrentJobId || !conDb) return;
  if (!confirm('Delete this job? This will also permanently delete its estimate, invoices, change orders, logs, and any to-dos tied to it. This cannot be undone.')) return;
  const deletingId = conCurrentJobId;
  try {
    // Previously did a bare doc delete here, which left every
    // subcollection behind AND — the specific bug reported — any
    // to-dos in the top-level todos collection referencing this job's
    // ID, since those live outside the job doc entirely and a bare
    // delete never touches them. deleteJobCompletely() already does
    // this correctly (it's used by the bulk admin cleanup tool); this
    // just makes the everyday Delete button use the same real cleanup
    // instead of a second, incomplete copy of the logic.
    await deleteJobCompletely(deletingId);
    kClose('jobDetailModal');
    conCurrentJobId = null;
    conJobs = conJobs.filter(j => j.id !== deletingId);
    conRenderBoard();
    conRenderList();
    conRenderStats();
  } catch (e) {
    alert('Error deleting: ' + e.message);
  }
}
window.deleteCurrentJob = deleteCurrentJob;

// ── Job Data Cleanup Tool ────────────────────────────────────────────────
// Built after real Red Maples/JobTread test data was found still sitting
// as live job records (should never have persisted as actual jobs — only
// anonymized catalog/vendor reference data was ever supposed to carry
// over). Lets the account owner review every job and permanently remove
// anything that doesn't belong, with full cascading cleanup — not just
// the job doc, but its estimate tree, invoices, change orders, logs,
// proposals, and any SLA to-dos already generated referencing it. Plain
// job.delete() alone would leave all of that behind as orphaned data.
let _jobCleanupAll = [];
let _jobCleanupSelected = new Set();

function openJobCleanupModal() {
  if (!conDb) return;
  const listEl = document.getElementById('jobCleanupList');
  if (listEl) listEl.innerHTML = '<p class="muted">Loading every job…</p>';
  _jobCleanupSelected = new Set();
  kOpen('jobCleanupModal');

  coll('jobs').get().then(snap => {
    _jobCleanupAll = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    // Oldest first — leftover test/import data is far more likely to be
    // old than anything genuinely created recently.
    _jobCleanupAll.sort((a, b) => {
      const ta = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
      const tb = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
      return ta - tb;
    });
    renderJobCleanupList();
  }).catch(e => {
    if (listEl) listEl.innerHTML = '<p style="color:#ef5350">Error loading jobs: ' + esc(e.message) + '</p>';
  });
}
window.openJobCleanupModal = openJobCleanupModal;

function renderJobCleanupList() {
  const listEl = document.getElementById('jobCleanupList');
  if (!listEl) return;
  const q = (document.getElementById('jobCleanupSearch')?.value || '').toLowerCase().trim();
  const filtered = q
    ? _jobCleanupAll.filter(j => (j.name || '').toLowerCase().includes(q) || (j.address || '').toLowerCase().includes(q))
    : _jobCleanupAll;

  if (!filtered.length) {
    listEl.innerHTML = '<p class="muted">No jobs match.</p>';
    updateJobCleanupSelectedCount();
    return;
  }

  listEl.innerHTML = filtered.map(j => {
    const created = j.createdAt?.toDate ? j.createdAt.toDate().toLocaleDateString() : '—';
    const checked = _jobCleanupSelected.has(j.id) ? 'checked' : '';
    return `<div style="display:flex;align-items:center;gap:12px;padding:10px 8px;border-bottom:1px solid rgba(110,145,210,.1)">
      <input type="checkbox" ${checked} onchange="toggleJobCleanupSelect('${j.id}',this.checked)" style="flex-shrink:0;cursor:pointer" />
      <div style="flex:1;min-width:0">
        <div style="font-weight:600;font-size:.9rem">${esc(j.name || j.address || j.id)}</div>
        <div class="muted small">${esc(j.address || '')}${j.address && j.status ? ' · ' : ''}${esc(j.status || '')} · created ${created}</div>
      </div>
    </div>`;
  }).join('');
  updateJobCleanupSelectedCount();
}
window.renderJobCleanupList = renderJobCleanupList;

function toggleJobCleanupSelect(jobId, checked) {
  if (checked) _jobCleanupSelected.add(jobId);
  else _jobCleanupSelected.delete(jobId);
  updateJobCleanupSelectedCount();
}
window.toggleJobCleanupSelect = toggleJobCleanupSelect;

function selectAllJobCleanup(select) {
  const q = (document.getElementById('jobCleanupSearch')?.value || '').toLowerCase().trim();
  const filtered = q
    ? _jobCleanupAll.filter(j => (j.name || '').toLowerCase().includes(q) || (j.address || '').toLowerCase().includes(q))
    : _jobCleanupAll;
  if (select) filtered.forEach(j => _jobCleanupSelected.add(j.id));
  else filtered.forEach(j => _jobCleanupSelected.delete(j.id));
  renderJobCleanupList();
}
window.selectAllJobCleanup = selectAllJobCleanup;

function updateJobCleanupSelectedCount() {
  const el = document.getElementById('jobCleanupSelectedCount');
  if (el) el.textContent = _jobCleanupSelected.size + ' selected';
}

// Deletes a job and everything hanging off it: estimateGroups (with
// nested subgroups/items/sub-subgroups), invoices, changeorders,
// logs, proposals, dailyLogs, and any company-wide todos referencing
// this jobId (this is specifically what was generating the "URGENT:
// still unscheduled" alerts for jobs that never should have existed).
async function deleteJobCompletely(jobId) {
  const jobRef = coll('jobs').doc(jobId);

  const deleteAllDocs = async (ref) => {
    const snap = await ref.get();
    await Promise.all(snap.docs.map(d => d.ref.delete()));
    return snap.docs;
  };

  // Estimate tree: fetch groups first, clean every nested subcollection
  // (items, subgroups, sub-subgroups and their items), then delete each
  // group doc — order matters, deleting the group first would leave its
  // children as unreachable orphans.
  try {
    const groupsSnap = await jobRef.collection('estimateGroups').get();
    for (const groupDoc of groupsSnap.docs) {
      await deleteAllDocs(groupDoc.ref.collection('items'));
      const subgroupsSnap = await groupDoc.ref.collection('subgroups').get();
      for (const subDoc of subgroupsSnap.docs) {
        await deleteAllDocs(subDoc.ref.collection('items'));
        const subsubSnap = await subDoc.ref.collection('subgroups').get();
        for (const ssDoc of subsubSnap.docs) {
          await deleteAllDocs(ssDoc.ref.collection('items'));
          await ssDoc.ref.delete();
        }
        await subDoc.ref.delete();
      }
      await groupDoc.ref.delete();
    }
  } catch(e) { console.warn('Estimate tree cleanup error for', jobId, e.message); }

  // Other job subcollections
  for (const sub of ['invoices', 'changeorders', 'changeOrders', 'logs', 'dailyLogs', 'proposals']) {
    try { await deleteAllDocs(jobRef.collection(sub)); } catch(e) {}
  }

  // Orphaned SLA/manual todos referencing this job, company-wide
  try {
    const todosSnap = await coll('todos').where('jobId', '==', jobId).get();
    await Promise.all(todosSnap.docs.map(d => d.ref.delete()));
  } catch(e) { console.warn('Todo cleanup error for', jobId, e.message); }

  // Finally, the job doc itself
  await jobRef.delete();
}
window.deleteJobCompletely = deleteJobCompletely;

async function confirmJobCleanupDelete() {
  const count = _jobCleanupSelected.size;
  if (!count) { alert('Nothing selected.'); return; }
  const typed = prompt(`You're about to PERMANENTLY delete ${count} job${count===1?'':'s'} and everything attached to them (estimates, invoices, change orders, logs, SLA to-dos). This cannot be undone.\n\nType DELETE to confirm:`);
  if (typed !== 'DELETE') return;

  const btn = document.getElementById('jobCleanupDeleteBtn');
  if (btn) { btn.disabled = true; }
  const ids = Array.from(_jobCleanupSelected);
  let done = 0, failed = 0;
  for (const jobId of ids) {
    if (btn) btn.textContent = `Deleting ${done + failed + 1} of ${ids.length}…`;
    try {
      await deleteJobCompletely(jobId);
      done++;
    } catch(e) {
      console.error('Failed to delete job', jobId, e);
      failed++;
    }
  }
  if (btn) { btn.disabled = false; btn.textContent = 'Delete Selected'; }
  alert(`Deleted ${done} job${done===1?'':'s'}.` + (failed ? ` ${failed} failed — check console for details.` : ''));
  _jobCleanupSelected = new Set();
  openJobCleanupModal(); // refresh the list from scratch
}
window.confirmJobCleanupDelete = confirmJobCleanupDelete;

window.ktNav = ktNav;

// Returns the set of job IDs assigned to the current user - via crew
// membership (email match, reliable) or superintendent/pm field (name
// match, best-effort since those are free-text fields, not linked to
// the team roster). Used to scope the dashboard for restricted roles.
function getMyJobIds() {
  const myEmail = (conCurrentUser?.email || '').toLowerCase();
  const myName = (currentUserTeamData?.name || '').toLowerCase();
  const ids = new Set();
  conJobs.forEach(j => {
    const crewMatch = (j.crew || []).some(c => (c.email || '').toLowerCase() === myEmail);
    const nameMatch = myName && ((j.superintendent || '').toLowerCase() === myName || (j.pm || '').toLowerCase() === myName);
    if (crewMatch || nameMatch) ids.add(j.id);
  });
  return ids;
}
window.getMyJobIds = getMyJobIds;

// Master Schedule's own date-update functions -- deliberately
// separate from updatePhaseDate/updateRoomDate (the per-job Schedule
// tab's versions), which rely on the implicit _ganttJobId global.
// Master Schedule shows many jobs on screen at once, so every write
// here takes jobId explicitly instead -- reusing the per-job
// functions as-is would silently write to whatever job happened to
// be open last on the Schedule tab, corrupting a different job's
// dates. Full re-render after each save, matching how
// renderMasterSchedulePage already refetches every job's tree on
// every call -- not a new performance cost, just reusing the existing
// pattern.
async function updateMasterPhaseDate(jobId, phaseId, field, value) {
  if (!jobId || !conDb) return;
  try {
    await coll('jobs').doc(jobId)
      .collection('estimateGroups').doc(phaseId)
      .update({ [field]: value, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save phase date: ' + e.message);
  }
}
window.updateMasterPhaseDate = updateMasterPhaseDate;

async function updateMasterRoomDate(jobId, phaseId, roomId, field, value) {
  if (!jobId || !conDb) return;
  try {
    await coll('jobs').doc(jobId)
      .collection('estimateGroups').doc(phaseId)
      .collection('subgroups').doc(roomId)
      .update({ [field]: value, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save room date: ' + e.message);
  }
}
window.updateMasterRoomDate = updateMasterRoomDate;

async function updateMasterJobDate(jobId, field, value) {
  if (!jobId || !conDb) return;
  try {
    const job = conJobs.find(j => j.id === jobId);
    if (job) job[field] = value;
    await coll('jobs').doc(jobId).update({ [field]: value, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save job date: ' + e.message);
  }
}
window.updateMasterJobDate = updateMasterJobDate;

// Task-level dates -- only for REAL tasks (actual items in Firestore).
// Rooms with no real tasks yet fall back to parsing room.scopeNotes
// into synthetic display-only rows (id 'scope_<roomId>_<n>') so
// something still renders -- those aren't Firestore documents and
// can't be written to, so the row stays read-only for those
// specifically (checked at the call site via task.id.startsWith
// ('scope_'), the same synthetic-row marker used when they're built).
async function updateMasterTaskDate(jobId, phaseId, roomId, taskId, field, value) {
  if (!jobId || !conDb) return;
  try {
    await coll('jobs').doc(jobId)
      .collection('estimateGroups').doc(phaseId)
      .collection('subgroups').doc(roomId)
      .collection('items').doc(taskId)
      .update({ [field]: value, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save task date: ' + e.message);
  }
}
window.updateMasterTaskDate = updateMasterTaskDate;

// Duration and explicit dates are mutually exclusive, same rule as
// the per-job Schedule tab: setting a duration switches the row back
// to computed scheduling and clears any manual Start/Finish override
// -- keeping both active at once would let the Days column lie about
// what's actually driving the row.
async function updateMasterRoomDuration(jobId, phaseId, roomId, days) {
  if (!jobId || !conDb) return;
  const d = Math.max(1, Math.round(Number(days) || 1));
  try {
    await coll('jobs').doc(jobId)
      .collection('estimateGroups').doc(phaseId)
      .collection('subgroups').doc(roomId)
      .update({
        durationDays: d,
        startDate: firebase.firestore.FieldValue.delete(),
        endDate: firebase.firestore.FieldValue.delete(),
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save duration: ' + e.message);
  }
}
window.updateMasterRoomDuration = updateMasterRoomDuration;

async function updateMasterTaskDuration(jobId, phaseId, roomId, taskId, days) {
  if (!jobId || !conDb) return;
  const d = Math.max(1, Math.round(Number(days) || 1));
  try {
    // No local task object here (Master Schedule doesn't hold the
    // per-job _ganttData tree) -- read the existing startDate first so
    // Days edits anchor to it instead of blindly wiping both dates,
    // same fix as updateTaskDuration.
    const docRef = coll('jobs').doc(jobId)
      .collection('estimateGroups').doc(phaseId)
      .collection('subgroups').doc(roomId)
      .collection('items').doc(taskId);
    const snap = await docRef.get();
    const existingStart = snap.exists ? snap.data().startDate : null;
    const updates = existingStart
      ? { durationDays: d, endDate: addWorkDaysISO(existingStart, d) }
      : { durationDays: d, startDate: firebase.firestore.FieldValue.delete(), endDate: firebase.firestore.FieldValue.delete() };
    await docRef.update({ ...updates, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    renderMasterSchedulePage();
  } catch(e) {
    alert('Could not save duration: ' + e.message);
  }
}
window.updateMasterTaskDuration = updateMasterTaskDuration;

// Reuses the EXISTING dependency modal (openRoomScheduleModal /
// saveRoomSchedule) rather than building a parallel one -- that modal
// reads/writes through the _ganttData/_ganttJobId globals the per-job
// Schedule tab normally owns, so this temporarily populates those
// with the ONE job being edited (fresh fetch + the same numbering
// pass renderJobGantt itself runs), opens the real modal unchanged,
// and saveRoomSchedule's own re-render call has been extended (see
// below) to also refresh Master Schedule when it's the active page.
// Genuinely the same dependency editor, not an approximation of it.
async function openMasterRoomScheduleModal(jobId, phaseId, roomId) {
  try {
    const tree = await loadEpicTree(jobId);
    _ganttJobId = jobId;
    _ganttData = tree.map(phase => ({
      phase,
      rooms: phase.features.map(room => ({ room, tasks: room.tasks || [] })),
    }));
    buildGanttNumbering();
    openRoomScheduleModal(phaseId, roomId);
  } catch(e) {
    alert('Could not open dependency editor: ' + e.message);
  }
}
window.openMasterRoomScheduleModal = openMasterRoomScheduleModal;

// Shared by every Master-Schedule action that reuses a per-job
// function (dependency modal, clear-date buttons): those functions
// only know how to refresh the per-job Schedule tab (renderJobGantt),
// which safely no-ops on Master Schedule since #ganttLeftRows doesn't
// exist there. This is the other half -- refresh Master Schedule too,
// but only when it's actually the visible page (it stays in the DOM
// at all times, just hidden via the .active class, so existence alone
// isn't the right check).
function refreshMasterIfActive() {
  const msPage = document.getElementById('ktPageMasterschedule');
  if (msPage && msPage.classList.contains('active')) renderMasterSchedulePage();
}
window.refreshMasterIfActive = refreshMasterIfActive;

// Same borrow-the-per-job-globals pattern as openMasterRoomScheduleModal
// above -- these four clear-date buttons call the REAL
// clearRoomDateOverride/clearPhaseDateOverride/clearTaskDateOverride/
// clearAllJobDates functions unchanged (all four already extended to
// call refreshMasterIfActive themselves), just with _ganttData/
// _ganttJobId pointed at the right job first.
async function withMasterJobContext(jobId, fn) {
  const tree = await loadEpicTree(jobId);
  _ganttJobId = jobId;
  _ganttData = tree.map(phase => ({
    phase,
    rooms: phase.features.map(room => ({ room, tasks: room.tasks || [] })),
  }));
  buildGanttNumbering();
  return fn();
}
window.withMasterJobContext = withMasterJobContext;

function clearMasterPhaseDate(jobId, phaseId) {
  withMasterJobContext(jobId, () => clearPhaseDateOverride(phaseId));
}
window.clearMasterPhaseDate = clearMasterPhaseDate;

function clearMasterRoomDate(jobId, phaseId, roomId) {
  withMasterJobContext(jobId, () => clearRoomDateOverride(phaseId, roomId));
}
window.clearMasterRoomDate = clearMasterRoomDate;

function clearMasterTaskDate(jobId, phaseId, roomId, taskId) {
  withMasterJobContext(jobId, () => clearTaskDateOverride(phaseId, roomId, taskId));
}
window.clearMasterTaskDate = clearMasterTaskDate;

function clearMasterAllJobDates(jobId) {
  withMasterJobContext(jobId, () => clearAllJobDates());
}
window.clearMasterAllJobDates = clearMasterAllJobDates;

// Phase drag-reorder for Master Schedule -- same visual behavior as
// the per-job Schedule tab's ganttPhaseDragStart/Over/Leave/End, but
// the drop handler is different by necessity: phases only make sense
// reordered WITHIN their own job, so this checks the dragged and
// target phases share a job before doing anything, silently ignoring
// a drop across two different jobs' phase lists rather than doing
// something nonsensical with it.
let _masterDraggedPhaseId = null;
let _masterDraggedJobId = null;

function masterPhaseDragStart(e, jobId, phaseId) {
  _masterDraggedPhaseId = phaseId;
  _masterDraggedJobId = jobId;
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', phaseId);
  e.currentTarget.classList.add('dragging');
}
window.masterPhaseDragStart = masterPhaseDragStart;

function masterPhaseDragOver(e) {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'move';
  e.currentTarget.classList.add('drag-over');
}
window.masterPhaseDragOver = masterPhaseDragOver;

function masterPhaseDragLeave(e) {
  e.currentTarget.classList.remove('drag-over');
}
window.masterPhaseDragLeave = masterPhaseDragLeave;

function masterPhaseDragEnd(e) {
  e.currentTarget.classList.remove('dragging');
  document.querySelectorAll('.gantt-left-row.phase-row.drag-over').forEach(el => el.classList.remove('drag-over'));
}
window.masterPhaseDragEnd = masterPhaseDragEnd;

async function masterPhaseDrop(e, targetJobId, targetPhaseId) {
  e.preventDefault();
  e.currentTarget.classList.remove('drag-over');
  const draggedId = _masterDraggedPhaseId;
  const draggedJobId = _masterDraggedJobId;
  _masterDraggedPhaseId = null;
  _masterDraggedJobId = null;
  if (!draggedId || draggedId === targetPhaseId || !conDb) return;
  if (draggedJobId !== targetJobId) return; // different jobs -- not a valid reorder, ignore silently

  try {
    const tree = await loadEpicTree(targetJobId);
    const fromIdx = tree.findIndex(p => p.id === draggedId);
    const toIdx = tree.findIndex(p => p.id === targetPhaseId);
    if (fromIdx === -1 || toIdx === -1) return;

    const [moved] = tree.splice(fromIdx, 1);
    tree.splice(toIdx, 0, moved);

    const writes = tree.map((phase, i) =>
      coll('jobs').doc(targetJobId).collection('estimateGroups').doc(phase.id)
        .update({ order: i, updatedAt: firebase.firestore.FieldValue.serverTimestamp() })
    );
    await Promise.all(writes);
    renderMasterSchedulePage();
  } catch(e2) {
    alert('Could not save the new phase order: ' + e2.message);
  }
}
window.masterPhaseDrop = masterPhaseDrop;

// Task-level wrappers -- same borrow-the-per-job-globals pattern used
// throughout. Every one of these calls the REAL per-job function
// unchanged (all five have been extended above to call
// refreshMasterIfActive themselves).
function indentMasterTask(jobId, phaseId, roomId, taskId) {
  withMasterJobContext(jobId, () => indentGanttTask(phaseId, roomId, taskId));
}
window.indentMasterTask = indentMasterTask;

function outdentMasterTask(jobId, phaseId, roomId, taskId) {
  withMasterJobContext(jobId, () => outdentGanttTask(phaseId, roomId, taskId));
}
window.outdentMasterTask = outdentMasterTask;

function removeMasterTaskFromSchedule(jobId, phaseId, roomId, taskId, taskName) {
  withMasterJobContext(jobId, () => removeTaskFromSchedule(phaseId, roomId, taskId, taskName));
}
window.removeMasterTaskFromSchedule = removeMasterTaskFromSchedule;

function restoreMasterTaskToSchedule(jobId, phaseId, roomId, taskId) {
  withMasterJobContext(jobId, () => restoreTaskToSchedule(phaseId, roomId, taskId));
}
window.restoreMasterTaskToSchedule = restoreMasterTaskToSchedule;

function updateMasterTaskPct(jobId, phaseId, roomId, taskId, pct) {
  withMasterJobContext(jobId, () => updateTaskPct(phaseId, roomId, taskId, pct));
}
window.updateMasterTaskPct = updateMasterTaskPct;

async function openMasterTaskScheduleModal(jobId, phaseId, roomId, taskId) {
  try {
    const tree = await loadEpicTree(jobId);
    _ganttJobId = jobId;
    _ganttData = tree.map(phase => ({
      phase,
      rooms: phase.features.map(room => ({ room, tasks: room.tasks || [] })),
    }));
    buildGanttNumbering();
    openTaskScheduleModal(phaseId, roomId, taskId);
  } catch(e) {
    alert('Could not open dependency editor: ' + e.message);
  }
}
window.openMasterTaskScheduleModal = openMasterTaskScheduleModal;

function toggleMasterRow(type, id) {
  if (!window._masterCollapsed) window._masterCollapsed = {};
  const nowCollapsed = !window._masterCollapsed[id];
  window._masterCollapsed[id] = nowCollapsed;

  function showEl(el) {
    el.style.display = el.hasAttribute('data-master-row') ? 'flex' : 'block';
  }

  if (type === 'job') {
    const arrow = document.getElementById('masterArrowJob_' + id);
    if (arrow) arrow.textContent = nowCollapsed ? '▶' : '▼';
    document.querySelectorAll('[data-parent-job="' + id + '"]').forEach(el => {
      if (nowCollapsed) {
        el.style.display = 'none';
      } else {
        const phaseId = el.getAttribute('data-parent-phase');
        const roomId = el.getAttribute('data-parent-room');
        if (roomId && window._masterCollapsed[roomId]) { el.style.display = 'none'; return; }
        if (phaseId && window._masterCollapsed[phaseId]) { el.style.display = 'none'; return; }
        showEl(el);
      }
    });
  } else if (type === 'phase') {
    const arrow = document.getElementById('masterArrowPhase_' + id);
    if (arrow) arrow.textContent = nowCollapsed ? '▶' : '▼';
    document.querySelectorAll('[data-parent-phase="' + id + '"]').forEach(el => {
      if (nowCollapsed) {
        el.style.display = 'none';
      } else {
        const roomId = el.getAttribute('data-parent-room');
        if (roomId && window._masterCollapsed[roomId]) { el.style.display = 'none'; return; }
        showEl(el);
      }
    });
  } else if (type === 'room') {
    const arrow = document.getElementById('masterArrowRoom_' + id);
    if (arrow) arrow.textContent = nowCollapsed ? '▶' : '▼';
    document.querySelectorAll('[data-parent-room="' + id + '"]').forEach(el => {
      el.style.display = nowCollapsed ? 'none' : (el.hasAttribute('data-master-row') ? 'flex' : 'block');
    });
  }
}
window.toggleMasterRow = toggleMasterRow;

async function renderMasterSchedulePage() {
  const el = document.getElementById('masterPageGantt');
  const meta = document.getElementById('masterPageMeta');
  if (!el) return;

  el.innerHTML = '<div class="small muted" style="padding:24px;font-style:italic">Loading all jobs...</div>';

  const ACTIVE = ['Scheduled','In Progress','To Be Scheduled','Inspection Pending'];
  const activeJobs = conJobs.filter(j => ACTIVE.includes(j.status))
    .sort((a,b) => (a.startDate||'9999').localeCompare(b.startDate||'9999'));

  if (meta) meta.textContent = activeJobs.length + ' active job' + (activeJobs.length !== 1 ? 's' : '');

  const jobPhaseMap = {};
  await Promise.all(activeJobs.map(async job => {
    try { jobPhaseMap[job.id] = await loadEpicTree(job.id); }
    catch(e) { jobPhaseMap[job.id] = []; }
  }));

  const today = new Date(); today.setHours(0,0,0,0);
  const allDates = [];
  activeJobs.forEach(job => {
    if (job.startDate) allDates.push(new Date(job.startDate));
    if (job.endDate) allDates.push(new Date(job.endDate));
    (jobPhaseMap[job.id] || []).forEach(phase => {
      if (phase.startDate) allDates.push(new Date(phase.startDate));
      if (phase.endDate) allDates.push(new Date(phase.endDate));
    });
  });

  if (!allDates.length) {
    el.innerHTML = '<div class="small muted" style="padding:24px;font-style:italic">No jobs with dates set.</div>';
    return;
  }

  let minDate = new Date(Math.min(...allDates));
  let maxDate = new Date(Math.max(...allDates));
  minDate.setDate(minDate.getDate() - 5);
  maxDate.setDate(maxDate.getDate() + 14);

  const totalDays = Math.ceil((maxDate - minDate) / 86400000);
  const DAY_W = 32;
  const totalWidth = totalDays * DAY_W;
  // Matches the per-job Schedule tab's #ganttLeft column widths exactly
  // (340 + 70 + 125 + 125 + 95 + 70 = 825), so Master Schedule reads as
  // the same tool, not a lighter cousin of it.
  const LEFT_W = 825;
  const ROW_H = 44;
  const PHASE_H = 34;
  const TASK_H = 26;
  const todayOffset = Math.floor((today - minDate) / 86400000) * DAY_W;

  if (!window._masterCollapsed) window._masterCollapsed = {};
  const isOwner = ['Owner', 'Full Access'].includes(currentUserRole);

  // Build month header html
  let monthHtml = '<div style="display:flex">';
  let d = new Date(minDate.getFullYear(), minDate.getMonth(), 1);
  while (d <= maxDate) {
    const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
    const visStart = d < minDate ? minDate : d;
    const visEnd = monthEnd > maxDate ? maxDate : monthEnd;
    const days = Math.ceil((visEnd - visStart) / 86400000) + 1;
    const w = days * DAY_W;
    monthHtml += `<div style="width:${w}px;flex-shrink:0;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.1);padding:4px 6px;white-space:nowrap;overflow:hidden">${d.toLocaleString('default',{month:'short',year:'numeric'})}</div>`;
    d = new Date(d.getFullYear(), d.getMonth() + 1, 1);
  }
  monthHtml += '</div>';

  // Inline bar renderer — returns the bar cell html for the right side of a row
  function rowBar(startDate, endDate, color, height, pct, label) {
    if (!startDate || !endDate) return `<div style="flex:1;min-width:${totalWidth}px"></div>`;
    const s = new Date(startDate), e = new Date(endDate);
    const leftPx = Math.floor((s - minDate) / 86400000) * DAY_W;
    const width = Math.max(DAY_W, Math.ceil((e - s) / 86400000) * DAY_W);
    const pctNum = pct || 0;
    const overlay = (pctNum >= 0 && pctNum < 100)
      ? `<div style="position:absolute;right:0;top:0;height:100%;width:${100-pctNum}%;background:rgba(0,0,0,0.5);pointer-events:none;border-radius:0 4px 4px 0"></div>`
      : '';
    return `<div style="flex:1;min-width:${totalWidth}px;position:relative">
      <div style="position:absolute;left:${leftPx}px;width:${width}px;height:${height}px;top:50%;transform:translateY(-50%);${color};border-radius:4px;overflow:hidden;display:flex;align-items:center">
        ${overlay}
        ${width > 50 ? `<span style="position:relative;z-index:1;font-size:.6rem;font-weight:700;color:#fff;padding:0 5px;white-space:nowrap;overflow:hidden;max-width:${width-10}px">${esc(label)}</span>` : ''}
      </div>
    </div>`;
  }

  // Six fixed-width columns matching .gantt-name-cell/.gantt-days-cell/
  // .gantt-start-cell/.gantt-end-cell/.gantt-deps-cell/.gantt-pct-cell
  // exactly (same CSS classes, reused as-is -- not reimplemented) so
  // this genuinely looks and reads like the same tool as the per-job
  // Schedule tab, not an approximation of it. Read-only for now
  // (plain text/spans, no <input> elements) -- editing comes in the
  // next pass, once this display layer is confirmed correct.
  function sixCols(nameHtml, daysHtml, startHtml, finishHtml, deps, pct, pctColorVal, depsOnClick, depsTitle, pctHtml) {
    return `<div class="gantt-name-cell">${nameHtml}</div>
      <div class="gantt-days-cell" onclick="event.stopPropagation()">${daysHtml ?? '—'}</div>
      <div class="gantt-date-cell gantt-start-cell" onclick="event.stopPropagation()">${startHtml}</div>
      <div class="gantt-date-cell gantt-end-cell" onclick="event.stopPropagation()">${finishHtml}</div>
      <div class="gantt-deps-cell" onclick="event.stopPropagation();${depsOnClick||''}" title="${depsTitle||''}">${deps || ''}</div>
      <div class="gantt-pct-cell" onclick="event.stopPropagation()" style="color:${pctColorVal || 'var(--muted)'};font-weight:700">${pctHtml ?? (pct+'%')}</div>`;
  }

  // Recursive task-tree renderer -- mirrors renderTaskNodeRow's
  // structure exactly (rollup %/dates for summary tasks, indent/
  // outdent, dependency editing, remove/restore, %-done editing) but
  // built on Master's own sixCols column layout and with jobId
  // threaded through every handler, since renderTaskNodeRow's own
  // handlers all assume the single implicit _ganttJobId. Nested here
  // (not top-level) specifically so it closes over sixCols -- defined
  // one line up, and only ever existing as a local inside this
  // function. Previously Master Schedule's task rows were a flat list
  // with no tree structure at all, which is why indent/outdent
  // wouldn't have been visible even once wired up -- this is the
  // companion change that makes the result of indenting/outdenting
  // actually show.
  function renderMasterTaskNode(node, depth, phase, room, job, isOwner, siblings, siblingIdx) {
    const isReal = !node.fromScopeNotes;
    const hasKids = node.children && node.children.length > 0;
    const collapsed = window._masterCollapsed[node.id];
    const indentPx = 36 + depth * 24;

    let tPct, taskStart, taskEnd, taskCircular, taskDays;
    if (hasKids) {
      tPct = getTaskNodePct(node);
      const d = getTaskNodeDates(node, room, phase);
      taskStart = d.start; taskEnd = d.end; taskCircular = d.circular;
      taskDays = workDaysBetween(taskStart, taskEnd);
    } else {
      tPct = isReal ? getTaskPct(node) : (node.taskStatus === 'done' ? 100 : 0);
      const d = isReal ? getTaskDates(node, room, phase) : { start: null, end: null, circular: false };
      taskStart = d.start; taskEnd = d.end; taskCircular = d.circular;
      taskDays = isReal ? workDaysBetween(taskStart, taskEnd) : 1;
    }
    const isDone = tPct === 100;
    const glyphColor = isDone ? '#10b981' : (tPct > 0 ? '#60a5fa' : 'var(--muted)');
    const canIndent = isReal && isOwner && siblingIdx > 0;
    const canOutdent = isReal && isOwner && depth > 0;

    const nameHtml = `${hasKids ? `<span class="gantt-collapse-btn" onclick="event.stopPropagation();window._masterCollapsed['${node.id}']=!window._masterCollapsed['${node.id}'];renderMasterSchedulePage()" style="cursor:pointer">${collapsed?'▶':'▼'}</span>` : ''}<span class="gantt-task-name-text" style="padding-left:${indentPx}px;${isDone?'text-decoration:line-through;opacity:.5':''}" title="${esc(node.name)}">${esc(node.name)}</span>${isReal && isOwner ? `<span style="display:inline-flex;gap:2px;margin-left:6px;flex-shrink:0">${canOutdent?`<button onclick="event.stopPropagation();outdentMasterTask('${job.id}','${phase.id}','${room.id}','${node.id}')" title="Outdent" style="background:none;border:1px solid rgba(110,145,210,.25);border-radius:4px;color:var(--muted);cursor:pointer;font-size:.65rem;padding:0 4px">◀</button>`:''}${canIndent?`<button onclick="event.stopPropagation();indentMasterTask('${job.id}','${phase.id}','${room.id}','${node.id}')" title="Indent" style="background:none;border:1px solid rgba(110,145,210,.25);border-radius:4px;color:var(--muted);cursor:pointer;font-size:.65rem;padding:0 4px">▶</button>`:''}</span>${node.excludeFromSchedule?`<button onclick="event.stopPropagation();restoreMasterTaskToSchedule('${job.id}','${phase.id}','${room.id}','${node.id}')" title="Restore to schedule" style="background:none;border:1px solid rgba(110,145,210,.25);border-radius:6px;color:var(--amber);cursor:pointer;font-size:.65rem;margin-left:4px;padding:0 5px;flex-shrink:0">↺</button>`:`<button onclick="event.stopPropagation();removeMasterTaskFromSchedule('${job.id}','${phase.id}','${room.id}','${node.id}','${jsAttrEsc(node.name)}')" title="Remove from schedule" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:.72rem;margin-left:4px;padding:0;flex-shrink:0">✕</button>`}` : ''}`;

    const daysHtml = taskCircular ? '⚠' : (hasKids
      ? (taskDays !== null ? `${taskDays}d` : '—')
      : (isReal && isOwner
        ? `<input type="number" min="1" value="${node.durationDays || (taskDays!==null?taskDays:'')}" placeholder="—" onchange="updateMasterTaskDuration('${job.id}','${phase.id}','${room.id}','${node.id}',this.value)">`
        : (taskDays !== null ? taskDays+'d' : '—')));

    const startHtml = taskCircular ? `<span style="color:#f87171">⚠</span>` : (hasKids
      ? esc(taskStart || '—')
      : (isReal && isOwner
        ? `<input type="date" value="${node.startDate||''}" onchange="updateMasterTaskDate('${job.id}','${phase.id}','${room.id}','${node.id}','startDate',this.value)">`
        : esc(taskStart || '—')));

    const finishHtml = taskCircular ? '' : (hasKids
      ? esc(taskEnd || '—')
      : (isReal && isOwner
        ? `<input type="date" value="${node.endDate||''}" onchange="updateMasterTaskDate('${job.id}','${phase.id}','${room.id}','${node.id}','endDate',this.value)">${(node.startDate||node.endDate)?`<button onclick="event.stopPropagation();clearMasterTaskDate('${job.id}','${phase.id}','${room.id}','${node.id}')" title="Clear this task's custom dates" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:.7rem;flex-shrink:0;padding:0">✕</button>`:''}`
        : esc(taskEnd || '—')));

    const pctHtml = hasKids
      ? `<span style="color:${glyphColor}">${tPct}%</span>`
      : (isReal && isOwner
        ? `<input type="number" min="0" max="100" step="5" value="${tPct}" onchange="updateMasterTaskPct('${job.id}','${phase.id}','${room.id}','${node.id}',this.value)" style="width:50px;background:rgba(110,145,210,.08);border:1px solid rgba(110,145,210,.25);border-radius:5px;color:${glyphColor};font-weight:700;font-size:.72rem;padding:3px 2px;text-align:center">`
        : `<span style="color:${glyphColor}">${tPct}%</span>`);

    let html = `<div data-master-row="task" data-task-idx="${node.id}" data-parent-room="${room.id}" data-parent-phase="${phase.id}" data-parent-job="${job.id}" class="gantt-left-row task-row" style="min-height:26px;${node.excludeFromSchedule?'opacity:.45':''}">
      ${sixCols(
        nameHtml, daysHtml, startHtml, finishHtml,
        isReal ? formatDependsOn(node.dependsOn) : '',
        tPct, glyphColor,
        isReal && isOwner ? `openMasterTaskScheduleModal('${job.id}','${phase.id}','${room.id}','${node.id}')` : '',
        isReal && isOwner ? 'Click to set dependencies' : '',
        pctHtml
      )}
      <div style="flex:1"></div>
    </div>`;

    if (hasKids && !collapsed) {
      node.children.forEach((child, i) => {
        html += renderMasterTaskNode(child, depth + 1, phase, room, job, isOwner, node.children, i);
      });
    }
    return html;
  }


  let rowsHtml = '';

  activeJobs.forEach(job => {
    const jobCollapsed = window._masterCollapsed[job.id];
    const phases = (jobPhaseMap[job.id] || []).filter(p => p.startDate && p.endDate);
    const allPhases = jobPhaseMap[job.id] || [];
    const isLate = job.endDate && new Date(job.endDate) < today;
    const isActive = job.status === 'In Progress';
    const jobBarColor = isLate ? 'background:linear-gradient(90deg,#991b1b,#ef4444)'
      : isActive ? 'background:linear-gradient(90deg,#065f46,#10b981)'
      : 'background:linear-gradient(90deg,#b45309,#d97706)';

    let _jobDone = 0, _jobTotal = 0;
    allPhases.forEach(p => {
      (p.features || []).forEach(room => {
        const sm = room.scopeNoteStatus || {};
        const tl = (room.scopeNotes && room.scopeNotes.trim())
          ? room.scopeNotes.split('\n').map(l=>l.trim()).filter(Boolean).map((ln,i)=>({taskStatus:sm['scope_'+room.id+'_'+i]||'todo'}))
          : (_ganttShowExcluded ? (room.tasks||[]) : (room.tasks||[]).filter(t=>!t.excludeFromSchedule));
        const hasChildTasks = id => tl.some(x => x.parentTaskId === id);
        tl.forEach(t => {
          if (hasChildTasks(t.id)) return; // summary task -- children already counted, skip to avoid double-counting
          const w = taskWeight(t);
          _jobTotal += w;
          _jobDone += w * (getTaskPct(t) / 100);
        });
      });
    });
    const _jobPct = _jobTotal ? Math.round(_jobDone / _jobTotal * 100) : 0;
    const _jobPctColor = _jobPct===100 ? '#10b981' : _jobPct>0 ? '#60a5fa' : 'var(--muted)';
    const jobDays = workDaysBetween(job.startDate, job.endDate);

    rowsHtml += `<div data-master-row="job" data-job-id="${job.id}" class="gantt-left-row phase-row" style="min-height:${ROW_H}px;background:rgba(245,158,11,.06)" onclick="toggleMasterRow('job','${job.id}')">
      ${sixCols(
        `<span id="masterArrowJob_${job.id}" style="flex-shrink:0">${jobCollapsed?'▶':'▼'}</span><span class="gantt-task-name-text" style="color:var(--amber)" title="${esc(job.name)}">🏠 ${esc(job.name)}</span>${isOwner?`<button onclick="event.stopPropagation();clearMasterAllJobDates('${job.id}')" title="Clear ALL dates on this job -- job, every phase, room, and task" style="background:none;border:1px dashed rgba(248,113,113,.4);border-radius:4px;color:#f87171;cursor:pointer;font-size:.62rem;margin-left:8px;padding:0 5px;flex-shrink:0">🗑 Clear All</button><button onclick="event.stopPropagation();simplifySchedule('${job.id}')" title="Hides material/product tasks (tape, screws, fixtures) that don't represent progress. Keeps labor tasks visible and trackable, since those DO drive completion percent." style="background:none;border:1px dashed rgba(110,145,210,.4);border-radius:4px;color:var(--muted);cursor:pointer;font-size:.62rem;margin-left:4px;padding:0 5px;flex-shrink:0">📋 Simplify</button>`:''}`,
        jobDays !== null ? jobDays + 'd' : null,
        isOwner ? `<input type="date" value="${job.startDate||''}" onchange="updateMasterJobDate('${job.id}','startDate',this.value)">` : esc(job.startDate || '—'),
        isOwner ? `<input type="date" value="${job.endDate||''}" onchange="updateMasterJobDate('${job.id}','endDate',this.value)">` : esc(job.endDate || '—'),
        '', _jobPct, _jobPctColor
      )}
      ${rowBar(job.startDate, job.endDate, jobBarColor, 22, _jobPct, job.name)}
    </div>`;

    if (!jobCollapsed) {
      if (!phases.length) {
        rowsHtml += `<div class="gantt-left-row" style="min-height:28px">
          ${sixCols('<span style="padding-left:24px;font-style:italic;color:var(--muted)">No phases with dates set</span>', null, '—', '—', '', 0)}
          <div style="flex:1;min-width:${totalWidth}px"></div>
        </div>`;
      }
      phases.forEach(phase => {
        const phaseCollapsed = window._masterCollapsed[phase.id];
        const roomCount = (phase.features||[]).length;
        let phaseDone = 0, phaseTotal = 0;
        (phase.features||[]).forEach(room => {
          const sm = room.scopeNoteStatus||{};
          const tl = (room.scopeNotes&&room.scopeNotes.trim())
            ? room.scopeNotes.split('\n').map(l=>l.trim()).filter(Boolean).map((ln,i)=>({taskStatus:sm['scope_'+room.id+'_'+i]||'todo'}))
            : (_ganttShowExcluded ? (room.tasks||[]) : (room.tasks||[]).filter(t=>!t.excludeFromSchedule));
          const hasChildTasks2 = id => tl.some(x => x.parentTaskId === id);
          tl.forEach(t => {
            if (hasChildTasks2(t.id)) return; // summary task -- skip to avoid double-counting
            const w = taskWeight(t);
            phaseTotal += w;
            phaseDone += w * (getTaskPct(t) / 100);
          });
        });
        const phasePct = phaseTotal ? Math.round(phaseDone/phaseTotal*100) : 0;
        const phaseDays = workDaysBetween(phase.startDate, phase.endDate);

        rowsHtml += `<div data-master-row="phase" data-phase-id="${phase.id}" data-parent-job="${job.id}" class="gantt-left-row phase-row" draggable="${isOwner}" ondragstart="masterPhaseDragStart(event,'${job.id}','${phase.id}')" ondragover="masterPhaseDragOver(event)" ondragleave="masterPhaseDragLeave(event)" ondrop="masterPhaseDrop(event,'${job.id}','${phase.id}')" ondragend="masterPhaseDragEnd(event)" style="min-height:${PHASE_H}px" onclick="toggleMasterRow('phase','${phase.id}')">
          ${sixCols(
            `${isOwner?`<span class="gantt-drag-handle" title="Drag to reorder phases within this job" onclick="event.stopPropagation()">⠿</span>`:''}${roomCount?`<span id="masterArrowPhase_${phase.id}" style="flex-shrink:0">${phaseCollapsed?'▶':'▼'}</span>`:'<span style="width:10px;flex-shrink:0"></span>'}<span class="gantt-task-name-text" style="padding-left:14px;color:#93c5fd" title="${esc(phase.name)}">${esc(phase.name)}</span>`,
            phaseDays !== null ? phaseDays + 'd' : null,
            isOwner ? `<input type="date" value="${phase.startDate||''}" onchange="updateMasterPhaseDate('${job.id}','${phase.id}','startDate',this.value)">` : esc(phase.startDate || '—'),
            isOwner ? `<input type="date" value="${phase.endDate||''}" onchange="updateMasterPhaseDate('${job.id}','${phase.id}','endDate',this.value)">${(phase.startDate||phase.endDate)?`<button onclick="event.stopPropagation();clearMasterPhaseDate('${job.id}','${phase.id}')" title="Clear this phase's dates" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:.7rem;flex-shrink:0;padding:0">✕</button>`:''}` : esc(phase.endDate || '—'),
            '', phasePct, pctColor(phasePct)
          )}
          ${rowBar(phase.startDate, phase.endDate, 'background:linear-gradient(90deg,#1d4ed8,#3b82f6)', 16, phasePct, phase.name)}
        </div>`;

        if (!phaseCollapsed) {
          (phase.features||[]).forEach(room => {
            const roomCollapsed = window._masterCollapsed[room.id];
            const sm = room.scopeNoteStatus||{};
            const displayTasks = (room.scopeNotes&&room.scopeNotes.trim())
              ? room.scopeNotes.split('\n').map(l=>l.trim()).filter(Boolean).map((line,i)=>({id:'scope_'+room.id+'_'+i,name:line,taskStatus:sm['scope_'+room.id+'_'+i]||'todo'}))
              : getDisplayTasks(room, room.tasks||[]);
            let _roomW = 0, _roomDone = 0;
            const hasChildTasks3 = id => displayTasks.some(x => x.parentTaskId === id);
            displayTasks.forEach(t => { if (hasChildTasks3(t.id)) return; const w = taskWeight(t); _roomW += w; _roomDone += w * (getTaskPct(t) / 100); });
            const doneTasks = displayTasks.filter(t=>getTaskPct(t)===100).length;
            const pct = _roomW ? Math.round(_roomDone/_roomW*100) : 0;
            const roomColor = pct===100 ? 'background:#10b981'
              : room.endDate && new Date(room.endDate)<today ? 'background:#ef4444'
              : 'background:linear-gradient(90deg,#0d9488,#14b8a6)';
            const roomStartD = room.startDate || phase.startDate;
            const roomEndD = room.endDate || phase.endDate;
            const roomDays = workDaysBetween(roomStartD, roomEndD);

            rowsHtml += `<div data-master-row="room" data-room-id="${room.id}" data-parent-phase="${phase.id}" data-parent-job="${job.id}" class="gantt-left-row room-row" style="min-height:${PHASE_H}px;cursor:${displayTasks.length?'pointer':'default'}" ${displayTasks.length?`onclick="toggleMasterRow('room','${room.id}')"`:''}>
              ${sixCols(
                `${displayTasks.length?`<span id="masterArrowRoom_${room.id}" style="flex-shrink:0">${roomCollapsed?'▶':'▼'}</span>`:'<span style="width:8px;flex-shrink:0"></span>'}<span class="gantt-task-name-text" style="padding-left:24px;color:#94a3b8" title="${esc(room.name)}">${esc(customerSafeLabel({name: room.name, items: room.tasks}))}</span><span style="color:var(--muted);font-size:.62rem;flex-shrink:0">(${doneTasks}/${displayTasks.length})</span>`,
                isOwner ? `<input type="number" min="1" value="${room.durationDays || (roomDays!==null?roomDays:'')}" placeholder="—" onchange="updateMasterRoomDuration('${job.id}','${phase.id}','${room.id}',this.value)" title="Set duration directly -- clears any manual Start/Finish override and drives the schedule from here">` : (roomDays !== null ? roomDays + 'd' : '—'),
                isOwner ? `<input type="date" value="${room.startDate||''}" onchange="updateMasterRoomDate('${job.id}','${phase.id}','${room.id}','startDate',this.value)" title="${room.startDate?'Custom date':'Auto-scheduled from phase -- set a date here to override'}">` : esc(roomStartD || '—'),
                isOwner ? `<input type="date" value="${room.endDate||''}" onchange="updateMasterRoomDate('${job.id}','${phase.id}','${room.id}','endDate',this.value)" title="${room.endDate?'Custom date':'Auto-scheduled from phase -- set a date here to override'}">${(room.startDate||room.endDate)?`<button onclick="event.stopPropagation();clearMasterRoomDate('${job.id}','${phase.id}','${room.id}')" title="Clear override, go back to duration/dependency-based or auto-scheduling" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:.7rem;flex-shrink:0;padding:0">✕</button>`:''}` : esc(roomEndD || '—'),
                formatDependsOn(room.dependsOn), pct, pctColor(pct),
                isOwner ? `openMasterRoomScheduleModal('${job.id}','${phase.id}','${room.id}')` : '',
                isOwner ? 'Click to set dependencies' : ''
              )}
              ${rowBar(roomStartD, roomEndD, roomColor, 12, pct, room.name)}
            </div>`;

            if (!roomCollapsed) {
              const taskTree = buildTaskTree(displayTasks, true); // already filtered above; true = don't re-filter/prune here
              taskTree.forEach((rootNode, i) => {
                rowsHtml += renderMasterTaskNode(rootNode, 0, phase, room, job, isOwner, taskTree, i);
              });
            }
          });
        }
      });
    }
  });

  if (!activeJobs.length) {
    el.innerHTML = '<div class="small muted" style="padding:24px;font-style:italic">No active jobs found.</div>';
    return;
  }

  el.innerHTML = `
    <div style="height:100%;overflow:auto" id="masterPageScroll">
      <div style="display:flex;position:sticky;top:0;z-index:20;background:rgba(8,19,37,.97);border-bottom:2px solid rgba(110,145,210,.2)">
        <div style="width:${LEFT_W}px;flex-shrink:0;display:flex;align-items:center;height:32px">
          <div style="width:340px;flex-shrink:0;padding:0 10px;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.1)">TASK NAME</div>
          <div style="width:70px;flex-shrink:0;padding:0 4px;font-size:.7rem;font-weight:800;color:var(--muted);text-align:center;border-right:1px solid rgba(110,145,210,.1)">DAYS</div>
          <div style="width:125px;flex-shrink:0;padding:0 6px;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.1)">START</div>
          <div style="width:125px;flex-shrink:0;padding:0 6px;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.1)">FINISH</div>
          <div style="width:95px;flex-shrink:0;padding:0 6px;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.1)">DEPENDENCY</div>
          <div style="width:70px;flex-shrink:0;padding:0 4px;font-size:.7rem;font-weight:800;color:var(--muted);text-align:center">% DONE</div>
        </div>
        <div style="flex:1;min-width:${totalWidth}px;position:relative">
          ${monthHtml}
          <div style="position:absolute;left:${todayOffset}px;top:0;bottom:0;width:1px;background:rgba(239,68,68,.4);pointer-events:none"></div>
        </div>
      </div>
      <div style="position:relative">
        <div style="position:absolute;left:${LEFT_W+todayOffset}px;top:0;bottom:0;width:1px;background:rgba(239,68,68,.2);z-index:5;pointer-events:none"></div>
        ${rowsHtml}
      </div>
    </div>`;
}
window.renderMasterSchedulePage = renderMasterSchedulePage;

function masterGanttOpenJob(jobId) {
  // Exit fullscreen first if active
  const card = document.getElementById('homeMasterGanttCard');
  if (card && card.dataset.fullscreen === 'true') {
    toggleMasterGanttFullscreen();
  }
  // Small delay to let fullscreen exit animate, then open job on Schedule tab
  setTimeout(() => openJobDetail(jobId, 'schedule'), 150);
}
window.masterGanttOpenJob = masterGanttOpenJob;

function toggleMasterGanttFullscreen() {
  const card = document.getElementById('homeMasterGanttCard');
  const exitBtn = document.getElementById('masterGanttExitBtn');
  if (!card) return;

  const isFullscreen = card.dataset.fullscreen === 'true';
  if (isFullscreen) {
    card.dataset.fullscreen = 'false';
    card.style.cssText = 'margin-bottom:16px';
    if (exitBtn) exitBtn.style.display = 'none';
    document.body.style.overflow = '';
  } else {
    card.dataset.fullscreen = 'true';
    card.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;z-index:9999;height:100vh;border-radius:0;overflow:hidden;background:var(--bg);display:flex;flex-direction:column';
    if (exitBtn) exitBtn.style.display = 'block';
    document.body.style.overflow = 'hidden';
  }
  renderMasterGantt();
}
window.toggleMasterGanttFullscreen = toggleMasterGanttFullscreen;

function renderMasterGantt() {
  const el = document.getElementById('homeMasterGantt');
  const meta = document.getElementById('homeMasterGanttMeta');
  const card = document.getElementById('homeMasterGanttCard');
  if (!el) return;
  const isFullscreen = card?.dataset.fullscreen === 'true';

  const ACTIVE = ['Scheduled','In Progress','To Be Scheduled','Inspection Pending'];
  const allActive = conJobs.filter(j => ACTIVE.includes(j.status))
    .sort((a,b) => (a.startDate||'9999').localeCompare(b.startDate||'9999'));
  const jobs = allActive.filter(j => j.startDate && j.endDate);
  const undated = allActive.filter(j => !j.startDate || !j.endDate);

  if (!allActive.length) {
    el.innerHTML = '<div class="small muted" style="padding:16px;font-style:italic">No active jobs found.</div>';
    if (meta) meta.textContent = '';
    return;
  }

  if (meta) meta.textContent = allActive.length + ' active job' + (allActive.length !== 1 ? 's' : '') + (undated.length ? ` · ${undated.length} no dates` : '');

  // Date range
  const today = new Date(); today.setHours(0,0,0,0);
  const allDates = jobs.flatMap(j => [new Date(j.startDate), new Date(j.endDate)]);
  let minDate = new Date(Math.min(...allDates));
  let maxDate = new Date(Math.max(...allDates));
  minDate.setDate(minDate.getDate() - 3);
  maxDate.setDate(maxDate.getDate() + 7);

  const totalDays = Math.ceil((maxDate - minDate) / 86400000);
  const DAY_W = 28; // px per day
  const totalWidth = totalDays * DAY_W;
  const ROW_H = 40;
  const LABEL_W = 220;

  // Build month headers
  let monthHtml = `<div style="display:flex;margin-left:${LABEL_W}px;min-width:${totalWidth}px">`;
  let d = new Date(minDate);
  while (d <= maxDate) {
    const monthStart = new Date(d.getFullYear(), d.getMonth(), 1);
    const monthEnd = new Date(d.getFullYear(), d.getMonth() + 1, 0);
    const visStart = d < minDate ? minDate : d;
    const visEnd = monthEnd > maxDate ? maxDate : monthEnd;
    const days = Math.ceil((visEnd - visStart) / 86400000) + 1;
    const w = days * DAY_W;
    monthHtml += `<div style="width:${w}px;flex-shrink:0;font-size:.7rem;font-weight:800;color:var(--muted);border-right:1px solid rgba(110,145,210,.15);padding:3px 4px;white-space:nowrap;overflow:hidden">${d.toLocaleString('default',{month:'short'})} ${d.getFullYear()}</div>`;
    d = new Date(d.getFullYear(), d.getMonth() + 1, 1);
  }
  monthHtml += '</div>';

  // Today line offset
  const todayOffset = LABEL_W + Math.floor((today - minDate) / 86400000) * DAY_W;

  // Job rows
  let rowsHtml = '';
  jobs.forEach(job => {
    const s = new Date(job.startDate), e = new Date(job.endDate);
    const left = LABEL_W + Math.floor((s - minDate) / 86400000) * DAY_W;
    const width = Math.max(DAY_W, Math.ceil((e - s) / 86400000) * DAY_W);
    const isLate = e < today;
    const isActive = job.status === 'In Progress';
    const barColor = isLate
      ? 'background:linear-gradient(90deg,#991b1b,#ef4444)'
      : isActive
        ? 'background:linear-gradient(90deg,#065f46,#10b981)'
        : 'background:linear-gradient(90deg,#b45309,#d97706)';

    const days = Math.ceil((e - s) / 86400000);

    rowsHtml += `
      <div style="display:flex;align-items:center;border-bottom:1px solid rgba(110,145,210,.07);min-height:${ROW_H}px;cursor:pointer;transition:background .1s" 
           onclick="masterGanttOpenJob('${job.id}')" onmouseover="this.style.background='rgba(245,158,11,.05)'" onmouseout="this.style.background=''">
        <!-- Label -->
        <div style="width:${LABEL_W}px;flex-shrink:0;padding:6px 10px;font-size:.78rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-right:1px solid rgba(110,145,210,.1)">
          <div style="font-weight:700;color:#eaf0fb;overflow:hidden;text-overflow:ellipsis">${esc(job.name)}</div>
          <div style="font-size:.68rem;color:var(--muted)">${esc(job.status)} · ${days}d</div>
        </div>
        <!-- Bar row -->
        <div style="flex:1;min-width:${totalWidth}px;height:${ROW_H}px;position:relative">
          <div style="position:absolute;left:${left - LABEL_W}px;width:${width}px;height:22px;top:9px;${barColor};border-radius:4px;display:flex;align-items:center;overflow:hidden">
            ${width > 60 ? `<span style="font-size:.65rem;font-weight:700;color:#fff;padding:0 8px;white-space:nowrap;overflow:hidden;max-width:${width-16}px">${esc(job.name)}</span>` : ''}
          </div>
        </div>
      </div>`;
  });

  // Undated jobs — show as rows with no bar
  undated.forEach(job => {
    rowsHtml += `
      <div class="master-gantt-row" style="display:flex;align-items:center;border-bottom:1px solid rgba(110,145,210,.07);min-height:${ROW_H}px;cursor:pointer;opacity:.6;transition:background .1s"
           onclick="masterGanttOpenJob('${job.id}')" onmouseover="this.style.background='rgba(245,158,11,.05)'" onmouseout="this.style.background=''">
        <div style="width:${LABEL_W}px;flex-shrink:0;padding:6px 10px;font-size:.78rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border-right:1px solid rgba(110,145,210,.1)">
          <div style="font-weight:700;color:#eaf0fb;overflow:hidden;text-overflow:ellipsis">${esc(job.name)}</div>
          <div style="font-size:.68rem;color:var(--muted)">${esc(job.status)} · <span style="color:#f59e0b">No dates set</span></div>
        </div>
        <div style="flex:1;min-width:${totalWidth||600}px;height:${ROW_H}px;display:flex;align-items:center;padding-left:12px">
          <span style="font-size:.7rem;color:var(--muted);font-style:italic">Set start &amp; end dates to show on timeline</span>
        </div>
      </div>`;
  });

  el.innerHTML = `
    <div style="position:relative;overflow-x:auto">
      ${monthHtml}
      <div style="position:relative">
        <!-- Today line -->
        <div style="position:absolute;left:${todayOffset}px;top:0;bottom:0;width:1px;background:rgba(239,68,68,.35);z-index:10;pointer-events:none"></div>
        ${rowsHtml}
      </div>
    </div>`;
}
window.renderMasterGantt = renderMasterGantt;

// ── Field Technician simplified home (Time / My Job / Calendar /
// Messages / To-Do) -- replaces the full dashboard entirely for this
// role, per Travis: no left sidebar, just these as big tappable tiles.
function renderFieldTechHome() {
  const jobBox = document.getElementById('ftJobTileContent');
  if (!jobBox) return; // page not in the DOM yet

  const closedStatuses = ['Closed Completed', 'Closed Lost'];
  const myJobIds = getMyJobIds();
  const myJobs = conJobs.filter(j => myJobIds.has(j.id) && !closedStatuses.includes(j.status));

  if (!myJobs.length) {
    jobBox.innerHTML = `<div style="padding:14px 0;color:var(--muted);font-style:italic;text-align:center">No job assigned yet</div>`;
  } else if (myJobs.length === 1) {
    const j = myJobs[0];
    jobBox.innerHTML = `
      <div style="font-size:1.1rem;font-weight:800;margin-bottom:4px">${esc(j.name || 'Job')}</div>
      <div style="color:var(--muted);font-size:.85rem">${esc(j.address || '')}</div>
      <div style="margin-top:6px;font-size:.78rem;color:var(--amber);font-weight:700">${esc(j.status || '')}</div>`;
  } else {
    // More than one active assignment -- list them, each opens directly.
    jobBox.innerHTML = myJobs.map(j => `
      <div onclick="event.stopPropagation();openJobDetail('${j.id}')" style="padding:8px 0;border-bottom:1px solid var(--line);cursor:pointer">
        <div style="font-weight:700">${esc(j.name || 'Job')}</div>
        <div style="color:var(--muted);font-size:.78rem">${esc(j.status || '')}</div>
      </div>`).join('');
  }
  window._ftMyJobs = myJobs;
}

// The "My Job" tile itself -- opens directly into the single assigned
// job, or does nothing extra for 0/many (those cases already render
// their own clickable rows/empty state inside the tile via
// renderFieldTechHome() above).
function openMyFieldTechJob() {
  const jobs = window._ftMyJobs || [];
  if (jobs.length === 1) openJobDetail(jobs[0].id);
}
window.openMyFieldTechJob = openMyFieldTechJob;

function renderHomeDashboard() {
  const fullAccess = isOwnerOrAdmin();

  const toggle = (id, show) => { const el = document.getElementById(id); if (el) el.style.display = show ? '' : 'none'; };
  // homeRestrictedNotice banner removed per Travis -- the hidden tiles
  // below already make the restriction obvious without a callout.
  // Every one of these carries company-wide $ or pipeline data the
  // banner above explicitly promises a restricted role won't see.
  // Real bug found here: 'statMarginWrap' doesn't exist anywhere in the
  // HTML (the real id is statAvgMarginTile) -- getElementById() on a
  // nonexistent id returns null, and toggle()'s `if (el)` guard means
  // that silently did nothing, so Avg Margin was never actually hidden.
  // Five more tiles (Collected/Spent/Net MTD, Avg Job Value, Outstanding
  // Invoices) had NO hide call at all -- confirmed live on a real
  // Field Technician test account: the banner said financials weren't
  // shown while $28,459 Collected, $4,085 Spent, +$24,374 Net, 12.4%
  // Avg Margin, and $18,644 Avg Job Value were all fully visible right
  // underneath it.
  toggle('statContractWrap', fullAccess);
  toggle('statAvgMarginTile', fullAccess);
  toggle('statCollectedTile', fullAccess);
  toggle('statSpentTile', fullAccess);
  toggle('statNetTile', fullAccess);
  toggle('statAvgJobValTile', fullAccess);
  toggle('statOutstandingTile', fullAccess);
  // "Pipeline... data" is the banner's own wording -- Estimates Pending
  // and Close Rate are pipeline-stage metrics same as the Pipeline card
  // itself (homePipelineCard), which was already correctly gated.
  toggle('statEstPendingTile', fullAccess);
  toggle('statCloseRateTile', fullAccess);
  toggle('homePipelineCard', fullAccess);
  // "Labor Eff" tile referenced here (statLaborEffTile) doesn't exist
  // anywhere in the HTML -- harmless (nothing to leak since nothing
  // renders), but dead/orphaned code, removed rather than left sitting
  // here looking like it does something.
  toggle('homeInfoGrid', fullAccess);

  const myJobIds = fullAccess ? null : getMyJobIds();
  const closedStatuses = ['Closed Completed','Closed Lost'];

  // ── Active Jobs table with attention flags ──
  const tbody = document.getElementById('homeActiveJobsBody');
  if (tbody) {
    let active = conJobs.filter(j => !closedStatuses.includes(j.status));
    if (!fullAccess) active = active.filter(j => myJobIds.has(j.id));
    active = active.sort((a,b) => (a.statusDate||'').localeCompare(b.statusDate||''));

    if (!active.length) {
      tbody.innerHTML = `<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:20px;font-style:italic">${fullAccess ? 'No active jobs yet' : 'No jobs assigned to you yet'}</td></tr>`;
    } else {
      tbody.innerHTML = active.map(job => {
        const s = KYTRAC_STATUSES.find(x => x.name === job.status) || {color:'var(--amber)'};
        // Attention flags
        const flags = [];
        const daysSinceLog = job.lastLogDate
          ? Math.floor((Date.now() - new Date(job.lastLogDate)) / 86400000)
          : null;
        if (daysSinceLog === null || daysSinceLog > 2) flags.push({icon:'🟡', tip:'No daily logs in 2+ days'});
        const hasOverdueInvoice = (job.invoices||[]).some(inv =>
          inv.status !== 'Paid' && inv.dueDate && inv.dueDate < new Date().toISOString().split('T')[0]
        );
        if (hasOverdueInvoice) flags.push({icon:'🔴', tip:'Overdue invoice'});

        const flagHtml = flags.length
          ? flags.map(f => `<span title="${f.tip}" style="cursor:help">${f.icon}</span>`).join(' ')
          : '<span style="color:var(--muted);font-size:.7rem">✓</span>';

        return `<tr onclick="openJobDetail('${job.id}')" style="cursor:pointer">
          <td><div style="font-weight:700;font-size:.86rem">${esc(job.name)}</div><div style="font-size:.72rem;color:var(--amber)">${job.jobNumber||''}</div></td>
          <td style="font-size:.84rem">${esc(job.client||'—')}</td>
          <td><span style="background:${s.color}22;color:${s.color};padding:2px 8px;border-radius:999px;font-size:.72rem;font-weight:700;white-space:nowrap">${job.status}</span></td>
          <td style="font-size:.82rem;color:var(--muted)">${esc(job.superintendent || job.teamLead || '—')}</td>
          <td style="text-align:right;font-weight:700;color:#a3f2d2;font-size:.84rem">${fullAccess ? (getJobValue(job)?'$'+Math.round(getJobValue(job)).toLocaleString():'—') : '—'}</td>
          <td style="text-align:center">${flagHtml}</td>
        </tr>`;
      }).join('');
    }
  }

  if (!fullAccess) return;

  // ── Pipeline — horizontal strip (active stages only) ──
  const pipeline = document.getElementById('homePipelineSummary');
  if (pipeline) {
    const groups = [
      { label: 'Estimates', color: '#f97316', key: 'estimates', statuses: PIPELINE_BUCKETS.estimates },
      { label: 'Bidding',   color: '#d97706', key: 'bidding',   statuses: PIPELINE_BUCKETS.bidding },
      { label: 'Scheduled', color: '#0d9488', key: 'scheduled', statuses: PIPELINE_BUCKETS.scheduled },
      { label: 'Active',color:'#3b82f6', key: 'inprogress',statuses: PIPELINE_BUCKETS.inprogress },
      { label: 'Closing',   color: '#7c3aed', key: 'closing',   statuses: PIPELINE_BUCKETS.closing },
    ];
    pipeline.innerHTML = groups.map((g, i) => {
      const jobs = conJobs.filter(j => g.statuses.includes(j.status));
      return `<div style="padding:14px 16px;border-right:${i < groups.length-1 ? '1px solid rgba(110,145,210,.1)' : 'none'};text-align:center;flex:1">
        <div style="display:flex;align-items:center;justify-content:center;gap:6px;margin-bottom:6px">
          <div style="width:8px;height:8px;border-radius:50%;background:${g.color}"></div>
          <span style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em">${g.label}</span>
        </div>
        <div onclick="filterJobsToStage('${g.key}')"
          style="font-size:1.6rem;font-weight:900;color:${g.color};cursor:pointer;transition:opacity .15s"
          title="Click to view ${g.label} jobs"
          onmouseover="this.style.opacity='.7'" onmouseout="this.style.opacity='1'">${jobs.length}</div>
      </div>`;
    }).join('');
  }

  // ── Bottom panels ──
  renderWhatsChanged();
  renderCompanyLaborEfficiency();
  renderOffToday();
}
window.renderHomeDashboard = renderHomeDashboard;

// Pipeline click — filter Jobs page to selected stage group
function filterJobsToStage(key) {
  // Navigate to Jobs page — board shows all columns, user can see the stage
  ktNav('jobs', document.querySelector('.kt-nav-item:nth-child(5)'));
}
window.filterJobsToStage = filterJobsToStage;

// ── Off Today — show approved time off on dashboard ──
async function renderOffToday() {
  const card = document.getElementById('homeOffTodayCard');
  const el = document.getElementById('homeOffToday');
  if (!card || !el || !conDb) return;

  const today = new Date().toISOString().split('T')[0];
  card.style.display = 'block';

  try {
    // Try with status filter first, fall back to all if index missing
    let snap;
    try {
      snap = await coll('timeOffRequests').where('status','==','approved').get();
    } catch(e) {
      snap = await coll('timeOffRequests').get();
    }

    const offToday = [];
    snap.forEach(d => {
      const r = d.data();
      if ((r.status || '').toLowerCase() === 'approved' &&
          r.startDate <= today && r.endDate >= today) {
        offToday.push(r);
      }
    });

    if (!offToday.length) {
      el.innerHTML = '<div style="color:#1dbb87;font-weight:700;font-size:.88rem">✅ Fully Staffed</div>';
      return;
    }

    el.innerHTML = offToday.map(r => `
      <div style="background:rgba(139,92,246,.12);border:1px solid rgba(139,92,246,.3);border-radius:8px;padding:6px 12px;font-size:.82rem">
        <span style="font-weight:700;color:#a78bfa">${esc(r.requestedByName || r.requestedBy)}</span>
        <span style="color:var(--muted);margin-left:6px">${esc(r.type)}</span>
        ${r.startDate !== r.endDate ? `<span style="color:var(--muted);font-size:.72rem;margin-left:6px">→ ${r.endDate}</span>` : ''}
      </div>`).join('');
  } catch(e) {
    el.innerHTML = '<div style="color:#1dbb87;font-weight:700;font-size:.88rem">✅ Fully Staffed</div>';
  }
}
window.renderOffToday = renderOffToday;

// ── TODAY'S ACTIVITY ──
function renderNeedsAttention() {
  const el = document.getElementById('homeNeedsAttention');
  if (!el) return;
  const today = new Date().toISOString().split('T')[0];
  const items = [];

  conJobs.forEach(job => {
    // Complete jobs needing attention (invoice follow-up handled by SLA triggers)
    if (job.status === 'Inspection Pending') {
      items.push({ color:'#2563eb', icon:'🔍', text: job.name, sub: 'Inspection pending', jobId: job.id });
    }
    // Jobs with no logs in 3+ days (active jobs only)
    const activeStatuses = ACTIVE_STATUSES;
    if (activeStatuses.includes(job.status)) {
      const lastLog = job.lastLogDate || '';
      if (!lastLog) {
        items.push({ color:'#f97316', icon:'📋', text: job.name, sub: 'No daily logs yet', jobId: job.id });
      } else {
        const daysSince = Math.floor((new Date() - new Date(lastLog)) / 86400000);
        if (daysSince >= 3) {
          items.push({ color:'#f97316', icon:'📋', text: job.name, sub: `No log in ${daysSince} days`, jobId: job.id });
        }
      }
    }
  });

  if (!items.length) {
    el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">✅ All jobs on track</div>';
    return;
  }

  el.innerHTML = items.map(i => `
    <div onclick="openJobDetail('${i.jobId}')" style="display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
      <span style="font-size:1rem;flex-shrink:0">${i.icon}</span>
      <div>
        <div style="font-size:.84rem;font-weight:700;color:#eaf0fb">${esc(i.text)}</div>
        <div style="font-size:.74rem;color:${i.color};margin-top:1px">${i.sub}</div>
      </div>
    </div>
  `).join('');
}

function renderRecentLogs() {
  const el = document.getElementById('homeRecentLogs');
  if (!el || !conDb) return;
  
  // Try collectionGroup first (requires index), fall back to per-job fetch
  conDb.collectionGroup('logs').where('companyId','==',currentCompanyId)
    .orderBy('date', 'desc')
    .limit(8)
    .get()
    .then(snap => {
      if (snap.empty) {
        el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No daily logs yet</div>';
        return;
      }
      el.innerHTML = snap.docs.map(doc => {
        const log = doc.data();
        const jobId = doc.ref.parent.parent.id;
        const job = conJobs.find(j => j.id === jobId);
        return `<div onclick="openJobDetail('${jobId}')" style="padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">
            <div style="font-size:.82rem;font-weight:700;color:var(--amber)">${esc(job ? job.name : 'Unknown Job')}</div>
            <div style="font-size:.7rem;color:var(--muted)">${log.date||''}</div>
          </div>
          <div style="font-size:.78rem;color:#eaf0fb;line-height:1.4">${esc((log.notes||'').slice(0,80))}${(log.notes||'').length>80?'…':''}</div>
          ${log.crew?`<div style="font-size:.7rem;color:var(--muted);margin-top:2px">👷 ${esc(log.crew)}</div>`:''}
          ${log.issues?`<div style="font-size:.72rem;color:#ef5350;margin-top:2px">⚠️ ${esc(log.issues.slice(0,60))}</div>`:''}
        </div>`;
      }).join('');
    })
    .catch(() => {
      // collectionGroup index not created yet — fall back to fetching logs per job
      if (!conJobs.length) {
        el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No daily logs yet</div>';
        return;
      }
      el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">Loading logs...</div>';
      const allLogs = [];
      let pending = conJobs.length;
      conJobs.forEach(job => {
        coll('jobs').doc(job.id).collection('logs')
          .orderBy('date','desc').limit(3).get()
          .then(snap => {
            snap.forEach(doc => allLogs.push({ ...doc.data(), jobId: job.id, jobName: job.name }));
          })
          .catch(() => {})
          .finally(() => {
            pending--;
            if (pending === 0) {
              allLogs.sort((a,b) => (b.date||'').localeCompare(a.date||''));
              const recent = allLogs.slice(0,8);
              if (!recent.length) {
                el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No daily logs yet</div>';
                return;
              }
              el.innerHTML = recent.map(log => `
                <div onclick="openJobDetail('${log.jobId}')" style="padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
                  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">
                    <div style="font-size:.82rem;font-weight:700;color:var(--amber)">${esc(log.jobName||'')}</div>
                    <div style="font-size:.7rem;color:var(--muted)">${log.date||''}</div>
                  </div>
                  <div style="font-size:.78rem;color:#eaf0fb;line-height:1.4">${esc((log.notes||'').slice(0,80))}${(log.notes||'').length>80?'…':''}</div>
                  ${log.crew?`<div style="font-size:.7rem;color:var(--muted);margin-top:2px">👷 ${esc(log.crew)}</div>`:''}
                  ${log.issues?`<div style="font-size:.72rem;color:#ef5350;margin-top:2px">⚠️ ${esc(log.issues.slice(0,60))}</div>`:''}
                </div>`).join('');
            }
          });
      });
    });
}

function renderUpcomingPhases() {
  const el = document.getElementById('homeUpcomingPhases');
  if (!el || !conDb) return;
  const today = new Date().toISOString().split('T')[0];
  const in7 = new Date(Date.now() + 7*86400000).toISOString().split('T')[0];

  // Query Sprints across all jobs starting in next 7 days — Sprints are the
  // date-bearing entity in the current Epic/Feature/Task model (Features
  // themselves don't carry dates, only their assigned Sprint does).
  conDb.collectionGroup('sprints').where('companyId','==',currentCompanyId)
    .orderBy('startDate')
    .startAt(today)
    .endAt(in7)
    .limit(10)
    .get()
    .then(snap => {
      if (snap.empty) {
        el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No sprints in the next 7 days</div>';
        return;
      }
      el.innerHTML = snap.docs.map(doc => {
        const sprint = doc.data();
        const jobId = doc.ref.parent.parent.id;
        const job = conJobs.find(j => j.id === jobId);
        const statusColors = { 'planned':'var(--muted)', 'active':'var(--amber)', 'complete':'#1dbb87' };
        const col = statusColors[sprint.status] || 'var(--muted)';
        const isToday = sprint.startDate === today;
        return `<div onclick="openJobDetail('${jobId}')" style="padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">
            <div style="font-size:.82rem;font-weight:700;color:#eaf0fb">${esc(sprint.name||'Sprint')}</div>
            <div style="font-size:.7rem;font-weight:700;color:${isToday?'var(--amber)':'var(--muted)'}">${isToday?'TODAY':sprint.startDate||''}</div>
          </div>
          <div style="font-size:.74rem;color:var(--amber);margin-bottom:2px">${esc(job ? job.name : '')}</div>
          <div style="display:flex;align-items:center;gap:6px">
            <div style="width:7px;height:7px;border-radius:50%;background:${col}"></div>
            <span style="font-size:.7rem;color:${col}">${sprint.status||'planned'}</span>
          </div>
        </div>`;
      }).join('');
    })
    .catch(() => {
      // collectionGroup index not ready — fall back to per-job fetch
      if (!conJobs.length) { el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No upcoming sprints yet</div>'; return; }
      const allSprints = [];
      let pending = conJobs.length;
      conJobs.forEach(job => {
        coll('jobs').doc(job.id).collection('sprints')
          .where('startDate','>=',today).where('startDate','<=',in7).get()
          .then(snap => { snap.forEach(doc => allSprints.push({ ...doc.data(), jobId: job.id, jobName: job.name })); })
          .catch(() => {})
          .finally(() => {
            pending--;
            if (pending === 0) {
              allSprints.sort((a,b) => (a.startDate||'').localeCompare(b.startDate||''));
              if (!allSprints.length) { el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No sprints in the next 7 days</div>'; return; }
              const statusColors = { 'planned':'var(--muted)', 'active':'var(--amber)', 'complete':'#1dbb87' };
              el.innerHTML = allSprints.map(sprint => {
                const col = statusColors[sprint.status] || 'var(--muted)';
                const isToday = sprint.startDate === today;
                return `<div onclick="openJobDetail('${sprint.jobId}')" style="padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
                  <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px">
                    <div style="font-size:.82rem;font-weight:700;color:#eaf0fb">${esc(sprint.name||'Sprint')}</div>
                    <div style="font-size:.7rem;font-weight:700;color:${isToday?'var(--amber)':'var(--muted)'}">${isToday?'TODAY':sprint.startDate||''}</div>
                  </div>
                  <div style="font-size:.74rem;color:var(--amber)">${esc(sprint.jobName||'')}</div>
                </div>`;
              }).join('');
            }
          });
      });
    });
}

// ── WHAT'S CHANGED TODAY ──
// A small, curated "what happened today" glance — new customer messages and
// new document uploads across all jobs. Deliberately NOT a full activity
// firehose (that's what the per-job Activity tab is for) — just today's
// two categories Needs Attention doesn't already surface.
// ── Company Labor Efficiency (Weekly Scorecard number) ──
// Rolls up estimated-vs-actual labor hours across every active job. This is
// the company-wide version of the per-job Labor Hours section in Reports —
// if this trends consistently under 100%, estimates may be padded too high;
// consistently over 100% means bids may need to go up. Feed the resulting
// percentage into your KYTHROS Weekly Metrics manually each week — JOBSMETRIX
// and KYTHROS aren't linked yet (KYTHROS is still local-only, pre-SaaS-rebuild).
async function renderCompanyLaborEfficiency() {
  const el = document.getElementById('homeLaborEfficiency');
  const tileVal = document.getElementById('statLaborEffVal');
  if (!conDb) return;
  const closedStatuses = ['Closed Completed','Closed Lost'];
  const activeJobs = conJobs.filter(j => !closedStatuses.includes(j.status));

  if (!activeJobs.length) {
    if (tileVal) tileVal.textContent = '—';
    if (el) el.innerHTML = '<div class="small muted" style="font-style:italic">No active jobs yet</div>';
    return;
  }

  try {
    const results = await Promise.all(activeJobs.map(j => computeJobLaborHours(j.id).then(r => ({ ...r, job: j }))));
    let totalEst = 0, totalAct = 0;
    const perJob = results.filter(r => r.estHours > 0);
    perJob.forEach(r => { totalEst += r.estHours; totalAct += r.actHours; });

    if (!totalEst) {
      if (tileVal) tileVal.textContent = '—';
      if (el) el.innerHTML = '<div class="small muted" style="font-style:italic">No labor hours estimated yet</div>';
      return;
    }

    const pctUsed = totalAct / totalEst * 100;
    const health = laborHoursHealth(totalEst, totalAct);

    // Update KPI tile
    if (tileVal) {
      tileVal.textContent = pctUsed.toFixed(1) + '%';
      tileVal.style.color = health.color;
    }
    const tileEl = document.getElementById('statLaborEffTile');
    if (tileEl) tileEl.title = `${totalAct.toFixed(1)}h logged of ${totalEst.toFixed(1)}h estimated — ${health.label}`;

    const hot = perJob.filter(r => (r.actHours / r.estHours) > 1.15)
      .sort((a,b) => (b.actHours/b.estHours) - (a.actHours/a.estHours)).slice(0,3);

    if (el) el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="font-size:1.6rem;font-weight:900;color:${health.color}">${pctUsed.toFixed(1)}%</div>
        <span style="background:${health.color}22;color:${health.color};padding:3px 12px;border-radius:999px;font-size:.76rem;font-weight:700">${health.label}</span>
      </div>
      <div style="font-size:.8rem;color:var(--muted);margin-bottom:10px">${totalAct.toFixed(1)}h logged of ${totalEst.toFixed(1)}h estimated across ${perJob.length} active job${perJob.length!==1?'s':''}</div>
      <div style="height:10px;background:rgba(110,145,210,.12);border-radius:6px;overflow:clip;margin-bottom:${hot.length?'12px':'0'}">
        <div style="height:100%;width:${Math.min(pctUsed,100)}%;background:${health.color}"></div>
      </div>
      ${hot.length ? '<div style="font-size:.74rem;color:var(--muted);margin-bottom:4px">Running hottest:</div>' + hot.map(r =>
        `<div style="font-size:.78rem;display:flex;justify-content:space-between;padding:3px 0"><span>${esc(r.job.name)}</span><span style="color:#ef5350;font-weight:700">${(r.actHours/r.estHours*100).toFixed(0)}%</span></div>`
      ).join('') : ''}
    `;
  } catch (e) {
    if (tileVal) tileVal.textContent = '—';
    if (el) el.innerHTML = '<div class="small muted" style="font-style:italic">Could not compute labor efficiency</div>';
  }
}

// Comprehensive Activity Feed - the real ask behind "our dashboard doesn't
// have a running items list". Pulls from every real event type across
// every job (messages, documents, daily logs, status changes) via
// collectionGroup queries, same pattern already proven out for messages/
// documents above. Unlike the old "What's Changed Today" panel, this is
// NOT limited to today - it's a genuine scrollable history, grouped by
// date, matching what JobTread's Activity tab already does.
function renderActivityFeed(targetElId, itemCap) {
  targetElId = targetElId || 'homeWhatsChanged';
  itemCap = itemCap || 60;
  const el = document.getElementById(targetElId);
  if (!el || !conDb) return;

  const items = [];
  let pending = 3;
  const finish = () => {
    pending--;
    if (pending > 0) return;
    if (!items.length) { el.innerHTML = '<div class="small muted" style="font-style:italic;padding:10px 0;text-align:center">No activity yet</div>'; return; }
    items.sort((a,b) => (b.ms||0) - (a.ms||0));
    const top = items.slice(0, itemCap);

    // Group by date for JobTread-style date headers
    const groups = [];
    let lastDateKey = null;
    top.forEach(i => {
      const d = i.ms ? new Date(i.ms) : null;
      const dateKey = d ? d.toISOString().split('T')[0] : 'unknown';
      const todayKey = new Date().toISOString().split('T')[0];
      const yestKey = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      const label = dateKey === todayKey ? 'Today' : dateKey === yestKey ? 'Yesterday' :
        (d ? d.toLocaleDateString('en-US', { weekday:'long', month:'short', day:'numeric' }) : '');
      if (dateKey !== lastDateKey) { groups.push({ label, rows: [] }); lastDateKey = dateKey; }
      groups[groups.length-1].rows.push(i);
    });

    el.innerHTML = groups.map(g =>
      '<div style="font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--amber);margin:10px 0 4px">' + esc(g.label) + '</div>' +
      g.rows.map(i => `
        <div onclick="${i.docId ? `openDocument('${i.docId}')` : `openJobDetail('${i.jobId}')`}" style="display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer">
          <span style="font-size:1rem;flex-shrink:0">${i.icon}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:.83rem;font-weight:700;color:#eaf0fb;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(i.text)}</div>
            <div style="font-size:.74rem;color:var(--amber)">${esc(i.sub)}</div>
          </div>
        </div>`).join('')
    ).join('');
  };

  // Messages, business-wide via collectionGroup (falls back to per-job if index/companyId isn't ready)
  conDb.collectionGroup('messages').where('companyId','==',currentCompanyId)
    .orderBy('createdMs','desc').limit(itemCap).get()
    .then(snap => {
      snap.forEach(doc => {
        const m = doc.data();
        const jobId = doc.ref.parent.parent.id;
        const job = conJobs.find(j => j.id === jobId);
        items.push({ icon:'💬', text: (m.authorName||'Someone') + ': ' + (m.text||''), sub: job ? job.name : '', jobId, ms: m.createdMs||0 });
      });
      finish();
    })
    .catch(() => {
      if (!conJobs.length) { finish(); return; }
      let jp = conJobs.length;
      conJobs.forEach(job => {
        coll('jobs').doc(job.id).collection('messages').orderBy('createdMs','desc').limit(10).get()
          .then(snap => snap.forEach(doc => {
            const m = doc.data();
            items.push({ icon:'💬', text: (m.authorName||'Someone') + ': ' + (m.text||''), sub: job.name, jobId: job.id, ms: m.createdMs||0 });
          }))
          .catch(() => {})
          .finally(() => { jp--; if (jp === 0) finish(); });
      });
    });

  // Documents uploaded, business-wide
  conDb.collectionGroup('documents').where('companyId','==',currentCompanyId)
    .orderBy('uploadedAt','desc').limit(itemCap).get()
    .then(snap => {
      snap.forEach(doc => {
        const d = doc.data();
        const jobId = doc.ref.parent.parent.id;
        const job = conJobs.find(j => j.id === jobId);
        const ms = d.uploadedAt?.toDate ? d.uploadedAt.toDate().getTime() : 0;
        items.push({ icon:'📎', text: d.name||'Document uploaded', sub: job ? job.name : '', jobId, ms });
      });
      finish();
    })
    .catch(() => {
      if (!conJobs.length) { finish(); return; }
      let jp = conJobs.length;
      conJobs.forEach(job => {
        coll('jobs').doc(job.id).collection('documents').orderBy('uploadedAt','desc').limit(10).get()
          .then(snap => snap.forEach(doc => {
            const d = doc.data();
            const ms = d.uploadedAt?.toDate ? d.uploadedAt.toDate().getTime() : 0;
            items.push({ icon:'📎', text: d.name||'Document uploaded', sub: job.name, jobId: job.id, ms });
          }))
          .catch(() => {})
          .finally(() => { jp--; if (jp === 0) finish(); });
      });
    });

  // Daily logs + status changes, business-wide (share the same 'logs' subcollection)
  conDb.collectionGroup('logs').where('companyId','==',currentCompanyId)
    .orderBy('createdAt','desc').limit(itemCap).get()
    .then(snap => {
      snap.forEach(doc => {
        const l = doc.data();
        const jobId = doc.ref.parent.parent.id;
        const job = conJobs.find(j => j.id === jobId);
        const ms = l.createdAt?.toDate ? l.createdAt.toDate().getTime() : 0;
        if (l.type === 'status_change') {
          items.push({ icon: l.toStatus === 'Closed Lost' ? '🔴' : '🔄', text: l.notes || 'Status changed', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'proposal_emailed') {
          items.push({ icon: '📧', text: l.notes || 'Proposal emailed to customer', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'proposal_viewed') {
          items.push({ icon: '👁', text: 'Customer opened proposal in portal', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'proposal_signed') {
          items.push({ icon: '📎', text: l.notes || 'Customer signed proposal', sub: job ? job.name : '', jobId, ms, docId: l.docId || null });
        } else if (l.type === 'invoice_created') {
          items.push({ icon: '🧾', text: l.notes || 'Invoice created', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'invoice_emailed') {
          items.push({ icon: '📧', text: l.notes || 'Invoice emailed to customer', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'invoice_paid') {
          items.push({ icon: '💰', text: l.notes || 'Invoice paid', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'materials_purchase') {
          items.push({ icon: '🧱', text: l.notes || 'Materials purchase logged', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'subcontractor_payment') {
          items.push({ icon: '💼', text: l.notes || 'Subcontractor payment logged', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'vendor_bill') {
          items.push({ icon: '👷', text: l.notes || 'Vendor bill added', sub: job ? job.name : '', jobId, ms });
        } else if (l.type === 'photos_uploaded') {
          items.push({ icon: '📸', text: l.notes || 'Photos uploaded', sub: job ? job.name : '', jobId, ms });
        } else {
          items.push({ icon:'📋', text: l.notes ? (l.notes.length > 60 ? l.notes.slice(0,60)+'…' : l.notes) : 'Daily log added', sub: job ? job.name : '', jobId, ms });
        }
      });
      finish();
    })
    .catch(() => {
      if (!conJobs.length) { finish(); return; }
      let jp = conJobs.length;
      conJobs.forEach(job => {
        coll('jobs').doc(job.id).collection('logs').orderBy('createdAt','desc').limit(10).get()
          .then(snap => snap.forEach(doc => {
            const l = doc.data();
            const ms = l.createdAt?.toDate ? l.createdAt.toDate().getTime() : 0;
            if (l.type === 'status_change') {
              items.push({ icon: l.toStatus === 'Closed Lost' ? '🔴' : '🔄', text: l.notes || 'Status changed', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'proposal_emailed') {
              items.push({ icon: '📧', text: l.notes || 'Proposal emailed to customer', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'proposal_viewed') {
              items.push({ icon: '👁', text: 'Customer opened proposal in portal', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'proposal_signed') {
              items.push({ icon: '📎', text: l.notes || 'Customer signed proposal', sub: job.name, jobId: job.id, ms, docId: l.docId || null });
            } else if (l.type === 'invoice_created') {
              items.push({ icon: '🧾', text: l.notes || 'Invoice created', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'invoice_emailed') {
              items.push({ icon: '📧', text: l.notes || 'Invoice emailed to customer', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'invoice_paid') {
              items.push({ icon: '💰', text: l.notes || 'Invoice paid', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'materials_purchase') {
              items.push({ icon: '🧱', text: l.notes || 'Materials purchase logged', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'subcontractor_payment') {
              items.push({ icon: '💼', text: l.notes || 'Subcontractor payment logged', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'vendor_bill') {
              items.push({ icon: '👷', text: l.notes || 'Vendor bill added', sub: job.name, jobId: job.id, ms });
            } else if (l.type === 'photos_uploaded') {
              items.push({ icon: '📸', text: l.notes || 'Photos uploaded', sub: job.name, jobId: job.id, ms });
            } else {
              items.push({ icon:'📋', text: l.notes ? (l.notes.length > 60 ? l.notes.slice(0,60)+'…' : l.notes) : 'Daily log added', sub: job.name, jobId: job.id, ms });
            }
          }))
          .catch(() => {})
          .finally(() => { jp--; if (jp === 0) finish(); });
      });
    });
}
