window.mpToggleCheckFields = mpToggleCheckFields;

async function commitMarkPaid(jobId, invId, total) {
  const method = document.getElementById('mpMethod')?.value || 'Other';
  const payment = { paymentMethod: method };
  if (method === 'Check') {
    payment.checkNumber = document.getElementById('mpCheckNum')?.value.trim() || '';
    payment.checkDate = document.getElementById('mpCheckDate')?.value || '';
    payment.checkMemo = document.getElementById('mpCheckMemo')?.value.trim() || '';
  }
  document.getElementById('markPaidModal')?.remove();

  try {
    // 0. Read the invoice first so we know if it's tied to a Change Order.
    const invSnap = await coll('jobs').doc(jobId).collection('invoices').doc(invId).get();
    const invData = invSnap.exists ? invSnap.data() : {};
    const linkedCOId = invData.changeOrderId || null;

    // 1. Mark the invoice paid, recording how it was paid.
    await coll('jobs').doc(jobId).collection('invoices').doc(invId).update({
      status: 'Paid',
      amtPaid: total,
      paidDate: new Date().toISOString().split('T')[0],
      ...payment,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    });

    // 1b. Log to Activity.
    const paidAmt = (total || 0).toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
    let paidNote = `Invoice ${invData.number || ''} paid — $${paidAmt} (${method})`.replace('  ', ' ');
    if (method === 'Check' && payment.checkNumber) paidNote += ` #${payment.checkNumber}`;
    logInvoiceActivity(jobId, 'invoice_paid', paidNote.trim());

    const job = conJobs.find(j => j.id === jobId);

    // 1c-early. Show the bucket breakdown immediately -- right at the
    // moment of confirming payment, not a separate step to remember
    // later. Fires before the rest of this function's slower work
    // (subcontractor to-dos, estimate-tree flagging, CO line-item
    // application) so it doesn't wait behind any of that.
    if (job && total > 0) showPaymentBucketBreakdown(job, total);

    // 1c. For every subcontractor payment logged on this job that isn't
    // marked Paid yet, create a To-Do ("Pay Domingo Handyman LLC...")
    // and push a PlannerXD notification, same as the proposal-signed
    // flow — always logs its outcome to Activity (sent/skipped/failed)
    // rather than swallowing errors, since a silent failure here was
    // exactly what made the original signature bridge undiagnosable.
    // Deliberately fires on ANY invoice paid, not just a "final" one —
    // it only actually does anything if unpaid sub payments already
    // exist on the job, so a deposit invoice with no sub work logged
    // yet is a harmless no-op.
    try {
      const subPaySnap = await coll('jobs').doc(jobId).collection('subcontractorPayments').get();
      const unpaidDocs = [];
      subPaySnap.forEach(d => { if ((d.data().status || 'Agreed') !== 'Paid') unpaidDocs.push(d); });
      if (unpaidDocs.length) {
        const jobLabel = (job && (job.address || job.name)) || 'Job';
        const todoWrites = [];
        unpaidDocs.forEach(d => {
          const p = d.data();
          const amtStr = (p.amount || 0).toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
          todoWrites.push(coll('todos').add({
            text: `Pay ${p.subName || 'subcontractor'} — $${amtStr}${p.desc ? ' (' + p.desc + ')' : ''} — ${jobLabel}`,
            priority: 'high',
            dueDate: '',
            jobId,
            jobName: jobLabel,
            assignee: '',
            assigneeName: '',
            done: false,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdBy: conCurrentUser?.email || '',
            createdByName: conCurrentUser?.displayName || conCurrentUser?.email || '',
            source: 'invoice_paid_sub_owed'
          }));
        });
        await Promise.all(todoWrites);
        logInvoiceActivity(jobId, 'todo_created', `${unpaidDocs.length} subcontractor payment to-do(s) created — invoice paid.`);

        const settDoc = await coll('settings').doc('company').get();
        const ownerUid = settDoc.exists ? settDoc.data().ownerUid : null;
        if (!ownerUid) {
          logInvoiceActivity(jobId, 'plannerxd_push_skipped', 'PlannerXD notification skipped — no ownerUid set on company settings.');
        } else {
          const subNames = unpaidDocs.map(d => d.data().subName || 'subcontractor');
          try {
            await conDb.collection('plannerxd_notifications').doc(ownerUid).collection('items').add({
              type: 'sub_payment_owed',
              title: 'Pay Subcontractor(s) — ' + jobLabel,
              body: 'Invoice paid. Subcontractor(s) owed: ' + subNames.join(', '),
              jobId, companyId: currentCompanyId, actionLabel: 'Open Job',
              createdAt: firebase.firestore.FieldValue.serverTimestamp(),
              createdMs: Date.now(), read: false
            });
            logInvoiceActivity(jobId, 'plannerxd_push_sent', 'PlannerXD notified — subcontractor payment owed.');
          } catch (pushErr) {
            logInvoiceActivity(jobId, 'plannerxd_push_failed', 'PlannerXD notification failed: ' + pushErr.message);
          }
        }
      }
    } catch (subErr) {
      logInvoiceActivity(jobId, 'sub_payment_todo_failed', 'Could not check/create subcontractor payment to-do: ' + subErr.message);
    }

    // 2. Auto-advance job status to To Be Scheduled (Approved was removed
    // as a distinct stage), but only if it hasn't already progressed
    // further in the pipeline (never move a job backwards).
    const approvedIdx = CON_JOB_STATUSES.indexOf('To Be Scheduled');
    const currentIdx = job ? CON_JOB_STATUSES.indexOf(job.status) : -1;
    if (job && (currentIdx === -1 || currentIdx < approvedIdx)) {
      if (conCurrentJobId === jobId && typeof commitJobStatusChange === 'function') {
        commitJobStatusChange('To Be Scheduled');
      } else {
        await coll('jobs').doc(jobId).update({
          status: 'To Be Scheduled',
          statusDate: new Date().toISOString().split('T')[0],
          updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
      }
    }

    // 3. Flag this job's estimate tree as board-ready: every Epic gets
    // sprintEnabled, every Feature/Task gets a default status if it doesn't
    // already have one. Never overwrite an existing value.
    const groupsSnap = await coll('jobs').doc(jobId).collection('estimateGroups').get();
    const writes = [];
    for (const groupDoc of groupsSnap.docs) {
      const groupData = groupDoc.data();
      if (!groupData.sprintEnabled) {
        writes.push(groupDoc.ref.update({ sprintEnabled: true }));
      }
      const subSnap = await coll('jobs').doc(jobId).collection('estimateGroups')
        .doc(groupDoc.id).collection('subgroups').get();
      for (const subDoc of subSnap.docs) {
        const subData = subDoc.data();
        if (!subData.status) {
          writes.push(subDoc.ref.update({ status: 'not-started' }));
        }
        const itemSnap = await coll('jobs').doc(jobId).collection('estimateGroups')
          .doc(groupDoc.id).collection('subgroups').doc(subDoc.id).collection('items').get();
        for (const itemDoc of itemSnap.docs) {
          const itemData = itemDoc.data();
          if (!itemData.taskStatus) {
            writes.push(itemDoc.ref.update({ taskStatus: 'todo' }));
          }
        }
      }
    }
    await Promise.all(writes);

    // 3b. If this invoice was for an approved Change Order, push its line
    // items into a brand new estimate group — its own Epic, which means its
    // own fresh page the next time the Punch List gets printed.
    if (linkedCOId) {
      const coSnap = await coll('jobs').doc(jobId).collection('changeorders').doc(linkedCOId).get();
      if (coSnap.exists) {
        const co = coSnap.data();
        if (!co.appliedToEstimate) {
          const groupRef = await coll('jobs').doc(jobId).collection('estimateGroups').add({
            name: 'CO: ' + (co.title || 'Change Order'),
            order: groupsSnap.size,
            sprintEnabled: true,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
          });
          const subRef = await coll('jobs').doc(jobId).collection('estimateGroups')
            .doc(groupRef.id).collection('subgroups').add({
              name: co.title || 'Change Order Work',
              order: 0,
              status: 'not-started',
              createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
          const coItemWrites = (co.lineItems || []).map((li, i) =>
            coll('jobs').doc(jobId).collection('estimateGroups').doc(groupRef.id)
              .collection('subgroups').doc(subRef.id).collection('items').add({
                desc: li.desc || '',
                qty: li.qty || 1,
                unit: li.unit || 'ea',
                costType: li.costType || 'Materials',
                unitCost: li.unitCost || 0,
                unitPrice: li.unitPrice || 0,
                markup: li.unitCost > 0 ? Math.round((li.unitPrice / li.unitCost - 1) * 100) : 0,
                taskStatus: 'todo',
                order: i,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
              })
          );
          await Promise.all(coItemWrites);

          await coll('jobs').doc(jobId).collection('changeorders').doc(linkedCOId).update({
            status: 'Paid',
            appliedToEstimate: true,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
          });

          if (conCurrentJobId === jobId && typeof loadEstimate === 'function') loadEstimate(jobId);
        }
      }
    }

    // 4. Jump straight to the Kanban Board / Schedule tab, ready to schedule
    if (conCurrentJobId === jobId) {
      const scheduleBtn = document.querySelector('#jobDetailModal .con-subtab[onclick*="phases"]');
      if (scheduleBtn) scheduleBtn.click();
    }
  } catch (e) {
    alert('Error marking invoice paid: ' + e.message);
  }
}
window.quickMarkPaid = quickMarkPaid;
window.commitMarkPaid = commitMarkPaid;

// ── Print Invoice ──
function printInvoiceById(jobId, invId) {
  if (!conDb) return;
  // Same mobile popup-blocker fix as viewInvoiceById -- open
  // synchronously first, before the async fetch below.
  const win = window.open('', '_blank');
  if (win) win.document.write('<html><body style="font-family:sans-serif;padding:40px;text-align:center;color:#666">Loading invoice…</body></html>');
  const jobRef = coll('jobs').doc(jobId);
  Promise.all([
    jobRef.collection('invoices').doc(invId).get(),
    jobRef.collection('invoices').get()
  ]).then(([doc, allSnap]) => {
      if (!doc.exists) return;
      const inv = doc.data();
      const job = conJobs.find(j => j.id === jobId);
      const otherInvoices = [];
      allSnap.forEach(d => { if (d.id !== invId) otherInvoices.push(d.data()); });
      printInvoiceData(inv, job, otherInvoices, win);
    });
}

// "View" was missing entirely -- Print opens the browser's print
// dialog immediately, which isn't what you want when you just need to
// glance at what the customer actually received. Same underlying
// renderInvoiceDocumentHtml() as Print and the Email preview (single
// source of truth for what an invoice document looks like) — just
// opened plain, no print dialog forced on top of it.
function viewInvoiceById(jobId, invId) {
  if (!conDb) return;
  // Open the window FIRST, synchronously, before any async work — this
  // is what "on mobile, View does nothing" actually was. Mobile Safari/
  // Chrome only allow window.open() to succeed when it happens directly
  // within the same tap that triggered it; once there's an await/.then()
  // delay before it (the Firestore fetch below), the popup is silently
  // blocked — no error, no visible warning, just nothing happens. Opening
  // immediately with a placeholder, then writing the real content into
  // that already-open window once the fetch resolves, works reliably.
  const win = window.open('', '_blank');
  if (win) win.document.write('<html><body style="font-family:sans-serif;padding:40px;text-align:center;color:#666">Loading invoice…</body></html>');

  const jobRef = coll('jobs').doc(jobId);
  Promise.all([
    jobRef.collection('invoices').doc(invId).get(),
    jobRef.collection('invoices').get()
  ]).then(([doc, allSnap]) => {
      if (!doc.exists) return;
      const inv = doc.data();
      const job = conJobs.find(j => j.id === jobId);
      const otherInvoices = [];
      allSnap.forEach(d => { if (d.id !== invId) otherInvoices.push(d.data()); });
      if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
      win.document.open();
      win.document.write(renderInvoiceDocumentHtml(inv, job, otherInvoices, false));
      win.document.close();
    });
}
window.viewInvoiceById = viewInvoiceById;

function printInvoice() {
  // Build from current modal state
  const jobId = document.getElementById('invJobId')?.value;
  const invId = document.getElementById('invId')?.value;
  const job = conJobs.find(j => j.id === jobId);
  const subtotal = _invLineItems.reduce((s,i) => s + (i.qty||1)*(i.rate||0), 0);
  const taxRate = parseFloat(document.getElementById('invTaxRate')?.value) || 0;
  const total = subtotal * (1 + taxRate/100);
  const inv = {
    number: document.getElementById('invNumber')?.value,
    type: document.getElementById('invType')?.value,
    date: document.getElementById('invDate')?.value,
    dueDate: document.getElementById('invDueDate')?.value,
    status: document.getElementById('invStatus')?.value,
    lineItems: _invLineItems,
    subtotal, taxRate, taxAmt: subtotal*taxRate/100, total,
    amtPaid: parseFloat(document.getElementById('invAmtPaid')?.value)||0,
    notes: document.getElementById('invNotes')?.value
  };
  const otherInvoices = (allInvoices || []).filter(i => i.jobId === jobId && i.id !== invId);
  printInvoiceData(inv, job, otherInvoices);
}

