// ── Patch switchDetailTab to handle invoices tab ──
// switchDetailTab defined above


// invoicing nav trigger handled in base ktNav above

// ── Patch conLoadJobs to also load all invoices ──
const _origConLoadJobsInv = conLoadJobs;
function conLoadJobs() {
  if (!conDb) return;
  coll('jobs').onSnapshot(snap => {
    conJobs = [];
    snap.forEach(doc => {
      const job = { id: doc.id, ...doc.data() };
      if (!job.archived) conJobs.push(job);
    });
    conJobs.sort((a,b) => {
      const ta = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
      const tb = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
      return tb - ta;
    });
    migrateJobStatuses(conJobs); // remap any legacy status values in-memory
    conRenderBoard();
    conRenderList();
    conRenderStats();
    conRenderSchedule();
    // Jobs page has its own separate Kanban render (renderJobsBoard),
    // distinct from the Home dashboard board above — was missing from
    // this refresh entirely, so deleting/archiving a job while on the
    // Jobs page left a stale card until a manual page refresh.
    if (typeof renderJobsBoard === 'function' && _jobsView === 'kanban') renderJobsBoard();
    loadAllCOTotals();
    loadCatalog();
    loadAllInvoices();
    loadTodos();
    loadCustomers();
    loadTimeEntries();
    loadVendors();
    // Same reasoning as loadTeamMembers below — Contractors need to be
    // loaded at startup, not just when someone visits the Contractors
    // page, so the Subcontractor Payment dropdown on a job's Financials
    // tab always has real data instead of showing empty until someone
    // happens to click Contractors first.
    loadContractors();
    loadDocuments();
    loadGlobalLogs();
    loadGlobalPhases();
    loadCalendarEvents();
    // Needed early (not just when visiting Settings) so
    // getPersonBurdenRate() has real per-person rates available no
    // matter which page loads first — job cost tracking shouldn't
    // silently fall back to the flat company rate just because nobody
    // happened to open Settings yet this session.
    loadTeamMembers();
    loadPOs();
    loadTeamCache();
    renderHomeDashboard();
  }, (err) => {
    // Real gap this closes: this listener had no error handler at
    // all, so a permission-denied read (e.g. a team member's custom
    // claims not yet synced on their current session — confirmed as
    // a real, live case, not hypothetical, for a brand-new Field
    // Technician who could log in but saw zero jobs anywhere, Time
    // included, with nothing in the UI or console explaining why)
    // failed completely silently: conJobs just stayed permanently
    // empty, forever, with no visible error at all. Surfacing it
    // now so this is diagnosable instead of a silent dead end.
    console.error('conLoadJobs: jobs listener failed —', err.code, err.message);
    if (err.code === 'permission-denied') {
      alert('Could not load jobs — your account permissions may not be fully set up yet. Try signing out and back in. If this keeps happening, contact your Owner.');
    }
  });
}

