// ── Pay-by-check remittance note (single source of truth) ──
// Returns { payableTo, address } or null if we have nothing useful to show.
// Uses companyProfile.checkPayableTo if set (legal payee may differ from the
// display name), otherwise companyName. Address is optional.
function remittanceInfo() {
  const payableTo = (companyProfile.checkPayableTo || companyProfile.companyName || '').trim();
  const address = (companyProfile.address || '').trim();
  if (!payableTo) return null;
  return { payableTo, address };
}

// HTML block for emails / portal. Returns '' when there's nothing to show.
function remittanceHtml() {
  const r = remittanceInfo();
  if (!r) return '';
  return '<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:14px;margin:16px 0;font-size:.85rem;color:#374151">'
    + '<div style="font-weight:700;color:#111827;margin-bottom:6px">Prefer to pay by check?</div>'
    + 'Make checks payable to <strong>' + esc(r.payableTo) + '</strong>'
    + (r.address ? '<br>Mail to: ' + esc(r.address) : '')
    + '<div style="font-size:.78rem;color:#6b7280;margin-top:6px">Please include the invoice number on your check.</div>'
    + '</div>';
}

// Plain-text version for text email bodies.
function remittanceText() {
  const r = remittanceInfo();
  if (!r) return '';
  return '\n\nPrefer to pay by check? Make checks payable to ' + r.payableTo
    + (r.address ? '\nMail to: ' + r.address : '')
    + '\nPlease include the invoice number on your check.';
}

// ── Email Invoice to Customer ──
async function emailInvoiceToCustomer(jobId, invId) {
  if (!conDb || !jobId || !invId) return;

  const job = conJobs.find(j => j.id === jobId);
  if (!job) { alert('Job not found.'); return; }

  let inv = null;
  try {
    const d = await coll('jobs').doc(jobId).collection('invoices').doc(invId).get();
    if (d.exists) inv = { id: d.id, ...d.data() };
  } catch(e) {}
  if (!inv) { alert('Invoice not found.'); return; }

  // STRIPE-ONLY: emailed invoices must carry a Stripe payment link and
  // NOTHING from QuickBooks. Generate a fresh Stripe link for the
  // remaining balance every send. If Stripe fails, we send with NO pay
  // button rather than silently falling back to a QuickBooks link.
  let stripePayLink = '';
  try {
    if (conFunctions && (inv.total || 0) > (inv.amtPaid || 0)) {
      const createLink = conFunctions.httpsCallable('createStripePaymentLink');
      const result = await createLink({ companyId: currentCompanyId, jobId, invoiceId: invId });
      if (result.data?.url) stripePayLink = result.data.url;
    }
  } catch (e) {
    console.warn('Stripe payment link not generated:', e.message);
  }

  // If there's a balance owed but Stripe couldn't produce a link, stop
  // and tell Travis rather than emailing a linkless (or worse, QB-linked)
  // invoice.
  if ((inv.total || 0) > (inv.amtPaid || 0) && !stripePayLink) {
    alert('Could not generate a Stripe payment link for this invoice.\n\n'
      + 'The invoice was NOT sent (to avoid emailing a QuickBooks link or no link at all).\n\n'
      + 'Check that Stripe is connected under Settings, then try again.');
    return;
  }

  const customerEmail = job.email || job.clientEmail || '';
  const customerName = job.client || 'Customer';
  const invNum = inv.number || 'Invoice';
  const total = (inv.total || 0).toLocaleString(undefined, {minimumFractionDigits:2});
  const due = inv.dueDate || '';
  const payLink = stripePayLink; // Stripe only — never inv.qbPaymentLink

  // Get portal link for invoice viewing
  let portalUrl = '';
  try {
    const snap = await conDb.collection('portalTokens').where('jobId','==',jobId).limit(1).get();
    if (!snap.empty) {
      portalUrl = `${location.origin}${location.pathname}?portal=${snap.docs[0].id}`;
    }
  } catch(e) {}

  const subject = `Invoice ${invNum} — $${total} — ${job.name || 'Your Project'}`;

  const bodyHtml = `
    <h2 style="color:#d97706;margin-top:0">Invoice ${invNum}</h2>
    <p>Hi ${customerName},</p>
    <p>Please find your invoice details below.</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0">
      <tr><td style="padding:8px;color:#666;width:140px">Project</td><td style="padding:8px;font-weight:600">${esc(job.name||'')}</td></tr>
      <tr style="background:#f9f9f9"><td style="padding:8px;color:#666">Invoice #</td><td style="padding:8px;font-weight:600">${esc(invNum)}</td></tr>
      <tr><td style="padding:8px;color:#666">Amount Due</td><td style="padding:8px;font-weight:700;font-size:1.1rem;color:#d97706">$${total}</td></tr>
      ${due ? `<tr style="background:#f9f9f9"><td style="padding:8px;color:#666">Due Date</td><td style="padding:8px">${due}</td></tr>` : ''}
    </table>
    ${payLink ? `
    <div style="text-align:center;margin:24px 0">
      <a href="${payLink}" style="background:#d97706;color:#fff;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:700;font-size:1rem;display:inline-block">
        💳 Pay Now
      </a>
    </div>` : ''}
    ${portalUrl ? `<p style="font-size:.85rem;color:#666;text-align:center">
      <a href="${portalUrl}" style="color:#d97706">View your project portal →</a>
    </p>` : ''}
    ${remittanceHtml()}
    ${inv.notes ? `<p style="font-size:.85rem;color:#444;border-top:1px solid #eee;padding-top:12px;margin-top:16px">${esc(inv.notes)}</p>` : ''}`;

  const bodyText = `Hi ${customerName},\n\nInvoice ${invNum} for $${total} is ready.\n${due ? 'Due: ' + due + '\n' : ''}${payLink ? '\nPay online: ' + payLink : ''}\n${portalUrl ? '\nView portal: ' + portalUrl : ''}${remittanceText()}`;

  // Same preview-before-send pattern as sendProposalViaEmail(): render
  // the ACTUAL invoice document — the thing a customer clicking "Pay
  // Now"/viewing the portal really sees — into the shared preview
  // modal's iframe, not just the wrapper email text. Was previously a
  // small custom modal with only a "Customer Email" field and no way
  // to see what was actually about to be sent.
  let otherInvoices = [];
  try {
    const allSnap = await coll('jobs').doc(jobId).collection('invoices').get();
    allSnap.forEach(d => { if (d.id !== invId) otherInvoices.push(d.data()); });
  } catch (e) {}
  const invoiceHtml = renderInvoiceDocumentHtml(inv, job, otherInvoices, false);
  document.getElementById('emailPreviewProposalFrame').srcdoc = invoiceHtml;

  _pendingInvoiceEmail = { jobId, invId, to: customerEmail, toName: customerName, subject, bodyHtml, bodyText };
  document.getElementById('emailPreviewTo').textContent = customerEmail + (customerName ? ' (' + customerName + ')' : '');
  document.getElementById('emailPreviewSubject').textContent = subject;
  document.getElementById('emailPreviewBody').innerHTML = bodyHtml;

  // The shared modal's Confirm button is hardcoded in HTML to call the
  // proposal's confirm function — repoint it here rather than touch
  // that markup, so the proposal flow is completely undisturbed.
  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  if (confirmBtn) confirmBtn.onclick = confirmSendInvoiceEmailFromPreview;

  kOpen('emailPreviewModal');
}
window.emailInvoiceToCustomer = emailInvoiceToCustomer;

let _pendingInvoiceEmail = null;

async function confirmSendInvoiceEmailFromPreview() {
  if (!_pendingInvoiceEmail) return;
  const { jobId, invId, to, toName, subject, bodyHtml, bodyText } = _pendingInvoiceEmail;
  if (!to) { alert('This job has no customer email on file. Add one in the job details first.'); return; }

  const btn = document.getElementById('emailPreviewConfirmBtn');
  if (btn) { btn.textContent = 'Sending…'; btn.disabled = true; }

  try {
    const sendEmail = conFunctions.httpsCallable('sendJobspanEmail');
    await sendEmail({ to, toName, subject, bodyHtml, bodyText, docType: 'invoice', jobId });
    kClose('emailPreviewModal');
    // Was never updating invoice status at all -- an emailed invoice
    // stayed stuck on "Draft" forever, indistinguishable from one that
    // was never sent. Only advances FROM Draft specifically; resending
    // an already-Sent/Paid/Partial invoice for someone's records
    // shouldn't downgrade its real status back to something less
    // advanced.
    try {
      const invDoc = await coll('jobs').doc(jobId).collection('invoices').doc(invId).get();
      if (invDoc.exists && invDoc.data().status === 'Draft') {
        await coll('jobs').doc(jobId).collection('invoices').doc(invId).update({ status: 'Sent' });
      }
    } catch (statusErr) {
      console.error('Could not update invoice status to Sent:', statusErr.message);
    }
    alert(`✅ Invoice sent to ${to}`);
    logInvoiceActivity(jobId, 'invoice_emailed', `Invoice emailed to ${to}`);
    loadJobInvoices(jobId);
  } catch (e) {
    alert('Email send failed: ' + e.message);
  } finally {
    if (btn) { btn.textContent = '✅ Confirm & Send'; btn.disabled = false; }
    _pendingInvoiceEmail = null;
  }
}
window.confirmSendInvoiceEmailFromPreview = confirmSendInvoiceEmailFromPreview;

// ════════════════════════════════════════════════════
// ── LIEN WAIVER SYSTEM ──
// E-SIGN Act compliant: stores signer name, drawn signature image,
// timestamp (server), IP address (client-side best-effort), document
// content hash (SHA-256 of the frozen text), and portal token identity.
// Missouri uses two standard forms:
//   Conditional   — signed at invoice send (payment not yet confirmed)
//   Unconditional — signed after payment is confirmed (clears the lien)
// Both are generated pre-filled from job/invoice data, sent via the
// existing Customer Portal token link, and stored in Firestore under
// jobs/{jobId}/lienWaivers/{waiverId}.
// ════════════════════════════════════════════════════

// ── Generate lien waiver text (Missouri standard language) ──
function buildLienWaiverText(type, job, inv, co) {
  const ownerName   = job.client || 'Property Owner';
  const propAddress = job.address || 'Property Address on File';
  const contractor  = (companyProfile.companyName || companyProfile.legalName || 'Contractor');
  const amount      = (inv ? (inv.total || 0) : (co ? (co.amount || 0) : 0));
  const docNum      = inv ? (inv.number || 'Invoice') : (co ? ('Change Order: ' + (co.title || '')) : 'Contract');
  const jobName     = job.name || 'Project';
  const today       = new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });

  if (type === 'conditional') {
    return [
      `CONDITIONAL WAIVER AND RELEASE UPON PROGRESS PAYMENT`,
      ``,
      `Project: ${jobName}`,
      `Property Address: ${propAddress}`,
      `Owner / Customer: ${ownerName}`,
      `Contractor: ${contractor}`,
      `Document Reference: ${docNum}`,
      `Amount of this Payment: $${amount.toLocaleString(undefined, {minimumFractionDigits:2,maximumFractionDigits:2})}`,
      `Date: ${today}`,
      ``,
      `CONDITIONAL WAIVER`,
      `The undersigned has been paid and has received a progress payment in the sum of`,
      `$${amount.toLocaleString(undefined, {minimumFractionDigits:2,maximumFractionDigits:2})} for labor, services, equipment, or`,
      `materials furnished to ${ownerName} on the job of ${jobName}, located at`,
      `${propAddress}, and does hereby waive and release any mechanic's lien,`,
      `stop payment notice, or any right against a labor and material bond on the`,
      `job, to the following extent:`,
      ``,
      `This release covers a progress payment for labor, services, equipment, or`,
      `materials furnished to the property through the date of this document only`,
      `and does not cover any retentions retained before or after the release date;`,
      `extras or change orders furnished before or after the release date for which`,
      `payment has not been received; or disputed items.`,
      ``,
      `THIS RELEASE IS CONDITIONED UPON RECEIPT OF PAYMENT IN THE AMOUNT`,
      `STATED ABOVE. If payment is not received, this release is void and of no`,
      `effect, and the undersigned retains all lien rights as if this release had`,
      `not been executed.`,
      ``,
      `The undersigned warrants that they have authority to execute this release on`,
      `behalf of the contracting party identified above.`,
    ].join('\n');
  } else {
    return [
      `UNCONDITIONAL WAIVER AND RELEASE UPON FINAL PAYMENT`,
      ``,
      `Project: ${jobName}`,
      `Property Address: ${propAddress}`,
      `Owner / Customer: ${ownerName}`,
      `Contractor: ${contractor}`,
      `Document Reference: ${docNum}`,
      `Final Payment Amount: $${amount.toLocaleString(undefined, {minimumFractionDigits:2,maximumFractionDigits:2})}`,
      `Date: ${today}`,
      ``,
      `UNCONDITIONAL WAIVER`,
      `The undersigned has been paid in full for all labor, services, equipment,`,
      `or materials furnished to ${ownerName} on the job of ${jobName},`,
      `located at ${propAddress}, and does hereby unconditionally waive and`,
      `release any mechanic's lien, stop payment notice, or any right against a`,
      `labor and material bond on the job.`,
      ``,
      `The undersigned warrants that all subcontractors and suppliers have been`,
      `paid in full or that all claims for labor, services, equipment, or materials`,
      `furnished to the above-referenced project have been released.`,
      ``,
      `THIS RELEASE IS UNCONDITIONAL AND IS EFFECTIVE UPON EXECUTION. The`,
      `undersigned warrants that they have authority to execute this release on`,
      `behalf of the contracting party identified above.`,
    ].join('\n');
  }
}

// ── Simple SHA-256 hash via Web Crypto (async) ──
async function sha256(str) {
  try {
    const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
    return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2,'0')).join('');
  } catch(e) { return 'hash-unavailable'; }
}

// ── Send lien waiver — creates the waiver doc and opens share dialog ──
async function sendLienWaiver(jobId, invId, type) {
  if (!conDb || !jobId) return;

  const job = conJobs.find(j => j.id === jobId);
  if (!job) { alert('Job not found.'); return; }

  let inv = null, co = null;
  if (invId) {
    // Load the invoice data
    try {
      const invDoc = await coll('jobs').doc(jobId).collection('invoices').doc(invId).get();
      if (invDoc.exists) inv = { id: invDoc.id, ...invDoc.data() };
    } catch(e) {}
  }

  const waiverText = buildLienWaiverText(type, job, inv, co);
  const hash = await sha256(waiverText);

  const waiverData = {
    type,                      // 'conditional' | 'unconditional'
    jobId,
    jobName: job.name || '',
    invoiceId: invId || null,
    invoiceNumber: inv?.number || null,
    amount: inv?.total || 0,
    propertyAddress: job.address || '',
    ownerName: job.client || '',
    contractorName: companyProfile.companyName || companyProfile.legalName || '',
    documentText: waiverText,
    documentHash: hash,
    status: 'pending',         // pending | signed | declined
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdBy: conCurrentUser?.email || '',
  };

  try {
    const ref = await coll('jobs').doc(jobId).collection('lienWaivers').add({
      ...waiverData,
      companyId: currentCompanyId || null,
    });
    const waiverId = ref.id;

    // Reuse existing portal token for this job if one exists (same pattern
    // as shareCustomerPortal and sendProposalViaEmail which both work).
    let token;
    try {
      const snap = await conDb.collection('portalTokens')
        .where('jobId','==',jobId).limit(1).get();
      if (!snap.empty) {
        token = snap.docs[0].id;
      } else {
        token = jobId + '-hash-' + Math.random().toString(36).slice(2,10);
        await conDb.collection('portalTokens').doc(token).set({
          jobId, companyId: currentCompanyId || null,
          created: Date.now(), createdBy: conCurrentUser?.email || '',
          expires: null, shareInvoices: true
        });
      }
    } catch(tokenErr) {
      // Token lookup failed — generate a fresh one
      token = jobId + '-hash-' + Math.random().toString(36).slice(2,10);
      await conDb.collection('portalTokens').doc(token).set({
        jobId, companyId: currentCompanyId || null,
        created: Date.now(), createdBy: conCurrentUser?.email || '',
        expires: null, shareInvoices: true
      });
    }

    const portalUrl = `${location.origin}${location.pathname}?portal=${token}&waiver=${waiverId}`;
    const typeLabel = type === 'conditional' ? 'Conditional Lien Waiver' : 'Unconditional Lien Waiver';
    const customerEmail = job.email || job.clientEmail || '';

    // Show send dialog instead of just copying to clipboard
    showLienWaiverSendDialog({
      waiverId, jobId, portalUrl, typeLabel,
      customerName: job.client || 'Customer',
      customerEmail,
      invoiceNumber: inv?.number || null,
      amount: inv?.total || 0,
    });

    // Refresh invoice list to show waiver status
    loadJobInvoices(jobId);
  } catch(e) {
    alert('Error creating lien waiver: ' + e.message);
  }
}
window.sendLienWaiver = sendLienWaiver;

// ════════════════════════════════════════════════════
// ── SUBCONTRACTOR AGREEMENT SYSTEM ──
// Mirrors the Lien Waiver system above: pre-filled document, sent via
// the same Customer Portal token link, signed on the same canvas pad,
// stored under jobs/{jobId}/subAgreements/{agreementId}. Auto-populated
// from the sub's existing record (name, trade, contract amount) the
// same way lien waivers auto-populate from invoice data.
// ════════════════════════════════════════════════════

function buildSubAgreementText(sub, job, co) {
  const companyName = co.companyName || co.legalName || 'TDX Holdings LLC dba JTXD Contracting';
  const jobName = job.name || 'Project';
  const jobAddress = job.address || 'Address on File';
  const subName = sub.name || 'Subcontractor';
  const trade = sub.trade || 'General Labor';
  // Defensive: bid-award flow currently writes the amount to `contract`,
  // while the sub card and this agreement read `amount` -- support both
  // so an existing data quirk doesn't produce a $0 agreement.
  const amount = sub.amount || sub.contract || 0;
  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const amtStr = Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // Reuse the job's existing customer payment schedule (same stages/
  // percentages already set on the Estimate tab), applied to the SUB's
  // bid amount instead of the job's grand total -- via the same shared
  // helper the customer proposal and invoicing already use, so the
  // vocabulary/percentages can never drift out of sync with those.
  // Falls back to the generic line below if the job has no schedule set.
  const subPaymentRows = (typeof getPaymentScheduleRows === 'function')
    ? getPaymentScheduleRows(job.paymentSchedule, amount)
    : [];
  const paymentScheduleLines = subPaymentRows.length
    ? subPaymentRows.map(r => `   \u2022 ${r.label} (${r.pct}%): $${Number(r.amount).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`).join('\n')
    : null;
  const contractPriceClause = paymentScheduleLines
    ? `3. CONTRACT PRICE. The total contract price for the Work is $${amtStr}, payable according to the following schedule:\n\n${paymentScheduleLines}\n\nEach payment is due upon Company's acceptance of the Work completed for that stage.`
    : `3. CONTRACT PRICE. The total contract price for the Work is $${amtStr}, payable per Company's standard payment schedule upon completion of agreed milestones and Company's acceptance of the Work.`;

  // Estimated Days to Complete is derived from the job's own Start/Target
  // dates (job.startDate / job.endDate) via the same workDaysBetween()
  // helper the Master Schedule already uses, so it can never drift out of
  // sync with what's actually scheduled. If the job has no dates set yet,
  // the clause still reads correctly -- it just states the Start Date will
  // be confirmed separately, rather than printing a blank or a broken
  // sentence.
  const scheduleStartDate = job.startDate
    ? new Date(job.startDate + 'T00:00:00').toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
    : null;
  const scheduleDays = (typeof workDaysBetween === 'function')
    ? workDaysBetween(job.startDate, job.endDate)
    : null;
  const scheduleClause = scheduleStartDate
    ? `2. SCHEDULE. Subcontractor shall commence the Work on or about ${scheduleStartDate} ("Start Date")${scheduleDays ? ` and shall substantially complete the Work within an estimated ${scheduleDays} working day${scheduleDays === 1 ? '' : 's'} of the Start Date` : ''}, subject to delays caused by Company, weather, material availability, or other matters beyond Subcontractor's reasonable control. Time is not of the essence solely by virtue of this clause, but Subcontractor shall notify Company promptly in writing of any anticipated delay.`
    : `2. SCHEDULE. The Start Date and estimated number of working days to complete the Work shall be confirmed by Company in writing (including by email or through Company's project management system) prior to or upon commencement of the Work, and once confirmed shall be deemed incorporated into this Agreement. Subcontractor shall notify Company promptly in writing of any anticipated delay. Time is not of the essence solely by virtue of this clause.`;

  return [
    'SUBCONTRACTOR AGREEMENT',
    '',
    `Agreement Date: ${today}`,
    `Company: ${companyName}`,
    `Subcontractor: ${subName}`,
    `Trade: ${trade}`,
    `Project: ${jobName}`,
    `Project Address: ${jobAddress}`,
    `Contract Price: $${amtStr}`,
    '',
    `This Subcontractor Agreement ("Agreement") is entered into as of the Agreement Date above by and between ${companyName} ("Company") and ${subName} ("Subcontractor").`,
    '',
    `1. SCOPE OF WORK. Subcontractor agrees to furnish all labor, equipment, and supervision necessary to perform ${trade} work at ${jobAddress}, in accordance with the agreed scope for this project. Company shall furnish and pay for all materials required for the Work, unless otherwise agreed in writing.`,
    '',
    scheduleClause,
    '',
    contractPriceClause,
    '',
    '4. INDEPENDENT CONTRACTOR STATUS. Subcontractor is retained as an independent contractor and not as an employee, agent, joint venturer, or partner of Company. Subcontractor shall determine the means and methods of performing the Work, shall furnish its own tools and equipment unless otherwise agreed, and is solely responsible for its own taxes and for the wages, taxes, and benefits of any individuals it employs or engages. Nothing in this Agreement creates an employer-employee relationship between Company and Subcontractor or Subcontractor\'s employees, agents, or lower-tier subcontractors.',
    '',
    '5. LICENSES AND COMPLIANCE. Subcontractor represents that it holds, and shall maintain, all licenses, permits, and certifications required by law to perform the Work, and shall comply with all applicable building codes, safety regulations (including OSHA), and municipal ordinances.',
    '',
    '6. CHANGE ORDERS. No changes to the Scope of Work, Contract Price, or Schedule are effective unless agreed in writing by both parties before the additional or extended work is performed. Subcontractor shall not proceed with, and Company shall have no obligation to pay for, any work performed outside the Scope of Work or beyond the Schedule set forth in Clause 2 without a signed Change Order. Subcontractor\'s performance of unauthorized additional work is at Subcontractor\'s own risk and expense.',
    '',
    '7. INSURANCE AND INDEMNIFICATION. Subcontractor shall maintain commercial general liability insurance and workers\' compensation insurance as required by law, and shall provide Company with a certificate of insurance upon request. Subcontractor shall indemnify, defend, and hold harmless Company from claims, damages, or losses arising out of Subcontractor\'s negligent acts, omissions, or breach of this Agreement, except to the extent caused by Company\'s own negligence.',
    '',
    '8. WARRANTY. Subcontractor warrants that the Work shall be free from defects in materials and workmanship for one (1) year from substantial completion, and shall promptly correct, at its own expense, any Work found defective during that period, ordinary wear and tear excepted.',
    '',
    '9. TERMINATION. Company may terminate this Agreement for cause upon written notice if Subcontractor fails to cure a material breach within ten (10) days of notice. Company may terminate for convenience upon written notice, in which case Subcontractor shall be paid for Work satisfactorily performed prior to termination.',
    '',
    '10. GOVERNING LAW. This Agreement shall be governed by the laws of the State of Missouri.',
    '',
    '11. ENTIRE AGREEMENT. This Agreement constitutes the entire agreement between the parties regarding the Work and supersedes all prior negotiations or representations, whether written or oral. This Agreement may only be amended in writing signed by both parties.',
    '',
    'By signing below, Subcontractor acknowledges having read and agreed to the terms of this Agreement, and that Subcontractor\'s electronic signature is legally binding under the federal Electronic Signatures in Global and National Commerce Act (E-SIGN).',
  ].join('\n');
}

async function sendSubAgreement(jobId, subId) {
  if (!conDb || !jobId || !subId) return;

  const job = conJobs.find(j => j.id === jobId);
  if (!job) { alert('Job not found.'); return; }

  let sub = null;
  try {
    const subDocSnap = await coll('jobs').doc(jobId).collection('subs').doc(subId).get();
    if (subDocSnap.exists) sub = { id: subDocSnap.id, ...subDocSnap.data() };
  } catch(e) {}
  if (!sub) { alert('Subcontractor record not found.'); return; }
  if (!sub.email) { alert('This subcontractor has no email on file \u2014 add one under Contractors before sending.'); return; }

  const agreementText = buildSubAgreementText(sub, job, companyProfile);
  const hash = await sha256(agreementText);

  const agreementData = {
    jobId,
    jobName: job.name || '',
    subId,
    subName: sub.name || '',
    subEmail: sub.email || '',
    trade: sub.trade || '',
    amount: sub.amount || sub.contract || 0,
    documentText: agreementText,
    documentHash: hash,
    status: 'pending', // pending | signed | declined
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdBy: conCurrentUser?.email || '',
  };

  let agreementId;
  try {
    const ref = await coll('jobs').doc(jobId).collection('subAgreements').add({
      ...agreementData,
      companyId: currentCompanyId || null,
    });
    agreementId = ref.id;
  } catch(e) {
    alert('Error creating subcontractor agreement: ' + e.message);
    return;
  }

  // Reuse existing portal token for this job if one exists (same
  // pattern as sendLienWaiver / sendProposalViaEmail).
  let token;
  try {
    const snap = await conDb.collection('portalTokens')
      .where('jobId','==',jobId).limit(1).get();
    if (!snap.empty) {
      token = snap.docs[0].id;
    } else {
      token = jobId + '-hash-' + Math.random().toString(36).slice(2,10);
      await conDb.collection('portalTokens').doc(token).set({
        jobId, companyId: currentCompanyId || null,
        created: Date.now(), createdBy: conCurrentUser?.email || '',
        expires: null, shareInvoices: true
      });
    }
  } catch(tokenErr) {
    token = jobId + '-hash-' + Math.random().toString(36).slice(2,10);
    await conDb.collection('portalTokens').doc(token).set({
      jobId, companyId: currentCompanyId || null,
      created: Date.now(), createdBy: conCurrentUser?.email || '',
      expires: null, shareInvoices: true
    });
  }

  const portalUrl = `${location.origin}${location.pathname}?portal=${token}&subagreement=${agreementId}`;
  const subject = 'Subcontractor Agreement \u2014 Signature Required';
  const bodyHtml = `
    <h2 style="color:#d97706;margin-top:0">Subcontractor Agreement</h2>
    <p>Hi ${esc(sub.name)},</p>
    <p>Please review and sign the subcontractor agreement for ${esc(job.name || 'this project')}.</p>
    <div style="text-align:center;margin:28px 0">
      <a href="${portalUrl}" style="background:#d97706;color:#fff;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:700;font-size:1rem;display:inline-block">
        \u270d\ufe0f Review &amp; Sign Agreement
      </a>
    </div>
    <p style="font-size:.85rem;color:#666">Or copy this link into your browser:<br>
      <a href="${portalUrl}" style="color:#d97706;word-break:break-all">${portalUrl}</a>
    </p>`;
  const bodyText = `Hi ${sub.name},\n\nPlease review and sign the subcontractor agreement for ${job.name || 'this project'}.\n\n${portalUrl}`;

  // Same preview-before-send pattern as invoices/proposals: render the
  // actual agreement document into the shared modal's iframe so nothing
  // goes out sight-unseen.
  const docHtml = buildSubAgreementPreviewHtml(agreementText, sub.name || 'Subcontractor', job.name || '');
  document.getElementById('emailPreviewProposalFrame').srcdoc = docHtml;

  _pendingSubAgreementEmail = { agreementId, jobId, to: sub.email, toName: sub.name, subject, bodyHtml, bodyText };
  document.getElementById('emailPreviewTo').textContent = sub.email + (sub.name ? ' (' + sub.name + ')' : '');
  document.getElementById('emailPreviewSubject').textContent = subject;
  document.getElementById('emailPreviewBody').innerHTML = bodyHtml;

  // Shared modal's Confirm button is repointed per document type,
  // same pattern used for invoices -- doesn't touch that markup.
  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  if (confirmBtn) confirmBtn.onclick = confirmSendSubAgreementEmail;

  kOpen('emailPreviewModal');
}
window.sendSubAgreement = sendSubAgreement;

function buildSubAgreementPreviewHtml(agreementText, subName, jobName) {
  return '<html><body style="font-family:Arial;padding:24px;max-width:720px;margin:auto;color:#222">' +
    '<h2 style="color:#d97706;margin-top:0">Subcontractor Agreement</h2>' +
    '<p style="color:#666;font-size:.9rem">' + esc(subName) + (jobName ? ' &middot; ' + esc(jobName) : '') + '</p>' +
    '<pre style="white-space:pre-wrap;font-family:Arial;font-size:.92rem;line-height:1.6;border:1px solid #eee;border-radius:8px;padding:20px;background:#fafafa">' +
    esc(agreementText) +
    '</pre></body></html>';
}

let _pendingSubAgreementEmail = null;

async function confirmSendSubAgreementEmail() {
  if (!_pendingSubAgreementEmail) return;
  const { to, toName, subject, bodyHtml, bodyText, jobId } = _pendingSubAgreementEmail;
  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  const originalText = confirmBtn ? confirmBtn.textContent : '';
  try {
    if (!conFunctions) throw new Error('Functions not available');
    const sendEmail = conFunctions.httpsCallable('sendJobspanEmail');
    if (confirmBtn) { confirmBtn.textContent = 'Sending\u2026'; confirmBtn.disabled = true; }
    await sendEmail({ to, toName, subject, bodyHtml, bodyText, docType: 'subAgreement', jobId });
    kClose('emailPreviewModal');
    alert('Subcontractor agreement sent to ' + to + '.');
  } catch(e) {
    alert('Error sending email: ' + e.message);
  } finally {
    if (confirmBtn) { confirmBtn.textContent = originalText || 'Confirm & Send'; confirmBtn.disabled = false; }
  }
}
window.confirmSendSubAgreementEmail = confirmSendSubAgreementEmail;

