// ── COMPANY SETTINGS ──
// ════════════════════════════════════════════════════
let companyProfile = {};

// Default profile — used only if no company settings doc exists yet in Firestore
const DEFAULT_COMPANY_PROFILE = {
  companyName: 'TDX Holdings, LLC',
  phone: '',
  email: '',
  website: '',
  address: '',
  checkPayableTo: '',
  license: '',
  insurance: '',
  logo: '',
  payTerms: 30,
  taxRate: 0,
  invNotes: 'Payment due within 30 days. Thank you for your business!',
  defaultMaterialsMarkup: 25,
  defaultLaborMarkup: 15,
  burdenRatePerManHour: 60,
  otWeeklyThreshold: 40,
  otMultiplier: 1.5,
  weekStartDay: 'mon'
};

function loadCompanyProfile() {
  if (!conDb || !conCurrentUser) return;
  const roleEl = document.getElementById('ktUserRole');
  if (roleEl && currentUserRole) {
    const roleData = KYTRAC_ROLES[currentUserRole] || {};
    roleEl.textContent = currentUserRole;
    roleEl.style.color = roleData.color || 'var(--muted)';
  }
  coll('settings').doc('company').get()
    .then(doc => {
      if (doc.exists) {
        companyProfile = { ...DEFAULT_COMPANY_PROFILE, ...doc.data() };
        // NOTE: this used to auto-set ownerUid to conCurrentUser.uid here
        // (the JOBSMETRIX login's own Firebase UID, from the kytrac-72d91
        // project) every time this loaded. That's the wrong UID entirely —
        // PlannerXD is a SEPARATE Firebase project with its own unrelated
        // UID namespace, so ownerUid needs to be PlannerXD's account UID,
        // not a JOBSMETRIX one. That auto-overwrite silently clobbered
        // whatever correct value might have existed on every single
        // JOBSMETRIX load, which is very likely why the PlannerXD bridge
        // has never actually worked. Removed — ownerUid is now only ever
        // set manually via the PlannerXD Owner UID field in Company
        // Settings.
      } else {
        companyProfile = { ...DEFAULT_COMPANY_PROFILE };
        coll('settings').doc('company').set(companyProfile).catch(() => {});
      }
      populateSettingsForm();
      updateSidebarUserInfo();
      checkQBConnectionStatus();
      checkStripeConnectionStatus();
    })
    .catch(() => {
      companyProfile = { ...DEFAULT_COMPANY_PROFILE };
      populateSettingsForm();
    });
}

// Opens the QuickBooks OAuth flow for THIS company specifically — each
// JOBSMETRIX company connects its own QuickBooks account independently.
// Passes a verified Firebase ID token (same security shape as
// connectGoogleCalendar below) since this connects ONE shared,
// company-wide financial account rather than an individual calendar —
// it needs the stronger check, not a weaker one.
const QBO_FUNCTIONS_BASE = 'https://us-central1-kytrac-72d91.cloudfunctions.net';

function connectQuickBooks() {
  if (!currentCompanyId || !conCurrentUser) { alert('Not ready yet — try again in a moment.'); return; }
  // Same mobile popup-blocker fix as viewInvoiceById/printInvoiceById:
  // open the popup SYNCHRONOUSLY first (satisfies the "was this a
  // direct user gesture" check mobile browsers require), THEN redirect
  // that already-open window to the real URL once the async token
  // fetch resolves — instead of opening a brand new window after the
  // delay, which is exactly what was getting silently blocked.
  const win = window.open('', '_blank', 'width=520,height=680');
  conCurrentUser.getIdToken().then(idToken => {
    const url = `${QBO_FUNCTIONS_BASE}/qbOAuthStart?token=${encodeURIComponent(idToken)}&companyId=${encodeURIComponent(currentCompanyId)}`;
    if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
    win.location = url;
    // Poll for the popup closing, then refresh status — same pattern as
    // connectGoogleCalendar below.
    const poll = setInterval(() => {
      if (win && win.closed) { clearInterval(poll); setTimeout(checkQBConnectionStatus, 800); }
    }, 500);
  }).catch(e => { if (win) win.close(); alert('Could not start QuickBooks connection: ' + e.message); });
}
window.connectQuickBooks = connectQuickBooks;

function disconnectQuickBooks() {
  if (!confirm('Disconnect QuickBooks? JOBSMETRIX will stop being able to push invoices, estimates, and payments until you reconnect.')) return;
  if (!conFunctions) { alert('Not available yet.'); return; }
  conFunctions.httpsCallable('qbDisconnect')({ companyId: currentCompanyId })
    .then(() => checkQBConnectionStatus())
    .catch(e => alert('Error disconnecting: ' + e.message));
}
window.disconnectQuickBooks = disconnectQuickBooks;

// Shows whether this company currently has a QuickBooks connection,
// and toggles the Connect/Disconnect button accordingly.
function checkQBConnectionStatus() {
  const el = document.getElementById('qbConnectionStatus');
  const btnEl = document.getElementById('qbConnectBtn');
  if (!el || !conDb || !currentCompanyId) return;
  coll('settings').doc('quickbooks').get()
    .then(doc => {
      const data = doc.exists ? doc.data() : {};
      if (data.connected && data.realmId) {
        el.innerHTML = '<span style="color:#1dbb87;font-weight:700">✓ Connected</span> — Realm ID: ' + esc(data.realmId) +
          (data.environment === 'sandbox' ? ' <span style="color:#f59e0b">(Sandbox — test mode)</span>' : '');
        if (btnEl) {
          btnEl.textContent = 'Disconnect';
          btnEl.className = 'btn';
          btnEl.onclick = disconnectQuickBooks;
        }
      } else {
        el.innerHTML = '<span style="color:#9ca3af">Not connected yet.</span>';
        if (btnEl) {
          btnEl.textContent = '📗 Connect QuickBooks';
          btnEl.className = 'btn-amber';
          btnEl.onclick = connectQuickBooks;
        }
      }
    })
    .catch(() => { el.innerHTML = '<span style="color:#9ca3af">Not connected yet.</span>'; });
}
window.checkQBConnectionStatus = checkQBConnectionStatus;

// Stripe doesn't use OAuth like QuickBooks/Google Calendar — the
// company just pastes their own secret key directly. Same
// connect/disconnect/status-check shape otherwise.
function connectStripe() {
  const keyEl = document.getElementById('stripeSecretKeyInput');
  const whEl = document.getElementById('stripeWebhookSecretInput');
  const secretKey = keyEl?.value.trim();
  const webhookSecret = whEl?.value.trim() || null;
  if (!secretKey) { alert('Enter your Stripe secret key first.'); return; }
  if (!conFunctions) { alert('Not available yet.'); return; }
  const btn = document.querySelector('#stripeConnectForm .btn-amber');
  if (btn) { btn.disabled = true; btn.textContent = 'Connecting…'; }
  conFunctions.httpsCallable('connectStripeAccount')({ companyId: currentCompanyId, secretKey, webhookSecret })
    .then(result => {
      if (keyEl) keyEl.value = '';
      if (whEl) whEl.value = '';
      alert('Stripe connected (' + (result.data?.mode || 'unknown') + ' mode).');
      checkStripeConnectionStatus();
    })
    .catch(e => alert('Error connecting Stripe: ' + e.message))
    .finally(() => { if (btn) { btn.disabled = false; btn.textContent = '💳 Connect Stripe'; } });
}
window.connectStripe = connectStripe;

function disconnectStripe() {
  if (!confirm('Disconnect Stripe? Customers won\'t be able to pay invoices online until you reconnect.')) return;
  if (!conFunctions) { alert('Not available yet.'); return; }
  conFunctions.httpsCallable('disconnectStripeAccount')({ companyId: currentCompanyId })
    .then(() => checkStripeConnectionStatus())
    .catch(e => alert('Error disconnecting: ' + e.message));
}
window.disconnectStripe = disconnectStripe;

function checkStripeConnectionStatus() {
  const el = document.getElementById('stripeConnectionStatus');
  const formEl = document.getElementById('stripeConnectForm');
  const disconnectBtn = document.getElementById('stripeDisconnectBtn');
  const keyLabel = document.getElementById('stripeSecretKeyLabel');
  const connectBtnEl = document.querySelector('#stripeConnectForm .btn-amber');
  if (!el || !conDb || !currentCompanyId) return;
  coll('settings').doc('stripe').get()
    .then(doc => {
      const data = doc.exists ? doc.data() : {};
      if (data.connected) {
        el.innerHTML = '<span style="color:#1dbb87;font-weight:700">✓ Connected</span>' +
          (data.keyMode === 'test' ? ' <span style="color:#f59e0b">(Test mode)</span>' : '') +
          (data.hasWebhook ? '' : ' <span style="color:#ef4444">— webhook secret not set yet, payments won\'t auto-confirm</span>');
        if (disconnectBtn) disconnectBtn.style.display = '';
        if (data.hasWebhook) {
          // Fully set up — hide the form by default, but leave a way back
          // in. Previously this was a dead end: the only way to correct a
          // wrong/stale webhook secret was Disconnect, which wipes the
          // secret key too and forces re-entering everything from
          // scratch. "Edit connection" re-opens the same form in place.
          if (formEl) formEl.style.display = 'none';
          el.innerHTML += ' <a href="javascript:void(0)" onclick="window.showStripeEditForm()" style="color:#63b3ed;text-decoration:underline;margin-left:10px;font-size:.82rem">Edit connection</a>';
        } else {
          // Connected, but still missing the webhook secret. Previously
          // this hid the whole form unconditionally the moment
          // 'connected' became true, with no other way to add the
          // webhook secret short of disconnecting the entire
          // integration and starting over. connectStripeAccount()
          // requires the secret key on every call (it re-verifies it
          // each time), so re-entering it is unavoidable — but at
          // least there's now a path to actually finish setup instead
          // of a dead end.
          if (formEl) formEl.style.display = '';
          if (keyLabel) keyLabel.textContent = 'Stripe Secret Key (already connected — re-enter it here to add the webhook secret below)';
          if (connectBtnEl) connectBtnEl.textContent = '💳 Update Stripe Connection';
        }
      } else {
        el.innerHTML = '<span style="color:#9ca3af">Not connected yet.</span>';
        if (formEl) formEl.style.display = '';
        if (keyLabel) keyLabel.textContent = 'Stripe Secret Key';
        if (connectBtnEl) connectBtnEl.textContent = '💳 Connect Stripe';
        if (disconnectBtn) disconnectBtn.style.display = 'none';
      }
    })
    .catch(() => {
      el.innerHTML = '<span style="color:#9ca3af">Not connected yet.</span>';
      if (formEl) formEl.style.display = '';
    });
}
window.checkStripeConnectionStatus = checkStripeConnectionStatus;

// Re-opens the connect form for an already-connected account so the
// secret key and webhook signing secret can be corrected in place —
// e.g. when the wrong webhook secret was pasted (mode mismatch, wrong
// endpoint) and the signature never verifies. Both fields must be
// re-entered: connectStripeAccount() always re-verifies the secret key,
// and we never echo the previously-saved values back to the client.
function showStripeEditForm() {
  const formEl = document.getElementById('stripeConnectForm');
  const keyLabel = document.getElementById('stripeSecretKeyLabel');
  const connectBtnEl = document.querySelector('#stripeConnectForm .btn-amber');
  const keyInput = document.getElementById('stripeSecretKeyInput');
  const whInput = document.getElementById('stripeWebhookSecretInput');
  if (formEl) formEl.style.display = '';
  if (keyLabel) keyLabel.textContent = 'Stripe Secret Key (re-enter to update — including a corrected webhook secret below)';
  if (connectBtnEl) connectBtnEl.textContent = '💳 Update Stripe Connection';
  if (keyInput) { keyInput.value = ''; keyInput.focus(); }
  if (whInput) whInput.value = '';
}
window.showStripeEditForm = showStripeEditForm;

function populateSettingsForm() {
  const p = companyProfile;
  const setVal = (id, val) => { const el = document.getElementById(id); if(el) el.value = val || ''; };
  setVal('settCompanyName', p.companyName);
  setVal('settPhone', p.phone);
  setVal('settEmail', p.email);
  setVal('settWebsite', p.website);
  setVal('settAddress', p.address);
  setVal('settCheckPayableTo', p.checkPayableTo);
  setVal('settLicense', p.license);
  setVal('settInsurance', p.insurance);
  setVal('settPayTerms', p.payTerms || 30);
  setVal('settTaxRate', p.taxRate || 0);
  setVal('settInvNotes', p.invNotes);
  setVal('settMaterialsMarkup', p.defaultMaterialsMarkup !== undefined ? p.defaultMaterialsMarkup : 25);
  setVal('settLaborMarkup', p.defaultLaborMarkup !== undefined ? p.defaultLaborMarkup : 15);
  setVal('settBurdenRate', p.burdenRatePerManHour !== undefined ? p.burdenRatePerManHour : 60);
  setVal('settOtThreshold', p.otWeeklyThreshold !== undefined ? p.otWeeklyThreshold : 40);
  setVal('settOtMultiplier', p.otMultiplier !== undefined ? p.otMultiplier : 1.5);
  setVal('settWeekStart', p.weekStartDay || 'mon');
  setVal('settPlannerxdOwnerUid', p.ownerUid);

  // Logo
  const img = document.getElementById('logoPreviewImg');
  const empty = document.getElementById('logoPreviewEmpty');
  if (img && empty) {
    if (p.logo) { img.src = p.logo; img.style.display = 'block'; empty.style.display = 'none'; }
    else { img.style.display = 'none'; empty.style.display = 'block'; }
  }

  // User info on settings page
  if (conCurrentUser) {
    const name = conCurrentUser.displayName || conCurrentUser.email || '';
    const sName = document.getElementById('settUserName');
    const sEmail = document.getElementById('settUserEmail');
    const sImg = document.getElementById('settAvatarImg');
    const sInit = document.getElementById('settAvatarInitial');
    if (sName) sName.textContent = name;
    if (sEmail) sEmail.textContent = conCurrentUser.email || '';
    if (conCurrentUser.photoURL && sImg) {
      sImg.src = conCurrentUser.photoURL;
      sImg.style.display = 'block';
      if (sInit) sInit.style.display = 'none';
    } else if (sInit) {
      sInit.textContent = (name[0] || '?').toUpperCase();
    }
  }
}

function saveCompanyProfile() {
  if (!conDb) return;
  const profile = {
    companyName: document.getElementById('settCompanyName')?.value.trim() || '',
    phone: document.getElementById('settPhone')?.value.trim() || '',
    email: document.getElementById('settEmail')?.value.trim() || '',
    website: document.getElementById('settWebsite')?.value.trim() || '',
    address: document.getElementById('settAddress')?.value.trim() || '',
    checkPayableTo: document.getElementById('settCheckPayableTo')?.value.trim() || '',
    license: document.getElementById('settLicense')?.value.trim() || '',
    insurance: document.getElementById('settInsurance')?.value.trim() || '',
    logo: companyProfile.logo || '',
    payTerms: parseInt(document.getElementById('settPayTerms')?.value) || 30,
    taxRate: parseFloat(document.getElementById('settTaxRate')?.value) || 0,
    invNotes: document.getElementById('settInvNotes')?.value.trim() || '',
    defaultMaterialsMarkup: parseFloat(document.getElementById('settMaterialsMarkup')?.value),
    defaultLaborMarkup: parseFloat(document.getElementById('settLaborMarkup')?.value),
    burdenRatePerManHour: parseFloat(document.getElementById('settBurdenRate')?.value),
    otWeeklyThreshold: parseFloat(document.getElementById('settOtThreshold')?.value),
    otMultiplier: parseFloat(document.getElementById('settOtMultiplier')?.value),
    weekStartDay: document.getElementById('settWeekStart')?.value || 'mon',
    ownerUid: document.getElementById('settPlannerxdOwnerUid')?.value.trim() || '',
    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
  };
  if (isNaN(profile.defaultMaterialsMarkup)) profile.defaultMaterialsMarkup = 25;
  if (isNaN(profile.defaultLaborMarkup)) profile.defaultLaborMarkup = 15;
  if (isNaN(profile.burdenRatePerManHour)) profile.burdenRatePerManHour = 60;
  if (isNaN(profile.otWeeklyThreshold)) profile.otWeeklyThreshold = 40;
  if (isNaN(profile.otMultiplier)) profile.otMultiplier = 1.5;

  coll('settings').doc('company').set(profile)
    .then(() => {
      companyProfile = profile;
      // Show saved confirmation
      const msg = document.getElementById('settSavedMsg');
      if (msg) { msg.style.display = 'block'; setTimeout(() => msg.style.display = 'none', 3000); }
      // Update invoice defaults
      const invNotesEl = document.getElementById('invNotes');
      if (invNotesEl && !invNotesEl.value) invNotesEl.value = profile.invNotes;
    })
    .catch(e => alert('Error saving: ' + e.message));
}

function handleLogoUpload(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    // Compress logo
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const max = 300;
      const scale = Math.min(1, max / Math.max(img.width, img.height));
      canvas.width = Math.floor(img.width * scale);
      canvas.height = Math.floor(img.height * scale);
      canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
      const dataUrl = canvas.toDataURL('image/png', 0.85);
      companyProfile.logo = dataUrl;
      const previewImg = document.getElementById('logoPreviewImg');
      const previewEmpty = document.getElementById('logoPreviewEmpty');
      if (previewImg) { previewImg.src = dataUrl; previewImg.style.display = 'block'; }
      if (previewEmpty) previewEmpty.style.display = 'none';
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function clearLogo() {
  companyProfile.logo = '';
  const img = document.getElementById('logoPreviewImg');
  const empty = document.getElementById('logoPreviewEmpty');
  if (img) { img.src = ''; img.style.display = 'none'; }
  if (empty) empty.style.display = 'block';
}

// ── Update sidebar with company name ──
function updateSidebarUserInfo() {
  const companyTag = document.getElementById('ktCompanyTag');
  if (companyTag && companyProfile.companyName) {
    companyTag.textContent = companyProfile.companyName;
  }
}

// ── Patch printInvoiceData to use company profile ──
const _origPrintInvoiceData = printInvoiceData;
function renderInvoiceDocumentHtml(inv, job, otherInvoices, forPrint) {
  const co = companyProfile;
  const fmt = v => '$' + Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});

  // Determine if this is a payment schedule invoice
  const isScheduled = (inv.type||'').toLowerCase().includes('deposit') ||
    (inv.lineItems||[]).some(li => /deposit|progress|final|payment/i.test(li.desc||''));

  // Project total from job
  const projectTotal = job?.contractValue || job?.approvedOrders || 0;

  // True cumulative remaining balance — subtract what's already been paid on
  // OTHER invoices for this job (e.g. a deposit already collected), not just
  // this invoice's own total. Without this, a later progress/final invoice
  // would show an inflated balance as if the deposit had never been paid.
  const collectedElsewhere = (otherInvoices || []).reduce((s, i) => s + (i.amtPaid || 0), 0);
  const remainingAfterThis = Math.max(0, projectTotal - collectedElsewhere - (inv.total || 0));

  // Build line rows
  const lineRows = (inv.lineItems||[]).map(item => {
    const amt = (item.qty||1) * (item.rate||0);
    const pct = projectTotal > 0 ? ' (' + Math.round(amt/projectTotal*100) + '% of project)' : '';
    return '<tr>' +
      '<td style="padding:10px 6px;border-bottom:1px solid #e5e7eb;font-size:.92rem">' + esc(item.desc||'') + '<span style="color:#9ca3af;font-size:.8rem">' + pct + '</span></td>' +
      '<td style="padding:10px 6px;border-bottom:1px solid #e5e7eb;text-align:right;font-size:.92rem">' + (item.qty||1) + '</td>' +
      '<td style="padding:10px 6px;border-bottom:1px solid #e5e7eb;text-align:right;font-weight:800;font-size:.95rem">' + fmt(amt) + '</td>' +
      '</tr>';
  }).join('');

  const logoHtml = co.logo ? '<img src="' + co.logo + '" style="height:64px;object-fit:contain;margin-bottom:8px" /><br>' : '';

  // Project summary block for scheduled payments
  const projectSummary = projectTotal > 0 ? (
    '<div style="background:#fffbeb;border:1px solid #fbbf24;border-radius:10px;padding:16px;margin-bottom:24px">' +
    '<div style="font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:#92400e;margin-bottom:8px">Project Summary</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px">' +
    '<div><div style="font-size:.7rem;color:#6b7280;text-transform:uppercase;letter-spacing:.05em">Total Project Value</div><div style="font-size:1.1rem;font-weight:900;color:#1a1a1a">' + fmt(projectTotal) + '</div></div>' +
    '<div><div style="font-size:.7rem;color:#6b7280;text-transform:uppercase;letter-spacing:.05em">This Invoice</div><div style="font-size:1.1rem;font-weight:900;color:#d97706">' + fmt(inv.total||0) + '</div></div>' +
    '<div><div style="font-size:.7rem;color:#6b7280;text-transform:uppercase;letter-spacing:.05em">Remaining Balance</div><div style="font-size:1.1rem;font-weight:900;color:#374151">' + fmt(remainingAfterThis) + '</div></div>' +
    '</div></div>'
  ) : '';

  return '<!DOCTYPE html><html><head><title>Invoice ' + (inv.number||'') + '</title>' +
    '<style>' +
    '@import url(\'https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap\');' +
    '* { box-sizing: border-box; }' +
    'body{font-family:\'Inter\',Arial,sans-serif;color:#1f2937;max-width:820px;margin:0 auto;padding:48px 40px;line-height:1.5}' +
    'table{width:100%;border-collapse:collapse}' +
    '.header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:4px solid #d97706;padding-bottom:24px;margin-bottom:24px}' +
    '.label{font-size:.7rem;text-transform:uppercase;letter-spacing:.07em;color:#9ca3af;font-weight:700}' +
    '@media print{body{padding:20px 30px}}' +
    '</style></head><body>' +

    // Header
    '<div class="header">' +
    '<div>' + logoHtml +
    '<div style="font-size:1.4rem;font-weight:900;color:#1a1a1a">' + esc(co.companyName||'') + '</div>' +
    (co.address ? '<div style="color:#6b7280;font-size:.84rem">' + esc(co.address) + '</div>' : '') +
    (co.phone ? '<div style="color:#6b7280;font-size:.84rem">' + esc(co.phone) + '</div>' : '') +
    (co.email ? '<div style="color:#6b7280;font-size:.84rem">' + esc(co.email) + '</div>' : '') +
    (co.license ? '<div style="color:#6b7280;font-size:.76rem">License: ' + esc(co.license) + '</div>' : '') +
    '</div>' +
    '<div style="text-align:right">' +
    '<div style="font-size:1.8rem;font-weight:900;color:#d97706">INVOICE</div>' +
    '<div style="font-size:1.1rem;font-weight:800">' + esc(inv.number||'') + '</div>' +
    '<div style="margin-top:4px;background:' + (inv.status==='Paid'?'#dcfce7':inv.status==='Overdue'?'#fee2e2':'#fef9c3') + ';color:' + (inv.status==='Paid'?'#166534':inv.status==='Overdue'?'#991b1b':'#854d0e') + ';padding:3px 10px;border-radius:999px;font-size:.78rem;font-weight:800;display:inline-block">' + (inv.status||'Draft') + '</div>' +
    '</div></div>' +

    // Bill to / Invoice details
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:28px">' +
    '<div style="padding:16px 20px;background:#f9fafb;border-radius:10px;border:1px solid #e5e7eb">' +
    '<div class="label" style="margin-bottom:6px">Bill To</div>' +
    '<div style="font-weight:700;font-size:1.05rem;color:#111827">' + esc(job?.client||'') + '</div>' +
    '<div style="color:#374151;font-size:.9rem;margin-top:2px">' + esc(job?.name||'') + '</div>' +
    '<div style="color:#6b7280;font-size:.84rem">' + esc(job?.address||'') + '</div>' +
    '</div>' +
    '<div style="text-align:right;padding:16px 4px">' +
    '<div style="margin-bottom:5px"><span class="label">Invoice Date: </span>' + (inv.date||'') + '</div>' +
    '<div style="margin-bottom:5px"><span class="label">Due Date: </span><strong>' + (inv.dueDate||'') + '</strong></div>' +
    '<div><span class="label">Type: </span>' + (inv.type||'') + '</div>' +
    (job?.jobNumber ? '<div style="margin-top:5px"><span class="label">Job #: </span>' + esc(job.jobNumber) + '</div>' : '') +
    '</div></div>' +

    // Project summary (for deposit/progress invoices)
    projectSummary +

    // Line items
    '<table style="margin-bottom:24px">' +
    '<thead><tr style="background:#f9fafb">' +
    '<th style="padding:10px 6px;text-align:left;font-size:.72rem;text-transform:uppercase;color:#6b7280;letter-spacing:.05em">Description</th>' +
    '<th style="padding:10px 6px;text-align:right;font-size:.72rem;text-transform:uppercase;color:#6b7280;letter-spacing:.05em">Qty</th>' +
    '<th style="padding:10px 6px;text-align:right;font-size:.72rem;text-transform:uppercase;color:#6b7280;letter-spacing:.05em">Amount</th>' +
    '</tr></thead>' +
    '<tbody>' + lineRows + '</tbody>' +
    '<tfoot>' +
    (inv.taxAmt>0 ? '<tr><td colspan="2" style="padding:8px 6px;text-align:right;color:#6b7280">Tax (' + (inv.taxRate||0) + '%)</td><td style="padding:8px 6px;text-align:right">' + fmt(inv.taxAmt) + '</td></tr>' : '') +
    '<tr style="border-top:2px solid #d97706"><td colspan="2" style="padding:12px 6px;text-align:right;font-weight:900;font-size:1.1rem">AMOUNT DUE</td><td style="padding:12px 6px;text-align:right;font-weight:900;font-size:1.2rem;color:#d97706">' + fmt(inv.total||0) + '</td></tr>' +
    ((inv.amtPaid||0)>0 ? '<tr><td colspan="2" style="padding:6px;text-align:right;color:#059669">Amount Paid</td><td style="padding:6px;text-align:right;color:#059669">-' + fmt(inv.amtPaid) + '</td></tr><tr><td colspan="2" style="padding:6px;text-align:right;font-weight:700">Balance Due</td><td style="padding:6px;text-align:right;font-weight:800;color:#d97706">' + fmt(Math.max(0,(inv.total||0)-(inv.amtPaid||0))) + '</td></tr>' : '') +
    '</tfoot></table>' +

    (inv.notes ? '<div style="background:#f9fafb;border-radius:8px;padding:14px;font-size:.85rem;color:#4b5563;margin-bottom:20px"><strong>Notes & Terms:</strong><br><br>' + esc(inv.notes) + '</div>' : '') +

    (inv.paymentLink ?
      '<div style="text-align:center;margin:24px 0">' +
      '<a href="' + inv.paymentLink + '" style="display:inline-block;background:#d97706;color:#fff;font-size:1.1rem;font-weight:800;padding:16px 48px;border-radius:12px;text-decoration:none;letter-spacing:.02em">💳 Pay Now</a>' +
      '<div style="font-size:.76rem;color:#9ca3af;margin-top:8px">Click to pay securely</div>' +
      '</div>' : '') +

    remittanceHtml() +

    '<div style="margin-top:32px;padding-top:16px;border-top:1px solid #e5e7eb;text-align:center;color:#9ca3af;font-size:.75rem">' +
    (co.companyName||'') + (co.phone?' · '+co.phone:'') + (co.email?' · '+co.email:'') +
    '<br>Powered by JOBSMETRIX Construction Management' +
    '</div>' +
    (forPrint ? '<script>window.print();<\/script>' : '') + '</body></html>';
}

// Thin wrapper: opens the print popup and writes the same HTML the
// email preview iframe renders via renderInvoiceDocumentHtml() above
// -- one source of truth for what an invoice document actually looks
// like, whether it's being printed or previewed before emailing.
function printInvoiceData(inv, job, otherInvoices, preOpenedWin) {
  const win = preOpenedWin || window.open('', '_blank');
  if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
  win.document.open();
  win.document.write(renderInvoiceDocumentHtml(inv, job, otherInvoices, true));
  win.document.close();
}
window.printInvoiceData = printInvoiceData;

