// ── Signup domain restriction ─────────────────────────────────────
// Only these domains may create a NEW company via onboarding. Invited
// members on ANY domain still get in through the memberEmails check in
// resolveCompany — this only closes the "signed in, no company found →
// create your own" path that let uninvited strangers spin up companies.
// Enforced server-side too (firestore.rules, companies create rule), so
// keep this list and the rules pattern in sync when adding domains.
const SIGNUP_ALLOWED_DOMAINS = ['7pillarsgroup.org', 'jtxdgroup.com'];

function canCreateCompany(email) {
  const domain = (email || '').toLowerCase().split('@')[1] || '';
  return SIGNUP_ALLOWED_DOMAINS.includes(domain);
}

function showAccessDenied(user) {
  const wall = document.getElementById('ktAuthWall');
  if (wall) wall.style.display = 'none';
  const app = document.getElementById('ktApp');
  if (app) app.style.display = 'none';

  let denied = document.getElementById('ktAccessDenied');
  if (!denied) {
    denied = document.createElement('div');
    denied.id = 'ktAccessDenied';
    denied.style.cssText = 'position:fixed;inset:0;background:#060e1e;display:flex;align-items:center;justify-content:center;z-index:99999;padding:20px';
    document.body.appendChild(denied);
  }
  const email = (user && user.email) || '';
  denied.innerHTML = `
    <div style="background:rgba(8,18,36,.95);border:1px solid rgba(239,83,80,.4);border-radius:20px;padding:36px;max-width:480px;width:100%;text-align:center">
      <div style="font-size:2.2rem;margin-bottom:10px">🔒</div>
      <div style="font-size:1.4rem;font-weight:900;color:#eaf0fb;margin-bottom:8px">Access Restricted</div>
      <div style="color:#94a3b8;font-size:.9rem;line-height:1.55;margin-bottom:24px">
        This JOBSMETRIX workspace is invite-only.<br>
        <span style="color:#eaf0fb;font-weight:600">${email.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</span> isn't on a team roster yet.<br>
        Ask your administrator to add you, then sign in again.
      </div>
      <button onclick="conSignOut();document.getElementById('ktAccessDenied').style.display='none';document.getElementById('ktAuthWall').style.display='';" style="padding:12px 28px;background:rgba(217,119,6,.15);border:1px solid rgba(217,119,6,.5);border-radius:10px;color:#f59e0b;font-size:.95rem;font-weight:700;cursor:pointer">
        Sign Out
      </button>
    </div>
  `;
  denied.style.display = 'flex';
}

function resolveCompany(user, callback) {
  const email = (user.email || '').toLowerCase();

  // 1. Check if this user owns a company
  conDb.collection('companies').where('ownerEmail', '==', email).limit(1).get()
    .then(snap => {
      if (!snap.empty) {
        // Found their company — they are the ownerEmail, so definitionally Owner
        currentCompanyId = snap.docs[0].id;
        isCompanyOwnerByEmail = true;
        console.log('JOBSMETRIX: Loaded company', currentCompanyId);
        if (callback) callback();
        return;
      }

      // 2. Check if they're a member of a company (invited user)
      conDb.collection('companies').where('memberEmails', 'array-contains', email).limit(1).get()
        .then(snap2 => {
          if (!snap2.empty) {
            currentCompanyId = snap2.docs[0].id;
            console.log('JOBSMETRIX: Joined company as member', currentCompanyId);
            if (callback) callback();
            return;
          }

          // 3. No company found — allowlisted domains may create one;
          // anyone else hits the access-denied wall instead of onboarding.
          if (canCreateCompany(email)) {
            showCompanyOnboarding(user, callback);
          } else {
            showAccessDenied(user);
          }
        })
        .catch(e => {
          // Previously unguarded — a denied/failed query here silently hung
          // the login screen forever with no error shown (root-caused
          // 7/30/26). Surface it and fall through the same way the outer
          // catch below does, instead of leaving the user stuck.
          console.error('resolveCompany memberEmails lookup error:', e);
          if (canCreateCompany(email)) {
            showCompanyOnboarding(user, callback);
          } else {
            showAccessDenied(user);
          }
        });
    })
    .catch(e => {
      console.error('resolveCompany error:', e);
      // Fallback for first-ever user — create company immediately
      // (still domain-gated so an error can't open a back door)
      if (canCreateCompany(email)) {
        showCompanyOnboarding(user, callback);
      } else {
        showAccessDenied(user);
      }
    });
}

function showCompanyOnboarding(user, callback) {
  // Hide auth wall, show onboarding overlay
  document.getElementById('ktAuthWall').style.display = 'none';
  document.getElementById('ktApp').style.display = 'none';

  let onboarding = document.getElementById('ktOnboarding');
  if (!onboarding) {
    onboarding = document.createElement('div');
    onboarding.id = 'ktOnboarding';
    onboarding.style.cssText = 'position:fixed;inset:0;background:#060e1e;display:flex;align-items:center;justify-content:center;z-index:99999;padding:20px';
    onboarding.innerHTML = `
      <div style="background:rgba(8,18,36,.95);border:1px solid rgba(217,119,6,.4);border-radius:20px;padding:36px;max-width:480px;width:100%">
        <div style="font-size:1.8rem;font-weight:900;color:#f59e0b;margin-bottom:6px">Welcome to JOBSMETRIX</div>
        <div style="color:#94a3b8;font-size:.88rem;margin-bottom:28px">Let's set up your company to get started.</div>
        <label style="display:block;font-size:.78rem;color:#94a3b8;margin-bottom:5px">Company Name *</label>
        <input id="onboardCompanyName" placeholder="Jason Hudson Construction" style="width:100%;padding:12px 14px;background:rgba(8,19,37,.8);border:1px solid rgba(217,119,6,.3);border-radius:10px;color:#eaf0fb;font-size:.95rem;margin-bottom:16px;box-sizing:border-box" />
        <label style="display:block;font-size:.78rem;color:#94a3b8;margin-bottom:5px">Your Name *</label>
        <input id="onboardOwnerName" placeholder="${user.displayName || ''}" value="${user.displayName || ''}" style="width:100%;padding:12px 14px;background:rgba(8,19,37,.8);border:1px solid rgba(217,119,6,.3);border-radius:10px;color:#eaf0fb;font-size:.95rem;margin-bottom:16px;box-sizing:border-box" />
        <label style="display:block;font-size:.78rem;color:#94a3b8;margin-bottom:5px">Phone</label>
        <input id="onboardPhone" placeholder="(314) 555-0100" style="width:100%;padding:12px 14px;background:rgba(8,19,37,.8);border:1px solid rgba(217,119,6,.3);border-radius:10px;color:#eaf0fb;font-size:.95rem;margin-bottom:24px;box-sizing:border-box" />
        <button onclick="createCompany('${user.email}')" style="width:100%;padding:14px;background:#d97706;border:none;border-radius:10px;color:#fff;font-size:1rem;font-weight:700;cursor:pointer">
          Create My Company →
        </button>
        <div id="onboardError" style="color:#f87171;font-size:.82rem;margin-top:10px;display:none"></div>
      </div>
    `;
    document.body.appendChild(onboarding);
  }
  onboarding.style.display = 'flex';
  window._onboardCallback = callback;
}

function createCompany(ownerEmail) {
  const name = document.getElementById('onboardCompanyName')?.value.trim();
  const ownerName = document.getElementById('onboardOwnerName')?.value.trim();
  const phone = document.getElementById('onboardPhone')?.value.trim();
  const errEl = document.getElementById('onboardError');

  if (!name) {
    if (errEl) { errEl.textContent = 'Company name is required.'; errEl.style.display = 'block'; }
    return;
  }

  const btn = document.querySelector('#ktOnboarding button');
  if (btn) { btn.disabled = true; btn.textContent = 'Creating...'; }

  const companyData = {
    name,
    ownerEmail: ownerEmail.toLowerCase(),
    ownerName: ownerName || ownerEmail,
    phone: phone || '',
    memberEmails: [ownerEmail.toLowerCase()],
    plan: 'trial',
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
  };

  conDb.collection('companies').add(companyData)
    .then(ref => {
      currentCompanyId = ref.id;
      console.log('JOBSMETRIX: Created company', currentCompanyId);

      // Also set up the settings/company doc with company profile
      return coll('settings').doc('company').set({
        companyName: name,
        phone: phone || '',
        email: ownerEmail,
        address: '',
        license: '',
        insurance: '',
        logo: '',
        updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
      });
    })
    .then(() => {
      const onboarding = document.getElementById('ktOnboarding');
      if (onboarding) onboarding.style.display = 'none';
      if (window._onboardCallback) window._onboardCallback();
    })
    .catch(e => {
      if (errEl) { errEl.textContent = 'Error: ' + e.message; errEl.style.display = 'block'; }
      if (btn) { btn.disabled = false; btn.textContent = 'Create My Company →'; }
    });
}
window.createCompany = createCompany;

// Returns the team members map regardless of whether they're nested under
// `members` (current write path) or sitting at the top level of the team doc
// (legacy/imported shape). Filters out non-member metadata fields.
function extractTeamMembers(data) {
  if (!data) return {};
  if (data.members && typeof data.members === 'object') return data.members;
  // Legacy shape: members are top-level fields on the team doc. Keep only
  // entries that look like a member record (have an email or role).
  const out = {};
  Object.keys(data).forEach(k => {
    const v = data[k];
    if (v && typeof v === 'object' && (v.email || v.role)) out[k] = v;
  });
  return out;
}

function loadUserRole(user, callback) {
  if (!conDb) { currentUserRole = 'Owner'; if(callback) callback(); return; }

  const email = (user.email || '').toLowerCase();

  coll('settings').doc('team').get()
    .then(doc => {
      if (!doc.exists) {
        // First user ever — make them Owner and create team doc
        currentUserRole = 'Owner';
        currentUserTeamData = { email, name: user.displayName || email, role: 'Owner', addedAt: new Date().toISOString() };
        const teamData = {};
        teamData[email.replace(/\./g,'_')] = currentUserTeamData;
        coll('settings').doc('team').set({ members: teamData })
          .catch(() => {});
        // Immediately update role display
        const roleElFirst = document.getElementById('ktUserRole');
        if (roleElFirst) { roleElFirst.textContent = 'Owner'; roleElFirst.style.color = KYTRAC_ROLES['Owner'].color; }
      } else {
        const members = extractTeamMembers(doc.data());
        const key = email.replace(/\./g,'_');
        if (members[key]) {
          currentUserRole = members[key].role || 'Field Technician';
          currentUserTeamData = members[key];
        } else if (isCompanyOwnerByEmail) {
          // Being the company's ownerEmail is always sufficient for
          // access on its own - it must never be gated behind also
          // having a matching team-roster entry. This specifically
          // matters whenever the Owner's login email changes (their
          // ownerEmail gets updated, but the old roster entry is still
          // keyed by their PREVIOUS email) - self-heal by creating the
          // missing roster entry here instead of locking them out.
          currentUserRole = 'Owner';
          currentUserTeamData = { email, name: user.displayName || email, role: 'Owner', addedAt: new Date().toISOString() };
          coll('settings').doc('team').set({ members: { [key]: currentUserTeamData } }, { merge: true }).catch(() => {});
        } else {
          // Email not in team — deny access
          conAuth.signOut();
          alert('Access denied. Contact your Owner to be added to the team.');
          return;
        }
        // The company's ownerEmail is always Owner. If a stale role says
        // otherwise, correct it in memory and persist to the team doc.
        if (isCompanyOwnerByEmail && currentUserRole !== 'Owner') {
          currentUserRole = 'Owner';
          coll('settings').doc('team').set(
            { members: { [key]: { role: 'Owner', updatedAt: new Date().toISOString() } } },
            { merge: true }
          ).catch(() => {});
        }
      }
      // Update role display
      const roleEl = document.getElementById('ktUserRole');
      if (roleEl) {
        const roleData = KYTRAC_ROLES[currentUserRole] || {};
        roleEl.textContent = currentUserRole || 'Member';
        roleEl.style.color = roleData.color || 'var(--muted)';
      }
      // Apply role-based permissions to UI
      setTimeout(applyRolePermissions, 100);
      if (callback) callback();
    })
    .catch(() => {
      // Firestore not ready yet — allow as owner for initial setup
      currentUserRole = 'Owner';
      if (callback) callback();
    });
}

// ── Team management ──
// Tracks which team members currently have their QuickBooks ID / phone
// fields open for editing (by sanitized key). Members with saved values
// render collapsed into a compact summary by default - only entries with
// NOTHING saved yet, or that the Owner explicitly clicked Edit on, show
// the open input fields. Purely a UI-state set, not persisted anywhere.
let _teamEditOpen = {};
let _lastTeamMemberList = [];

function toggleTeamMemberEdit(key) {
  _teamEditOpen[key] = !_teamEditOpen[key];
  renderTeamMemberList();
}
window.toggleTeamMemberEdit = toggleTeamMemberEdit;

function loadTeamMembers() {
  if (!conDb) return;
  const list = document.getElementById('teamMemberList');
  const form = document.getElementById('addMemberForm');

  // Previously this whole function returned early for non-Owners,
  // which meant _lastTeamMemberList — and therefore every per-person
  // burdened rate — never loaded at all for anyone but the literal
  // Owner role. Jason (Director of Operations, full-access override,
  // but role label "Sales") would silently get the flat fallback rate
  // for cost calculations, with no indication his real rate data
  // wasn't being used. The DATA needs to load for everyone; only the
  // ability to SEE/EDIT the list (sensitive payroll info) stays
  // Owner-restricted, below.
  if (currentUserRole !== 'Owner') {
    if (form) form.style.display = 'none';
    const section = document.getElementById('teamSection');
    if (section) section.style.display = 'none';
  }

  coll('settings').doc('team').get()
    .then(doc => {
      const members = doc.exists ? extractTeamMembers(doc.data()) : {};
      _lastTeamMemberList = Object.values(members).sort((a,b) => {
        const la = KYTRAC_ROLES[a.role]?.level || 0;
        const lb = KYTRAC_ROLES[b.role]?.level || 0;
        return lb - la;
      });
      renderTeamMemberList();
    })
    .catch(() => {
      if (list) list.innerHTML = '<div class="small muted">Could not load team members.</div>';
    });
}

function renderTeamMemberList() {
  const list = document.getElementById('teamMemberList');
  if (!list) return;
  const memberList = _lastTeamMemberList;

  if (!memberList.length) {
    list.innerHTML = '<div class="small muted" style="font-style:italic">No team members yet.</div>';
    return;
  }

  list.innerHTML = memberList.map(m => {
    const roleData = KYTRAC_ROLES[m.role] || { color: 'var(--muted)' };
    const isCurrentUser = (m.email || '').toLowerCase() === (conCurrentUser?.email || '').toLowerCase();
    const key = (m.email || '').replace(/\./g,'_');
    const hasSavedInfo = !!(m.qbEmployeeId || m.phone || m.burdenedRate);
    const isOpen = _teamEditOpen[key] || !hasSavedInfo; // empty state always shows open inputs

    const editableFields = `
      <div style="display:flex;align-items:center;gap:6px;margin-top:5px">
        <input id="qbEmpId_${key}" value="${esc(m.qbEmployeeId||'')}" placeholder="QuickBooks Employee ID (for payroll sync)"
          style="font-size:.72rem;padding:3px 8px;width:220px;background:rgba(8,19,37,.6);border:1px solid var(--line);border-radius:6px;color:var(--muted)" />
        <button class="btn" style="padding:2px 8px;font-size:.7rem" onclick="saveTeamMemberQBId('${key}')">Save</button>
      </div>
      <div style="display:flex;align-items:center;gap:6px;margin-top:5px">
        <input id="phone_${key}" value="${esc(m.phone||'')}" placeholder="Cell phone (for @mention SMS alerts)" type="tel"
          style="font-size:.72rem;padding:3px 8px;width:220px;background:rgba(8,19,37,.6);border:1px solid var(--line);border-radius:6px;color:var(--muted)" />
        <button class="btn" style="padding:2px 8px;font-size:.7rem" onclick="saveTeamMemberPhone('${key}')">Save</button>
      </div>
      <div style="display:flex;align-items:center;gap:6px;margin-top:5px">
        <span style="font-size:.72rem;color:var(--muted);min-width:90px">Payment Type</span>
        <select id="payType_${key}" onchange="saveTeamMemberPaymentType('${key}')"
          style="font-size:.72rem;padding:3px 8px;width:220px;background:rgba(8,19,37,.6);border:1px solid var(--line);border-radius:6px;color:var(--muted)">
          <option value="hourly" ${(m.paymentType||'hourly')==='hourly'?'selected':''}>Hourly (W-2 — hours × rate = cost)</option>
          <option value="subcontractor" ${m.paymentType==='subcontractor'?'selected':''}>Flat-Rate Subcontractor (1099 — paid a job price, not by the hour)</option>
        </select>
      </div>
      <div style="display:flex;align-items:center;gap:6px;margin-top:5px">
        <span style="font-size:.72rem;color:var(--muted)">$</span>
        <input id="rate_${key}" value="${m.burdenedRate!=null?m.burdenedRate:''}" placeholder="Rate" type="number" step="0.01" min="0"
          style="font-size:.72rem;padding:3px 8px;width:220px;background:rgba(8,19,37,.6);border:1px solid var(--line);border-radius:6px;color:var(--muted)" />
        <span style="font-size:.7rem;color:var(--muted)">/hr</span>
        <button class="btn" style="padding:2px 8px;font-size:.7rem" onclick="saveTeamMemberRate('${key}')">Save</button>
      </div>
      <div style="font-size:.66rem;color:var(--muted);margin-top:3px;max-width:340px;line-height:1.4">
        <strong>Hourly people:</strong> this IS their true cost — hours logged × this rate = real job cost, automatically.
        <strong>Flat-rate subcontractors:</strong> this is just your target/budgeted rate for figuring out what to OFFER them (e.g. 240 hrs × $85 = a $20,400 job offer) — it does NOT drive actual cost. Their real cost is the agreed price you enter per job (Financials tab, Subcontractor line). Clock-in/out still works for them either way — for a flat-rate person their hours feed Estimated vs. Actual comparisons only, so you can tell whether your pricing was right, without it changing what you owe.
      </div>
      <div style="font-size:.66rem;color:var(--muted);margin-top:3px;max-width:340px;line-height:1.4">
        By saving your number you consent to receive SMS job notifications from JOBSMETRIX. Msg &amp; data rates may apply. Reply STOP to opt out.
        <a href="https://jobsmetrix.com/privacy" target="_blank" style="color:var(--amber);text-decoration:none">Privacy Policy</a>
      </div>
      ${hasSavedInfo ? `<button class="btn" style="padding:2px 8px;font-size:.7rem;margin-top:5px" onclick="toggleTeamMemberEdit('${key}')">✕ Close</button>` : ''}
    `;

    const collapsedSummary = `
      <div style="display:flex;align-items:center;gap:10px;margin-top:5px;font-size:.76rem;color:var(--muted)">
        ${m.qbEmployeeId ? `<span>🧾 QB ID: ${esc(m.qbEmployeeId)}</span>` : ''}
        ${m.phone ? `<span>📱 ${esc(m.phone)}</span>` : ''}
        ${m.burdenedRate!=null ? `<span>💰 $${Number(m.burdenedRate).toFixed(2)}/hr</span>` : ''}
        ${m.paymentType==='subcontractor' ? `<span>📄 1099 Flat-Rate</span>` : ''}
        <button class="btn" style="padding:2px 8px;font-size:.7rem" onclick="toggleTeamMemberEdit('${key}')">✏️ Edit</button>
      </div>
    `;

    return `<div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid rgba(110,145,210,.07);flex-wrap:wrap">
      <div style="width:36px;height:36px;border-radius:50%;background:${roleData.color}22;border:2px solid ${roleData.color};display:flex;align-items:center;justify-content:center;font-size:.9rem;font-weight:800;color:${roleData.color};flex-shrink:0">
        ${(m.name||m.email||'?')[0].toUpperCase()}
      </div>
      <div style="flex:1;min-width:0">
        <div style="font-weight:700;font-size:.9rem">${esc(m.name||m.email||'')}</div>
        <div style="font-size:.78rem;color:var(--muted)">${esc(m.email||'')}</div>
        ${isOpen ? editableFields : collapsedSummary}
        <label style="display:flex;align-items:center;gap:6px;margin-top:6px;font-size:.72rem;color:var(--muted);cursor:pointer">
          <input type="checkbox" ${m.fullAccessOverride ? 'checked' : ''} onchange="setTeamMemberFullAccessOverride('${key}',this.checked)" />
          Full Access Override <span style="color:#9ca3af">(keeps their role label, but grants Owner-level permissions everywhere except adding/removing/promoting other team members — that stays Owner-only)</span>
        </label>
      </div>
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        <select onchange="updateMemberRole('${key}',this.value)"
          style="font-size:.78rem;padding:4px 8px;background:var(--input-bg);border:1px solid ${roleData.color}44;color:${roleData.color};border-radius:7px;font-weight:700"
          ${isCurrentUser && m.role==='Owner' ? 'title="You are the account Owner"' : ''}>
          ${Object.keys(KYTRAC_ROLES).map(r => `<option value="${r}" ${r===m.role?'selected':''}>${r}</option>`).join('')}
        </select>
        ${!isCurrentUser ? `<button class="btn btn-danger" onclick="removeMember('${key}')" style="padding:4px 8px;font-size:.75rem">Remove</button>` : '<span class="small muted">(you)</span>'}
      </div>
    </div>`;
  }).join('');
}

function addTeamMember() {
  if (currentUserRole !== 'Owner') { alert('Only Owners can add team members.'); return; }
  const email = (document.getElementById('newMemberEmail')?.value || '').trim().toLowerCase();
  const name = (document.getElementById('newMemberName')?.value || '').trim();
  const role = document.getElementById('newMemberRole')?.value || 'Field Technician';

  if (!email || !email.includes('@')) { alert('Enter a valid email address.'); return; }
  if (!name) { alert('Enter the team member name.'); return; }

  const key = email.replace(/\./g,'_');
  const memberData = { email, name, role, addedAt: new Date().toISOString(), addedBy: conCurrentUser?.email || '' };

  Promise.all([
    coll('settings').doc('team').set(
      { members: { [key]: memberData } },
      { merge: true }
    ),
    // CRITICAL: without this, resolveCompany() can never find this
    // company for the invited member - they'd get bounced into creating
    // a brand new separate company on their first login instead of
    // joining this one. This was a latent bug until now.
    conDb.collection('companies').doc(currentCompanyId).update({
      memberEmails: firebase.firestore.FieldValue.arrayUnion(email)
    })
  ]).then(() => {
    document.getElementById('newMemberEmail').value = '';
    document.getElementById('newMemberName').value = '';
    loadTeamMembers();
    alert(`${name} added as ${role}. They can now sign in with ${email}.`);
  }).catch(e => alert('Error: ' + e.message));
}

// Backfills company.memberEmails for anyone who has a real
// settings/team.members profile but is missing from memberEmails --
// the exact gap addTeamMember's arrayUnion fix (see comment above)
// closed for everyone added AFTER that fix, but never touched anyone
// added before it. Those people look completely normal in this
// Settings page (same profile, same role) but syncMyClaims can't find
// them in memberEmails, silently clears their claims, and every
// claims-gated read after that (starting with the jobs listener)
// fails with permission-denied -- with nothing in the UI pointing
// back to memberEmails specifically as the cause. Safe to run
// anytime: arrayUnion is idempotent, so re-running with nobody
// actually missing just does nothing.
async function repairTeamMemberAccess() {
  if (currentUserRole !== 'Owner') { alert('Only Owners can run this.'); return; }
  try {
    const teamDoc = await coll('settings').doc('team').get();
    const members = teamDoc.exists ? (teamDoc.data().members || {}) : {};
    const allEmails = Object.values(members).map(m => (m.email || '').toLowerCase()).filter(Boolean);
    if (!allEmails.length) { alert('No team members found in Settings to check.'); return; }

    const companyDoc = await conDb.collection('companies').doc(currentCompanyId).get();
    const existing = new Set((companyDoc.data()?.memberEmails || []).map(e => (e || '').toLowerCase()));
    const missing = allEmails.filter(e => !existing.has(e));

    if (!missing.length) {
      alert(`Checked ${allEmails.length} team member(s) -- everyone is already correctly set up. Nothing to repair.`);
      return;
    }

    if (!confirm(`Found ${missing.length} team member(s) with a Settings profile but missing from memberEmails (the actual permission gate):\n\n${missing.join('\n')}\n\nThis is very likely why they can't fully log in / see jobs. Fix now?`)) return;

    await conDb.collection('companies').doc(currentCompanyId).update({
      memberEmails: firebase.firestore.FieldValue.arrayUnion(...missing)
    });

    alert(`Repaired ${missing.length} team member(s):\n\n${missing.join('\n')}\n\nHave them sign all the way out and back in -- their claims will sync correctly now.`);
  } catch(e) {
    alert('Repair failed: ' + e.message);
  }
}
window.repairTeamMemberAccess = repairTeamMemberAccess;

// Stores the QuickBooks Employee ID mapping for a team member — needed
// before the daily payroll clock-out sync can push anything for that
// person. Doesn't sync anything itself, just records the mapping.
function saveTeamMemberQBId(key) {
  if (currentUserRole !== 'Owner') return;
  const input = document.getElementById('qbEmpId_' + key);
  if (!input) return;
  const qbEmployeeId = input.value.trim();
  coll('settings').doc('team').set(
    { members: { [key]: { qbEmployeeId, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => {
    input.style.borderColor = '#1dbb87';
    setTimeout(() => { _teamEditOpen[key] = false; loadTeamMembers(); }, 700);
  }).catch(e => alert('Error saving QuickBooks Employee ID: ' + e.message));
}
window.saveTeamMemberQBId = saveTeamMemberQBId;

// Cell phone for @mention SMS alerts (customer-message routing). Owner-only
// to edit, same boundary as everything else in Team Management. Actual SMS
// sending happens server-side (Cloud Function + Twilio) - this just stores
// the number the function will send to.
function saveTeamMemberPhone(key) {
  if (currentUserRole !== 'Owner') return;
  const input = document.getElementById('phone_' + key);
  if (!input) return;
  const phone = input.value.trim();
  coll('settings').doc('team').set(
    { members: { [key]: { phone, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => {
    input.style.borderColor = '#1dbb87';
    setTimeout(() => { _teamEditOpen[key] = false; loadTeamMembers(); }, 700);
  }).catch(e => alert('Error saving phone number: ' + e.message));
}
window.saveTeamMemberPhone = saveTeamMemberPhone;

// Per-person burdened hourly rate — the real all-in cost per hour
// (wage + payroll tax, insurance, workers comp), NOT the customer bill
// rate. This is the foundation "true job cost" tracking depends on:
// previously the whole company shared ONE flat burden rate
// (companyProfile.burdenRatePerManHour) for everyone, which is a rough
// average at best. Per-person rates here are what getTrueLaborCost()
// (below) actually uses when they exist, falling back to the old flat
// rate for anyone without one saved yet so nothing breaks mid-rollout.
// Overtime is NOT stored separately — it's computed as this rate ×
// companyProfile.otMultiplier at calc time (JobTread's own OT rates
// came out to exactly 1.5x Standard, matching the multiplier setting
// already in Settings, so a second stored number would just be
// redundant data that could drift out of sync with the multiplier).
function saveTeamMemberRate(key) {
  if (currentUserRole !== 'Owner') return;
  const input = document.getElementById('rate_' + key);
  if (!input) return;
  const val = parseFloat(input.value);
  const burdenedRate = isNaN(val) ? null : Math.round(val * 100) / 100;
  coll('settings').doc('team').set(
    { members: { [key]: { burdenedRate, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => {
    input.style.borderColor = '#1dbb87';
    setTimeout(() => { _teamEditOpen[key] = false; loadTeamMembers(); }, 700);
  }).catch(e => alert('Error saving hourly rate: ' + e.message));
}
window.saveTeamMemberRate = saveTeamMemberRate;

// Hourly vs flat-rate-subcontractor classification. Doesn't change how
// clock-in/out works at all (same button, same feature, for anyone
// with app access) — it only changes how that clocked time gets
// INTERPRETED when computing job cost: hourly people's hours × rate
// IS their real cost; a flat-rate subcontractor's hours are informational
// only (feeds Estimated vs. Actual comparisons for future pricing
// accuracy) since what's actually owed is a separately-agreed job
// price, not hours worked.
function saveTeamMemberPaymentType(key) {
  if (currentUserRole !== 'Owner') return;
  const sel = document.getElementById('payType_' + key);
  if (!sel) return;
  coll('settings').doc('team').set(
    { members: { [key]: { paymentType: sel.value, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => {
    sel.style.borderColor = '#1dbb87';
    setTimeout(() => loadTeamMembers(), 500);
  }).catch(e => alert('Error saving payment type: ' + e.message));
}
window.saveTeamMemberPaymentType = saveTeamMemberPaymentType;

// Sets/clears the full-access override for a team member - Owner-only,
// same security boundary as other team management actions (this is what
// grants Owner-level permissions to someone with a different role label,
// e.g. Jason: role label "Sales", full access underneath).
function setTeamMemberFullAccessOverride(key, checked) {
  if (currentUserRole !== 'Owner') return;
  coll('settings').doc('team').set(
    { members: { [key]: { fullAccessOverride: checked, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => loadTeamMembers())
   .catch(e => alert('Error: ' + e.message));
}
window.setTeamMemberFullAccessOverride = setTeamMemberFullAccessOverride;

function updateMemberRole(key, newRole) {
  if (currentUserRole !== 'Owner') return;
  coll('settings').doc('team').set(
    { members: { [key]: { role: newRole, updatedAt: new Date().toISOString() } } },
    { merge: true }
  ).then(() => loadTeamMembers())
   .catch(e => alert('Error: ' + e.message));
}

function removeMember(key) {
  if (currentUserRole !== 'Owner') return;
  if (!confirm('Remove this team member? They will lose access immediately.')) return;
  coll('settings').doc('team').get()
    .then(doc => {
      if (!doc.exists) return;
      const data = doc.data();
      const members = { ...extractTeamMembers(data) };
      const removedEmail = members[key]?.email;
      delete members[key];
      // Write canonical nested shape.
      const payload = { members };
      // If this doc used the legacy top-level shape, null out the old
      // top-level member fields so they don't shadow the nested map.
      if (!data.members) {
        Object.keys(data).forEach(k => {
          const v = data[k];
          if (v && typeof v === 'object' && (v.email || v.role)) {
            payload[k] = firebase.firestore.FieldValue.delete();
          }
        });
      }
      const writes = [coll('settings').doc('team').update(payload)];
      // Also strip them from memberEmails - otherwise a removed member
      // could still resolve into this company on their next login even
      // though their team entry (and custom claims role) is gone.
      if (removedEmail) {
        writes.push(conDb.collection('companies').doc(currentCompanyId).update({
          memberEmails: firebase.firestore.FieldValue.arrayRemove(removedEmail)
        }));
      }
      return Promise.all(writes);
    })
    .then(() => loadTeamMembers())
    .catch(e => alert('Error: ' + e.message));
}

// ── Apply role-based nav visibility ──
function applyRolePermissions() {
  const role = currentUserRole;
  if (!role) return;

  // Hide nav items based on role
  const canSeeCosting = hasPermission('costing') || hasPermission('invoicing');
  const canSeeInvoicing = hasPermission('invoicing');
  const canSeeCatalog = hasPermission('catalog') || hasPermission('catalog_read');
  const canSeeSettings = isOwnerOrAdmin(); // Owner or Project Manager — team mgmt inside stays Owner-only

  // Nav items
  const navItems = {
    'invoicing': canSeeInvoicing,
    'costing': canSeeCosting,
    'catalog': canSeeCatalog,
    'settings': canSeeSettings,
    'crewmap': canViewCrewMap(),
  };

  // Field Technician sidebar allowlist -- confirmed with Travis directly
  // (a real Field Tech test account had the FULL sidebar: Change Orders,
  // Master Schedule, Documents, Customers, Vendors, Contractors, Reports,
  // and Purchase Orders all fully visible, none of which a field crew
  // member needs day to day). Kept, not hidden: Home, Notes, Messages,
  // Jobs (now filtered to assigned-only, see renderJobsBoard), To-Dos,
  // Daily Logs, Calendar, Time -- everything a field tech actually uses.
  // Job-specific Plans/Documents are still reachable through Jobs -> their
  // assigned job -> Plans tab (already in FIELD_TECH_ALLOWED_TABS), so a
  // separate company-wide Documents link isn't needed on top of that.
  if (isFieldTechRestricted()) {
    Object.assign(navItems, {
      'globalChangeOrders': false,
      'masterschedule': false,
      'documents': false,
      'customers': false,
      'vendors': false,
      'contractors': false,
      'reports': false,
      'purchaseorders': false,
      'crewmap': false,
    });
  }

  document.querySelectorAll('.kt-nav-item').forEach(btn => {
    const onclick = btn.getAttribute('onclick') || '';
    Object.entries(navItems).forEach(([key, visible]) => {
      if (onclick.includes(`'${key}'`)) {
        btn.style.display = visible ? '' : 'none';
      }
    });
  });

  // A sidebar section header (e.g. "Financials", "Account") left sitting
  // alone with every item underneath it hidden looks broken -- this can
  // happen for more than just Field Technicians (Sales/Marketing Staff
  // also lack costing/invoicing/catalog access, emptying "Financials" the
  // same way; anyone who isn't Owner/PM empties "Account"). Generic fix:
  // walk each section header and hide it too if none of its own items
  // are visible, rather than hardcoding this to one specific role.
  document.querySelectorAll('.kt-nav-section').forEach(sectionEl => {
    let sib = sectionEl.nextElementSibling;
    let anyVisible = false;
    while (sib && sib.classList && sib.classList.contains('kt-nav-item')) {
      if (sib.style.display !== 'none') anyVisible = true;
      sib = sib.nextElementSibling;
    }
    sectionEl.style.display = anyVisible ? '' : 'none';
  });

  // Hide + New Job for read-only roles
  const canCreateJobs = hasPermission('jobs') || hasPermission('jobs_sales') || isOwnerOrAdmin();
  const newJobBtn = document.getElementById('newJobBtn');
  if (newJobBtn) newJobBtn.style.display = canCreateJobs ? 'inline-flex' : 'none';

  // Show/hide team management section
  const teamSection = document.getElementById('teamSection');
  if (teamSection) teamSection.style.display = role === 'Owner' ? 'block' : 'none';

  // Field Techs get a completely different, minimal experience per
  // Travis: no left sidebar at all, just a 5-tile home screen (Time,
  // their assigned job, Calendar, Messages, To-Do). Toggled both ways
  // (not just "hide for Field Tech") so switching between test accounts
  // without a full page reload correctly restores the normal sidebar
  // for everyone else too.
  const isFT = isFieldTechRestricted();
  const sidebarEl = document.getElementById('ktSidebar');
  const mainEl = document.querySelector('.kt-main');
  const menuBtn = document.querySelector('.kt-menu-btn');
  const ftHomeBtn = document.getElementById('ktFieldTechHomeBtn');
  if (sidebarEl) sidebarEl.style.display = isFT ? 'none' : '';
  if (mainEl) {
    // .kt-main has a hardcoded margin-left/width sized for the sidebar
    // (not flex-based spacing) -- display:none on the sidebar alone
    // would leave an empty gap rather than actually reflowing.
    mainEl.style.marginLeft = isFT ? '0' : '';
    mainEl.style.width = isFT ? '100%' : '';
  }
  if (menuBtn) menuBtn.style.display = isFT ? 'none' : '';
  if (ftHomeBtn) ftHomeBtn.style.display = isFT ? '' : 'none';
  if (isFT) {
    // Land a Field Tech on their simplified home instead of the normal
    // (still-default-active-in-the-static-HTML) full dashboard.
    const dashEl = document.getElementById('ktPageDashboard');
    if (dashEl && dashEl.classList.contains('active')) {
      ktNav('fieldtechhome', null);
    }
  }
}

// Expose team functions
window.addTeamMember = addTeamMember;
window.updateMemberRole = updateMemberRole;
window.removeMember = removeMember;
window.loadTeamMembers = loadTeamMembers;
window.applyRolePermissions = applyRolePermissions;

// ════════════════════════════════════════════════════
// ── TO-DOS ──
// ════════════════════════════════════════════════════
let allTodos = [];
let _todoFilter = 'all';

function loadTodos() {
  if (!conDb) return;
  coll('todos')
    .onSnapshot(snap => {
      allTodos = [];
      snap.forEach(doc => allTodos.push({ id: doc.id, ...doc.data() }));
      allTodos.sort((a,b) => {
        const ta = a.createdAt?.toMillis ? a.createdAt.toMillis() : 0;
        const tb = b.createdAt?.toMillis ? b.createdAt.toMillis() : 0;
        return tb - ta;
      });
      renderTodos();
      updateTodoBadge();
      populateTodoJobFilter();
      populateTodoAssigneeFilter();
    }, () => {});
}

function updateTodoBadge() {
  const open = allTodos.filter(t => !t.done).length;
  const badge = document.getElementById('navTodoBadge');
  if (badge) {
    badge.style.display = open > 0 ? 'inline-flex' : 'none';
    badge.textContent = open;
  }
}

function populateTodoJobFilter() {
  const sel = document.getElementById('newTodoJobLink');
  if (!sel) return;
  const cur = sel.value;
  sel.innerHTML = '<option value="">No job linked</option>' +
    conJobs.map(j => `<option value="${j.id}" ${j.id===cur?'selected':''}>${esc(j.name)}</option>`).join('');
}

function populateTodoAssigneeFilter() {
  // Load team members for assignee dropdown
  if (!conDb) return;
  coll('settings').doc('team').get().then(doc => {
    if (!doc.exists) return;
    const members = extractTeamMembers(doc.data());
    const sel = document.getElementById('newTodoAssignee');
    if (!sel) return;
    sel.innerHTML = '<option value="">Unassigned</option>' +
      Object.values(members).map(m =>
        `<option value="${esc(m.email)}">${esc(m.name||m.email)}</option>`
      ).join('');
  }).catch(() => {});
}

function filterTodos(filter, btn) {
  _todoFilter = filter;
  document.querySelectorAll('.todo-filter-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  renderTodos();
}

function renderTodos() {
  const el = document.getElementById('todoList');
  if (!el) return;

  const today = new Date().toISOString().split('T')[0];
  const myEmail = conCurrentUser?.email || '';

  let todos = [...allTodos];
  if (_todoFilter === 'mine') todos = todos.filter(t => t.assignee === myEmail || t.createdBy === myEmail);
  if (_todoFilter === 'open') todos = todos.filter(t => !t.done);
  if (_todoFilter === 'done') todos = todos.filter(t => t.done);
  if (_todoFilter === 'high') todos = todos.filter(t => t.priority === 'high' && !t.done);
  if (_todoFilter === 'today') todos = todos.filter(t => t.dueDate === today && !t.done);

  // Stats
  const open = allTodos.filter(t => !t.done).length;
  const done = allTodos.filter(t => t.done).length;
  const overdue = allTodos.filter(t => !t.done && t.dueDate && t.dueDate < today).length;
  const setEl = (id, v) => { const e = document.getElementById(id); if(e) e.textContent = v; };
  setEl('todoStatOpen', `${open} open`);
  setEl('todoStatDone', `${done} completed`);
  setEl('todoStatOverdue', overdue > 0 ? `${overdue} overdue` : '');

  if (!todos.length) {
    el.innerHTML = `<div style="text-align:center;padding:32px;color:var(--muted);font-style:italic">
      ${_todoFilter === 'all' && !allTodos.length ? 'No to-dos yet. Add your first one above.' : 'No to-dos match this filter.'}
    </div>`;
    return;
  }

  // Sort: high priority first, then by due date, then by created
  todos.sort((a,b) => {
    if (a.done !== b.done) return a.done ? 1 : -1;
    const pa = a.priority==='high'?0:a.priority==='med'?1:2;
    const pb = b.priority==='high'?0:b.priority==='med'?1:2;
    if (pa !== pb) return pa - pb;
    if (a.dueDate && b.dueDate) return a.dueDate.localeCompare(b.dueDate);
    if (a.dueDate) return -1;
    if (b.dueDate) return 1;
    return 0;
  });

  const priorityColors = { high:'#ef5350', med:'#f97316', normal:'var(--amber-border)' };

  el.innerHTML = todos.map(todo => {
    const pColor = priorityColors[todo.priority] || 'var(--amber-border)';
    const isOverdue = !todo.done && todo.dueDate && todo.dueDate < today;
    const linkedJob = todo.jobId ? conJobs.find(j => j.id === todo.jobId) : null;
    return `<div class="todo-item ${todo.done?'done':''}">
      <div class="todo-check ${todo.done?'checked':''} ${todo.priority!=='normal'?'todo-priority-'+todo.priority:''}"
        onclick="toggleTodo('${todo.id}',${!todo.done})" style="border-color:${pColor}${todo.done?';background:'+pColor:''}"></div>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:flex-start;gap:8px;flex-wrap:wrap">
          <span style="font-size:.88rem;font-weight:${todo.done?'400':'600'};color:${todo.done?'var(--muted)':'#eaf0fb'};${todo.done?'text-decoration:line-through':''};flex:1">${esc(todo.text||'')}</span>
          ${todo.priority==='high'?`<span style="font-size:.68rem;background:#ef535022;color:#fca5a5;border:1px solid #ef535044;border-radius:999px;padding:1px 6px;font-weight:700;flex-shrink:0">HIGH</span>`:''}
          ${todo.priority==='med'?`<span style="font-size:.68rem;background:#f9731622;color:#fed7aa;border:1px solid #f9731644;border-radius:999px;padding:1px 6px;font-weight:700;flex-shrink:0">MED</span>`:''}
          ${todo.source==='sla'?`<span style="font-size:.68rem;background:rgba(59,130,246,.15);color:#93c5fd;border:1px solid rgba(59,130,246,.3);border-radius:999px;padding:1px 6px;font-weight:700;flex-shrink:0">SLA</span>`:''}
        </div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:4px">
          ${linkedJob?`<span style="font-size:.72rem;color:var(--amber)">🔧 ${esc(linkedJob.name)}</span>`:''}
          ${todo.assignee?`<span style="font-size:.72rem;color:var(--muted)">👤 ${esc(todo.assigneeName||todo.assignee)}</span>`:''}
          ${todo.dueDate?`<span style="font-size:.72rem;color:${isOverdue?'#fca5a5':'var(--muted)'}">📅 ${todo.dueDate}${isOverdue?' ⚠️':''}</span>`:''}
          <span style="font-size:.7rem;color:rgba(110,145,210,.3)">${todo.createdByName||''}</span>
        </div>
      </div>
      <div style="display:flex;gap:6px;flex-shrink:0;align-items:center">
        ${todo.plannerxdPushedAt
          ? `<button onclick="pushTodoToPlannerXD('${todo.id}')" title="Already pushed — click to send again" style="background:none;border:1px solid rgba(29,187,135,.3);border-radius:6px;color:#1dbb87;cursor:pointer;font-size:.68rem;padding:3px 8px;white-space:nowrap">✓ PlannerXD (resend)</button>`
          : `<button onclick="pushTodoToPlannerXD('${todo.id}')" title="Manually add this to PlannerXD's Do First list" style="background:none;border:1px solid rgba(110,145,210,.25);border-radius:6px;color:var(--muted);cursor:pointer;font-size:.72rem;padding:3px 8px;white-space:nowrap">📤 To PlannerXD</button>`}
        <button onclick="openEditTodo('${todo.id}')" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:.9rem;padding:2px 4px">✏️</button>
        <button onclick="deleteTodo('${todo.id}')" style="background:none;border:none;color:rgba(239,83,80,.4);cursor:pointer;font-size:.9rem;padding:2px 4px">🗑</button>
      </div>
    </div>`;
  }).join('');
}

// Manual fallback while the automatic JOBSMETRIX->PlannerXD bridge
// (triggered on proposal signature) is being diagnosed — same
// destination (plannerxd_notifications/{ownerUid}/items), just
// triggered by hand from any To-Do instead of only automatically on
// signature. Errors are shown directly, not swallowed — today's
// automatic-bridge issue was invisible for exactly that reason.
function pushTodoToPlannerXD(todoId) {
  if (!conDb) return;
  const todo = allTodos.find(t => t.id === todoId);
  if (!todo) return;
  const btn = document.querySelector(`button[onclick="pushTodoToPlannerXD('${todoId}')"]`);
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }

  coll('settings').doc('company').get()
    .then(settDoc => {
      const ownerUid = settDoc.exists ? settDoc.data().ownerUid : null;
      if (!ownerUid) {
        alert("Can't push to PlannerXD — no PlannerXD account (ownerUid) is linked in Company Settings.");
        if (btn) { btn.disabled = false; btn.textContent = '📤 To PlannerXD'; }
        return;
      }
      const linkedJob = todo.jobId ? conJobs.find(j => j.id === todo.jobId) : null;
      return conDb.collection('plannerxd_notifications').doc(ownerUid).collection('items').add({
        type: 'manual_todo_push',
        title: todo.text || 'JOBSMETRIX to-do',
        body: linkedJob ? ('Job: ' + linkedJob.name) : '',
        jobId: todo.jobId || null,
        companyId: currentCompanyId,
        actionLabel: 'Open Job',
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        createdMs: Date.now(),
        read: false
      }).then(() => {
        return coll('todos').doc(todoId).update({
          plannerxdPushedAt: firebase.firestore.FieldValue.serverTimestamp()
        });
      }).then(() => {
        todo.plannerxdPushedAt = true; // local flag so renderTodos shows the ✓ immediately, before the listener re-fires
        renderTodos();
      });
    })
    .catch(e => {
      alert('Error pushing to PlannerXD: ' + e.message);
      if (btn) { btn.disabled = false; btn.textContent = '📤 To PlannerXD'; }
    });
}
window.pushTodoToPlannerXD = pushTodoToPlannerXD;

function addTodo() {
  const input = document.getElementById('newTodoInput');
  const text = (input?.value || '').trim();
  if (!text) { input?.focus(); return; }
  if (!conDb) return;

  const assigneeEl = document.getElementById('newTodoAssignee');
  const assigneeEmail = assigneeEl?.value || '';
  const assigneeName = assigneeEl?.options[assigneeEl.selectedIndex]?.text || '';

  const data = {
    text,
    priority: document.getElementById('newTodoPriority')?.value || 'normal',
    jobId: document.getElementById('newTodoJobLink')?.value || '',
    assignee: assigneeEmail,
    assigneeName: assigneeEmail ? assigneeName : '',
    done: false,
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdBy: conCurrentUser?.email || '',
    createdByName: conCurrentUser?.displayName || conCurrentUser?.email || ''
  };

  coll('todos').add(data)
    .then(() => {
      if (input) input.value = '';
    })
    .catch(e => alert('Error: ' + e.message));
}

function toggleTodo(id, done) {
  if (!conDb) return;
  coll('todos').doc(id).update({
    done,
    completedAt: done ? firebase.firestore.FieldValue.serverTimestamp() : null,
    completedBy: done ? (conCurrentUser?.email || '') : ''
  }).catch(e => alert('Error: ' + e.message));
}

function deleteTodo(id) {
  if (!confirm('Delete this to-do?')) return;
  coll('todos').doc(id).delete().catch(e => alert('Error: ' + e.message));
}

function openEditTodo(id) {
  const todo = allTodos.find(t => t.id === id);
  if (!todo) return;
  const newText = prompt('Edit to-do:', todo.text);
  if (newText === null) return;
  const trimmed = newText.trim();
  if (!trimmed) return;
  coll('todos').doc(id).update({ text: trimmed })
    .catch(e => alert('Error: ' + e.message));
}

// ════════════════════════════════════════════════════
// ── CUSTOMERS ──
// ════════════════════════════════════════════════════
let allCustomers = [];
let _editingCustomerId = null;

function loadCustomers() {
  if (!conDb) return;
  coll('customers')
    .orderBy('name')
    .onSnapshot(snap => {
      allCustomers = [];
      snap.forEach(doc => allCustomers.push({ id: doc.id, ...doc.data() }));
      renderCustomers();
    }, () => {});
}

function renderCustomers() {
  const grid = document.getElementById('customerGrid');
  const countEl = document.getElementById('customerCount');
  if (!grid) return;

  const q = (document.getElementById('customerSearch')?.value || '').toLowerCase();
  let customers = q
    ? allCustomers.filter(c =>
        (c.name||'').toLowerCase().includes(q) ||
        (c.email||'').toLowerCase().includes(q) ||
        (c.phone||'').toLowerCase().includes(q) ||
        (c.address||'').toLowerCase().includes(q)
      )
    : allCustomers;

  if (countEl) countEl.textContent = `${allCustomers.length} customer${allCustomers.length!==1?'s':''} total`;

  if (!customers.length) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--muted);font-style:italic">
      ${allCustomers.length === 0 ? 'No customers yet. Add your first customer above.' : 'No customers match your search.'}
    </div>`;
    return;
  }

  grid.innerHTML = customers.map(c => {
    const customerJobs = conJobs.filter(j => j.client === c.name || j.customerId === c.id);
    const openJobs = customerJobs.filter(j => !['Closed Completed','Closed Lost'].includes(j.status));
    const jobCount = customerJobs.length;
    const initials = (c.name||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();
    const jobsHtml = openJobs.slice(0,3).map(j =>
      '<div onclick="event.stopPropagation();openJobDetail(\'' + j.id + '\')" ' +
      'style="display:flex;justify-content:space-between;align-items:center;padding:5px 8px;background:rgba(217,119,6,.08);border:1px solid rgba(217,119,6,.15);border-radius:7px;margin-bottom:4px;cursor:pointer" ' +
      'onmouseover="this.style.background=\'rgba(217,119,6,.15)\'" onmouseout="this.style.background=\'rgba(217,119,6,.08)\'">' +
      '<div><div style="font-size:.8rem;font-weight:700;color:#eaf0fb">' + esc(j.name) + '</div>' +
      '<div style="font-size:.7rem;color:var(--muted)">#' + (j.jobNumber||'') + ' · ' + esc(j.status) + '</div></div>' +
      '<div style="font-size:.72rem;color:var(--amber);font-weight:700">→ Open</div></div>'
    ).join('');
    return '<div class="customer-card">' +
      '<div style="display:flex;gap:12px;align-items:flex-start;margin-bottom:10px">' +
      '<div class="customer-avatar">' + initials + '</div>' +
      '<div style="flex:1;min-width:0">' +
      '<div style="font-weight:800;font-size:.95rem;color:#eaf0fb">' + esc(c.name||'') + '</div>' +
      '<div style="font-size:.75rem;color:var(--muted);margin-top:1px">' + esc(c.type||'Homeowner') + '</div>' +
      (c.source ? '<div style="font-size:.72rem;color:rgba(110,145,210,.4);margin-top:1px">via ' + esc(c.source) + (c.referredBy ? ' — ' + esc(c.referredBy) : '') + '</div>' : '') +
      '</div>' +
      (jobCount>0 ? '<span style="background:var(--amber-dim);color:var(--amber);border:1px solid var(--amber-border);border-radius:999px;padding:2px 8px;font-size:.7rem;font-weight:700;white-space:nowrap">' + jobCount + ' job' + (jobCount!==1?'s':'') + '</span>' : '') +
      '</div>' +
      '<div style="display:flex;flex-direction:column;gap:4px">' +
      (c.phone ? '<div style="font-size:.82rem;display:flex;align-items:center;gap:6px"><a href="tel:' + esc(c.phone) + '" onclick="event.stopPropagation()" style="color:#a3f2d2;text-decoration:none;font-weight:600">📞 ' + esc(c.phone) + '</a><a href="sms:' + esc(c.phone) + '" onclick="event.stopPropagation()" style="background:rgba(59,130,246,.15);color:#93c5fd;border:1px solid rgba(59,130,246,.25);border-radius:6px;padding:1px 7px;font-size:.7rem;font-weight:700;text-decoration:none">📱 Text</a></div>' : '') +
      (c.email ? '<div style="font-size:.82rem;display:flex;align-items:center;gap:6px"><span style="color:var(--muted)">✉️</span><a href="mailto:' + esc(c.email) + '" onclick="event.stopPropagation()" style="color:#eaf0fb;text-decoration:none">' + esc(c.email) + '</a></div>' : '') +
      (c.address ? '<div style="font-size:.78rem;color:var(--muted);display:flex;align-items:center;gap:6px"><span>📍</span>' + esc(c.address) + '</div>' : '') +
      (c.notes ? '<div style="font-size:.76rem;color:rgba(110,145,210,.5);margin-top:4px;font-style:italic">' + esc(c.notes.slice(0,80)) + (c.notes.length>80?'…':'') + '</div>' : '') +
      '</div>' +
      (openJobs.length > 0 ?
        '<div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(110,145,210,.1)">' +
        '<div style="font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:6px">Open Jobs</div>' +
        jobsHtml +
        (openJobs.length > 3 ? '<div style="font-size:.74rem;color:var(--muted);padding:3px 6px">+' + (openJobs.length-3) + ' more open jobs</div>' : '') +
        '</div>' : '') +
      '<div style="display:flex;gap:6px;margin-top:10px">' +
      '<button onclick="event.stopPropagation();openNewJobForCustomer(\'' + c.id + '\')" style="flex:1;padding:6px;background:linear-gradient(135deg,var(--amber),var(--amber2));border:none;border-radius:8px;color:#fff;font-size:.76rem;font-weight:700;cursor:pointer">+ New Job</button>' +
      '<button onclick="event.stopPropagation();openCustomerModal(\'' + c.id + '\')" style="padding:6px 10px;background:transparent;border:1px solid rgba(110,145,210,.2);border-radius:8px;color:var(--muted);font-size:.76rem;cursor:pointer">✏️ Edit</button>' +
      '</div></div>';
  }).join('');
}

function openCustomerModal(id) {
  _editingCustomerId = id || null;
  const customer = id ? allCustomers.find(c => c.id === id) : null;
  const title = document.getElementById('customerModalTitle');
  if (title) title.textContent = customer ? 'Edit Customer' : 'Add Customer';
  document.getElementById('customerId').value = id || '';

  const setVal = (elId, val) => { const el = document.getElementById(elId); if(el) el.value = val||''; };
  setVal('custName', customer?.name);
  setVal('custBusinessName', customer?.businessName);
  setVal('custPhone', customer?.phone);
  setVal('custEmail', customer?.email);
  setVal('custAddress', customer?.address);
  setVal('custSource', customer?.source);
  setVal('custReferredBy', customer?.referredBy);
  setVal('custType', customer?.type || 'Homeowner');
  setVal('custNotes', customer?.notes);

  const deleteBtn = document.getElementById('deleteCustomerBtn');
  if (deleteBtn) deleteBtn.style.display = customer ? 'inline-flex' : 'none';
  kOpen('customerModal');
}

function saveCustomer(goToNewJob) {
  if (!conDb) return;
  const name = document.getElementById('custName')?.value.trim();
  if (!name) { alert('Name is required.'); return; }
  const id = document.getElementById('customerId')?.value;

  const data = {
    name,
    businessName: document.getElementById('custBusinessName')?.value.trim() || '',
    phone: document.getElementById('custPhone')?.value.trim() || '',
    email: document.getElementById('custEmail')?.value.trim() || '',
    address: document.getElementById('custAddress')?.value.trim() || '',
    source: document.getElementById('custSource')?.value || '',
    referredBy: document.getElementById('custReferredBy')?.value.trim() || '',
    type: document.getElementById('custType')?.value || 'Homeowner',
    notes: document.getElementById('custNotes')?.value.trim() || '',
    updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy: conCurrentUser?.email || ''
  };

  const col = coll('customers');
  const promise = id
    ? col.doc(id).update(data)
    : col.add({ ...data, companyId: currentCompanyId, createdAt: firebase.firestore.FieldValue.serverTimestamp(), createdBy: conCurrentUser?.email || '' });

  promise.then((ref) => {
      kClose('customerModal');
      if (goToNewJob) {
        const newCustomerId = id || (ref && ref.id);
        prefillNewJobForCustomerData({ id: newCustomerId, ...data });
      }
    })
    .catch(e => alert('Error: ' + e.message));
}

function deleteCustomer() {
  const id = document.getElementById('customerId')?.value;
  if (!id || !confirm('Delete this customer?')) return;
  coll('customers').doc(id).delete()
    .then(() => kClose('customerModal'))
    .catch(e => alert('Error: ' + e.message));
}

// Expose
window.addTodo = addTodo;
window.toggleTodo = toggleTodo;
window.deleteTodo = deleteTodo;
window.openEditTodo = openEditTodo;
window.filterTodos = filterTodos;
window.openCustomerModal = openCustomerModal;
window.saveCustomer = saveCustomer;
window.deleteCustomer = deleteCustomer;
window.renderCustomers = renderCustomers;

// ════════════════════════════════════════════════════
// ── TIME TRACKING ──
// ════════════════════════════════════════════════════
let allTimeEntries = [];
let _clockedInEntry = null;
let _clockInterval = null;
let _clockStart = null;

function loadTimeEntries() {
  if (!conDb) return;
  const today = new Date().toISOString().split('T')[0];
  // NOTE: order by 'date', not 'clockIn' - manual entries have no clockIn
  // field at all, and Firestore orderBy silently excludes documents
  // missing the ordered field, which was making manual entries invisible
  // everywhere on this page (Time Log, Weekly Overtime, totals).
  coll('timeentries')
    .orderBy('date', 'desc')
    .limit(200)
    .onSnapshot(snap => {
      allTimeEntries = [];
      _clockedInEntry = null;
      snap.forEach(doc => {
        const entry = { id: doc.id, ...doc.data() };
        allTimeEntries.push(entry);
        // Check if current user is clocked in
        if (!entry.clockOut && entry.userId === conCurrentUser?.uid) {
          _clockedInEntry = entry;
        }
      });
      updateClockUI();
      renderTimeLog();
      renderTodaySummary();
      updateTimeBadge();
      populateTimeFilters();
      refreshCrewMapIfLive();
    }, () => {});
}

function updateTimeBadge() {
  const badge = document.getElementById('navTimeBadge');
  if (badge) badge.style.display = _clockedInEntry ? 'inline-flex' : 'none';
}

// ═══════════════════ CREW MAP ═══════════════════
// Plots clock-in (and, since the clock-out GPS fix above, clock-out)
// locations on a Leaflet/OpenStreetMap map -- no Google Maps JS API key
// needed, consistent with the OSM approach already used for job-address
// maps and geocoding elsewhere in the app. Two modes:
//   - Live: crew currently clocked in right now (clockOut == null),
//     fed off the same always-on onSnapshot listener loadTimeEntries()
//     already runs at app init, so it updates in real time.
//   - History: a one-off date-range query (+ optional job filter), shows
//     both the clock-in AND clock-out point per shift, connected by a
//     thin line, so Travis can see where someone actually was for a
//     given day/job rather than only "right now."
let _crewMap = null;
let _crewMapLayer = null;
let _crewMapMode = 'live';
let _crewMapJobCoordsCache = {}; // jobId -> {lat, lon} | null, resolved once per page-life

function initCrewMap() {
  if (!canViewCrewMap()) return;
  if (!_crewMap) {
    const el = document.getElementById('crewMapEl');
    if (!el || typeof L === 'undefined') return;
    _crewMap = L.map(el).setView([38.6270, -90.1994], 10); // defaults to St. Louis area; fitBounds() below re-centers on real data
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(_crewMap);
    _crewMapLayer = L.layerGroup().addTo(_crewMap);
  } else {
    // Leaflet mis-sizes itself if initialized while its container was
    // display:none (which it was, on any earlier visit to another page).
    setTimeout(() => _crewMap.invalidateSize(), 50);
  }

  // Populate the job filter dropdown for History mode
  const jobSel = document.getElementById('crewMapJobFilter');
  if (jobSel && jobSel.options.length <= 1) {
    conJobs.forEach(j => {
      const opt = document.createElement('option');
      opt.value = j.id;
      opt.textContent = j.name || j.jobNumber || j.id;
      jobSel.appendChild(opt);
    });
  }
  // Default History date range to today, same as Daily Logs conventions elsewhere
  const today = new Date().toISOString().split('T')[0];
  const fromEl = document.getElementById('crewMapDateFrom');
  const toEl = document.getElementById('crewMapDateTo');
  if (fromEl && !fromEl.value) fromEl.value = today;
  if (toEl && !toEl.value) toEl.value = today;

  setCrewMapMode(_crewMapMode);
}

function setCrewMapMode(mode) {
  _crewMapMode = mode;
  const liveBtn = document.getElementById('crewMapModeLiveBtn');
  const histBtn = document.getElementById('crewMapModeHistoryBtn');
  const histControls = document.getElementById('crewMapHistoryControls');
  if (liveBtn) liveBtn.className = mode === 'live' ? 'btn-amber' : 'btn';
  if (histBtn) histBtn.className = mode === 'history' ? 'btn-amber' : 'btn';
  if (histControls) histControls.style.display = mode === 'history' ? 'flex' : 'none';

  if (mode === 'live') {
    renderCrewMapFromLive();
  } else {
    loadCrewMapHistory();
  }
}
window.setCrewMapMode = setCrewMapMode;

// Live mode reads off the same allTimeEntries array loadTimeEntries()
// already keeps current via its onSnapshot listener -- no separate query.
async function renderCrewMapFromLive() {
  if (!document.getElementById('ktPageCrewMap')?.classList.contains('active')) return;
  const rawEntries = (allTimeEntries || []).filter(e => !e.clockOut);
  const title = document.getElementById('crewMapListTitle');
  if (title) title.textContent = `Currently clocked in (${rawEntries.length})`;
  // Live mode must reflect the CURRENT jobsite pin, not whatever it was
  // at the moment someone clocked in -- offSite/distanceFt on the entry
  // itself are a one-time snapshot written by clockIn() and never
  // updated again. Real scenario this fixed: a job's pin gets corrected
  // (see fixJobPin below) while someone's still clocked in on it -- their
  // dot and badge used to keep showing the stale pre-fix distance until
  // they clocked out and back in. Recompute fresh here every render
  // instead. History mode intentionally does NOT do this -- a past shift
  // should keep showing what was true then, not get silently rewritten
  // by a pin correction made after the fact.
  const entries = await Promise.all(rawEntries.map(async e => {
    if (typeof e.clockInLat !== 'number' || typeof e.clockInLon !== 'number' || !e.jobId) return e;
    const job = conJobs.find(j => j.id === e.jobId);
    const coords = await getJobCoordinates(job);
    if (!coords) return e; // no current coords available -- fall back to the stored snapshot
    const distanceFt = Math.round(haversineDistanceFeet(e.clockInLat, e.clockInLon, coords.lat, coords.lon));
    return { ...e, offSite: distanceFt > OFFSITE_THRESHOLD_FEET, distanceFt };
  }));
  renderCrewMapMarkers(entries);
  renderCrewMapList(entries);
}

// Called by loadTimeEntries()'s onSnapshot whenever live data changes, so
// the map updates in real time while someone is actually looking at it.
function refreshCrewMapIfLive() {
  if (_crewMapMode === 'live' && _crewMap) renderCrewMapFromLive();
}

async function loadCrewMapHistory() {
  if (!conDb) return;
  const listEl = document.getElementById('crewMapList');
  const dateFrom = document.getElementById('crewMapDateFrom')?.value;
  const dateTo = document.getElementById('crewMapDateTo')?.value;
  const jobFilter = document.getElementById('crewMapJobFilter')?.value || '';
  if (!dateFrom || !dateTo) { alert('Pick a From and To date.'); return; }
  if (listEl) listEl.innerHTML = '<div class="small muted" style="text-align:center;padding:20px">Loading…</div>';

  try {
    let q = coll('timeentries').where('date', '>=', dateFrom).where('date', '<=', dateTo);
    const snap = await q.get();
    let entries = [];
    snap.forEach(doc => entries.push({ id: doc.id, ...doc.data() }));
    if (jobFilter) entries = entries.filter(e => e.jobId === jobFilter);
    // Only entries with an actual clock-in GPS point are mappable -- manual
    // hours entries (no clockIn at all) have nothing to plot.
    entries = entries.filter(e => typeof e.clockInLat === 'number' && typeof e.clockInLon === 'number');

    const title = document.getElementById('crewMapListTitle');
    if (title) title.textContent = `${dateFrom === dateTo ? dateFrom : dateFrom + ' → ' + dateTo} (${entries.length} shift${entries.length !== 1 ? 's' : ''})`;
    renderCrewMapMarkers(entries);
    renderCrewMapList(entries);
  } catch(e) {
    if (listEl) listEl.innerHTML = '<div class="small muted" style="text-align:center;padding:20px;color:#ef5350">Error loading: ' + esc(e.message) + '</div>';
  }
}
window.loadCrewMapHistory = loadCrewMapHistory;

function crewMapPersonLabel(e) {
  return e.userName || e.userEmail || 'Unknown';
}

function crewMapFmtTime(iso) {
  if (!iso) return '';
  try { return new Date(iso).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); }
  catch(e) { return ''; }
}

async function renderCrewMapMarkers(entries) {
  if (!_crewMap || !_crewMapLayer) return;
  _crewMapLayer.clearLayers();
  const bounds = [];

  // Job site pins (deduped), resolved via the same cached-then-geocode
  // helper the job detail map already uses -- never re-geocodes a job
  // that's already been located once this page-life or has cached coords.
  const jobIds = [...new Set(entries.map(e => e.jobId).filter(Boolean))];
  for (const jobId of jobIds) {
    let coords = _crewMapJobCoordsCache[jobId];
    if (coords === undefined) {
      const job = conJobs.find(j => j.id === jobId);
      coords = await getJobCoordinates(job);
      _crewMapJobCoordsCache[jobId] = coords;
    }
    if (coords) {
      const job = conJobs.find(j => j.id === jobId);
      L.marker([coords.lat, coords.lon], {
        icon: L.divIcon({ html: '📍', className: 'crewmap-emoji-icon', iconSize: [24, 24] })
      }).bindPopup(`<b>${esc(job?.name || 'Job site')}</b><br>${esc(job?.address || '')}`).addTo(_crewMapLayer);
      bounds.push([coords.lat, coords.lon]);
    }
  }

  entries.forEach(e => {
    if (typeof e.clockInLat === 'number' && typeof e.clockInLon === 'number') {
      const color = e.offSite ? '#ef5350' : '#1dbb87';
      L.circleMarker([e.clockInLat, e.clockInLon], {
        radius: 8, color: '#fff', weight: 2, fillColor: color, fillOpacity: 0.9
      }).bindPopup(
        `<b>${esc(crewMapPersonLabel(e))}</b><br>` +
        `${esc(e.jobName || '')}<br>` +
        `Clocked in ${crewMapFmtTime(e.clockInISO)}${e.offSite ? ` — <span style="color:#ef5350;font-weight:700">OFF-SITE${e.distanceFt != null ? ' (' + e.distanceFt + ' ft)' : ''}</span>` : ' — on-site'}`
      ).addTo(_crewMapLayer);
      bounds.push([e.clockInLat, e.clockInLon]);
    }
    if (typeof e.clockOutLat === 'number' && typeof e.clockOutLon === 'number') {
      L.circleMarker([e.clockOutLat, e.clockOutLon], {
        radius: 7, color: '#fff', weight: 2, fillColor: '#3b82f6', fillOpacity: 0.9
      }).bindPopup(
        `<b>${esc(crewMapPersonLabel(e))}</b><br>` +
        `${esc(e.jobName || '')}<br>` +
        `Clocked out ${crewMapFmtTime(e.clockOutISO)}${e.offSiteOut ? ` — <span style="color:#ef5350;font-weight:700">OFF-SITE${e.distanceFtOut != null ? ' (' + e.distanceFtOut + ' ft)' : ''}</span>` : ' — on-site'}`
      ).addTo(_crewMapLayer);
      bounds.push([e.clockOutLat, e.clockOutLon]);
      if (typeof e.clockInLat === 'number') {
        L.polyline([[e.clockInLat, e.clockInLon], [e.clockOutLat, e.clockOutLon]], {
          color: '#94a3b8', weight: 1.5, dashArray: '4,5', opacity: 0.6
        }).addTo(_crewMapLayer);
      }
    }
  });

  if (bounds.length === 1) {
    _crewMap.setView(bounds[0], 15);
  } else if (bounds.length > 1) {
    _crewMap.fitBounds(bounds, { padding: [30, 30], maxZoom: 16 });
  }
}

function renderCrewMapList(entries) {
  const listEl = document.getElementById('crewMapList');
  if (!listEl) return;
  if (!entries.length) {
    listEl.innerHTML = '<div class="small muted" style="text-align:center;padding:20px">Nobody to show for this view.</div>';
    return;
  }
  listEl.innerHTML = entries.map(e => {
    const inBadge = typeof e.clockInLat === 'number'
      ? (e.offSite
          ? `<span style="background:rgba(239,83,80,.15);color:#ef5350;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px">📍 IN — OFF-SITE${e.distanceFt != null ? ' (' + e.distanceFt + ' ft)' : ''}</span>`
          : `<span style="background:rgba(29,187,135,.15);color:#1dbb87;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px">📍 IN — on-site</span>`)
      : '';
    const outBadge = e.clockOut
      ? (typeof e.clockOutLat === 'number'
          ? (e.offSiteOut
              ? `<span style="background:rgba(239,83,80,.15);color:#ef5350;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px;margin-left:6px">📍 OUT — OFF-SITE${e.distanceFtOut != null ? ' (' + e.distanceFtOut + ' ft)' : ''}</span>`
              : `<span style="background:rgba(59,130,246,.15);color:#3b82f6;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px;margin-left:6px">📍 OUT — on-site</span>`)
          : `<span style="background:rgba(148,163,184,.15);color:#94a3b8;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px;margin-left:6px">OUT — no GPS (clocked out before this feature)</span>`)
      : `<span style="background:rgba(148,163,184,.15);color:#94a3b8;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px;margin-left:6px">Still clocked in</span>`;
    return `<div style="display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid rgba(217,119,6,.12)">
      <div style="min-width:140px;font-weight:700;color:#eaf0fb;font-size:.85rem">${esc(crewMapPersonLabel(e))}</div>
      <div style="flex:1;min-width:120px;font-size:.8rem;color:var(--muted)">${esc(e.jobName || '')}</div>
      <div style="font-size:.76rem;color:var(--muted)">${crewMapFmtTime(e.clockInISO)}${e.clockOutISO ? ' – ' + crewMapFmtTime(e.clockOutISO) : ''}</div>
      ${inBadge}${outBadge}
    </div>`;
  }).join('');
}

function handleClockToggle() {
  if (_clockedInEntry) {
    clockOut();
  } else {
    clockIn();
  }
}

let _clockFeatures = [];

// ── GPS verification for Clock In ──────────────────────────────────
// Wraps navigator.geolocation in a Promise with a hard timeout so a
// stalled GPS request can't hang the clock-in flow indefinitely, only
// ever resolves or rejects.
function getCurrentPositionAsync(timeoutMs) {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) { reject(new Error('Geolocation not supported on this device')); return; }
    navigator.geolocation.getCurrentPosition(
      pos => resolve(pos),
      err => reject(err),
      { enableHighAccuracy: true, timeout: timeoutMs || 12000, maximumAge: 0 }
    );
  });
}

// Straight-line distance in feet between two lat/lon points (haversine).
// Good enough for an on-site/off-site flag -- this isn't routing, it's a
// sanity check against the jobsite address.
function haversineDistanceFeet(lat1, lon1, lat2, lon2) {
  const R_MILES = 3958.8;
  const toRad = d => d * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat/2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2) ** 2;
  const miles = R_MILES * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return miles * 5280;
}

// Resolves a job's site coordinates, reusing the exact same cached-then-
// Nominatim-geocode pattern renderJobMap() already uses (job.geoLat/geoLon
// persisted to Firestore so a job is only ever geocoded once). Returns
// null (never throws) if the job has no address or geocoding fails --
// callers treat "no coordinates available" as "can't check distance,"
// not as a reason to block clock-in.
async function getJobCoordinates(job) {
  if (!job) return null;
  if (typeof job.geoLat === 'number' && typeof job.geoLon === 'number') {
    return { lat: job.geoLat, lon: job.geoLon };
  }
  if (_geoCache[job.address || '']) return _geoCache[job.address];
  const addr = job.address || '';
  if (!addr) return null;
  try {
    const url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(addr);
    const r = await fetch(url, { headers: { 'Accept': 'application/json' } });
    const results = await r.json();
    if (!Array.isArray(results) || !results.length) return null;
    const lat = parseFloat(results[0].lat), lon = parseFloat(results[0].lon);
    if (isNaN(lat) || isNaN(lon)) return null;
    _geoCache[addr] = { lat, lon };
    if (conDb) coll('jobs').doc(job.id).update({ geoLat: lat, geoLon: lon }).catch(() => {});
    return { lat, lon };
  } catch(e) {
    return null;
  }
}

const OFFSITE_THRESHOLD_FEET = 500;

async function clockIn() {
  const jobId = document.getElementById('clockJobSelect')?.value || '';
  if (!jobId) { alert('Please select a job first.'); return; }
  if (!conDb || !conCurrentUser) return;

  const job = conJobs.find(j => j.id === jobId);
  const selVal = document.getElementById('clockPhaseSelect')?.value || '';
  const [epicId, featureId] = selVal ? selVal.split('|') : ['', ''];
  const feature = featureId ? _clockFeatures.find(f => f.id === featureId) : null;

  // GPS is required to clock in -- per Travis's spec, a failed/denied/
  // unavailable location BLOCKS clock-in (crew needs to enable location
  // services), while a successful location that's simply far from the
  // jobsite does NOT block -- it just gets flagged for review.
  const clockBtn = document.getElementById('clockBtn');
  if (clockBtn) { clockBtn.disabled = true; clockBtn.style.opacity = '0.6'; }
  let position;
  try {
    position = await getCurrentPositionAsync(12000);
  } catch(e) {
    if (clockBtn) { clockBtn.disabled = false; clockBtn.style.opacity = ''; }
    alert('Location access is required to clock in. Please enable location services for this site and try again.\n\n(' + (e.message || 'Location unavailable') + ')');
    return;
  }

  const userLat = position.coords.latitude;
  const userLon = position.coords.longitude;
  let offSite = false;
  let distanceFt = null;
  const siteCoords = await getJobCoordinates(job);
  if (siteCoords) {
    distanceFt = Math.round(haversineDistanceFeet(userLat, userLon, siteCoords.lat, siteCoords.lon));
    offSite = distanceFt > OFFSITE_THRESHOLD_FEET;
  }

  const now = new Date();
  const entry = {
    userId: conCurrentUser.uid,
    userEmail: conCurrentUser.email || '',
    userName: conCurrentUser.displayName || conCurrentUser.email || '',
    jobId,
    jobName: job?.name || '',
    phaseId: featureId || '', // Feature id — kept as "phaseId" so existing hour-rollup code needs no changes
    phaseName: feature?.name || '',
    clockIn: firebase.firestore.FieldValue.serverTimestamp(),
    clockInISO: now.toISOString(),
    clockInLat: userLat,
    clockInLon: userLon,
    offSite,
    distanceFt,
    clockOut: null,
    notes: document.getElementById('clockNotes')?.value.trim() || '',
    date: now.toISOString().split('T')[0],
    hours: null,
    companyId: currentCompanyId,
  };

  coll('timeentries').add(entry)
    .then(() => { _clockStart = now; startClockTicker(); })
    .catch(e => alert('Error clocking in: ' + e.message))
    .finally(() => { if (clockBtn) { clockBtn.disabled = false; clockBtn.style.opacity = ''; } });
}

// Set while a clock-out is waiting on a required Daily Log — cleared once
// the log is saved (see the patched saveLog() further down, which checks
// this and completes the clock-out automatically) or if the user cancels
// out of the Add Log modal without saving, in which case they're still
// clocked in and nothing was lost.
let _pendingClockOut = null;

// Checks whether a genuine crew-submitted Daily Log (no `type` field --
// see loadGlobalLogs() for why that's the reliable signal) already exists
// for this job today. Small, single-day, single-job result set, so a
// client-side filter after the date query is cheap and needs no new index.
async function hasTodayDailyLog(jobId, dateStr) {
  if (!conDb || !jobId) return false;
  try {
    const snap = await coll('jobs').doc(jobId).collection('logs')
      .where('date', '==', dateStr).get();
    let found = false;
    snap.forEach(doc => { if (!doc.data().type) found = true; });
    return found;
  } catch(e) {
    // If the check itself fails, don't trap the crew out of clocking out
    // over a network hiccup -- fail open here specifically.
    return true;
  }
}

async function clockOut() {
  if (!_clockedInEntry || !conDb) return;
  const jobId = _clockedInEntry.jobId;
  const dateStr = _clockedInEntry.date || new Date().toISOString().split('T')[0];

  const clockBtn = document.getElementById('clockBtn');
  if (clockBtn) { clockBtn.disabled = true; clockBtn.style.opacity = '0.6'; }
  const alreadyLogged = await hasTodayDailyLog(jobId, dateStr);
  if (clockBtn) { clockBtn.disabled = false; clockBtn.style.opacity = ''; }

  if (!alreadyLogged) {
    // Required, not optional -- per Travis's spec, clocking out is blocked
    // until today's Daily Log (with the option to attach photos) is saved.
    // saveLog() saves against `conCurrentJobId`, which normally only gets
    // set by opening a job's detail page (openJobDetail()). Field Techs
    // clock in/out from the standalone Home dashboard Time tile and never
    // visit a job detail page, so conCurrentJobId was staying null/stale
    // here -- saveLog()'s first guard (`if (!conCurrentJobId...) return;`)
    // then silently no-opped on Save with zero feedback: the exact
    // "hit Save, nothing happens" freeze reported from the field. Set it
    // explicitly here, same pattern already used by pickJobForLog().
    conCurrentJobId = jobId;
    _pendingClockOut = { entry: _clockedInEntry };
    alert('Before you clock out, add today\'s Daily Log for this job (crew, notes, and photos if you have any). Save it to finish clocking out.');
    openAddLogModal();
    return;
  }

  await performClockOut(_clockedInEntry);
}

// The actual clock-out write, split out from clockOut() so both the normal
// path and the "resume after the required Daily Log was saved" path in
// saveLog() can call the same completion logic.
async function performClockOut(entry) {
  if (!entry || !conDb) return;
  const now = new Date();
  const clockInTime = entry.clockInISO ? new Date(entry.clockInISO) : new Date(now - 3600000);
  const hours = Math.round((now - clockInTime) / 3600000 * 100) / 100;
  const notes = document.getElementById('clockNotes');
  const notesValue = notes ? notes.value.trim() : '';

  // GPS at clock-out, mirroring the same required-not-blocking-on-distance
  // policy already used at clock-in: a failed/denied/unavailable location
  // blocks the clock-out (crew needs to enable location services), but a
  // successful location that's simply far from the jobsite does not block
  // -- it only gets flagged, same as clock-in's off-site flag. This gives
  // the Crew Map an "out" point for every shift, not just an "in" point.
  const clockBtn = document.getElementById('clockBtn');
  if (clockBtn) { clockBtn.disabled = true; clockBtn.style.opacity = '0.6'; }
  let position;
  try {
    position = await getCurrentPositionAsync(12000);
  } catch(e) {
    if (clockBtn) { clockBtn.disabled = false; clockBtn.style.opacity = ''; }
    alert('Location access is required to clock out. Please enable location services for this site and try again.\n\n(' + (e.message || 'Location unavailable') + ')');
    return;
  }
  if (clockBtn) { clockBtn.disabled = false; clockBtn.style.opacity = ''; }

  const userLat = position.coords.latitude;
  const userLon = position.coords.longitude;
  let offSiteOut = false;
  let distanceFtOut = null;
  const job = conJobs.find(j => j.id === entry.jobId);
  const siteCoords = await getJobCoordinates(job);
  if (siteCoords) {
    distanceFtOut = Math.round(haversineDistanceFeet(userLat, userLon, siteCoords.lat, siteCoords.lon));
    offSiteOut = distanceFtOut > OFFSITE_THRESHOLD_FEET;
  }

  try {
    await coll('timeentries').doc(entry.id).update({
      clockOut: firebase.firestore.FieldValue.serverTimestamp(),
      clockOutISO: now.toISOString(),
      clockOutLat: userLat,
      clockOutLon: userLon,
      offSiteOut,
      distanceFtOut,
      hours,
      notes: notesValue,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    stopClockTicker();
    // A clock-out note is field-crew activity on the job same as a
    // manually-added Daily Log — push it into that same collection so it
    // shows up in the Daily Logs tab/feed and counts toward "logged
    // today" staleness checks, not just the Time Log table.
    if (notesValue && entry.jobId) {
      coll('jobs').doc(entry.jobId).collection('logs').add(subDoc({
        date: entry.date || now.toISOString().split('T')[0],
        weather: '',
        crew: '',
        notes: notesValue,
        issues: '',
        createdBy: conCurrentUser ? (conCurrentUser.displayName || conCurrentUser.email) : 'unknown',
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      })).catch(() => {});
    }
    if (notes) notes.value = '';
  } catch(e) {
    alert('Error clocking out: ' + e.message);
  }
}

// ── Feature selectors for time entry (Epic/Feature/Task model) ──
// Option values are "epicId|featureId" composite strings since a Feature's
// Firestore path needs both to locate it. Sorted active-first, same as before.
async function loadClockPhases(jobId) {
  const sel = document.getElementById('clockPhaseSelect');
  if (!sel) return;
  sel.innerHTML = '<option value="">No Feature selected</option>';
  _clockFeatures = [];
  if (!jobId) return;

  try {
    const epics = await loadEpicTree(jobId);
    const features = [];
    epics.forEach(epic => epic.features.forEach(f => features.push({ ...f, epicId: epic.id })));
    features.sort((a,b) => {
      const order = {'in-progress':0,'not-started':1,'blocked':2,'complete':3};
      return (order[a.status]||1) - (order[b.status]||1);
    });
    _clockFeatures = features;
    features.forEach(f => {
      const opt = document.createElement('option');
      opt.value = f.epicId + '|' + f.id;
      const statusLabel = f.status === 'in-progress' ? '🔵' : f.status === 'complete' ? '✅' : f.status === 'blocked' ? '🚫' : '⬜';
      opt.textContent = statusLabel + ' ' + f.name + (f.assignedTeamLead ? ' — ' + f.assignedTeamLead : '');
      sel.appendChild(opt);
    });
  } catch(e) {}
}

async function loadManualPhases(jobId) {
  const sel = document.getElementById('manualPhaseSelect');
  if (!sel) return;
  sel.innerHTML = '<option value="">No Feature</option>';
  if (!jobId) return;
  try {
    const epics = await loadEpicTree(jobId);
    epics.forEach(epic => {
      epic.features.forEach(f => {
        const opt = document.createElement('option');
        opt.value = epic.id + '|' + f.id;
        opt.textContent = f.name + ' (' + epic.name + ')';
        sel.appendChild(opt);
      });
    });
  } catch(e) {}
}

function saveManualTimeEntry() {
  const jobId = document.getElementById('manualJobSelect')?.value;
  const hours = parseFloat(document.getElementById('manualHours')?.value);
  const date = document.getElementById('manualDate')?.value;
  if (!jobId || !hours || !date) { alert('Job, hours, and date are required.'); return; }

  const selVal = document.getElementById('manualPhaseSelect')?.value || '';
  const [epicId, featureId] = selVal ? selVal.split('|') : ['', ''];
  const crew = document.getElementById('manualCrew')?.value.trim();
  const notes = document.getElementById('manualNotes')?.value.trim();
  const job = conJobs.find(j => j.id === jobId);

  const entry = {
    userId: crew ? '' : (conCurrentUser?.uid || ''),
    userEmail: crew ? '' : (conCurrentUser?.email || ''),
    userName: crew || conCurrentUser?.displayName || conCurrentUser?.email || '',
    jobId,
    jobName: job?.name || '',
    phaseId: featureId || '', // Feature id — kept as "phaseId" so existing hour-rollup code needs no changes
    phaseName: '',
    date,
    hours,
    notes: notes || '',
    manual: true,
    companyId: currentCompanyId,
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdBy: conCurrentUser?.email || '',
  };

  // Get Feature name
  if (featureId && epicId) {
    coll('jobs').doc(jobId).collection('estimateGroups').doc(epicId)
      .collection('subgroups').doc(featureId).get().then(d => {
      if (d.exists) entry.phaseName = d.data().name || '';
      return coll('timeentries').add(entry);
    }).then(() => {
      document.getElementById('manualHours').value = '';
      document.getElementById('manualNotes').value = '';
      document.getElementById('manualCrew').value = '';
      alert('✅ ' + hours + 'h logged' + (entry.phaseName ? ' to ' + entry.phaseName : ''));
    }).catch(e => alert('Error: ' + e.message));
  } else {
    coll('timeentries').add(entry).then(() => {
      document.getElementById('manualHours').value = '';
      document.getElementById('manualNotes').value = '';
      document.getElementById('manualCrew').value = '';
      alert('✅ ' + hours + 'h logged');
    }).catch(e => alert('Error: ' + e.message));
  }
}

window.loadClockPhases = loadClockPhases;
window.loadManualPhases = loadManualPhases;
window.saveManualTimeEntry = saveManualTimeEntry;

function startClockTicker() {
  if (_clockInterval) clearInterval(_clockInterval);
  _clockInterval = setInterval(updateClockTicker, 1000);
  updateClockTicker();
}

function stopClockTicker() {
  if (_clockInterval) clearInterval(_clockInterval);
  _clockInterval = null;
}

function updateClockTicker() {
  if (!_clockedInEntry || !_clockStart) return;
  const elapsed = Math.floor((Date.now() - _clockStart.getTime()) / 1000);
  const h = Math.floor(elapsed / 3600).toString().padStart(2,'0');
  const m = Math.floor((elapsed % 3600) / 60).toString().padStart(2,'0');
  const s = (elapsed % 60).toString().padStart(2,'0');
  const ticker = document.getElementById('clockTicker');
  if (ticker) ticker.textContent = `${h}:${m}:${s}`;
}

function updateClockUI() {
  const btn = document.getElementById('clockBtn');
  const btnIcon = document.getElementById('clockBtnIcon');
  const btnLabel = document.getElementById('clockBtnLabel');
  const statusLabel = document.getElementById('clockStatusLabel');
  const ticker = document.getElementById('clockTicker');

  if (_clockedInEntry) {
    if (btn) { btn.className = 'clock-btn clock-btn-out'; }
    if (btnIcon) btnIcon.textContent = '■';
    if (btnLabel) btnLabel.textContent = 'Clock Out';
    if (statusLabel) statusLabel.innerHTML = `<span class="clocked-in-badge">● CLOCKED IN</span> — ${esc(_clockedInEntry.jobName||'')}`;
    // Start ticker from clockInISO
    _clockStart = _clockedInEntry.clockInISO ? new Date(_clockedInEntry.clockInISO) : new Date();
    startClockTicker();
    // Pre-select job
    const jobSel = document.getElementById('clockJobSelect');
    if (jobSel && _clockedInEntry.jobId) jobSel.value = _clockedInEntry.jobId;
  } else {
    if (btn) { btn.className = 'clock-btn clock-btn-in'; }
    if (btnIcon) btnIcon.textContent = '▶';
    if (btnLabel) btnLabel.textContent = 'Clock In';
    if (statusLabel) statusLabel.textContent = 'Not clocked in';
    if (ticker) ticker.textContent = '00:00:00';
    stopClockTicker();
  }
}

function renderTodaySummary() {
  const today = new Date().toISOString().split('T')[0];
  const todayEntries = allTimeEntries.filter(e => e.date === today);
  const myEntries = todayEntries.filter(e => e.userId === conCurrentUser?.uid);
  const myHours = myEntries.reduce((s,e) => s + (e.hours||0), 0);
  const teamOnSite = [...new Set(todayEntries.filter(e => !e.clockOut).map(e => e.userId))].length;

  const dateEl = document.getElementById('timeTodayDate');
  if (dateEl) dateEl.textContent = new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});

  const hoursEl = document.getElementById('timeTodayHours');
  if (hoursEl) hoursEl.textContent = myHours.toFixed(1) + 'h';

  const teamEl = document.getElementById('timeTodayTeam');
  if (teamEl) teamEl.textContent = teamOnSite;

  const listEl = document.getElementById('todayTimeEntries');
  if (listEl) {
    if (!todayEntries.length) {
      listEl.innerHTML = '<div class="small muted" style="font-style:italic">No time entries today yet.</div>';
      return;
    }
    listEl.innerHTML = todayEntries.map(e => {
      const inTime = e.clockInISO ? new Date(e.clockInISO).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) : '—';
      const outTime = e.clockOutISO ? new Date(e.clockOutISO).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) : null;
      return `<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid rgba(110,145,210,.07);font-size:.82rem">
        <div>
          <div style="font-weight:700">${esc(e.userName||e.userEmail||'')}</div>
          <div style="color:var(--amber);font-size:.76rem">${esc(e.jobName||'')}</div>
        </div>
        <div style="text-align:right">
          ${outTime
            ? `<div style="font-weight:700;color:#a3f2d2">${e.hours?.toFixed(1)||'0.0'}h</div><div style="font-size:.72rem;color:var(--muted)">${inTime} – ${outTime}</div>`
            : `<span class="clocked-in-badge">● Live</span><div style="font-size:.72rem;color:var(--muted);margin-top:2px">In: ${inTime}</div>`
          }
        </div>
      </div>`;
    }).join('');
  }
}

function populateTimeFilters() {
  const activeStatuses = ACTIVE_STATUSES;
  const activeJobs = conJobs.filter(j => activeStatuses.includes(j.status));

  const jobSel = document.getElementById('clockJobSelect');
  if (jobSel) {
    const cur = jobSel.value;
    jobSel.innerHTML = '<option value="">Select a job...</option>' +
      activeJobs.map(j => `<option value="${j.id}" ${j.id===cur?'selected':''}>${esc(j.jobNumber?'#'+j.jobNumber+' ':'')}${esc(j.name)}</option>`).join('');
  }

  // Manual entry job selector
  const manualJobSel = document.getElementById('manualJobSelect');
  if (manualJobSel) {
    const cur = manualJobSel.value;
    manualJobSel.innerHTML = '<option value="">Select job...</option>' +
      conJobs.map(j => `<option value="${j.id}" ${j.id===cur?'selected':''}>${esc(j.jobNumber?'#'+j.jobNumber+' ':'')}${esc(j.name)}</option>`).join('');
  }

  // Manual entry crew selector -- real team roster instead of free
  // text, so names are consistent and match who's actually on the
  // team (no typos, no "Jon" vs "Jason" fragmenting the same person
  // across entries).
  const manualCrewSel = document.getElementById('manualCrew');
  if (manualCrewSel) {
    const cur3 = manualCrewSel.value;
    manualCrewSel.innerHTML = '<option value="">Myself</option>' +
      (_lastTeamMemberList || []).map(m => `<option value="${esc(m.name||m.email||'')}" ${(m.name||m.email)===cur3?'selected':''}>${esc(m.name||m.email||'')}</option>`).join('');
  }

  // Set today's date on manual entry
  const manualDate = document.getElementById('manualDate');
  if (manualDate && !manualDate.value) manualDate.value = new Date().toISOString().split('T')[0];

  const filterJobSel = document.getElementById('timeFilterJob');
  if (filterJobSel) {
    const cur2 = filterJobSel.value;
    filterJobSel.innerHTML = '<option value="">All Jobs</option>' +
      conJobs.map(j => `<option value="${j.id}" ${j.id===cur2?'selected':''}>${esc(j.name)}</option>`).join('');
  }
}

// ── Overtime Rules ──────────────────────────────────────────────────
// Splits logged hours into regular vs. overtime per employee per work
// week (Settings > Overtime Rules: threshold, multiplier, week-start day).
// True labor cost = regular hrs × burden rate + OT hrs × burden rate ×
// OT multiplier. This is the actuals-side complement to Labor Burden
// (which sets the *estimated* cost) — together they set up the
// Estimate vs. Actual comparison that's next on the backlog.
function getOtSettings() {
  const p = companyProfile || {};
  return {
    threshold: p.otWeeklyThreshold > 0 ? p.otWeeklyThreshold : 40,
    multiplier: p.otMultiplier > 0 ? p.otMultiplier : 1.5,
    weekStart: p.weekStartDay === 'sun' ? 0 : 1 // 0=Sunday, 1=Monday
  };
}

// Returns the ISO date (YYYY-MM-DD) of the start of the work week
// containing the given date string, per the configured week-start day.
function weekStartOf(dateStr, weekStartDow) {
  const d = new Date(dateStr + 'T00:00:00');
  const day = d.getDay(); // 0=Sun..6=Sat
  const diff = (day - weekStartDow + 7) % 7;
  d.setDate(d.getDate() - diff);
  return d.toISOString().split('T')[0];
}

function computeWeeklyOvertime(entries) {
  const { threshold, multiplier, weekStart } = getOtSettings();
  const buckets = {}; // key: userKey|weekStartDate

  entries.forEach(e => {
    if (!e.hours || !e.date) return;
    const userKey = e.userId || e.userEmail || e.userName || 'unknown';
    const wkStart = weekStartOf(e.date, weekStart);
    const key = userKey + '|' + wkStart;
    if (!buckets[key]) {
      // Per-person rate looked up once per bucket, not per-entry —
      // same rate applies to every hour this person logged in this
      // week regardless of which job/entry it came from.
      buckets[key] = { userName: e.userName || e.userEmail || 'Unknown', weekStart: wkStart, hours: 0,
        burdenRate: getPersonBurdenRate(e.userId, e.userEmail),
        isSubcontractor: isFlatRateSubcontractor(e.userId, e.userEmail) };
    }
    buckets[key].hours += e.hours;
  });

  return Object.values(buckets).map(b => {
    const regHours = Math.min(b.hours, threshold);
    const otHours = Math.max(0, b.hours - threshold);
    // Flat-rate subcontractors: hours still show (useful for checking
    // estimating accuracy later), but hours×rate is NOT their real
    // cost — that's a separately-agreed job price entered elsewhere —
    // so cost stays 0 here rather than silently implying a dollar
    // figure nobody actually owes.
    const cost = b.isSubcontractor ? 0 : (regHours * b.burdenRate + otHours * b.burdenRate * multiplier);
    return { ...b, regHours, otHours, cost, isOt: otHours > 0 };
  }).sort((a,b) => b.weekStart.localeCompare(a.weekStart) || b.hours - a.hours);
}

function renderWeeklyOvertime() {
  const el = document.getElementById('weeklyOtSummary');
  if (!el) return;

  const jobFilter = document.getElementById('timeFilterJob')?.value || '';
  const userFilter = document.getElementById('timeFilterUser')?.value || '';
  let entries = (typeof allTimeEntries !== 'undefined') ? allTimeEntries : [];
  if (jobFilter) entries = entries.filter(e => e.jobId === jobFilter);
  if (userFilter) entries = entries.filter(e => e.userId === userFilter || e.userEmail === userFilter);

  const weeks = computeWeeklyOvertime(entries).slice(0, 12); // most recent 12 person-weeks
  const { threshold, multiplier } = getOtSettings();

  if (!weeks.length) {
    el.innerHTML = '<span class="small muted" style="font-style:italic">No hours logged yet.</span>';
    return;
  }

  el.innerHTML = `
    <div class="small muted" style="margin-bottom:8px">${threshold}h/week threshold · ${multiplier}× OT rate · burden rate per person (Settings &gt; Team)</div>
    <table class="kt-table" style="font-size:.8rem">
      <thead><tr><th>Employee</th><th>Week Of</th><th style="text-align:right">Reg</th><th style="text-align:right">OT</th><th style="text-align:right">True Cost</th></tr></thead>
      <tbody>
        ${weeks.map(w => `<tr${w.isOt ? ' style="background:rgba(217,119,6,.08)"' : ''}>
          <td>${esc(w.userName)}${w.isSubcontractor ? ' <span style="font-size:.68rem;color:var(--muted)">(1099 flat-rate)</span>' : ''}</td>
          <td>${w.weekStart}</td>
          <td style="text-align:right">${w.regHours.toFixed(1)}h</td>
          <td style="text-align:right;${w.isOt ? 'color:var(--amber);font-weight:700' : 'color:var(--muted)'}">${w.otHours > 0 ? w.otHours.toFixed(1)+'h' : '—'}</td>
          <td style="text-align:right;font-weight:700;${w.isSubcontractor ? 'color:var(--muted);font-style:italic;font-weight:400' : 'color:#a3f2d2'}">${w.isSubcontractor ? 'flat-rate — see job cost' : '$'+w.cost.toFixed(0)}</td>
        </tr>`).join('')}
      </tbody>
    </table>`;
}
window.renderWeeklyOvertime = renderWeeklyOvertime;

function renderTimeLog() {
  const tbody = document.getElementById('timeLogBody');
  const tfoot = document.getElementById('timeLogFoot');
  const totalEl = document.getElementById('timeLogTotal');
  if (!tbody) return;

  const jobFilter = document.getElementById('timeFilterJob')?.value || '';
  const userFilter = document.getElementById('timeFilterUser')?.value || '';

  let entries = allTimeEntries;
  if (jobFilter) entries = entries.filter(e => e.jobId === jobFilter);
  if (userFilter) entries = entries.filter(e => e.userId === userFilter || e.userEmail === userFilter);

  const totalHours = entries.filter(e => e.hours).reduce((s,e) => s + e.hours, 0);
  if (totalEl) totalEl.textContent = `${entries.length} entries · ${totalHours.toFixed(1)}h total`;

  if (!entries.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:24px;font-style:italic">No time entries yet.</td></tr>';
    if (tfoot) tfoot.innerHTML = '';
    renderWeeklyOvertime();
    return;
  }

  tbody.innerHTML = entries.map(e => {
    const inTime = e.clockInISO ? new Date(e.clockInISO).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) : '—';
    const outTime = e.clockOutISO ? new Date(e.clockOutISO).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}) : null;
    return `<tr>
      <td><div style="font-weight:600">${esc(e.userName||'')}</div><div style="font-size:.72rem;color:var(--muted)">${esc(e.userEmail||'')}</div></td>
      <td style="font-size:.82rem;color:var(--amber)">${esc(e.jobName||'—')}</td>
      <td style="font-size:.78rem;color:#60a5fa">${e.phaseName ? '⚡ '+esc(e.phaseName) : '<span style="color:var(--muted)">—</span>'}</td>
      <td style="font-size:.82rem">${e.date||'—'}</td>
      <td style="font-size:.82rem">${inTime}${e.offSite ? ` <span title="${e.distanceFt != null ? e.distanceFt + ' ft from jobsite' : 'Off-site'}" style="background:rgba(239,83,80,.15);color:#ef5350;font-size:.65rem;font-weight:800;padding:2px 6px;border-radius:5px;margin-left:4px;white-space:nowrap">📍 OFF-SITE</span>` : ''}</td>
      <td style="font-size:.82rem">${outTime || '<span class="clocked-in-badge" style="font-size:.68rem">● Live</span>'}</td>
      <td style="text-align:right;font-weight:700;color:${e.hours?'#a3f2d2':'var(--muted)'}">
        ${e.hours ? e.hours.toFixed(2)+'h' : '—'}
      </td>
      <td style="font-size:.78rem;color:var(--muted)">${esc(e.notes||'')}</td>
      <td>
        ${(() => {
          const canManage = currentUserRole === 'Owner' || currentUserTeamData?.fullAccessOverride;
          const isOwnLiveEntry = !e.clockOut && e.userId === conCurrentUser?.uid;
          const buttons = [];
          if (!e.clockOut && (isOwnLiveEntry || canManage)) {
            buttons.push(`<button class="btn btn-danger" onclick="forceClockOut('${e.id}')" style="padding:3px 8px;font-size:.74rem">Clock Out</button>`);
          }
          if (canManage) {
            buttons.push(`<button class="btn" onclick="openEditTimeEntry('${e.id}')" style="padding:3px 8px;font-size:.74rem">✏️ Edit</button>`);
          }
          buttons.push(`<button class="btn" onclick="deleteTimeEntry('${e.id}')" style="padding:3px 8px;font-size:.74rem">✕</button>`);
          return buttons.join(' ');
        })()}
      </td>
    </tr>`;
  }).join('');

  if (tfoot) tfoot.innerHTML = `<tr style="background:rgba(217,119,6,.06);font-weight:800">
    <td colspan="6" style="padding:10px 12px;color:var(--amber)">TOTAL (${entries.filter(e=>e.hours).length} entries)</td>
    <td style="text-align:right;color:#a3f2d2">${totalHours.toFixed(2)}h</td>
    <td colspan="2"></td>
  </tr>`;
  renderWeeklyOvertime();
}

// Owner/Full-Access editing for an existing time entry -- corrects a
// wrong clock-in time, adjusts hours after the fact, or fixes a typo
// in notes. Previously the only options on any entry were "force
// clock out your own live entry" or "delete" -- no way to actually
// correct a mistake without losing the record and re-entering it from
// scratch, and no way to touch anyone else's entry but your own live
// one at all.
function openEditTimeEntry(entryId) {
  const entry = allTimeEntries.find(e => e.id === entryId);
  if (!entry) return;
  const canManage = currentUserRole === 'Owner' || currentUserTeamData?.fullAccessOverride;
  if (!canManage) { alert('Only Owners (or team members with Full Access Override) can edit time entries.'); return; }

  document.getElementById('editTimeEntryWho').textContent = `${entry.userName || 'Unknown'} · ${entry.jobName || 'No job'}${entry.phaseName ? ' · ' + entry.phaseName : ''}`;
  document.getElementById('editTimeDate').value = entry.date || '';
  document.getElementById('editTimeClockIn').value = entry.clockInISO ? isoToLocalDatetimeInput(entry.clockInISO) : '';
  document.getElementById('editTimeClockOut').value = entry.clockOutISO ? isoToLocalDatetimeInput(entry.clockOutISO) : '';
  document.getElementById('editTimeHours').value = entry.hours != null ? entry.hours : '';
  document.getElementById('editTimeNotes').value = entry.notes || '';
  document.getElementById('editTimeEntryModal').dataset.entryId = entryId;
  kOpen('editTimeEntryModal');
}
window.openEditTimeEntry = openEditTimeEntry;

// datetime-local inputs need "YYYY-MM-DDTHH:mm" in the browser's own
// local time, not UTC -- toISOString() would silently shift the
// displayed time by the browser's UTC offset every time this modal
// opens, showing the wrong clock-in time even though the stored value
// is correct.
function isoToLocalDatetimeInput(iso) {
  const d = new Date(iso);
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function saveEditTimeEntry() {
  const entryId = document.getElementById('editTimeEntryModal').dataset.entryId;
  if (!entryId) return;
  const canManage = currentUserRole === 'Owner' || currentUserTeamData?.fullAccessOverride;
  if (!canManage) { alert('Only Owners (or team members with Full Access Override) can edit time entries.'); return; }

  const date = document.getElementById('editTimeDate').value;
  const clockInVal = document.getElementById('editTimeClockIn').value;
  const clockOutVal = document.getElementById('editTimeClockOut').value;
  const hoursVal = document.getElementById('editTimeHours').value;
  const notes = document.getElementById('editTimeNotes').value.trim();

  if (!date) { alert('Date is required.'); return; }

  const updates = { date, notes, editedAt: firebase.firestore.FieldValue.serverTimestamp(), editedBy: conCurrentUser?.email || '' };
  const del = firebase.firestore.FieldValue.delete();

  if (clockInVal) {
    const clockInDate = new Date(clockInVal);
    updates.clockInISO = clockInDate.toISOString();
    updates.clockIn = firebase.firestore.Timestamp.fromDate(clockInDate);
    if (clockOutVal) {
      const clockOutDate = new Date(clockOutVal);
      if (clockOutDate <= clockInDate) { alert('Clock Out must be after Clock In.'); return; }
      updates.clockOutISO = clockOutDate.toISOString();
      updates.clockOut = firebase.firestore.Timestamp.fromDate(clockOutDate);
      updates.hours = Math.round((clockOutDate - clockInDate) / 3600000 * 100) / 100;
    } else {
      // Clock In given, Clock Out left blank -- back to live/in-progress.
      updates.clockOutISO = del;
      updates.clockOut = del;
      updates.hours = del;
    }
  } else {
    // No clock times at all -- treat as a manual hours entry.
    updates.clockInISO = del;
    updates.clockIn = del;
    updates.clockOutISO = del;
    updates.clockOut = del;
    const hours = parseFloat(hoursVal);
    if (isNaN(hours) || hours <= 0) { alert('Enter hours, or set a Clock In time instead.'); return; }
    updates.hours = hours;
  }

  coll('timeentries').doc(entryId).update(updates).then(() => {
    kClose('editTimeEntryModal');
  }).catch(e => alert('Error saving: ' + e.message));
}
window.saveEditTimeEntry = saveEditTimeEntry;

function forceClockOut(entryId) {
  const entry = allTimeEntries.find(e => e.id === entryId);
  if (!entry) return;
  const now = new Date();
  const clockInTime = entry.clockInISO ? new Date(entry.clockInISO) : new Date(now - 3600000);
  const hours = Math.round((now - clockInTime) / 3600000 * 100) / 100;
  coll('timeentries').doc(entryId).update({
    clockOut: firebase.firestore.FieldValue.serverTimestamp(),
    clockOutISO: now.toISOString(),
    hours
  }).catch(e => alert('Error: ' + e.message));
}

function deleteTimeEntry(id) {
  if (!confirm('Delete this time entry?')) return;
  coll('timeentries').doc(id).delete().catch(e => alert('Error: ' + e.message));
}

// ════════════════════════════════════════════════════
// ── CALENDAR ──
// ════════════════════════════════════════════════════
let _calDate = new Date();
let _calView = 'month';

function switchCalView(view, btn) {
  _calView = view;
  document.querySelectorAll('.view-toggle-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  document.getElementById('calMonthView').style.display = view === 'month' ? 'block' : 'none';
  document.getElementById('calWeekView').style.display = view === 'week' ? 'block' : 'none';
  renderCalendar();
}

function calNav(dir) {
  if (_calView === 'month') {
    _calDate = new Date(_calDate.getFullYear(), _calDate.getMonth() + dir, 1);
  } else {
    _calDate = new Date(_calDate.getTime() + dir * 7 * 86400000);
  }
  renderCalendar();
}

function calGoToday() {
  _calDate = new Date();
  renderCalendar();
  // In week view, scroll to current time after render
  if (_calView === 'week') {
    setTimeout(() => {
      const scrollTarget = document.querySelector('#calWeekView div[style*="overflow-y"]');
      if (scrollTarget) scrollTarget.scrollTop = (new Date().getHours() - 6) * 48;
    }, 100);
  }
}

function renderCalendar() {
  const titleEl = document.getElementById('calTitle');
  if (_calView === 'month') {
    if (titleEl) titleEl.textContent = _calDate.toLocaleDateString(undefined,{month:'long',year:'numeric'});
    renderMonthView();
  } else {
    // Get start of week (Sunday)
    const dow = _calDate.getDay();
    const weekStart = new Date(_calDate.getTime() - dow * 86400000);
    const weekEnd = new Date(weekStart.getTime() + 6 * 86400000);
    if (titleEl) titleEl.textContent =
      weekStart.toLocaleDateString(undefined,{month:'short',day:'numeric'}) + ' – ' +
      weekEnd.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
    renderWeekView(weekStart);
  }
}

function renderMonthView() {
  const grid = document.getElementById('calMonthGrid');
  if (!grid) return;
  const today = new Date().toISOString().split('T')[0];
  const year = _calDate.getFullYear();
  const month = _calDate.getMonth();
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrev = new Date(year, month, 0).getDate();

  let cells = '';
  // Previous month fill
  for (let i = firstDay - 1; i >= 0; i--) {
    const d = daysInPrev - i;
    cells += `<div class="cal-day other-month"><div class="cal-day-num">${d}</div></div>`;
  }
  // Current month
  for (let d = 1; d <= daysInMonth; d++) {
    const dateISO = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const isToday = dateISO === today;
    const events = getCalEvents(dateISO);
    const evHtml = events.slice(0,3).map(ev =>
      `<div class="cal-event" style="background:${ev.color}22;color:${ev.color};border-left:2px solid ${ev.color}">${ev.label}</div>`
    ).join('') + (events.length > 3 ? `<div style="font-size:.6rem;color:var(--muted)">+${events.length-3} more</div>` : '');
    cells += `<div class="cal-day${isToday?' today':''}">
      <div class="cal-day-num">${d}</div>
      ${evHtml}
    </div>`;
  }
  // Next month fill
  const totalCells = Math.ceil((firstDay + daysInMonth) / 7) * 7;
  for (let d = 1; d <= totalCells - firstDay - daysInMonth; d++) {
    cells += `<div class="cal-day other-month"><div class="cal-day-num">${d}</div></div>`;
  }
  grid.innerHTML = cells;
}

function renderWeekView(weekStart) {
  const header = document.getElementById('calWeekHeader');
  const grid = document.getElementById('calWeekGrid');
  if (!header || !grid) return;
  const today = new Date().toISOString().split('T')[0];
  const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  // Build week day dates
  const weekDays = Array.from({length:7}, (_,i) => {
    const d = new Date(weekStart.getTime() + i * 86400000);
    return { d, iso: d.toISOString().split('T')[0], isToday: d.toISOString().split('T')[0] === today };
  });

  // Header row with day names + dates
  header.innerHTML = '<div style="padding:8px 4px;font-size:.7rem;color:var(--muted);border-bottom:1px solid rgba(110,145,210,.1)"></div>' +
    weekDays.map(({d, iso, isToday}) => {
      // Count events for badge
      const evCount = window.getCalEvents(iso).length;
      return `<div style="text-align:center;padding:8px 4px;font-size:.78rem;font-weight:700;color:${isToday?'var(--amber)':'var(--muted)'};border-bottom:1px solid rgba(110,145,210,.1)">
        ${days[d.getDay()]}<br>
        <span style="font-size:1.1rem;color:${isToday?'var(--amber)':'#eaf0fb'};${isToday?'background:var(--amber);color:#000;border-radius:50%;width:26px;height:26px;display:inline-flex;align-items:center;justify-content:center;':''}">${d.getDate()}</span>
        ${evCount>0?`<div style="font-size:.65rem;color:var(--amber);margin-top:2px">${evCount} event${evCount>1?'s':''}</div>`:''}
      </div>`;
    }).join('');

  // All-day events row (phases, todos without time)
  const allDayRow = '<div style="font-size:.65rem;color:var(--muted);padding:4px;text-align:right;border-bottom:1px solid rgba(110,145,210,.1)">all-day</div>' +
    weekDays.map(({iso}) => {
      const allDay = window.getCalEvents(iso).filter(e => e.type === 'phase' || (e.type === 'todo') || (e.type === 'event' && !e.ev?.time));
      return `<div style="padding:2px;border-bottom:1px solid rgba(110,145,210,.1);min-height:28px">
        ${allDay.map(e => `<span class="cal-event-pill" style="background:${e.color}20;color:${e.color};border-left-color:${e.color};font-size:.62rem;cursor:${e.type==='phase'||e.type==='event'?'pointer':'default'}" onclick="event.stopPropagation();${e.type==='phase'?`openJobDetail('${e.jobId}');switchDetailTab('phases',null)`:e.type==='event'?`openCalEventModal('${e.id}')`:''}" title="${e.label}">${e.label.slice(0,20)}${e.label.length>20?'…':''}</span>`).join('')}
      </div>`;
    }).join('');

  // Hour rows 6am-9pm
  let rows = '';
  const now = new Date();
  const currentHour = now.getHours();
  const currentMin = now.getMinutes();

  for (let h = 6; h <= 21; h++) {
    const label = h < 12 ? `${h}am` : h === 12 ? '12pm' : `${h-12}pm`;
    rows += `<div class="cal-week-hour" style="font-size:.68rem;color:var(--muted);text-align:right;padding-right:8px;padding-top:6px;border-top:1px solid rgba(110,145,210,.06)">${label}</div>`;

    weekDays.forEach(({d, iso, isToday}) => {
      // Get timed events for this hour
      const timedEvents = window.getCalEvents(iso).filter(e => {
        if (e.type === 'event' && e.ev?.time) {
          const evH = parseInt(e.ev.time.split(':')[0]);
          return evH === h;
        }
        if (e.type === 'time') {
          const entry = allTimeEntries.find(t => t.id === e.id);
          if (entry?.clockInISO) {
            return new Date(entry.clockInISO).getHours() === h;
          }
        }
        return false;
      });

      const isCurrentHour = isToday && h === currentHour;
      const timeBarPos = isCurrentHour ? Math.round((currentMin / 60) * 100) : -1;

      rows += `<div style="border-top:1px solid rgba(110,145,210,.06);min-height:48px;padding:2px;position:relative;background:${isToday?'rgba(217,119,6,.03)':'transparent'}">
        ${timeBarPos >= 0 ? `<div style="position:absolute;left:0;right:0;top:${timeBarPos}%;height:2px;background:var(--amber);z-index:2;opacity:.7"></div>` : ''}
        ${timedEvents.map(e => `<span class="cal-event-pill" style="background:${e.color}20;color:${e.color};border-left-color:${e.color};font-size:.68rem;cursor:pointer" onclick="${e.type==='event'?`openCalEventModal('${e.id}')`:''}">
          ${e.label.slice(0,22)}${e.label.length>22?'…':''}
          ${e.ev?.meetLink?`<a href="${e.ev.meetLink}" target="_blank" onclick="event.stopPropagation()" style="color:#fff;font-size:.6rem;background:#0d9488;border-radius:3px;padding:0 3px;margin-left:2px;text-decoration:none">🎥 Join</a>`:''}
        </span>`).join('')}
      </div>`;
    });
  }

  grid.innerHTML = allDayRow + rows;

  // Scroll to current hour (or 8am default)
  const scrollTarget = document.querySelector('#calWeekView div[style*="overflow-y"]');
  if (scrollTarget) {
    const targetHour = today >= weekDays[0].iso && today <= weekDays[6].iso ? Math.max(6, currentHour - 1) : 8;
    scrollTarget.scrollTop = (targetHour - 6) * 48;
  }
}

// Expose time + calendar functions
window.handleClockToggle = handleClockToggle;
window.forceClockOut = forceClockOut;
window.deleteTimeEntry = deleteTimeEntry;
window.renderTimeLog = renderTimeLog;
window.switchCalView = switchCalView;
window.calNav = calNav;
window.calGoToday = calGoToday;
window.renderCalendar = renderCalendar;

// ════════════════════════════════════════════════════
// ── VENDORS & SUBCONTRACTORS ──
// ════════════════════════════════════════════════════
let allVendors = [];
let _currentVendorId = null;
let _editingBillId = null;
let _vendorBills = []; // bills for current vendor detail view

function loadVendors() {
  if (!conDb) return;
  coll('vendors').orderBy('name').onSnapshot(snap => {
    allVendors = [];
    snap.forEach(doc => allVendors.push({ id: doc.id, ...doc.data() }));
    renderVendors();
    updateVendorBadge();
  }, () => {});
}

function updateVendorBadge() {
  const today = new Date().toISOString().split('T')[0];
  const in30 = new Date(Date.now() + 30*86400000).toISOString().split('T')[0];
  const expiring = allVendors.filter(v => v.insExp && v.insExp <= in30).length;
  const badge = document.getElementById('navVendorBadge');
  if (badge) { badge.style.display = expiring > 0 ? 'inline-flex' : 'none'; badge.textContent = expiring; }
}

function renderVendors() {
  const grid = document.getElementById('vendorGrid');
  const countEl = document.getElementById('vendorCount');
  if (!grid) return;

  const q = (document.getElementById('vendorSearch')?.value || '').toLowerCase();
  const tradeFilter = document.getElementById('vendorTradeFilter')?.value || '';
  const today = new Date().toISOString().split('T')[0];
  const in30 = new Date(Date.now() + 30*86400000).toISOString().split('T')[0];

  let vendors = allVendors;
  if (q) vendors = vendors.filter(v =>
    (v.name||'').toLowerCase().includes(q) ||
    (v.trade||'').toLowerCase().includes(q) ||
    (v.contact||'').toLowerCase().includes(q) ||
    (v.email||'').toLowerCase().includes(q)
  );
  if (tradeFilter) vendors = vendors.filter(v => v.trade === tradeFilter);

  // Stats
  const activeOnJobs = new Set(conJobs.flatMap(j => j.subIds||[])).size;
  const insWarn = allVendors.filter(v => v.insExp && v.insExp <= in30 && v.insExp >= today).length;
  const insExpired = allVendors.filter(v => v.insExp && v.insExp < today).length;
  const setEl = (id,v) => { const el=document.getElementById(id); if(el) el.textContent=v; };
  setEl('vendorStatTotal', allVendors.length);
  setEl('vendorStatActive', conJobs.filter(j=>ACTIVE_STATUSES.includes(j.status)).length + ' jobs active');
  setEl('vendorStatInsWarn', insWarn + (insExpired > 0 ? ` (+${insExpired} expired)` : ''));

  if (countEl) countEl.textContent = `${allVendors.length} vendor${allVendors.length!==1?'s':''} total`;

  if (!vendors.length) {
    grid.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--muted);font-style:italic">
      ${allVendors.length===0 ? 'No vendors yet. Add your first vendor or subcontractor above.' : 'No vendors match your search.'}
    </div>`;
    return;
  }

  grid.innerHTML = vendors.map(v => {
    const insExpired = v.insExp && v.insExp < today;
    const insWarn = v.insExp && !insExpired && v.insExp <= in30;
    const insClass = insExpired ? 'ins-expired' : insWarn ? 'ins-warn' : 'ins-ok';
    const insLabel = insExpired ? '⚠️ INS EXPIRED' : insWarn ? '⚠️ Ins expiring' : v.insExp ? '✓ Insured' : '';
    const statusColors = { Active:'#1dbb87', Preferred:'#f59e0b', 'On Hold':'#ef5350', Inactive:'#6b7280' };
    const sColor = statusColors[v.status||'Active'] || '#1dbb87';
    // Jobs linked to this vendor
    const linkedJobs = conJobs.filter(j => (j.vendorIds||[]).includes(v.id)).length;
    const initials = (v.name||'?').split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase();

    return `<div class="vendor-card" onclick="openVendorDetail('${v.id}')">
      <div style="display:flex;gap:12px;align-items:flex-start;margin-bottom:10px">
        <div class="vendor-avatar">${initials}</div>
        <div style="flex:1;min-width:0">
          <div style="font-weight:800;font-size:.95rem;color:#eaf0fb">${esc(v.name||'')}</div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px">
            <span class="vendor-trade-badge">${esc(v.trade||'')}</span>
            <span style="font-size:.7rem;font-weight:700;color:${sColor}">${v.status||'Active'}</span>
          </div>
        </div>
        ${linkedJobs > 0 ? `<span style="background:var(--amber-dim);color:var(--amber);border:1px solid var(--amber-border);border-radius:999px;padding:2px 8px;font-size:.7rem;font-weight:700;white-space:nowrap">${linkedJobs} job${linkedJobs!==1?'s':''}</span>` : ''}
      </div>
      <div style="display:flex;flex-direction:column;gap:4px">
        ${v.contact ? `<div style="font-size:.82rem;color:var(--muted)">👤 ${esc(v.contact)}</div>` : ''}
        ${v.phone ? `<div style="font-size:.82rem;display:flex;align-items:center;gap:6px">
          <a href="tel:${esc(v.phone)}" onclick="event.stopPropagation()" style="color:#a3f2d2;text-decoration:none;font-weight:600">📞 ${esc(v.phone)}</a>
          <a href="sms:${esc(v.phone)}" onclick="event.stopPropagation()" style="background:rgba(59,130,246,.15);color:#93c5fd;border:1px solid rgba(59,130,246,.25);border-radius:6px;padding:1px 7px;font-size:.7rem;font-weight:700;text-decoration:none">📱 Text</a>
        </div>` : ''}
        ${v.email ? `<div style="font-size:.82rem"><a href="mailto:${esc(v.email)}" onclick="event.stopPropagation()" style="color:#eaf0fb;text-decoration:none">✉️ ${esc(v.email)}</a></div>` : ''}
        ${v.insExp ? `<div style="font-size:.76rem;margin-top:4px" class="${insClass}">${insLabel}: ${v.insExp}</div>` : ''}
        ${v.payTerms ? `<div style="font-size:.74rem;color:rgba(110,145,210,.4)">Terms: ${esc(v.payTerms)}</div>` : ''}
      </div>
    </div>`;
  }).join('');
}

// ── Vendor Detail Modal ──
function openVendorDetail(id) {
  const v = allVendors.find(x => x.id === id);
  if (!v) return;
  _currentVendorId = id;
  const modal = document.getElementById('vendorDetailModal');
  if (modal) modal.dataset.vendorId = id;

  const today = new Date().toISOString().split('T')[0];
  const insExpired = v.insExp && v.insExp < today;
  const insWarn = v.insExp && !insExpired && v.insExp <= new Date(Date.now()+30*86400000).toISOString().split('T')[0];

  const setEl = (id, v) => { const el = document.getElementById(id); if(el) el.textContent = v || '—'; };
  setEl('vdName', v.name);
  setEl('vdContact', v.contact);
  setEl('vdPhone', v.phone);
  setEl('vdEmail', v.email);
  setEl('vdLicense', v.license);
  setEl('vdPayTerms', v.payTerms);
  setEl('vdRate', v.rate ? `$${v.rate}/hr` : '—');
  setEl('vdAddress', v.address);
  setEl('vdNotes', v.notes);

  const tradeEl = document.getElementById('vdTrade');
  if (tradeEl) tradeEl.textContent = v.trade || '';

  const statusEl = document.getElementById('vdStatus');
  const statusColors = { Active:'#1dbb87', Preferred:'#f59e0b', 'On Hold':'#ef5350', Inactive:'#6b7280' };
  if (statusEl) { statusEl.textContent = v.status||'Active'; statusEl.style.color = statusColors[v.status||'Active']; }

  const insEl = document.getElementById('vdInsExp');
  if (insEl) {
    insEl.textContent = v.insExp || '—';
    insEl.className = insExpired ? 'ins-expired' : insWarn ? 'ins-warn' : '';
  }

  // Jobs tab
  const jobListEl = document.getElementById('vdJobList');
  if (jobListEl) {
    const linked = conJobs.filter(j => (j.vendorIds||[]).includes(id) || j.client === v.name);
    if (!linked.length) {
      jobListEl.innerHTML = '<p class="muted" style="font-style:italic">No jobs linked to this vendor yet.</p>';
    } else {
      jobListEl.innerHTML = linked.map(j => {
        const s = KYTRAC_STATUSES.find(x => x.name === j.status) || {color:'var(--amber)'};
        return `<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid rgba(110,145,210,.07);cursor:pointer" onclick="kClose('vendorDetailModal');openJobDetail('${j.id}')">
          <div><div style="font-weight:700">${esc(j.name)}</div><div style="font-size:.76rem;color:var(--amber)">${esc(j.jobNumber||'')}</div></div>
          <span style="background:${s.color}22;color:${s.color};padding:2px 8px;border-radius:999px;font-size:.72rem;font-weight:700">${j.status}</span>
        </div>`;
      }).join('');
    }
  }

  switchVendorTab('info', document.querySelector('#vendorDetailModal .con-subtab'));
  loadVendorBills(id);
  kOpen('vendorDetailModal');
}

function switchVendorTab(tab, btn) {
  ['info','jobs','bills'].forEach(t => {
    const el = document.getElementById('vdTab' + t.charAt(0).toUpperCase() + t.slice(1));
    if (el) el.style.display = t === tab ? 'block' : 'none';
  });
  document.querySelectorAll('#vendorDetailModal .con-subtab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  else {
    const btns = document.querySelectorAll('#vendorDetailModal .con-subtab');
    const idx = ['info','jobs','bills'].indexOf(tab);
    if (btns[idx]) btns[idx].classList.add('active');
  }
}

// ── Vendor CRUD ──
