// ════════════════════════════════════════════════════
// ── CUSTOMER PORTAL ──
// ════════════════════════════════════════════════════

// ── Check for portal URL parameter on page load ──
function checkPortalMode() {
  const params = new URLSearchParams(window.location.search);
  const token = params.get('portal');
  if (token) {
    // Hide main app, show portal
    document.getElementById('ktAuthWall').style.display = 'none';
    document.getElementById('ktApp').style.display = 'none';
    document.getElementById('ktPortalView').classList.add('active');
    loadPortalData(token);
  }
}

function loadPortalData(token) {
  // Token format: jobId-randomHash
  // Extract jobId from token
  const parts = token.split('-hash-');
  const jobId = parts[0];
  if (!jobId) { showPortalNotFound(); return; }

  // Load Firebase for portal (read-only anonymous access)
  // Portal uses same Firebase project but reads via token validation
  function loadNext(i, scripts) {
    if (i >= scripts.length) { initPortalFirebase(jobId, token); return; }
    const s = document.createElement('script');
    s.src = scripts[i];
    s.onload = () => loadNext(i+1, scripts);
    s.onerror = () => showPortalNotFound();
    document.head.appendChild(s);
  }

  if (typeof firebase !== 'undefined') {
    initPortalFirebase(jobId, token);
  } else {
    loadNext(0, [
      'https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js',
      'https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore-compat.js'
    ]);
  }
}

function initPortalFirebase(jobId, token) {
  try {
    let app, db;
    if (firebase.apps.length) {
      app = firebase.apps[0];
    } else {
      app = firebase.initializeApp(CON_FIREBASE_CONFIG);
    }
    db = firebase.firestore();

    // Validate token exists in Firestore
    db.collection('portalTokens').doc(token).get()
      .then(tokenDoc => {
        if (!tokenDoc.exists) { showPortalNotFound(); return; }
        const tokenData = tokenDoc.data();
        if (tokenData.jobId !== jobId) { showPortalNotFound(); return; }
        if (tokenData.expires && tokenData.expires < Date.now()) {
          showPortalNotFound(); return;
        }
        // Token valid - load all portal data
        return loadPortalJob(db, jobId, tokenData, token);
      })
      .catch(() => {
        // If token collection doesn't exist yet, try loading job directly
        // This allows portal to work even before token system is set up
        loadPortalJob(db, jobId, {}, token);
      });
  } catch(e) {
    showPortalNotFound();
  }
}

// Module-level refs so the signature-pad submit handler (fired from a
// button click, not from inside loadPortalJob's closure) can still reach
// the right Firestore scope. _portalToken is included on every write the
// portal makes (signature, decline, view timestamp) so Firestore security
// rules can validate the anonymous visitor against the portalTokens
// collection — rules have no other way to check a "bearer token" style
// credential for an unauthenticated portal visitor.
let _portalDb = null;
let _portalCompanyId = null;
let _portalJobId = null;
let _portalJobName = null;
let _portalColl = null;
let _portalLatestProposal = null;
let _portalToken = null;
// True only when the current portal load is a subcontractor agreement
// link (?subagreement=...), not a customer link. Gates the customer's
// pricing, payment schedule, invoices, activity log, and messages out
// of what a subcontractor's link can see -- checked in loadPortalJob()
// (what gets loaded at all) and renderPortalProposal() (what gets shown
// from the shared room/task list vs. the customer-only financial parts).
let _portalSubAgreementMode = false;

function loadPortalJob(db, jobId, tokenData, token) {
  _portalToken = token || null;
  const companyId = tokenData.companyId || null;
  _portalDb = db;
  _portalCompanyId = companyId;
  _portalJobId = jobId;

  // Helper to get company-scoped collection
  function portalColl(name) {
    if (companyId) return db.collection('companies').doc(companyId).collection(name);
    return db.collection(name); // fallback for old tokens
  }
  _portalColl = portalColl;

  // Subcontractor Agreement links are a different audience than the
  // customer -- see the flag's own comment above for what this gates.
  const urlSubAgreementId = new URLSearchParams(location.search).get('subagreement');
  _portalSubAgreementMode = !!urlSubAgreementId;
  if (_portalSubAgreementMode) {
    // Unlike portalInvoicesSection/portalCOSection, these two have no
    // display:none default in the HTML -- simply never loading their
    // data (done above) left them visible but empty instead of hidden.
    const logsSec = document.getElementById('portalLogsSection');
    const msgSec = document.getElementById('portalMessagesSection');
    if (logsSec) logsSec.style.display = 'none';
    if (msgSec) msgSec.style.display = 'none';
  }

  // Load company profile for branding
  portalColl('settings').doc('company').get()
    .then(doc => {
      const co = doc.exists ? doc.data() : {};
      renderPortalHeader(co);
    }).catch(() => renderPortalHeader({}));

  // Load job
  portalColl('jobs').doc(jobId).get()
    .then(doc => {
      if (!doc.exists) { showPortalNotFound(); return; }
      const job = { id: doc.id, ...doc.data() };
      _portalJobName = job.name || '';
      renderPortalJob(job);

      // Load phases
      portalColl('jobs').doc(jobId).collection('phases')
        .orderBy('startDate').get()
        .then(snap => {
          const phases = [];
          snap.forEach(d => phases.push({ id: d.id, ...d.data() }));
          renderPortalPhases(phases);
        }).catch(() => renderPortalPhases([]));

      // Daily logs, invoices, change orders, and messages are all
      // customer-only -- never loaded at all for a subcontractor link,
      // not just hidden after the fact.
      if (!_portalSubAgreementMode) {
        // Load shared daily logs (last 20)
        portalColl('jobs').doc(jobId).collection('logs')
          .orderBy('date','desc').limit(20).get()
          .then(snap => {
            const logs = [];
            snap.forEach(d => logs.push({ id: d.id, ...d.data() }));
            renderPortalLogs(logs);
          }).catch(() => renderPortalLogs([]));

        // Load invoices if sharing enabled
        if (tokenData.shareInvoices !== false) {
          portalColl('jobs').doc(jobId).collection('invoices')
            .orderBy('date','desc').get()
            .then(snap => {
              const invs = [];
              snap.forEach(d => invs.push({ id: d.id, ...d.data() }));
              renderPortalInvoices(invs, jobId);
            }).catch(() => {});
        }

        // Load approved change orders
        portalColl('jobs').doc(jobId).collection('changeorders')
          .where('status','==','Approved').get()
          .then(snap => {
            const cos = [];
            snap.forEach(d => cos.push({ id: d.id, ...d.data() }));
            renderPortalCOs(cos);
          }).catch(() => {});

        // Load customer's own message thread (portal only ever shows
        // customer-originated messages, never internal team chatter -
        // internal replies aren't customer-visible yet, a known v1 gap)
        loadPortalMessages(portalColl, jobId);
      }

      // Load the latest Proposal version (Draft versions are never shown
      // to the customer — only Pending/Approved/Declined are customer-facing).
      // Still loaded in sub-agreement mode -- it's the source of the
      // room/task scope checklist a subcontractor should see; the
      // customer-only pricing parts are suppressed inside
      // renderPortalProposal() itself via _portalSubAgreementMode.
      portalColl('jobs').doc(jobId).collection('proposals')
        .orderBy('version', 'desc').limit(1).get()
        .then(snap => {
          if (snap.empty) return;
          const d = snap.docs[0];
          renderPortalProposal({ id: d.id, ...d.data() }, jobId);
        }).catch(() => {});

      // Load lien waiver if ?waiver= param is present in the URL
      const urlWaiverId = new URLSearchParams(location.search).get('waiver');
      if (urlWaiverId) {
        // Small delay so portal sections are in the DOM first
        setTimeout(() => renderPortalLienWaiver(urlWaiverId), 400);
      }

      // Load subcontractor agreement if ?subagreement= param is present
      if (urlSubAgreementId) {
        setTimeout(() => renderPortalSubAgreement(urlSubAgreementId), 400);
      }
    })
    .catch(() => showPortalNotFound());
}

function renderPortalHeader(co) {
  const nameEl = document.getElementById('portalCompanyName');
  const subEl = document.getElementById('portalCompanySub');
  const logoEl = document.getElementById('portalLogoImg');
  const contactEl = document.getElementById('portalContactBar');
  const footerEl = document.getElementById('portalFooterCompany');

  if (nameEl) nameEl.textContent = co.companyName || 'Construction Company';
  if (subEl) subEl.textContent = co.address || 'Professional Construction Services';
  if (logoEl && co.logo) { logoEl.src = co.logo; logoEl.style.display = 'block'; }
  if (footerEl) footerEl.textContent = co.companyName || '';

  if (contactEl) {
    contactEl.innerHTML = [
      co.phone ? `<div class="portal-contact-item">📞 <a href="tel:${esc(co.phone)}">${esc(co.phone)}</a></div>` : '',
      co.email ? `<div class="portal-contact-item">✉️ <a href="mailto:${esc(co.email)}">${esc(co.email)}</a></div>` : '',
      co.website ? `<div class="portal-contact-item">🌐 <a href="${esc(co.website)}" target="_blank">${esc(co.website.replace(/https?:\/\//,''))}</a></div>` : '',
    ].join('');
  }
}

function renderPortalJob(job) {
  document.getElementById('portalLoading').style.display = 'none';
  document.getElementById('portalJobHero').style.display = 'block';

  document.getElementById('portalJobName').textContent = job.name || '';
  document.getElementById('portalJobAddress').textContent = job.address || '';

  const s = KYTRAC_STATUSES.find(x => x.name === job.status) || {color:'var(--amber)'};
  const statusEl = document.getElementById('portalJobStatus');
  if (statusEl) {
    statusEl.textContent = job.status || '';
    statusEl.style.background = s.color + '22';
    statusEl.style.color = s.color;
    statusEl.style.border = `1px solid ${s.color}44`;
  }

  const datesEl = document.getElementById('portalJobDates');
  if (datesEl && job.startDate) {
    datesEl.textContent = `Start: ${job.startDate}${job.endDate ? ' · Target: ' + job.endDate : ''}`;
  }

  // Build visual status track
  // Show simplified customer-facing stages
  const customerStages = [
    { label: 'Estimate', statuses: ['New Lead','Appointment Set','Building Estimate','Submitted'] },
    { label: 'Scheduled', statuses: ['To Be Scheduled','Permitting','Scheduled'] },
    { label: 'In Progress', statuses: ['In Progress','Inspection Pending'] },
    { label: 'Complete', statuses: ['Complete','Closed Completed'] },
  ];

  const currentIdx = customerStages.findIndex(st => st.statuses.includes(job.status));
  const trackEl = document.getElementById('portalStatusTrack');
  if (trackEl) {
    trackEl.innerHTML = customerStages.map((st, i) => {
      const isDone = i < currentIdx;
      const isActive = i === currentIdx;
      return `<div class="portal-stage">
        <div class="portal-stage-dot ${isDone?'done':isActive?'active':''}"></div>
        <div class="portal-stage-label ${isDone?'done':isActive?'active':''}">${st.label}</div>
      </div>
      ${i < customerStages.length-1 ? `<div class="portal-stage-line ${isDone?'done':''}"></div>` : ''}`;
    }).join('');
  }
}

function renderPortalPhases(phases) {
  const el = document.getElementById('portalPhasesList');
  const section = document.getElementById('portalPhasesSection');
  if (!el) return;

  if (!phases.length) {
    if (section) section.style.display = 'none';
    return;
  }

  const statusIcons = { 'not-started':'○', 'in-progress':'◐', 'complete':'●' };
  const statusColors = { 'not-started':'var(--muted)', 'in-progress':'var(--amber)', 'complete':'#1dbb87' };

  el.innerHTML = phases.map(p => {
    const color = statusColors[p.status] || 'var(--muted)';
    const icon = statusIcons[p.status] || '○';
    return `<div class="portal-phase-row">
      <span style="font-size:1.1rem;color:${color};flex-shrink:0">${icon}</span>
      <div style="flex:1">
        <div style="font-weight:700;font-size:.88rem">${esc(p.name||'Phase')}</div>
        ${p.startDate||p.endDate ? `<div style="font-size:.76rem;color:var(--muted)">${p.startDate||''}${p.endDate&&p.endDate!==p.startDate?' – '+p.endDate:''}</div>` : ''}
      </div>
      <span style="font-size:.72rem;font-weight:700;color:${color};text-transform:capitalize">${(p.status||'not-started').replace('-',' ')}</span>
    </div>`;
  }).join('');
}

function renderPortalLogs(logs) {
  const el = document.getElementById('portalLogsList');
  const countEl = document.getElementById('portalLogsCount');
  const section = document.getElementById('portalLogsSection');
  if (!el) return;

  if (countEl) countEl.textContent = `${logs.length} update${logs.length!==1?'s':''}`;

  if (!logs.length) {
    el.innerHTML = '<p class="muted" style="font-style:italic">No updates yet.</p>';
    return;
  }

  el.innerHTML = logs.map(log => {
    const hasPhotos = log.photos && log.photos.length > 0;
    return `<div class="portal-log-card">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <div style="font-weight:700;font-size:.82rem;color:var(--amber)">${log.date||''}</div>
        <div style="display:flex;gap:10px">
          ${log.weather?`<span style="font-size:.76rem;color:var(--muted)">🌤 ${esc(log.weather)}</span>`:''}
          ${log.crewCount?`<span style="font-size:.76rem;color:var(--muted)">👷 ${esc(String(log.crewCount))} on site</span>`:''}
        </div>
      </div>
      ${log.notes?`<div style="font-size:.86rem;color:#eaf0fb;line-height:1.6;margin-bottom:${hasPhotos?'10px':'0'}">${esc(log.notes)}</div>`:''}
      ${hasPhotos?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">
        ${log.photos.slice(0,8).map(p => `<img src="${p.dataUrl}" style="width:80px;height:80px;object-fit:cover;border-radius:8px;cursor:pointer;border:1px solid rgba(110,145,210,.2)" onclick="window.open('${p.dataUrl.replace(/'/g,"\\'")}','_blank')" />`).join('')}
      </div>`:''}
    </div>`;
  }).join('');
}

function renderPortalInvoices(invs, jobId) {
  // Draft invoices are still being put together — customers should
  // never see them. Previously every invoice rendered regardless of
  // status, meaning a Draft invoice with an unfinished/wrong amount
  // could be visible in the portal the moment it was saved.
  invs = invs.filter(i => i.status !== 'Draft');
  if (!invs.length) return;
  const section = document.getElementById('portalInvoicesSection');
  const el = document.getElementById('portalInvList');
  const sumEl = document.getElementById('portalInvSummary');
  if (!section || !el) return;

  section.style.display = 'block';
  const totalAmt = invs.reduce((s,i) => s+(i.total||0), 0);
  const totalPaid = invs.reduce((s,i) => s+(i.amtPaid||0), 0);
  if (sumEl) sumEl.textContent = `$${Math.round(totalPaid).toLocaleString()} paid of $${Math.round(totalAmt).toLocaleString()}`;

  const statusColors = { Draft:'var(--muted)', Sent:'#3b82f6', Paid:'#1dbb87', Overdue:'#ef5350', Partial:'#f97316' };

  // Same honest view-tracking as proposals: records the moment the customer
  // actually looks at a non-Draft invoice in the portal. Not email-open
  // tracking (JOBSMETRIX doesn't send email itself), but a real "they saw it" signal.
  if (jobId) {
    invs.forEach(inv => {
      if (inv.status !== 'Draft' && !inv.viewedAt) {
        _portalInvoiceColl(jobId).doc(inv.id).update({
          viewedAt: firebase.firestore.FieldValue.serverTimestamp()
        }).then(() => { inv.viewedAt = { toDate: () => new Date() }; }).catch(() => {});
      }
    });
  }

  el.innerHTML = invs.map(inv => {
    const bal = (inv.total||0) - (inv.amtPaid||0);
    const sColor = statusColors[inv.status] || 'var(--muted)';
    const payLink = inv.paymentLink; // Stripe only — never inv.qbPaymentLink in the customer portal
    const payBtn = payLink && bal > 0 && inv.status !== 'Paid'
      ? `<a href="${payLink}" target="_blank" style="display:inline-block;margin-top:8px;background:#d97706;color:#fff;font-size:.78rem;font-weight:800;padding:7px 18px;border-radius:8px;text-decoration:none">💳 Pay Now</a>`
      : '';
    const viewedBadge = inv.viewedAt?.toDate
      ? `<div style="font-size:.7rem;color:#1dbb87;margin-top:2px" title="Customer opened this invoice in the portal">👁 Viewed ${inv.viewedAt.toDate().toLocaleDateString()}</div>`
      : '';
    return `<div class="portal-invoice-row" style="flex-direction:column;gap:6px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start">
        <div>
          <div style="font-weight:700;color:var(--amber)">${esc(inv.number||'Invoice')}</div>
          <div style="font-size:.76rem;color:var(--muted)">${inv.date||''} · Due: ${inv.dueDate||'—'}</div>
          ${inv.type ? `<div style="font-size:.74rem;color:var(--muted)">${esc(inv.type)}</div>` : ''}
        </div>
        <div style="text-align:right">
          <div style="font-weight:800;font-size:1rem">$${(inv.total||0).toLocaleString()}</div>
          <div style="font-size:.76rem;color:${sColor};font-weight:700">${inv.status||'Draft'}</div>
          ${bal > 0 ? `<div style="font-size:.74rem;color:var(--muted)">Balance: $${bal.toFixed(2)}</div>` : ''}
          ${viewedBadge}
        </div>
      </div>
      ${payBtn}
    </div>`;
  }).join('');
}
function _portalInvoiceColl(jobId) {
  const base = _portalCompanyId
    ? _portalDb.collection('companies').doc(_portalCompanyId).collection('jobs')
    : _portalDb.collection('jobs');
  return base.doc(jobId).collection('invoices');
}

function renderPortalCOs(cos) {
  if (!cos.length) return;
  const section = document.getElementById('portalCOSection');
  const el = document.getElementById('portalCOList');
  if (!section || !el) return;
  section.style.display = 'block';
  el.innerHTML = cos.map(co => `
    <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(110,145,210,.07)">
      <div>
        <div style="font-weight:700">${esc(co.title||co.description||'Change Order')}</div>
        <div style="font-size:.76rem;color:var(--muted)">${co.date||''}</div>
      </div>
      <div style="text-align:right">
        <div style="font-weight:800;color:#a3f2d2">+$${(co.amount||0).toLocaleString()}</div>
        <div style="font-size:.72rem;color:#1dbb87;font-weight:700">Approved</div>
      </div>
    </div>`).join('');
}

// ── Portal Messages: customer-facing "Message Us" box ──
// Writes into the SAME jobs/{jobId}/messages collection the internal team
// thread uses (fromCustomer:true flag distinguishes them), so team members
// see customer messages inline in their existing Job > Messages tab with
// no extra plumbing. The portal itself only ever displays messages this
// specific customer sent (fromCustomer:true) - internal team replies
// aren't customer-visible yet, a known v1 limitation worth revisiting.
let _portalMsgUnsub = null;

function loadPortalMessages(portalColl, jobId) {
  if (_portalMsgUnsub) { try { _portalMsgUnsub(); } catch(e){} _portalMsgUnsub = null; }
  _portalMsgUnsub = portalColl('jobs').doc(jobId).collection('messages')
    .where('visibleToCustomer','==',true)
    .onSnapshot(snap => {
      const msgs = [];
      snap.forEach(d => msgs.push({ id: d.id, ...d.data() }));
      msgs.sort((a,b) => (a.createdMs||0) - (b.createdMs||0));
      renderPortalMessages(msgs);
    }, () => renderPortalMessages([]));
}

function renderPortalMessages(msgs) {
  const el = document.getElementById('portalMessagesList');
  if (!el) return;
  if (!msgs.length) {
    el.innerHTML = '<div class="small muted" style="font-style:italic;padding:8px 0">No messages yet — send one below.</div>';
    return;
  }
  el.innerHTML = msgs.map(m => {
    const mine = m.fromCustomer;
    const when = m.createdMs ? new Date(m.createdMs).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : '';
    return `<div style="display:flex;flex-direction:column;align-items:${mine?'flex-end':'flex-start'}">
      <div style="max-width:82%;background:${mine?'rgba(217,119,6,.14)':'rgba(110,145,210,.09)'};border:1px solid ${mine?'rgba(217,119,6,.28)':'rgba(110,145,210,.16)'};border-radius:${mine?'14px 14px 4px 14px':'14px 14px 14px 4px'};padding:9px 13px">
        ${!mine ? `<div style="font-size:.68rem;color:var(--amber);font-weight:700;margin-bottom:3px">${esc(m.authorName||'Team')}</div>` : ''}
        <div style="font-size:.88rem;white-space:pre-wrap;word-break:break-word">${esc(m.text||'')}</div>
      </div>
      <div style="font-size:.66rem;color:var(--muted);margin-top:3px;padding:0 4px">${when}</div>
    </div>`;
  }).join('');
  el.scrollTop = el.scrollHeight;
}

function sendPortalMessage() {
  const input = document.getElementById('portalMessageInput');
  const text = (input?.value || '').trim();
  if (!text || !_portalDb || !_portalJobId || !_portalColl) return;
  input.value = '';

  fetchTeamMembersFlat(_portalDb, _portalCompanyId).then(teamMembers => {
    const notifyTargets = computeNotifyTargets(text, teamMembers, { fromCustomer: true, senderEmail: '' });
    const data = {
      text,
      authorEmail: '',
      authorName: 'Customer',
      fromCustomer: true,
      visibleToCustomer: true,
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      createdMs: Date.now(),
      companyId: _portalCompanyId,
      lastPortalToken: _portalToken || '',
      notifyTargets,
      notifyStatus: notifyTargets.length ? 'pending' : 'none'
    };
    _portalColl('jobs').doc(_portalJobId).collection('messages').add(data)
      .catch(e => { alert('Error sending message: ' + e.message); if (input) input.value = text; });
  });
}
window.sendPortalMessage = sendPortalMessage;

function showPortalNotFound() {
  document.getElementById('portalLoading').style.display = 'none';
  document.getElementById('portalNotFound').style.display = 'block';
}

// ── Portal: Lien Waiver signing view ──
// When the customer opens a portal link with ?waiver=id, this renders
// the lien waiver document for e-signature instead of (or alongside)
// the normal portal view. The waiver doc is pre-filled and frozen —
// the customer cannot edit it, only sign or decline.
function renderPortalLienWaiver(waiverId) {
  if (!_portalDb || !_portalCompanyId || !_portalJobId) return;

  const waiverColl = _portalDb
    .collection('companies').doc(_portalCompanyId)
    .collection('jobs').doc(_portalJobId)
    .collection('lienWaivers');

  waiverColl.doc(waiverId).get().then(doc => {
    if (!doc.exists) return;
    const waiver = { id: doc.id, ...doc.data() };

    // Find or create the lien waiver section in the portal
    let section = document.getElementById('portalLienWaiverSection');
    if (!section) {
      section = document.createElement('div');
      section.id = 'portalLienWaiverSection';
      section.className = 'portal-section';
      // Insert before the message section or append
      const msgSection = document.getElementById('portalMessageSection');
      if (msgSection) msgSection.parentNode.insertBefore(section, msgSection);
      else document.getElementById('ktPortalView')?.appendChild(section);
    }
    section.style.display = 'block';

    const typeLabel = waiver.type === 'conditional'
      ? 'Conditional Lien Waiver (Progress Payment)'
      : 'Unconditional Lien Waiver (Final Payment)';

    if (waiver.status === 'signed') {
      section.innerHTML = `
        <div class="portal-section-head">📋 ${typeLabel}</div>
        <div style="color:#1dbb87;font-weight:700;margin-bottom:8px">✅ Signed</div>
        <div style="font-size:.82rem;color:var(--muted)">Signed by ${esc(waiver.signedByName||'customer')}
          ${waiver.signedAt ? ' on ' + new Date(waiver.signedAt).toLocaleDateString() : ''}.
        </div>
        ${waiver.signatureDataUrl ? `<img src="${waiver.signatureDataUrl}" style="height:50px;margin-top:10px;background:#fff;border-radius:4px;padding:4px">` : ''}`;
      return;
    }

    if (waiver.status === 'declined') {
      section.innerHTML = `
        <div class="portal-section-head">📋 ${typeLabel}</div>
        <div style="color:#ef5350;font-weight:700">Declined</div>
        <div style="font-size:.82rem;color:var(--muted);margin-top:4px">
          ${waiver.declineReason ? esc(waiver.declineReason) : 'No reason provided.'}
        </div>`;
      return;
    }

    // Pending — show document + signature pad
    // Record view timestamp
    waiverColl.doc(waiverId).update({
      viewedAt: firebase.firestore.FieldValue.serverTimestamp(),
      lastPortalToken: _portalToken || ''
    }).catch(() => {});

    section.innerHTML = `
      <div class="portal-section-head">📋 ${typeLabel} — Signature Required</div>
      <div style="background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.2);border-radius:10px;padding:16px;margin-bottom:16px">
        <div style="font-size:.72rem;color:var(--amber);font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px">Document</div>
        <pre style="font-size:.75rem;color:var(--muted);white-space:pre-wrap;word-break:break-word;line-height:1.6;font-family:inherit">${esc(waiver.documentText||'')}</pre>
      </div>
      <div style="font-size:.78rem;color:var(--muted);margin-bottom:14px;line-height:1.55">
        By signing below, you acknowledge that you have read and agree to the terms of this
        ${typeLabel} and that your electronic signature is legally binding under the
        federal Electronic Signatures in Global and National Commerce Act (E-SIGN).
      </div>
      <div style="margin-bottom:10px">
        <input id="portalLienSigName" placeholder="Type your full legal name"
          style="width:100%;max-width:460px;padding:9px 12px;border-radius:8px;border:1px solid var(--line);background:rgba(8,18,36,.6);color:#eaf0fb;font-size:.9rem" />
      </div>
      <canvas id="portalLienSigCanvas" class="portal-sig-canvas" style="width:100%;max-width:460px;height:120px;border:1px solid var(--line);border-radius:8px;background:#fff;display:block;margin-bottom:10px"></canvas>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        <button class="btn" style="padding:6px 14px;font-size:.8rem" onclick="clearPortalLienSignature()">Clear</button>
        <button class="btn-amber" style="padding:9px 20px;font-size:.88rem" onclick="submitPortalLienSignature('${waiverId}','approved')">✓ Sign &amp; Submit</button>
        <button class="btn" style="padding:9px 20px;font-size:.88rem;color:#ef5350" onclick="submitPortalLienSignature('${waiverId}','declined')">Decline</button>
      </div>`;

    // Init signature pad on the lien canvas
    const canvas = document.getElementById('portalLienSigCanvas');
    if (canvas) {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = (rect.width || 460) * ratio;
      canvas.height = (rect.height || 120) * ratio;
      const ctx = canvas.getContext('2d');
      ctx.scale(ratio, ratio);
      ctx.strokeStyle = '#111827';
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      window._lienSigCtx = ctx;
      window._lienSigDrawing = false;
      window._lienSigHasStroke = false;

      function pos(e) {
        const r = canvas.getBoundingClientRect();
        const t = e.touches ? e.touches[0] : e;
        return { x: (t.clientX - r.left), y: (t.clientY - r.top) };
      }
      function start(e) { e.preventDefault(); window._lienSigDrawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
      function move(e) { if (!window._lienSigDrawing) return; e.preventDefault(); const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); window._lienSigHasStroke = true; }
      function end() { window._lienSigDrawing = false; }
      canvas.onmousedown = start; canvas.onmousemove = move; canvas.onmouseup = end; canvas.onmouseleave = end;
      canvas.ontouchstart = start; canvas.ontouchmove = move; canvas.ontouchend = end;
    }
  }).catch(() => {});
}
window.renderPortalLienWaiver = renderPortalLienWaiver;

function clearPortalLienSignature() {
  const canvas = document.getElementById('portalLienSigCanvas');
  if (canvas && window._lienSigCtx) {
    window._lienSigCtx.clearRect(0, 0, canvas.width, canvas.height);
    window._lienSigHasStroke = false;
  }
}
window.clearPortalLienSignature = clearPortalLienSignature;

async function submitPortalLienSignature(waiverId, action) {
  if (!_portalDb || !_portalCompanyId || !_portalJobId) return;

  const waiverRef = _portalDb
    .collection('companies').doc(_portalCompanyId)
    .collection('jobs').doc(_portalJobId)
    .collection('lienWaivers').doc(waiverId);

  if (action === 'declined') {
    const reason = prompt('Optional: let us know why (or leave blank).') || '';
    try {
      await waiverRef.update({
        status: 'declined',
        declineReason: reason,
        signedAt: firebase.firestore.FieldValue.serverTimestamp(),
        lastPortalToken: _portalToken || ''
      });
      renderPortalLienWaiver(waiverId);
    } catch(e) { alert('Error: ' + e.message); }
    return;
  }

  const nameEl = document.getElementById('portalLienSigName');
  const name = nameEl ? nameEl.value.trim() : '';
  if (!name) { alert('Please type your full legal name before signing.'); return; }
  if (!window._lienSigHasStroke) { alert('Please sign in the box before submitting.'); return; }

  const canvas = document.getElementById('portalLienSigCanvas');
  const sigDataUrl = canvas ? canvas.toDataURL('image/png') : '';

  // E-SIGN audit fields
  const signerIp = await fetch('https://api.ipify.org?format=json')
    .then(r => r.json()).then(d => d.ip).catch(() => 'unavailable');

  try {
    await waiverRef.update({
      status: 'signed',
      signedByName: name,
      signatureDataUrl: sigDataUrl,
      signerIp,
      signedAt: firebase.firestore.FieldValue.serverTimestamp(),
      signedAtMs: Date.now(),
      lastPortalToken: _portalToken || '',
      // Document hash was stored at creation — immutable, not re-hashed here
      // so the audit trail proves the customer signed the exact frozen text
    });
    renderPortalLienWaiver(waiverId);
  } catch(e) { alert('Error submitting signature: ' + e.message); }
}
window.submitPortalLienSignature = submitPortalLienSignature;

// ── Portal Subcontractor Agreement: view + e-signature capture ──
// Mirrors renderPortalLienWaiver / submitPortalLienSignature exactly.
function renderPortalSubAgreement(agreementId) {
  if (!_portalDb || !_portalCompanyId || !_portalJobId) return;

  const agreementColl = _portalDb
    .collection('companies').doc(_portalCompanyId)
    .collection('jobs').doc(_portalJobId)
    .collection('subAgreements');

  agreementColl.doc(agreementId).get().then(doc => {
    if (!doc.exists) return;
    const agreement = { id: doc.id, ...doc.data() };

    let section = document.getElementById('portalSubAgreementSection');
    if (!section) {
      section = document.createElement('div');
      section.id = 'portalSubAgreementSection';
      section.className = 'portal-section';
      const msgSection = document.getElementById('portalMessagesSection');
      if (msgSection) msgSection.parentNode.insertBefore(section, msgSection);
      else document.getElementById('ktPortalView')?.appendChild(section);
    }
    section.style.display = 'block';

    if (agreement.status === 'signed') {
      section.innerHTML = `
        <div class="portal-section-head">\u270d\ufe0f Subcontractor Agreement</div>
        <div style="color:#1dbb87;font-weight:700;margin-bottom:8px">\u2705 Signed</div>
        <div style="font-size:.82rem;color:var(--muted)">Signed by ${esc(agreement.signedByName||'subcontractor')}
          ${agreement.signedAt ? ' on ' + new Date(agreement.signedAt).toLocaleDateString() : ''}.
        </div>
        ${agreement.signatureDataUrl ? `<img src="${agreement.signatureDataUrl}" style="height:50px;margin-top:10px;background:#fff;border-radius:4px;padding:4px">` : ''}`;
      return;
    }

    if (agreement.status === 'declined') {
      section.innerHTML = `
        <div class="portal-section-head">\u270d\ufe0f Subcontractor Agreement</div>
        <div style="color:#ef5350;font-weight:700">Declined</div>
        <div style="font-size:.82rem;color:var(--muted);margin-top:4px">
          ${agreement.declineReason ? esc(agreement.declineReason) : 'No reason provided.'}
        </div>`;
      return;
    }

    agreementColl.doc(agreementId).update({
      viewedAt: firebase.firestore.FieldValue.serverTimestamp(),
      lastPortalToken: _portalToken || ''
    }).catch(() => {});

    section.innerHTML = `
      <div class="portal-section-head">\u270d\ufe0f Subcontractor Agreement \u2014 Signature Required</div>
      <div style="background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.2);border-radius:10px;padding:16px;margin-bottom:16px">
        <div style="font-size:.72rem;color:var(--amber);font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px">Document</div>
        <pre style="font-size:.75rem;color:var(--muted);white-space:pre-wrap;word-break:break-word;line-height:1.6;font-family:inherit">${esc(agreement.documentText||'')}</pre>
      </div>
      <div style="font-size:.78rem;color:var(--muted);margin-bottom:14px;line-height:1.55">
        By signing below, you acknowledge that you have read and agree to the terms of this
        Subcontractor Agreement and that your electronic signature is legally binding under the
        federal Electronic Signatures in Global and National Commerce Act (E-SIGN).
      </div>
      <div style="margin-bottom:10px">
        <input id="portalSubAgreementSigName" placeholder="Type your full legal name"
          style="width:100%;max-width:460px;padding:9px 12px;border-radius:8px;border:1px solid var(--line);background:rgba(8,18,36,.6);color:#eaf0fb;font-size:.9rem" />
      </div>
      <canvas id="portalSubAgreementSigCanvas" class="portal-sig-canvas" style="width:100%;max-width:460px;height:120px;border:1px solid var(--line);border-radius:8px;background:#fff;display:block;margin-bottom:10px"></canvas>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        <button class="btn" style="padding:6px 14px;font-size:.8rem" onclick="clearPortalSubAgreementSignature()">Clear</button>
        <button class="btn-amber" style="padding:9px 20px;font-size:.88rem" onclick="submitPortalSubAgreement('${agreementId}','approved')">\u2713 Sign &amp; Submit</button>
        <button class="btn" style="padding:9px 20px;font-size:.88rem;color:#ef5350" onclick="submitPortalSubAgreement('${agreementId}','declined')">Decline</button>
      </div>`;

    const canvas = document.getElementById('portalSubAgreementSigCanvas');
    if (canvas) {
      const ratio = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = (rect.width || 460) * ratio;
      canvas.height = (rect.height || 120) * ratio;
      const ctx = canvas.getContext('2d');
      ctx.scale(ratio, ratio);
      ctx.strokeStyle = '#111827';
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      window._subAgreementSigCtx = ctx;
      window._subAgreementSigDrawing = false;
      window._subAgreementSigHasStroke = false;

      function pos(e) {
        const r = canvas.getBoundingClientRect();
        const t = e.touches ? e.touches[0] : e;
        return { x: (t.clientX - r.left), y: (t.clientY - r.top) };
      }
      function start(e) { e.preventDefault(); window._subAgreementSigDrawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
      function move(e) { if (!window._subAgreementSigDrawing) return; e.preventDefault(); const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); window._subAgreementSigHasStroke = true; }
      function end() { window._subAgreementSigDrawing = false; }
      canvas.onmousedown = start; canvas.onmousemove = move; canvas.onmouseup = end; canvas.onmouseleave = end;
      canvas.ontouchstart = start; canvas.ontouchmove = move; canvas.ontouchend = end;
    }
  }).catch(() => {});
}
window.renderPortalSubAgreement = renderPortalSubAgreement;

function clearPortalSubAgreementSignature() {
  const canvas = document.getElementById('portalSubAgreementSigCanvas');
  if (canvas && window._subAgreementSigCtx) {
    window._subAgreementSigCtx.clearRect(0, 0, canvas.width, canvas.height);
    window._subAgreementSigHasStroke = false;
  }
}
window.clearPortalSubAgreementSignature = clearPortalSubAgreementSignature;

async function submitPortalSubAgreement(agreementId, action) {
  if (!_portalDb || !_portalCompanyId || !_portalJobId) return;

  const agreementRef = _portalDb
    .collection('companies').doc(_portalCompanyId)
    .collection('jobs').doc(_portalJobId)
    .collection('subAgreements').doc(agreementId);

  if (action === 'declined') {
    const reason = prompt('Optional: let us know why (or leave blank).') || '';
    try {
      await agreementRef.update({
        status: 'declined',
        declineReason: reason,
        signedAt: firebase.firestore.FieldValue.serverTimestamp(),
        lastPortalToken: _portalToken || ''
      });
      renderPortalSubAgreement(agreementId);
    } catch(e) { alert('Error: ' + e.message); }
    return;
  }

  const nameEl = document.getElementById('portalSubAgreementSigName');
  const name = nameEl ? nameEl.value.trim() : '';
  if (!name) { alert('Please type your full legal name before signing.'); return; }
  if (!window._subAgreementSigHasStroke) { alert('Please sign in the box before submitting.'); return; }

  const canvas = document.getElementById('portalSubAgreementSigCanvas');
  const sigDataUrl = canvas ? canvas.toDataURL('image/png') : '';

  const signerIp = await fetch('https://api.ipify.org?format=json')
    .then(r => r.json()).then(d => d.ip).catch(() => 'unavailable');

  try {
    const agreementSnap = await agreementRef.get();
    const agreement = agreementSnap.exists ? agreementSnap.data() : {};

    await agreementRef.update({
      status: 'signed',
      signedByName: name,
      signatureDataUrl: sigDataUrl,
      signerIp,
      signedAt: firebase.firestore.FieldValue.serverTimestamp(),
      signedAtMs: Date.now(),
      lastPortalToken: _portalToken || ''
    });
    renderPortalSubAgreement(agreementId);

    const db = _portalDb;
    const companyId = _portalCompanyId;
    const jobId = _portalJobId;
    const jobRef = db.collection('companies').doc(companyId).collection('jobs').doc(jobId);
    const now = firebase.firestore.FieldValue.serverTimestamp();
    const nowMs = Date.now();
    const todayDateStr = new Date().toISOString().split('T')[0];

    // Confirmed decision: reuse the existing sub status field rather
    // than adding a new flag -- 'Contracted' already exists as one of
    // the defined statuses shown on the sub card.
    if (agreement.subId) {
      jobRef.collection('subs').doc(agreement.subId).update({ status: 'Contracted' }).catch(() => {});
    }

    jobRef.collection('logs').add({
      type: 'sub_agreement_signed',
      notes: 'Subcontractor agreement signed \u2014 ' + name + (agreement.subName ? ' (' + agreement.subName + ')' : ''),
      jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
    }).catch(() => {});

    // PlannerXD notification -- identical bridge to proposal signing,
    // no PlannerXD-side changes needed since it listens generically.
    try {
      db.collection('companies').doc(companyId).collection('settings').doc('company').get()
        .then(settDoc => {
          const ownerUid = settDoc.exists ? settDoc.data().ownerUid : null;
          if (!ownerUid) {
            jobRef.collection('logs').add({
              type: 'plannerxd_push_skipped',
              notes: 'PlannerXD notification skipped \u2014 no ownerUid set on company settings.',
              jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
            }).catch(()=>{});
            return;
          }
          db.collection('plannerxd_notifications').doc(ownerUid)
            .collection('items').add({
              type: 'sub_agreement_signed',
              title: 'Subcontractor Signed Agreement',
              body: (agreement.subName || 'Subcontractor') + ' signed the agreement for ' + (agreement.jobName || 'the job') + '. Ready to schedule.',
              jobId, companyId, actionLabel: 'Open Job',
              createdAt: now, createdMs: nowMs, read: false
            }).then(() => {
              jobRef.collection('logs').add({
                type: 'plannerxd_push_sent',
                notes: 'PlannerXD notified \u2014 subcontractor confirmation pushed to Do First.',
                jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
              }).catch(()=>{});
            }).catch(e => {
              jobRef.collection('logs').add({
                type: 'plannerxd_push_failed',
                notes: 'PlannerXD notification failed: ' + e.message,
                jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
              }).catch(()=>{});
            });
        }).catch(() => {});
    } catch(e) {}
  } catch(e) { alert('Error submitting signature: ' + e.message); }
}
window.submitPortalSubAgreement = submitPortalSubAgreement;

// ── Portal Proposal: view + e-signature capture ──
// Renders whatever the latest proposal version looks like, branching on
// status: 'draft' is never shown to the customer (not yet sent); 'pending'
// shows the full breakdown + signature pad; 'approved'/'declined' show a
// read-only confirmation of what was already decided. All content is
// built from the FROZEN snapshot stored on the proposal doc — never
// recomputed from the live estimate — so what the customer sees here is
// guaranteed to match what they're being asked to sign.
function renderPortalProposal(prop, jobId) {
  if (!prop || prop.status === 'draft') return; // not yet sent, nothing to show
  _portalLatestProposal = prop;
  const section = document.getElementById('portalProposalSection');
  const body = document.getElementById('portalProposalBody');
  const heading = document.getElementById('portalProposalHeading');
  if (!section || !body) return;
  section.style.display = 'block';

  // Real "viewed" tracking — the one honest piece of the sent/opened/viewed
  // audit trail JOBSMETRIX can actually deliver right now, since it doesn't
  // send email itself (every "email" action is a mailto: link opening the
  // user's own client — no way to embed an open-tracking pixel on top of
  // that without switching to a real transactional email API). This
  // records the moment the customer actually looks at their Pending
  // proposal in the portal — a real signal, just not the same thing as
  // "email opened". Only fires once, on first view.
  if (prop.status === 'pending' && !prop.viewedAt) {
    _portalProposalColl(jobId).doc(prop.id).update({
      viewedAt: firebase.firestore.FieldValue.serverTimestamp(),
      lastPortalToken: _portalToken || ''
    }).then(() => {
      prop.viewedAt = { toDate: () => new Date() };
      // Log to activity feed — portal-side write uses firebase directly (no coll() helper)
      try {
        firebase.firestore().collection('companies').doc(_portalCompanyId)
          .collection('jobs').doc(jobId).collection('logs').add({
            type: 'proposal_viewed',
            notes: 'Customer opened proposal in portal',
            jobId, companyId: _portalCompanyId,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            createdMs: Date.now(), createdBy: 'customer-portal'
          });
      } catch(e) {}
    }).catch(() => {});
  }

  const data = prop.snapshot || { rooms: [], grandTotal: 0, itemized: false, paymentSchedule: null };
  const roomsHtml = data.rooms.map(room => {
    const lines = [...room.catBlocks, ...room.directBlocks];
    return `<div class="portal-prop-room">
      <div style="font-weight:800;color:#eaf0fb;margin-bottom:4px">${esc(room.name)}</div>
      ${lines.map(l => `<div style="font-size:.86rem;color:var(--muted);padding-left:8px">
        ${esc(l.label)}${data.itemized ? ` <span style="float:right;color:#eaf0fb;font-weight:700">$${l.price.toFixed(2)}</span>` : ''}
      </div>`).join('')}
    </div>`;
  }).join('');

  const paymentRows = getPaymentScheduleRows(data.paymentSchedule, data.grandTotal);
  const paymentHtml = paymentRows.length ? `
    <div style="margin-top:16px">
      <div style="font-weight:800;color:#eaf0fb;margin-bottom:6px;font-size:.85rem;text-transform:uppercase;letter-spacing:.04em">Payment Schedule</div>
      ${paymentRows.map(r => `<div style="display:flex;justify-content:space-between;font-size:.86rem;padding:4px 0;color:var(--muted)">
        <span>${esc(r.label)} (${r.pct}%)</span><span style="color:#eaf0fb;font-weight:700">$${r.amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</span>
      </div>`).join('')}
    </div>` : '';

  const termsHtml = `<div id="portalTermsBody" style="display:none;margin-top:12px;font-size:.78rem;color:var(--muted);line-height:1.6">
    ${TERMS_AND_CONDITIONS.map(([title, text]) => `<div style="margin-bottom:10px"><strong style="color:#eaf0fb">${title}</strong><br>${text}</div>`).join('')}
  </div>
  <span class="portal-terms-toggle" onclick="const t=document.getElementById('portalTermsBody'); t.style.display = t.style.display==='none'?'block':'none';">View full Terms &amp; Conditions</span>`;

  if (prop.status === 'pending') {
    heading.textContent = '📄 Proposal — Awaiting Your Signature';
    body.innerHTML = `
      ${roomsHtml}
      ${_portalSubAgreementMode ? '' : `
      <div class="portal-prop-total">
        <span style="font-weight:800;color:#eaf0fb">Total Project Investment</span>
        <span style="font-weight:900;font-size:1.2rem;color:#fbbf24">$${data.grandTotal.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</span>
      </div>
      ${paymentHtml}
      ${termsHtml}
      <div style="margin-top:20px;padding-top:16px;border-top:1px solid var(--line)">
        <div style="font-weight:700;color:#eaf0fb;margin-bottom:8px">Sign to Approve</div>
        <input id="portalSigName" placeholder="Type your full name" autocomplete="off" style="width:100%;max-width:460px;margin-bottom:10px;padding:8px 10px;border-radius:8px;border:1px solid var(--line);background:rgba(8,18,36,.6);color:#eaf0fb" />
        <canvas id="portalSigCanvas" class="portal-sig-canvas"></canvas>
        <div style="margin-top:8px;display:flex;gap:10px;flex-wrap:wrap">
          <button class="btn" style="padding:6px 14px;font-size:.8rem" onclick="clearPortalSignature()">Clear</button>
          <button id="portalSignApproveBtn" class="btn-amber" style="padding:8px 18px;font-size:.85rem" onclick="submitPortalSignature('${prop.id}','${jobId}','approved')">✓ Approve &amp; Sign</button>
          <button id="portalSignDeclineBtn" class="btn" style="padding:8px 18px;font-size:.85rem;color:#ef5350" onclick="submitPortalSignature('${prop.id}','${jobId}','declined')">Decline</button>
        </div>
      </div>`}`;
    if (!_portalSubAgreementMode) initPortalSignaturePad();
  } else if (prop.status === 'approved') {
    heading.textContent = '✅ Proposal — Approved';
    body.innerHTML = `
      ${roomsHtml}
      ${_portalSubAgreementMode ? '' : `
      <div class="portal-prop-total">
        <span style="font-weight:800;color:#eaf0fb">Total Project Investment</span>
        <span style="font-weight:900;font-size:1.2rem;color:#fbbf24">$${data.grandTotal.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</span>
      </div>
      ${paymentHtml}
      <div style="margin-top:14px;font-size:.82rem;color:#1dbb87">
        Signed by ${esc(prop.signedByName || 'customer')}${prop.respondedAt?.toDate ? ' on ' + prop.respondedAt.toDate().toLocaleDateString() : ''}.
        ${prop.signatureDataUrl ? `<br><img src="${prop.signatureDataUrl}" style="height:50px;margin-top:8px;background:#fff;border-radius:4px;padding:4px">` : ''}
      </div>`}`;
  } else if (prop.status === 'declined') {
    heading.textContent = 'Proposal — Declined';
    body.innerHTML = `<div style="font-size:.86rem;color:var(--muted)">
      This proposal was declined${prop.declineReason ? ': "' + esc(prop.declineReason) + '"' : '.'} Please reach out using the contact info below if you'd like to discuss a revised scope.
    </div>`;
  }
}

// Basic mouse + touch signature pad — no external library needed.
let _portalSigCtx = null, _portalSigDrawing = false, _portalSigHasStroke = false;
function initPortalSignaturePad() {
  const canvas = document.getElementById('portalSigCanvas');
  if (!canvas) return;
  // Match backing resolution to displayed size for crisp lines
  const ratio = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * ratio;
  canvas.height = rect.height * ratio;
  const ctx = canvas.getContext('2d');
  ctx.scale(ratio, ratio);
  ctx.strokeStyle = '#111827';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  _portalSigCtx = ctx;
  _portalSigHasStroke = false;

  function pos(e) {
    const r = canvas.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: t.clientX - r.left, y: t.clientY - r.top };
  }
  function start(e) { e.preventDefault(); _portalSigDrawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
  function move(e) { if (!_portalSigDrawing) return; e.preventDefault(); const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); _portalSigHasStroke = true; }
  function end() { _portalSigDrawing = false; }

  canvas.onmousedown = start; canvas.onmousemove = move; canvas.onmouseup = end; canvas.onmouseleave = end;
  canvas.ontouchstart = start; canvas.ontouchmove = move; canvas.ontouchend = end;
}
window.initPortalSignaturePad = initPortalSignaturePad;

function clearPortalSignature() {
  const canvas = document.getElementById('portalSigCanvas');
  if (!canvas || !_portalSigCtx) return;
  _portalSigCtx.clearRect(0, 0, canvas.width, canvas.height);
  _portalSigHasStroke = false;
}
window.clearPortalSignature = clearPortalSignature;

// Writes the customer's decision straight to the frozen proposal doc.
// NOTE: this requires Firestore security rules that allow an anonymous
// portal visitor to update ONLY status/signature fields on a proposal doc
// matching their portal token — that rule needs to be added in the
// Firebase console; it's not something this environment can deploy.
let _portalSigSubmitting = false;
function submitPortalSignature(proposalId, jobId, action) {
  // Guard against double-click / slow-network double-tap re-firing this
  // whole handler — each run independently creates a document, activity
  // log entry, and "Schedule job" to-do, so a double-submit produced
  // duplicates of all three (root-caused 7/30/26 via duplicate to-dos).
  if (_portalSigSubmitting) return;
  _portalSigSubmitting = true;
  const approveBtn = document.getElementById('portalSignApproveBtn');
  const declineBtn = document.getElementById('portalSignDeclineBtn');
  if (approveBtn) approveBtn.disabled = true;
  if (declineBtn) declineBtn.disabled = true;
  const _releaseSigGuard = () => {
    _portalSigSubmitting = false;
    if (approveBtn) approveBtn.disabled = false;
    if (declineBtn) declineBtn.disabled = false;
  };

  const nameEl = document.getElementById('portalSigName');
  const name = nameEl ? nameEl.value.trim() : '';

  if (action === 'approved') {
    if (!name) { alert('Please type your full name before signing.'); _releaseSigGuard(); return; }
    if (!_portalSigHasStroke) { alert('Please sign in the box before approving.'); _releaseSigGuard(); return; }
    const canvas = document.getElementById('portalSigCanvas');
    const dataUrl = canvas.toDataURL('image/png');
    const update = {
      status: 'approved',
      signedByName: name,
      signatureDataUrl: dataUrl,
      respondedAt: firebase.firestore.FieldValue.serverTimestamp(),
      lastPortalToken: _portalToken || ''
    };
    _portalProposalColl(jobId).doc(proposalId).update(update)
      .then(() => {
        _portalLatestProposal.status = 'approved';
        _portalLatestProposal.signedByName = name;
        _portalLatestProposal.signatureDataUrl = dataUrl;
        _portalLatestProposal.respondedAt = { toDate: () => new Date() };
        renderPortalProposal(_portalLatestProposal, jobId);

        const db = firebase.firestore();
        const companyId = _portalCompanyId;
        const jobRef = db.collection('companies').doc(companyId).collection('jobs').doc(jobId);
        const now = firebase.firestore.FieldValue.serverTimestamp();
        const nowMs = Date.now();
        // The job's Activity tab (loadJobActivity) queries this same
        // logs subcollection ordered by a 'date' field — Firestore
        // silently EXCLUDES any document missing that field from an
        // orderBy query entirely, not just sorts it oddly. Every log
        // entry below was missing this (including the pre-existing
        // 'proposal_signed' one), which is why none of them, including
        // 'Customer signed proposal', were ever actually showing up in
        // the Activity tab despite writing successfully to Firestore.
        const todayDateStr = new Date().toISOString().split('T')[0];

        // 1. Activity log — written after doc save so we can store docId
        // (done below after document write)

        // 2. Auto-advance job to To Be Scheduled — any pre-To-Be-Scheduled
        // canonical status advances. 'Approved' was removed as a distinct
        // stage (signing now goes straight from Submitted to To Be
        // Scheduled, skipping the old intermediate Approved column
        // entirely) — see the pipeline change made when Approved was
        // dropped from KYTRAC_STATUSES/KANBAN_COLUMNS.
        const PORTAL_STATUS_ORDER = ['New Lead','Appointment Set','Building Estimate','Submitted','To Be Scheduled'];
        jobRef.get().then(snap => {
          if (!snap.exists) return;
          const curIdx = PORTAL_STATUS_ORDER.indexOf(snap.data().status);
          const targetIdx = PORTAL_STATUS_ORDER.indexOf('To Be Scheduled');
          if (curIdx !== -1 && curIdx < targetIdx) {
            jobRef.update({ status: 'To Be Scheduled', statusDate: new Date().toISOString().split('T')[0],
              lastActivity: now, lastActivityNote: `Proposal signed by ${name}` })
              .then(() => {
                jobRef.collection('logs').add({
                  type: 'status_auto_advanced',
                  notes: `Job auto-advanced to To Be Scheduled (was ${snap.data().status}) — customer signed proposal.`,
                  jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
                }).catch(()=>{});
              })
              .catch(e => {
                jobRef.collection('logs').add({
                  type: 'status_advance_failed',
                  notes: 'Auto-advance to To Be Scheduled failed: ' + e.message,
                  jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
                }).catch(()=>{});
              });
          }
        }).catch(()=>{});

        // 3. Save signed proposal to Documents then log with docId
        try {
          const jobName = _portalJobName || '';
          const signedHtml = '<html><body style="font-family:Arial;padding:20px;max-width:700px;margin:auto">' +
            '<h2 style="color:#d97706">Signed Proposal</h2>' +
            '<p><strong>Job:</strong> ' + (jobName || jobId) + '</p>' +
            '<p><strong>Signed by:</strong> ' + name + '</p>' +
            '<p><strong>Date:</strong> ' + new Date().toLocaleDateString() + '</p>' +
            (dataUrl ? '<p><strong>Signature:</strong><br><img src="' + dataUrl + '" style="height:60px;border:1px solid #ccc;padding:4px;border-radius:4px"></p>' : '') +
            '<hr><p style="font-size:.85em;color:#666">Proposal ID: ' + proposalId + ' &middot; Job ID: ' + jobId + '</p>' +
            '</body></html>';
          const docData = 'data:text/html;base64,' + btoa(unescape(encodeURIComponent(signedHtml)));
          db.collection('companies').doc(companyId).collection('documents').add({
            name: 'Signed Proposal — ' + new Date().toLocaleDateString(),
            type: 'text/html', category: 'Contract',
            jobId, jobName, companyId, dataUrl: docData,
            signedByName: name, signatureDataUrl: dataUrl,
            uploadedAt: now, uploadedDate: new Date().toISOString().split('T')[0],
            uploadedBy: 'customer-portal', source: 'proposal_signature'
          }).then(docRef => {
            // Activity log with docId so feed can link directly to the document
            jobRef.collection('logs').add({
              type: 'proposal_signed',
              notes: 'Customer signed proposal — ' + name,
              jobId, companyId, docId: docRef.id,
              createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
            }).catch(()=>{});
          }).catch(()=>{
            // Log without docId if doc save failed
            jobRef.collection('logs').add({
              type: 'proposal_signed', notes: 'Customer signed proposal — ' + name,
              jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
            }).catch(()=>{});
          });
        } catch(e) {
          jobRef.collection('logs').add({
            type: 'proposal_signed', notes: 'Customer signed proposal — ' + name,
            jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
          }).catch(()=>{});
        }

        // 4. Create To-Do: Schedule this job
        try {
          const jobNameForTodo = _portalJobName || jobId;
          db.collection('companies').doc(companyId).collection('todos').add({
            text: 'Schedule job — ' + jobNameForTodo + ' (customer signed proposal)',
            priority: 'high',
            dueDate: '',
            jobId,
            jobName: jobNameForTodo,
            assignee: '',
            assigneeName: '',
            done: false,
            companyId,
            createdAt: now,
            createdBy: 'customer-portal',
            source: 'proposal_signed'
          }).then(() => {
            jobRef.collection('logs').add({
              type: 'todo_created',
              notes: 'Schedule to-do created automatically (customer signed proposal).',
              jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
            }).catch(()=>{});
          }).catch(()=>{});
        } catch(e) {}

        // 5. PlannerXD notification — look up ownerUid from company settings.
        // Always logs its outcome to Activity (success, skipped, or failed
        // with the actual reason) — previously every failure mode here was
        // silently swallowed by a bare .catch(()=>{}), making this
        // undiagnosable when it didn't work.
        try {
          db.collection('companies').doc(companyId).collection('settings').doc('company').get()
            .then(settDoc => {
              const ownerUid = settDoc.exists ? settDoc.data().ownerUid : null;
              if (!ownerUid) {
                jobRef.collection('logs').add({
                  type: 'plannerxd_push_skipped',
                  notes: 'PlannerXD notification skipped — no ownerUid set on company settings (Company Settings must be linked to a PlannerXD account for this to fire).',
                  jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
                }).catch(()=>{});
                return;
              }
              db.collection('plannerxd_notifications').doc(ownerUid)
                .collection('items').add({
                  type: 'proposal_signed',
                  title: 'Customer Signed Proposal — Schedule Now',
                  body: name + ' signed the proposal. Job approved and ready to schedule.',
                  jobId, companyId, actionLabel: 'Open Job',
                  createdAt: now, createdMs: nowMs, read: false
                }).then(() => {
                  jobRef.collection('logs').add({
                    type: 'plannerxd_push_sent',
                    notes: 'PlannerXD notified — schedule reminder pushed to Do First.',
                    jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
                  }).catch(()=>{});
                }).catch(e => {
                  jobRef.collection('logs').add({
                    type: 'plannerxd_push_failed',
                    notes: 'PlannerXD notification failed: ' + e.message,
                    jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
                  }).catch(()=>{});
                });
            }).catch(e => {
              jobRef.collection('logs').add({
                type: 'plannerxd_push_failed',
                notes: 'PlannerXD notification failed (settings lookup): ' + e.message,
                jobId, companyId, createdAt: now, createdMs: nowMs, date: todayDateStr, createdBy: 'customer-portal'
              }).catch(()=>{});
            });
        } catch(e) {}
        _releaseSigGuard();
      })
      .catch(e => { alert('Error submitting signature: ' + e.message); _releaseSigGuard(); });
  } else {
    const reason = prompt('Optional: let us know why, so we can follow up (or leave blank).') || '';
    _portalProposalColl(jobId).doc(proposalId).update({
      status: 'declined',
      declineReason: reason,
      respondedAt: firebase.firestore.FieldValue.serverTimestamp(),
      lastPortalToken: _portalToken || ''
    })
      .then(() => {
        _portalLatestProposal.status = 'declined';
        _portalLatestProposal.declineReason = reason;
        renderPortalProposal(_portalLatestProposal, jobId);
        _releaseSigGuard();
      })
      .catch(e => { alert('Error submitting response: ' + e.message); _releaseSigGuard(); });
  }
}
window.submitPortalSignature = submitPortalSignature;

function _portalProposalColl(jobId) {
  const base = _portalCompanyId
    ? _portalDb.collection('companies').doc(_portalCompanyId).collection('jobs')
    : _portalDb.collection('jobs');
  return base.doc(jobId).collection('proposals');
}

// ── Generate and share portal link ──
function shareCustomerPortal() {
  if (!conCurrentJobId || !conDb) return;
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (!job) return;

  // Generate token
  const token = conCurrentJobId + '-hash-' + Math.random().toString(36).slice(2,10);
  const portalUrl = window.location.origin + window.location.pathname + '?portal=' + token;

  // Save token to Firestore — include companyId for multi-tenant portal access
  conDb.collection('portalTokens').doc(token).set({
    jobId: conCurrentJobId,
    jobName: job.name || '',
    companyId: currentCompanyId,
    created: Date.now(),
    createdBy: conCurrentUser?.email || '',
    expires: null,
    shareInvoices: true,
  }).then(() => {
    // Copy to clipboard
    if (navigator.clipboard) {
      navigator.clipboard.writeText(portalUrl).then(() => {
        showPortalShareConfirm(portalUrl);
      }).catch(() => showPortalShareConfirm(portalUrl));
    } else {
      showPortalShareConfirm(portalUrl);
    }
  }).catch(e => alert('Error generating portal link: ' + e.message));
}

function showPortalShareConfirm(url) {
  // Show a nice confirmation with the URL
  const msg = `✅ Customer Portal Link Ready!

Send this link to your customer:

${url}

They can view their project status, schedule, daily updates, and invoices — no login required.`;
  
  // Create a styled modal instead of alert
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,5,14,.85);z-index:999999;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.innerHTML = `
    <div style="background:rgba(6,14,28,.99);border:1px solid var(--amber-border);border-radius:18px;padding:28px;max-width:520px;width:100%;box-shadow:0 24px 64px rgba(0,0,0,.6)">
      <div style="font-size:1.8rem;margin-bottom:12px">🔗</div>
      <div style="font-size:1.1rem;font-weight:800;color:#eaf0fb;margin-bottom:6px">Customer Portal Link Ready</div>
      <div style="font-size:.84rem;color:var(--muted);margin-bottom:16px">Send this link to your customer. They can view their project — no login needed.</div>
      <div style="background:rgba(8,18,36,.8);border:1px solid var(--amber-border);border-radius:10px;padding:12px 14px;margin-bottom:16px;word-break:break-all;font-size:.78rem;color:var(--amber);font-family:monospace">${esc(url)}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <button onclick="navigator.clipboard.writeText('${url.replace(/'/g,"\\'")}').then(()=>{this.textContent='✓ Copied!';setTimeout(()=>this.textContent='📋 Copy Link',2000)})" class="btn-amber" style="flex:1">📋 Copy Link</button>
        <a href="mailto:?subject=Your Project Portal&body=View your project here: ${encodeURIComponent(url)}" class="btn" style="flex:1;text-align:center;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:6px">✉️ Email Link</a>
        <button onclick="this.closest('div[style*=fixed]').remove()" class="btn" style="flex:1">Close</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

// Expose portal functions
window.shareCustomerPortal = shareCustomerPortal;
window.checkPortalMode = checkPortalMode;

