// ════════════════════════════════════════════════════
// ── HIERARCHICAL ESTIMATE ENGINE ──
// ════════════════════════════════════════════════════
// Data structure stored in Firestore as jobs/{jobId}/estimateGroups
// Each group has: { id, name, order, collapsed, subgroups: [] }
// Each subgroup has: { id, name, order, items: [] }
// Each item has: { id, desc, qty, unit, costType, unitCost, markup, unitPrice, phase, notes }

let estGroups = []; // [{id, name, order, collapsed, subgroups:[{id, name, order, items:[...]}]}]
let _estItemDraftKey = null;
// Holds the labor-side data {desc, unit, unitCost} for whatever catalog
// item was just picked, IF that catalog entry has both a materials and
// a labor price bundled into it. There is no separate "Labor - X"
// catalog entry to search for in these cases — the labor price lives
// as a sub-field on the same object — so this lets the checkbox in the
// modal add it as a real second line item on Save, instead of a note
// pointing the user at a search result that doesn't exist.
let _pendingCatalogLaborLine = null;
let _estItemDraftTimer = null;
// Debounced draft-autosave for the Add/Edit Line Item form — separate
// from the actual per-item Firestore save (Save Item button), which
// already protects everything already committed. This just protects
// whatever's mid-typed in the currently-open form against a crash,
// accidental tab close, or phone lock before Save Item gets clicked.
function scheduleEstItemDraftSave() {
  if (_estItemDraftTimer) clearTimeout(_estItemDraftTimer);
  _estItemDraftTimer = setTimeout(() => {
    if (!_estItemDraftKey) return;
    const desc = document.getElementById('estItemDesc')?.value.trim();
    if (!desc) { try { localStorage.removeItem(_estItemDraftKey); } catch(e){} return; }
    const draft = {
      desc,
      qty: document.getElementById('estItemQty')?.value,
      unit: document.getElementById('estItemUnit')?.value,
      costType: document.getElementById('estItemCostType')?.value,
      unitCost: document.getElementById('estItemUnitCost')?.value,
      markup: document.getElementById('estItemMarkup')?.value,
      unitPrice: document.getElementById('estItemUnitPrice')?.value,
      phase: document.getElementById('estItemPhase')?.value,
      notes: document.getElementById('estItemNotes')?.value,
    };
    try { localStorage.setItem(_estItemDraftKey, JSON.stringify(draft)); } catch(e) { console.warn('Draft save failed:', e); }
  }, 400);
}
function clearEstItemDraft() {
  if (_estItemDraftKey) { try { localStorage.removeItem(_estItemDraftKey); } catch(e){} }
}
window.scheduleEstItemDraftSave = scheduleEstItemDraftSave;
let _estCollapsed = {}; // groupId/subgroupId -> bool
let _editingGroupId = null;
let _editingSubgroupId = null;
let _editingSubSubgroupId = null;
let _editingEstItemId = null;

const COST_TYPES = ['Labor','Materials','Subcontractor','Equipment','Permits & Fees','Overhead','Other'];

// ── Load estimate from Firestore ──
// ── Labor Burden (true crew cost) ─────────────────────────────────────
// Jason's core critique of JobTread-derived numbers: labor "cost" per
// sqft was reverse-engineered from billing rates, so displayed profit
// only ever showed the markup spread — never real profit vs. what the
// crew actually costs. True labor cost = crew size × days × 8 hrs ×
// burden rate ($/man-hour, Settings > Supplier Cost Adjustment).
// Applying rewrites ONLY the unitCost of Labor line items (allocated
// proportionally to each line's share of labor price), leaving every
// unitPrice untouched — customer-facing numbers don't move, but cost/
// profit/margin become real everywhere without touching any calc code.
function getBurdenRate() {
  return (companyProfile && companyProfile.burdenRatePerManHour > 0) ? companyProfile.burdenRatePerManHour : 60;
}

// Per-person true hourly cost, saved on the team member record
// (Settings > Team). Falls back to the flat company-wide rate for
// anyone who hasn't had a rate entered yet, so cost tracking degrades
// gracefully during rollout instead of breaking for un-rated crew.
function getPersonBurdenRate(userId, userEmail) {
  const email = (userEmail || '').toLowerCase();
  const member = (_lastTeamMemberList || []).find(m =>
    (m.email || '').toLowerCase() === email || m.userId === userId
  );
  if (member && member.burdenedRate > 0) return member.burdenedRate;
  return getBurdenRate();
}

// Hourly (default) vs 1099 Flat-Rate Subcontractor — see
// saveTeamMemberPaymentType() for the full explanation. This is what
// lets clock-in/out stay open to everyone (so a subcontractor crew can
// track their own hours for estimating-accuracy purposes) WITHOUT
// their hours silently turning into a fake dollar cost via hours×rate,
// when what they're actually owed is a separately-agreed job price.
function isFlatRateSubcontractor(userId, userEmail) {
  const email = (userEmail || '').toLowerCase();
  const member = (_lastTeamMemberList || []).find(m =>
    (m.email || '').toLowerCase() === email || m.userId === userId
  );
  return member?.paymentType === 'subcontractor';
}

function forEachLaborItem(cb) {
  estGroups.forEach(g => {
    (g.directItems || []).forEach(it => { if (it.costType === 'Labor') cb(it, g.id, null); });
    (g.subgroups || []).forEach(s => {
      (s.items || []).forEach(it => { if (it.costType === 'Labor') cb(it, g.id, s.id); });
    });
  });
}

function updateBurdenPreview() {
  const rate = getBurdenRate();
  const rateLabel = document.getElementById('laborBurdenRateLabel');
  if (rateLabel) rateLabel.textContent = '$' + rate + '/man-hour · $' + (rate * 8) + '/man-day (Settings)';
  const crew = parseFloat(document.getElementById('burdenCrewSize')?.value) || 0;
  const hours = parseFloat(document.getElementById('burdenDays')?.value) || 0;
  const total = crew * hours * rate;
  const el = document.getElementById('burdenTotalPreview');
  if (el) el.textContent = total > 0 ? ('$' + total.toLocaleString(undefined, {maximumFractionDigits: 0})) : '—';
}
window.updateBurdenPreview = updateBurdenPreview;

function loadLaborBurdenBasis(job) {
  const basis = job && job.laborBasis;
  const setV = (id, v) => { const el = document.getElementById(id); if (el) el.value = (v !== undefined && v !== null) ? v : ''; };
  setV('burdenCrewSize', basis ? basis.crewSize : '');
  setV('burdenDays', basis ? basis.days : '');
  const status = document.getElementById('burdenStatus');
  if (status) status.textContent = basis
    ? ('Applied ' + (basis.appliedAt || '') + ' — labor costs reflect ' + basis.crewSize + ' crew × ' + basis.days + ' hour(s) at $' + basis.burdenRate + '/man-hr = $' + (basis.totalCost || 0).toLocaleString())
    : 'Not applied yet — labor line costs still use billing-derived rates.';
  updateBurdenPreview();
}

async function applyLaborBurden() {
  if (!conCurrentJobId) { alert('Open a job first.'); return; }
  const crew = parseFloat(document.getElementById('burdenCrewSize')?.value);
  const hours = parseFloat(document.getElementById('burdenDays')?.value);
  if (!(crew > 0) || !(hours > 0)) { alert('Enter crew size and hours first.'); return; }
  const rate = getBurdenRate();
  const totalBurden = crew * hours * rate;

  // Collect labor lines and their price weight
  const laborLines = [];
  let totalLaborPrice = 0;
  forEachLaborItem((it, gId, sId) => {
    const extPrice = (it.qty || 0) * (it.unitPrice || 0);
    laborLines.push({ it, gId, sId, extPrice });
    totalLaborPrice += extPrice;
  });
  if (!laborLines.length) { alert('No Labor line items found on this estimate.'); return; }

  if (!confirm('Rewrite the COST of ' + laborLines.length + ' labor line(s) so total labor cost = $' + totalBurden.toLocaleString() + ' (' + crew + ' crew × ' + hours + ' hr(s) × $' + rate + '/hr)?\n\nPrices are NOT changed — only costs, so profit/margin become real.')) return;

  try {
    for (const L of laborLines) {
      // Allocate burden proportionally to this line's share of labor price
      // (equal split if all prices are zero), then back into a unitCost.
      const share = totalLaborPrice > 0 ? (L.extPrice / totalLaborPrice) : (1 / laborLines.length);
      const lineCost = totalBurden * share;
      const qty = L.it.qty || 1;
      const newUnitCost = parseFloat((lineCost / qty).toFixed(4));
      const newMarkup = newUnitCost > 0 ? Math.round(((L.it.unitPrice || 0) / newUnitCost - 1) * 100) : 0;
      const ref = L.sId
        ? coll('jobs').doc(conCurrentJobId).collection('estimateGroups').doc(L.gId).collection('subgroups').doc(L.sId).collection('items').doc(L.it.id)
        : coll('jobs').doc(conCurrentJobId).collection('estimateGroups').doc(L.gId).collection('items').doc(L.it.id);
      await ref.update({ unitCost: newUnitCost, markup: newMarkup, costBasis: 'burden' });
      L.it.unitCost = newUnitCost; L.it.markup = newMarkup;
    }
    const basis = {
      crewSize: crew, days, burdenRate: rate, totalCost: totalBurden,
      appliedAt: new Date().toISOString().split('T')[0]
    };
    await coll('jobs').doc(conCurrentJobId).update({ laborBasis: basis });
    const jobObj = (typeof conJobs !== 'undefined') ? conJobs.find(j => j.id === conCurrentJobId) : null;
    if (jobObj) jobObj.laborBasis = basis;
    loadLaborBurdenBasis(jobObj || { laborBasis: basis });
    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
    alert('Done — labor cost is now $' + totalBurden.toLocaleString() + '. Profit and margin now reflect true crew cost.');
  } catch (e) {
    console.error('applyLaborBurden error:', e);
    alert('Error applying burden: ' + e.message);
  }
}
window.applyLaborBurden = applyLaborBurden;

// ── Live estimate sync ──────────────────────────────────────────────
// Was a one-time .get() fetch chain — meant two people looking at the
// same job's estimate wouldn't see each other's changes until closing
// and reopening it. Converted to a tree of onSnapshot listeners so
// changes made by anyone show up live for everyone else who has that
// job's Estimate tab open, matching the real-time behavior already
// used elsewhere in the app (Kanban board, Files tab, etc.).
//
// Strategy: groups/subgroups/items are 3-4 levels of nested
// subcollections. Rather than diff each level incrementally (real but
// fiddly bug surface — stale listeners on renamed/reordered docs),
// this tears down and rebuilds the nested (subgroup/item) listeners
// whenever their parent level changes. Groups/subgroups being added or
// removed is rare (adding a whole new room/category), so the rebuild
// cost is a non-issue; the correctness win is worth it. A short
// debounce collapses multiple nested listeners firing in one burst
// (e.g. loading 5 groups' subgroups at once) into a single re-render.

let _estimateGroupsUnsub = null;   // top-level listener, torn down only on job switch
let _estimateNestedUnsub = [];     // every subgroup/item listener, torn down + rebuilt on any group/subgroup change
let _estimateRenderPending = false;

function _clearEstimateListeners() {
  if (_estimateGroupsUnsub) { try { _estimateGroupsUnsub(); } catch(e){} _estimateGroupsUnsub = null; }
  _clearNestedEstimateListeners();
}
function _clearNestedEstimateListeners() {
  _estimateNestedUnsub.forEach(fn => { try { fn(); } catch(e){} });
  _estimateNestedUnsub = [];
}

function _scheduleEstimateRerender(jobId) {
  if (_estimateRenderPending) return;
  _estimateRenderPending = true;
  setTimeout(() => {
    _estimateRenderPending = false;
    estGroups.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    renderEstimateTree();
    updateEstimateSummary();
    loadLaborBurdenBasis(conJobs.find(j => j.id === jobId));
    renderPaymentScheduleControls(jobId);
    renderFFDiscountControl(jobId);
    loadProposals(jobId);
  }, 60);
}

function loadEstimate(jobId) {
  if (!conDb || !jobId) return;
  _clearEstimateListeners();
  estGroups = [];

  const groupsRef = coll('jobs').doc(jobId).collection('estimateGroups');

  // Force a genuine server round-trip before the live listener takes
  // over. With offline persistence enabled, onSnapshot's very first
  // callback can be served from local IndexedDB cache — if this device
  // had an older cached copy of this job's estimate from a previous
  // session, that stale snapshot would paint first. This doesn't
  // change the live-sync behavior at all (the onSnapshot listener below
  // still keeps everything current going forward); it just guarantees
  // the FIRST thing you see when opening the tab is confirmed current,
  // not whatever happened to be sitting in cache.
  groupsRef.get({ source: 'server' }).catch(e => {
    console.warn('Estimate server-fresh pre-fetch failed (will still get live updates via cache/listener):', e);
  });

  _estimateGroupsUnsub = groupsRef.onSnapshot(snap => {
    _clearNestedEstimateListeners();
    estGroups = [];
    snap.forEach(doc => {
      const group = { id: doc.id, ...doc.data(), subgroups: [], directItems: [] };
      estGroups.push(group);
      _attachEstGroupListeners(jobId, doc.id, group);
    });
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Estimate groups listener error:', e));
}

function _attachEstGroupListeners(jobId, groupId, group) {
  const groupRef = coll('jobs').doc(jobId).collection('estimateGroups').doc(groupId);

  const directItemsRef = groupRef.collection('items');
  directItemsRef.get({ source: 'server' }).catch(() => {});
  const unsubDirect = directItemsRef.onSnapshot(itemSnap => {
    group.directItems = [];
    itemSnap.forEach(d => group.directItems.push({ id: d.id, ...d.data() }));
    group.directItems.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Group items listener error:', e));
  _estimateNestedUnsub.push(unsubDirect);

  const subgroupsRef = groupRef.collection('subgroups');
  subgroupsRef.get({ source: 'server' }).catch(() => {});
  const unsubSub = subgroupsRef.onSnapshot(subSnap => {
    // Same rebuild strategy one level down.
    group.subgroups = [];
    subSnap.forEach(subDoc => {
      const subgroup = { id: subDoc.id, ...subDoc.data(), items: [], subgroups: [] };
      group.subgroups.push(subgroup);
      _attachEstSubgroupListeners(jobId, groupId, subDoc.id, subgroup);
    });
    group.subgroups.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Subgroups listener error:', e));
  _estimateNestedUnsub.push(unsubSub);
}

function _attachEstSubgroupListeners(jobId, groupId, subgroupId, subgroup) {
  const subRef = coll('jobs').doc(jobId).collection('estimateGroups').doc(groupId)
    .collection('subgroups').doc(subgroupId);

  const itemsRef = subRef.collection('items');
  itemsRef.get({ source: 'server' }).catch(() => {});
  const unsubItems = itemsRef.onSnapshot(itemSnap => {
    subgroup.items = [];
    itemSnap.forEach(d => subgroup.items.push({ id: d.id, ...d.data() }));
    subgroup.items.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Subgroup items listener error:', e));
  _estimateNestedUnsub.push(unsubItems);

  const unsubSubSub = subRef.collection('subgroups').onSnapshot(ssSnap => {
    subgroup.subgroups = [];
    ssSnap.forEach(ssDoc => {
      const subsub = { id: ssDoc.id, ...ssDoc.data(), items: [] };
      subgroup.subgroups.push(subsub);
      _attachEstSubSubgroupListeners(jobId, groupId, subgroupId, ssDoc.id, subsub);
    });
    subgroup.subgroups.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Sub-subgroups listener error:', e));
  _estimateNestedUnsub.push(unsubSubSub);
}

function _attachEstSubSubgroupListeners(jobId, groupId, subgroupId, subsubId, subsub) {
  const ssRef = coll('jobs').doc(jobId).collection('estimateGroups').doc(groupId)
    .collection('subgroups').doc(subgroupId).collection('subgroups').doc(subsubId);
  const unsub = ssRef.collection('items').onSnapshot(itemSnap => {
    subsub.items = [];
    itemSnap.forEach(d => subsub.items.push({ id: d.id, ...d.data() }));
    subsub.items.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
    _scheduleEstimateRerender(jobId);
  }, e => console.error('Sub-subgroup items listener error:', e));
  _estimateNestedUnsub.push(unsub);
}

// ── Payment Schedule (Proposal) ──
// Populates the Payment Schedule select/custom-input from the job's saved
// paymentSchedule (if any) whenever the Estimate tab loads for a job.
function renderPaymentScheduleControls(jobId) {
  const sel = document.getElementById('paymentScheduleType');
  const custom = document.getElementById('paymentScheduleCustomInput');
  if (!sel) return;
  const job = conJobs.find(j => j.id === jobId);
  const ps = job?.paymentSchedule || { type: 'none' };
  sel.value = ps.type || 'none';
  custom.style.display = (ps.type === 'custom') ? '' : 'none';
  custom.value = (ps.type === 'custom' && Array.isArray(ps.customPcts)) ? ps.customPcts.join(',') : '';
}

// Saves the selected Payment Schedule choice to the current job in
// Firestore. Called on change of either the preset dropdown or the
// custom-percentages input.
function savePaymentSchedule() {
  const sel = document.getElementById('paymentScheduleType');
  const custom = document.getElementById('paymentScheduleCustomInput');
  if (!sel || !conCurrentJobId || !conDb) return;
  const type = sel.value;
  custom.style.display = (type === 'custom') ? '' : 'none';

  const data = { type };
  if (type === 'custom') {
    // Accept commas, slashes, or whitespace as separators — the preset
    // dropdown options themselves display as "50 / 25 / 25", so typing
    // a custom value the same way (e.g. "5/95") is a completely
    // reasonable expectation. Previously only commas worked, so "5/95"
    // silently parsed as just 5 (parseFloat stops at the first
    // non-numeric character), giving a confusing "currently 5" error.
    const pcts = (custom.value || '').split(/[,/]+/).map(s => parseFloat(s.trim())).filter(n => !isNaN(n) && n > 0);
    const sum = pcts.reduce((a, b) => a + b, 0);
    if (pcts.length && Math.abs(sum - 100) > 0.01) {
      alert('Custom payment percentages must add up to 100 (currently ' + sum + ').');
      return;
    }
    data.customPcts = pcts;
  }
  coll('jobs').doc(conCurrentJobId).update({ paymentSchedule: data })
    .then(() => {
      const job = conJobs.find(j => j.id === conCurrentJobId);
      if (job) job.paymentSchedule = data;
    })
    .catch(e => alert('Error saving payment schedule: ' + e.message));
}
window.savePaymentSchedule = savePaymentSchedule;

// Turns a job's saved paymentSchedule + the Proposal's grand total into an
// array of { label, pct, amount } rows ready to print. Returns [] for
// 'none' or when there's nothing usable to show — printProposal skips the
// whole table in that case rather than printing an empty box.
//
// Now built on resolveScheduleStages() — the same shared resolver the
// invoice picker and estimate importer already use — instead of
// maintaining its own separate hardcoded list of schedule types. That
// second list had already drifted out of sync once (missing
// 10/40/25/25's proper labels) and would have silently missed every
// new schedule type added going forward, including this one
// (35/25/25/15), if left as its own copy.
function getPaymentScheduleRows(paymentSchedule, grandTotal) {
  const ps = paymentSchedule || { type: 'none' };
  let stages = null;
  if (ps.type === 'full') {
    stages = [{ label: 'Due On Completion (DOC)', pct: 100 }];
  } else {
    const resolved = resolveScheduleStages(ps);
    if (resolved.length) {
      stages = resolved.map((s, i) => ({
        label: i === resolved.length - 1 ? s.label + ' (Due Upon Completion)' : s.label,
        pct: s.pct,
      }));
    }
  }
  if (!stages) return [];

  // Proposal-specific wording: any stage genuinely labeled "Progress
  // Payment" (with or without a trailing number) gets a construction-
  // completion milestone attached — e.g. "Progress Payment 1 due upon
  // 50% completion". Deposit, Final, "Materials & Mobilization", and
  // custom schedules ("Payment N") are untouched by design — Travis
  // confirmed that wording is already correct as-is; this only applies
  // to stages that are actually progress payments. Scoped to THIS
  // function (the proposal renderer) specifically, not
  // resolveScheduleStages() itself, since the invoice stage-picker and
  // estimate importer use that shared resolver too and don't need this
  // more verbose customer-facing phrasing.
  //
  // Completion milestones are evenly spaced by halving the remaining
  // distance to 100% for each successive progress stage: 50%, 75%,
  // 87.5%, ... -- matches the given example (1st → 50%, 2nd → 75%)
  // and generalizes cleanly to schedules with 3+ progress payments.
  const progressIdxs = stages.reduce((arr, s, i) => { if (/^Progress Payment(\s\d+)?$/.test(s.label)) arr.push(i); return arr; }, []);
  progressIdxs.forEach((idx, n) => {
    const completionPct = Math.round((100 - 100 / Math.pow(2, n + 1)) * 10) / 10;
    const num = progressIdxs.length > 1 ? ' ' + (n + 1) : '';
    stages[idx].label = `Progress Payment${num} due upon ${completionPct}% completion`;
  });

  return stages.map(s => ({ label: s.label, pct: s.pct, amount: grandTotal * (s.pct / 100) }));
}

// ── Render the estimate tree ──
function renderEstimateTree() {
  const tree = document.getElementById('estimateTree');
  const emptyState = document.getElementById('estEmptyState');
  if (!tree) return;

  if (!estGroups.length) {
    tree.innerHTML = '';
    if (emptyState) emptyState.style.display = 'block';
    return;
  }
  if (emptyState) emptyState.style.display = 'none';

  tree.innerHTML = estGroups.map(group => renderGroupHTML(group)).join('');
}

function renderGroupHTML(group) {
  const isCollapsed = _estCollapsed[group.id];
  const allItems = getAllItemsInGroup(group);
  const totals = calcGroupTotals(allItems);
  const marginColor = totals.margin >= 20 ? '#1dbb87' : totals.margin >= 10 ? '#f59e0b' : '#ef5350';

  return `<div class="est-group" id="estGroup_${group.id}" style="${group.visibleToCustomer===false?'opacity:.55':''}">
    <div class="est-group-head" onclick="toggleGroupCollapse('${group.id}')">
      <span class="est-group-toggle ${isCollapsed?'':'open'}">▶</span>
      <span class="est-group-name">${esc(group.name)}</span>
      <span class="est-group-total-val" style="color:var(--muted);font-size:.76rem">${allItems.length} item${allItems.length!==1?'s':''}</span>
      <span class="est-group-total-val" style="color:var(--muted)">Cost: $${Math.round(totals.cost).toLocaleString()}</span>
      <span class="est-group-total-val" style="color:var(--amber)">Price: $${Math.round(totals.price).toLocaleString()}</span>
      <span class="est-group-total-val" style="color:${marginColor}">${Math.round(totals.margin)}%</span>
      <div style="display:flex;gap:6px;margin-left:8px" onclick="event.stopPropagation()">
        <button onclick="toggleGroupVisibility('${group.id}')" class="btn" style="padding:2px 8px;font-size:.7rem" title="${group.visibleToCustomer===false?'Hidden from customer - click to show':'Visible to customer - click to hide'}">${group.visibleToCustomer===false?'🚫':'👁️'}</button>
        <button onclick="openAddSubgroupModal('${group.id}')" class="btn" style="padding:2px 8px;font-size:.7rem">+ Sub</button>
        <button onclick="openAddEstItemModal(null,'${group.id}')" class="btn" style="padding:2px 8px;font-size:.7rem">+ Item</button>
        <button onclick="openEditGroupModal('${group.id}')" class="btn" style="padding:2px 8px;font-size:.7rem">✏️</button>
        <button onclick="deleteGroup('${group.id}')" class="btn btn-danger" style="padding:2px 8px;font-size:.7rem">✕</button>
      </div>
    </div>
    ${isCollapsed ? '' : `<div>
      ${(group.subgroups||[]).map(sub => renderSubgroupHTML(group.id, sub)).join('')}
      ${(group.directItems||[]).map(item => renderItemRowHTML(item, group.id, null)).join('')}
      ${(group.directItems||[]).length > 0 || (group.subgroups||[]).length === 0 ? `
        <div style="padding:6px 12px 10px">
          <button class="est-add-btn" onclick="openAddEstItemModal(null,'${group.id}')">+ Add line item to ${esc(group.name)}</button>
        </div>` : ''}
    </div>`}
  </div>`;
}

function renderSubgroupHTML(groupId, sub) {
  const isCollapsed = _estCollapsed[sub.id];
  const totals = calcGroupTotals(sub.items||[]);
  const marginColor = totals.margin >= 20 ? '#1dbb87' : totals.margin >= 10 ? '#f59e0b' : '#ef5350';

  return `<div class="est-subgroup" id="estSub_${sub.id}" style="${sub.visibleToCustomer===false?'opacity:.55':''}">
    <div class="est-subgroup-head" onclick="toggleGroupCollapse('${sub.id}')">
      <span class="est-group-toggle ${isCollapsed?'':'open'}" style="font-size:.75rem">▶</span>
      <span class="est-subgroup-name">${esc(sub.name)}</span>
      ${sub.pendingBid ? `<span title="${esc(sub.pendingBidNote || 'Pending Vendor Bid — customer sees a preliminary-pricing caveat on the Proposal')}" style="font-size:.85rem;cursor:help" onclick="event.stopPropagation()">⚠️</span>` : ''}
      <span style="font-size:.74rem;color:var(--muted)">${(sub.items||[]).length} items · Cost $${Math.round(totals.cost).toLocaleString()} · Price $${Math.round(totals.price).toLocaleString()}</span>
      <span style="font-size:.74rem;color:${marginColor}">${Math.round(totals.margin)}%</span>
      <div style="display:flex;gap:4px" onclick="event.stopPropagation()">
        <button onclick="toggleSubgroupVisibility('${groupId}','${sub.id}')" class="btn" style="padding:1px 6px;font-size:.68rem" title="${sub.visibleToCustomer===false?'Hidden from customer - click to show':'Visible to customer - click to hide'}">${sub.visibleToCustomer===false?'🚫':'👁️'}</button>
        <button onclick="openAddSubSubgroupModal('${groupId}','${sub.id}')" class="btn" style="padding:1px 6px;font-size:.68rem">+ Sub</button>
        <button onclick="openAddEstItemModal(null,'${groupId}','${sub.id}')" class="btn" style="padding:1px 6px;font-size:.68rem">+ Item</button>
        <button onclick="duplicateSubgroup('${groupId}','${sub.id}')" class="btn" style="padding:1px 6px;font-size:.68rem" title="Duplicate this subgroup and all its line items">⧉ Duplicate</button>
        <button onclick="openEditSubgroupModal('${groupId}','${sub.id}')" class="btn" style="padding:1px 6px;font-size:.68rem">✏️</button>
        <button onclick="deleteSubgroup('${groupId}','${sub.id}')" class="btn btn-danger" style="padding:1px 6px;font-size:.68rem">✕</button>
      </div>
    </div>
    ${sub.scopeNotes ? `<div style="padding:4px 12px 6px 36px;font-size:.78rem;color:#94a3b8;font-style:italic;line-height:1.5;white-space:pre-wrap;border-left:2px solid rgba(217,119,6,.25);margin:0 0 2px 16px">${esc(sub.scopeNotes)}</div>` : ''}
    ${isCollapsed ? '' : `<div>
      ${(sub.subgroups||[]).map(subsub => renderSubSubgroupHTML(groupId, sub.id, subsub)).join('')}
      ${(sub.items||[]).map(item => renderItemRowHTML(item, groupId, sub.id)).join('')}
      <div style="padding:4px 12px 8px 48px">
        <button class="est-add-btn" onclick="openAddSubSubgroupModal('${groupId}','${sub.id}')">+ Add subgroup to ${esc(sub.name)}</button>
        <button class="est-add-btn" onclick="openAddEstItemModal(null,'${groupId}','${sub.id}')" style="margin-left:8px">+ Add item to ${esc(sub.name)}</button>
      </div>
    </div>`}
  </div>`;
}

function renderSubSubgroupHTML(groupId, subgroupId, subsub) {
  const isCollapsed = _estCollapsed[subsub.id];
  const totals = calcGroupTotals(subsub.items||[]);
  const marginColor = totals.margin >= 20 ? '#1dbb87' : totals.margin >= 10 ? '#f59e0b' : '#ef5350';
  const gid = groupId, sid = subgroupId, ssid = subsub.id;
  const itemRows = (subsub.items||[]).map(item => renderItemRowHTML(item, gid, sid, ssid)).join('');
  const collapsed = isCollapsed ? 'open' : '';

  let html = '<div class="est-subgroup" id="estSubSub_' + ssid + '" style="margin-left:24px">';
  html += '<div class="est-subgroup-head" onclick="toggleGroupCollapse(\'' + ssid + '\')">';
  html += '<span class="est-group-toggle ' + (isCollapsed ? '' : 'open') + '" style="font-size:.7rem">&#9654;</span>';
  html += '<span class="est-subgroup-name" style="font-size:.82rem">' + esc(subsub.name) + '</span>';
  html += '<span style="font-size:.7rem;color:var(--muted)">' + (subsub.items||[]).length + ' items</span>';
  html += '<span style="font-size:.7rem;color:' + marginColor + '">' + Math.round(totals.margin) + '%</span>';
  html += '<div style="display:flex;gap:4px" onclick="event.stopPropagation()">';
  html += '<button onclick="openAddEstItemModal(null,' + JSON.stringify(gid) + ',' + JSON.stringify(sid) + ',' + JSON.stringify(ssid) + ')" class="btn" style="padding:1px 5px;font-size:.65rem">+ Item</button>';
  html += '<button onclick="openEditSubSubgroupModal(' + JSON.stringify(gid) + ',' + JSON.stringify(sid) + ',' + JSON.stringify(ssid) + ')" class="btn" style="padding:1px 5px;font-size:.65rem">&#9999;</button>';
  html += '<button onclick="deleteSubSubgroup(' + JSON.stringify(gid) + ',' + JSON.stringify(sid) + ',' + JSON.stringify(ssid) + ')" class="btn btn-danger" style="padding:1px 5px;font-size:.65rem">&#10005;</button>';
  html += '</div></div>';
  if (!isCollapsed) {
    html += '<div>' + itemRows;
    html += '<div style="padding:4px 12px 8px 72px">';
    html += '<button class="est-add-btn" onclick="openAddEstItemModal(null,' + JSON.stringify(gid) + ',' + JSON.stringify(sid) + ',' + JSON.stringify(ssid) + ')">+ Add item to ' + esc(subsub.name) + '</button>';
    html += '</div></div>';
  }
  html += '</div>';
  return html;
}


function renderItemRowHTML(item, groupId, subgroupId, subSubgroupId) {
  const qty = item.qty || 1;
  const unitCost = item.unitCost || 0;
  const markup = item.markup || 0;
  const unitPrice = item.unitPrice || unitCost * (1 + markup/100);
  const extCost = qty * unitCost;
  const extPrice = qty * unitPrice;
  const margin = extPrice > 0 ? Math.round((extPrice - extCost) / extPrice * 100) : 0;
  const marginColor = margin >= 20 ? '#1dbb87' : margin >= 10 ? '#f59e0b' : '#ef5350';
  const ctColors = { Labor:'#3b82f6', Materials:'#f59e0b', Subcontractor:'#8b5cf6', Equipment:'#06b6d4', 'Permits & Fees':'#f97316' };
  const ctColor = ctColors[item.costType] || 'var(--muted)';

  return `<div class="est-item-row" id="estItem_${item.id}">
    <div style="font-size:.68rem;color:rgba(110,145,210,.3)">${item.order||''}</div>
    <div>
      <div style="font-weight:600">${esc(item.desc||'Unnamed item')}</div>
      ${item.notes?`<div style="font-size:.72rem;color:var(--muted);font-style:italic">${esc(item.notes)}</div>`:''}
    </div>
    <div style="color:var(--muted)">${qty}${item.unit?' '+esc(item.unit):''}</div>
    <div><span style="font-size:.7rem;color:${ctColor};font-weight:700">${esc(item.costType||'')}</span></div>
    <div style="text-align:right">$${unitCost.toFixed(2)}</div>
    <div style="text-align:right;font-weight:700">$${extCost.toFixed(2)}</div>
    <div style="text-align:right">$${unitPrice.toFixed(2)}</div>
    <div style="text-align:right;font-weight:700;color:var(--amber)">$${extPrice.toFixed(2)}</div>
    <div style="text-align:right;font-weight:700;color:${marginColor}">${margin}%</div>
    <div style="display:flex;gap:3px;justify-content:flex-end">
      <button onclick="openAddEstItemModal('${item.id}','${groupId}','${subgroupId||''}')" class="btn" style="padding:2px 6px;font-size:.7rem">✏️</button>
      <button onclick="deleteEstItem('${item.id}','${groupId}','${subgroupId||''}')" class="btn btn-danger" style="padding:2px 6px;font-size:.7rem">✕</button>
    </div>
  </div>`;
}

function getAllItemsInGroup(group) {
  const items = [...(group.directItems||[])];
  (group.subgroups||[]).forEach(sub => {
    items.push(...(sub.items||[]));
    (sub.subgroups||[]).forEach(subsub => items.push(...(subsub.items||[])));
  });
  return items;
}

function calcGroupTotals(items) {
  let cost = 0, price = 0;
  items.forEach(item => {
    const qty = item.qty||1;
    const uc = item.unitCost||0;
    const up = item.unitPrice || uc*(1+(item.markup||0)/100);
    cost += qty * uc;
    price += qty * up;
  });
  const profit = price - cost;
  const margin = price > 0 ? profit/price*100 : 0;
  return { cost, price, profit, margin };
}

// Every room (group) → category (subgroup) → sub-category (subsub) →
// item, one row each, with the Materials/Labor split and a subtotal
// row after every category — same breakdown Travis asked for on the
// Roofing group, just for the whole estimate at once. Opens directly
// in Excel (CSV, same pattern as exportReport() for the Reports tab).
function exportEstimateBreakdown() {
  if (!estGroups.length) { alert('No estimate line items to export yet.'); return; }

  const job = conJobs.find(j => j.id === conCurrentJobId);
  const csvRow = (...fields) => fields.map(f => '"'+String(f??'').replace(/"/g,'""')+'"').join(',') + '\n';
  const money = n => Math.round((n||0)*100)/100;

  let csv = '';
  csv += csvRow('Job', job ? `${job.jobNumber||''} ${job.name||''}`.trim() : '');
  csv += csvRow('Exported', new Date().toLocaleString());
  csv += '\n';
  csv += csvRow('Room','Category','Sub-Category','Item','Qty','Unit','Type','Unit Cost','Total Cost','Unit Price','Total Price','Margin %');

  let grandCost = 0, grandPrice = 0;

  const itemRow = (roomName, catName, subName, item) => {
    const qty = item.qty || 1;
    const uc = item.unitCost || 0;
    const up = item.unitPrice || uc*(1+(item.markup||0)/100);
    const totalCost = qty*uc, totalPrice = qty*up;
    const margin = totalPrice > 0 ? (totalPrice-totalCost)/totalPrice*100 : 0;
    csv += csvRow(roomName, catName, subName, item.desc||item.name||'', qty, item.unit||'', item.costType||'',
      money(uc), money(totalCost), money(up), money(totalPrice), Math.round(margin));
    return { cost: totalCost, price: totalPrice };
  };

  // Writes a Materials subtotal / Labor subtotal / Category total block
  // right after a category's items — mirrors what Travis asked for on
  // Roofing specifically, applied to every category in the estimate.
  const subtotalBlock = (label, items) => {
    let matCost=0, matPrice=0, labCost=0, labPrice=0;
    items.forEach(it => {
      const qty = it.qty||1, uc = it.unitCost||0, up = it.unitPrice || uc*(1+(it.markup||0)/100);
      if ((it.costType||'') === 'Labor') { labCost += qty*uc; labPrice += qty*up; }
      else { matCost += qty*uc; matPrice += qty*up; }
    });
    csv += csvRow('','','','MATERIALS SUBTOTAL','','','', '', money(matCost), '', money(matPrice), '');
    csv += csvRow('','','','LABOR SUBTOTAL','','','', '', money(labCost), '', money(labPrice), '');
    csv += csvRow('','','',label+' TOTAL','','','', '', money(matCost+labCost), '', money(matPrice+labPrice), '');
    csv += '\n';
  };

  estGroups.forEach(group => {
    const roomName = group.name || 'General';
    (group.directItems||[]).forEach(it => itemRow(roomName, '(direct)', '', it));
    if ((group.directItems||[]).length) subtotalBlock(roomName+' (direct)', group.directItems);

    (group.subgroups||[]).forEach(sub => {
      const catName = sub.name || '';
      (sub.items||[]).forEach(it => itemRow(roomName, catName, '', it));
      if ((sub.items||[]).length) subtotalBlock(`${roomName} — ${catName}`, sub.items);

      (sub.subgroups||[]).forEach(subsub => {
        const subName = subsub.name || '';
        (subsub.items||[]).forEach(it => itemRow(roomName, catName, subName, it));
        if ((subsub.items||[]).length) subtotalBlock(`${roomName} — ${catName} — ${subName}`, subsub.items);
      });
    });

    const t = calcGroupTotals(getAllItemsInGroup(group));
    grandCost += t.cost; grandPrice += t.price;
  });

  csv += csvRow('','','','GRAND TOTAL (all rooms)','','','', '', money(grandCost), '', money(grandPrice), Math.round(grandPrice>0?(grandPrice-grandCost)/grandPrice*100:0));

  const blob = new Blob([csv], {type:'text/csv'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const jobNum = job?.jobNumber ? job.jobNumber.replace(/[^a-zA-Z0-9-]/g,'') : 'job';
  a.download = `estimate-breakdown-${jobNum}-${new Date().toISOString().split('T')[0]}.csv`;
  a.click();
}
window.exportEstimateBreakdown = exportEstimateBreakdown;


// ── Friends & Family Labor Discount ──────────────────────────────────
// Reduces the CUSTOMER-FACING price on every Labor line item by a flat
// %, while leaving unitCost untouched — so real labor cost/margin
// tracking stays accurate, only the price charged goes down. Applied
// as an actual write to each line item's markup/unitPrice (not a
// display-time overlay), specifically because it needs to flow through
// to invoices generated via "Import from Estimate" later, which read
// the real stored unitPrice/qty off each item — a display-only
// discount on the Estimate summary total would never reach those.
// Reversible: the pre-discount values are snapshotted onto the job doc
// before any line item is touched, so "Remove Discount" can restore
// exact original pricing.

// The full 6-bucket ESTIMATED breakdown, known instantly once a
// proposal is signed -- extends the Labor Budget math above (Labor is
// literally "whatever's left after Materials and the three targets")
// to all six buckets, so every one of them has both an Estimated and
// an Actual figure to compare from day one.
// Uses the LOCKED formula from the "consultant hat" session, not the
// earlier 15/12/3-of-revenue model this function used before that —
// Materials is raw billed (the ~15% markup is Travis's own deliberate
// overrun float, staying IN the bucket, never backed out), Overhead
// is 18% of revenue, Marketing is 1.5%. Labor Budget here is a
// pre-negotiation CEILING — the whole remainder after Materials/
// Overhead/Marketing, before Flex/Taxes/Profit are carved out of it.
// That's a real, stated modeling choice, not an attempt to replicate
// the full post-Labor waterfall (Flex/Taxes/RE) for a number that by
// definition exists before Labor is chosen.
async function computeEstimatedBreakdown(job) {
  const { materials: billedMaterials } = await fetchEstimateCostSplitFresh(job.id);
  const revenue = getJobValue(job) || 0;
  const overhead = revenue * 0.18;
  const marketing = revenue * 0.015;
  const labor = Math.max(0, revenue - billedMaterials - overhead - marketing);
  const r = v => Math.round(v * 100) / 100;
  return {
    revenue: r(revenue), materials: r(billedMaterials), labor: r(labor),
    overhead: r(overhead), marketing: r(marketing),
  };
}

async function renderLaborBudget() {
  const wrap = document.getElementById('fhLaborBudgetWrap');
  if (!wrap) return;
  if (currentUserRole !== 'Owner') { wrap.style.display = 'none'; return; }
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (!job) { wrap.style.display = 'none'; return; }
  wrap.style.display = '';
  wrap.innerHTML = `<div class="finhub-sec-head" style="cursor:default"><span>🎯 Budget: Estimated vs Actual <span class="small muted">(Owner only)</span></span></div>
    <div class="finhub-sec-body"><div class="finhub-empty">Calculating…</div></div>`;
  try {
    const [est, act] = await Promise.all([computeEstimatedBreakdown(job), computeCOOBudgetBreakdown(job)]);
    const fmt = v => '$' + v.toLocaleString(undefined, {minimumFractionDigits:0, maximumFractionDigits:0});
    const body = document.querySelector('#fhLaborBudgetWrap .finhub-sec-body');
    if (!body) return;

    // Cost buckets: over-estimate is bad (red). Value buckets: under-
    // target is bad (red) -- a real consequence of cost running hot,
    // not something separately controlled, but still worth flagging.
    // Retained Earnings/Taxes are deliberately NOT compared here --
    // computeEstimatedBreakdown's Labor Budget is a pre-negotiation
    // ceiling (the whole remainder after Materials/Overhead/Marketing),
    // so there's no meaningful "Estimated" Retained Earnings/Taxes
    // figure to compare against until Labor is actually chosen -- those
    // only exist downstream of Labor in the locked waterfall.
    const costBuckets = ['materials', 'labor'];
    const rows = [
      ['Materials', 'materials'], ['Labor', 'labor'], ['Overhead', 'overhead'], ['Marketing', 'marketing'],
    ];
    const rowsHtml = rows.map(([label, key]) => {
      const e = est[key], a = act[key];
      const variance = a - e;
      const isCost = costBuckets.includes(key);
      const isBad = isCost ? variance > 0 : variance < 0;
      const vColor = Math.abs(variance) < 1 ? 'var(--muted)' : (isBad ? '#fca5a5' : '#86efac');
      const vSign = variance > 0 ? '+' : '';
      return `<div class="finhub-line">
        <div class="finhub-line-title">${label}</div>
        <div class="small muted" style="width:90px;text-align:right">${fmt(e)}</div>
        <div class="finhub-line-amt" style="width:90px">${fmt(a)}</div>
        <div class="small" style="width:90px;text-align:right;color:${vColor};font-weight:700">${vSign}${fmt(variance)}</div>
      </div>`;
    }).join('');

    const materialsFlag = act.materialsSource && act.materialsSource.startsWith('estimate-derived')
      ? `<div class="small muted" style="font-style:italic">⚠ Actual Materials still estimate-derived — no vendor bills/expenses logged against this job yet.</div>` : '';
    const laborFlag = act.costSource && act.costSource.startsWith('PLACEHOLDER')
      ? `<div class="small muted" style="font-style:italic">⚠ Actual Labor still a placeholder — no subcontractor payments logged yet.</div>` : '';

    body.innerHTML = `
      <div class="finhub-line" style="font-weight:800;border-bottom:1px solid rgba(110,145,210,.15);padding-bottom:6px;margin-bottom:2px">
        <div class="finhub-line-title small muted">BUCKET</div>
        <div class="small muted" style="width:90px;text-align:right">ESTIMATED</div>
        <div class="small muted" style="width:90px">ACTUAL</div>
        <div class="small muted" style="width:90px;text-align:right">VARIANCE</div>
      </div>
      ${rowsHtml}
      ${materialsFlag}${laborFlag}
      <div class="small muted" style="font-style:italic;padding-top:6px;border-top:1px solid rgba(110,145,210,.1);margin-top:4px">Estimated = known from the signed price the moment it's signed, no subcontractor or purchase needed. Actual = real cost as it comes in. Red variance means a cost bucket ran over or a value bucket is falling short of target.</div>`;
  } catch (e) {
    const body = document.querySelector('#fhLaborBudgetWrap .finhub-sec-body');
    if (body) body.innerHTML = `<div class="finhub-empty">Could not calculate: ${esc(e.message)}</div>`;
  }
}
window.renderLaborBudget = renderLaborBudget;
window.computeEstimatedBreakdown = computeEstimatedBreakdown;

// ── COO Budget Breakdown ──────────────────────────────────────────
// Splits a job's estimate into a category breakdown: Materials and
// Labor/Subs flex per-job (derived from THIS estimate's real
// composition), while Overhead/Profit/Marketing/Flex stay FIXED
// company-wide percentages — the framework worked out with Travis:
// discipline on every dollar, without forcing every job into an
// identical ratio that doesn't reflect what the job actually is.
// Taxes are computed off the PROFIT line, not off revenue — taxing
// revenue directly overstates the real tax liability substantially.
//
// These company-wide percentages are intentionally hardcoded here for
// now rather than a Settings field — they're a business decision
// Travis is still tuning, not yet a stable configuration value. Move
// to Settings once these numbers settle.
const COO_BUDGET_PCTS = {
  overhead: 0.15,
  profit: 0.12,
  marketing: 0.03,
};
// These three no longer mean "fixed % of revenue" — they're RATIO
// WEIGHTS (15:12:3) applied to this job's REAL gross margin dollar
// amount, so the buckets scale with what the job actually costs
// instead of assuming every job hits the same cost ratio. Flex was
// dropped entirely per Travis's 6-bucket model (Materials, Labor,
// Overhead, Retained Earnings, Marketing, Taxes) — Taxes is still
// derived FROM Retained Earnings below, not an independent weight.
const COO_BUDGET_WEIGHT_SUM = COO_BUDGET_PCTS.overhead + COO_BUDGET_PCTS.profit + COO_BUDGET_PCTS.marketing;
const COO_BUDGET_TAX_RATE = 0.275; // midpoint of the 25-30% SE+income tax range discussed, applied to Retained Earnings only

function getEstimateCostSplit() {
  // Materials vs everything-else (Labor, Subcontractor, Equipment,
  // etc.) across the whole live estimate tree — same traversal shape
  // as walkEstimateLaborItems, just bucketed differently.
  let materials = 0, laborAndOther = 0;
  const addItem = item => {
    const price = (item.unitPrice || 0) * (item.qty || 1);
    if (item.costType === 'Materials') materials += price;
    else laborAndOther += price;
  };
  estGroups.forEach(g => {
    (g.directItems || []).forEach(addItem);
    (g.subgroups || []).forEach(sub => {
      (sub.items || []).forEach(addItem);
      (sub.subgroups || []).forEach(subsub => (subsub.items || []).forEach(addItem));
    });
  });
  return { materials, laborAndOther };
}

// Real materials cost — paid vendor bills for this job + logged job
// expenses (materials purchases), same sources refreshJobFinancials
// already sums for the dashboard header. Falls back to null (caller
// uses the estimate-derived True Materials figure instead) if nothing
// real has been logged yet — same fallback philosophy as labor below.
async function computeRealMaterialsActual(jobId) {
  let billsPaid = 0, expensesTotal = 0;
  try {
    const vSnap = await coll('vendors').get();
    await Promise.all(vSnap.docs.map(vDoc =>
      vDoc.ref.collection('bills').where('jobId', '==', jobId).get()
        .then(bSnap => bSnap.forEach(bDoc => { billsPaid += (bDoc.data().amtPaid || 0); }))
        .catch(() => {})
    ));
  } catch (e) { /* fall through */ }
  try {
    const eSnap = await coll('jobs').doc(jobId).collection('expenses').get();
    eSnap.forEach(eDoc => { expensesTotal += (eDoc.data().amount || 0); });
  } catch (e) { /* fall through */ }
  const total = billsPaid + expensesTotal;
  return total > 0 ? total : null;
}

// Real cost for a job — Materials and Labor — in priority order from
// most to least trustworthy, never catalog placeholder rates:
//   Materials: real paid vendor bills + logged expenses for this job,
//     if any exist; otherwise billed materials ÷ 1.15 (backs out the
//     established 15% markup — same formula validated by hand all
//     session), flagged as estimate-derived rather than real spend.
//   Labor, in order:
//     1. Real subcontractor payments actually logged on this job
//        (jobs/{jobId}/subcontractorPayments) — real committed dollars.
//     2. If none logged yet, estimate from real contractor data: sum
//        each linked Contractor's crew hours clocked on this job ×
//        that contractor's burdenedRate — the exact same math the
//        Subcontractor Payment auto-suggest already uses, so this
//        never disagrees with what that modal would suggest.
//     3. Last resort: billed labor from the estimate itself, clearly
//        flagged as a placeholder — no real cost data exists yet.
async function computeRealJobCost(jobId) {
  const { materials: billedMaterials } = await fetchEstimateCostSplitFresh(jobId);
  const realMaterialsActual = await computeRealMaterialsActual(jobId);
  // Real bug found and fixed here: while a job is still actively being
  // purchased for, "actual spend so far" is NOT the same thing as "total
  // materials this job will cost" -- it starts low and ramps up as
  // purchasing happens. The old logic let ANY real spend (even a single
  // $5 receipt) completely REPLACE the full estimate-derived materials
  // figure, which understated total projected cost (and therefore
  // inflated Profit/Margin) on every in-progress job the moment its
  // first material purchase was logged. Confirmed live on 707 Karon
  // Drive: $304.95 actually spent vs. $22,943.06 in the signed
  // proposal's materials line -- Cost to Complete was reading ~$22.6K
  // too low, Profit ~$22.6K too high, Margin 59.2% instead of ~25.9%.
  // Taking the max of the two fixes this while still correctly
  // reflecting a genuine overrun once real spend exceeds the estimate
  // (at which point actual, being higher, naturally wins on its own).
  const materials = realMaterialsActual != null ? Math.max(realMaterialsActual, billedMaterials) : billedMaterials;
  const materialsSource = realMaterialsActual != null
    ? (realMaterialsActual > billedMaterials ? 'actual vendor bills + expenses (exceeds estimate -- real overrun)' : 'estimate-derived (full materials not yet purchased)')
    : 'estimate-derived (raw billed) — no real purchases logged yet';

  // Real, signed subcontractor agreements (status Contracted or later --
  // i.e. an actual signed contract, not just a bid still being
  // considered) live on jobs/{jobId}/subs, keyed by their own `amount`
  // field -- a completely separate collection from subcontractorPayments
  // below. Real gap found: signing an agreement flips a sub's status to
  // 'Contracted' but never creates a subcontractorPayments record, so
  // real signed contracts (707 Karon Drive: Kyle Martin $8,000 + Truedom
  // Contracting $10,000 + 7 Pillars $12,000 = $30,000) sat there while
  // this function fell through to a clocked-hours estimate or the Labor
  // Budget placeholder, missing the real committed cost entirely --
  // Travis: "under subs it is clear I signed 3 subs for 30,000... the
  // numbers don't add up anywhere." Same "take the higher, real number"
  // pattern as Materials above: summing contracted subs' amounts and
  // taking the max against whatever subcontractorPayments produces means
  // neither system has to be the sole source of truth, and a signed
  // contract is never invisible just because nobody separately logged a
  // payment record for it too.
  const subsSnap = await coll('jobs').doc(jobId).collection('subs').get();
  let contractedSubsTotal = 0;
  subsSnap.forEach(d => {
    const s = d.data();
    if (s.status && s.status !== 'Bidding' && typeof s.amount === 'number') {
      contractedSubsTotal += s.amount;
    }
  });

  const paySnap = await coll('jobs').doc(jobId).collection('subcontractorPayments').get();
  let loggedLabor = 0;
  paySnap.forEach(d => { const p = d.data(); if (p.status !== 'Voided') loggedLabor += (p.amount || 0); });

  const bestKnownLabor = Math.max(contractedSubsTotal, loggedLabor);
  if (bestKnownLabor > 0) {
    const source = contractedSubsTotal > loggedLabor
      ? 'signed subcontractor agreements (Subs & Vendors)'
      : 'actual subcontractor payments';
    return { materials, materialsSource, labor: bestKnownLabor, source };
  }

  const contractorsOnJob = (allContractors || []).filter(c => (c.crewMemberEmails||[]).length);
  if (contractorsOnJob.length) {
    try {
      const teSnap = await coll('timeentries').where('jobId', '==', jobId).get();
      const hoursByEmail = {};
      teSnap.forEach(d => {
        const t = d.data();
        if (!t.hours || !t.userEmail) return;
        const email = t.userEmail.toLowerCase();
        hoursByEmail[email] = (hoursByEmail[email] || 0) + t.hours;
      });
      let estimatedLabor = 0, anyHours = false;
      contractorsOnJob.forEach(c => {
        const rate = Number(c.burdenedRate) || 0;
        (c.crewMemberEmails || []).forEach(email => {
          const h = hoursByEmail[(email||'').toLowerCase()] || 0;
          if (h > 0) { anyHours = true; estimatedLabor += h * rate; }
        });
      });
      if (anyHours) return { materials, materialsSource, labor: estimatedLabor, source: 'estimated from clocked hours × contractor rate' };
    } catch (e) { /* fall through to placeholder */ }
  }

  // Last-resort placeholder: the SAME Labor Budget ceiling shown on
  // the Financials "Budget: Estimated vs Actual" card, not a
  // separately-derived number -- these two can never disagree with
  // each other now, since they're the same calculation.
  const job = conJobs.find(j => j.id === jobId);
  if (job) {
    try {
      const est = await computeEstimatedBreakdown(job);
      return { materials, materialsSource, labor: est.labor, source: 'PLACEHOLDER — Labor Budget ceiling (locked waterfall), no real subcontractor cost logged yet' };
    } catch (e) { /* fall through to raw billed labor below */ }
  }
  const { laborAndOther: billedLabor } = await fetchEstimateCostSplitFresh(jobId);
  return { materials, materialsSource, labor: billedLabor, source: 'PLACEHOLDER — billed labor, no real subcontractor cost data logged yet' };
}

// Delegates to computeLockedBucketSplit (the real formula locked
// directly with Travis, already verified live against 707 Karon
// tonight) instead of the earlier gross-margin-ratio model this
// function used before that -- Overhead 18%/Marketing 1.5% of
// REVENUE (not ratio-weighted off gross margin), Flex 20% of the
// remainder after Materials/Labor/Overhead/Marketing, Taxes 27.5% of
// what's left after Flex, Retained Earnings the final remainder.
// Return shape kept identical to what callers already expect
// (formatCOOBudgetBody, sendInvoiceSplitToPlannerXD, the Estimated vs
// Actual table) -- "profit" is Retained Earnings by another name here
// for backward compatibility, "flex" is a genuinely new field, purely
// additive, nothing existing breaks by its presence.
async function computeCOOBudgetBreakdown(job) {
  const realCost = await computeRealJobCost(job.id);
  const split = await computeLockedBucketSplit(job);
  return {
    revenue: split.revenue,
    materials: split.materials,
    labor: split.labor,
    overhead: split.overhead,
    profit: split.retainedEarnings,
    marketing: split.marketing,
    flex: split.flex,
    taxes: split.taxes,
    grossMarginDollar: Math.round((split.revenue - split.materials - split.labor) * 100) / 100,
    costSource: realCost.source,
    materialsSource: realCost.materialsSource,
    generatedAt: new Date().toISOString(),
  };
}

function formatCOOBudgetBody(b) {
  const fmt = v => '$' + v.toLocaleString(undefined, {minimumFractionDigits:2, maximumFractionDigits:2});
  const placeholderNote = b.costSource && b.costSource.startsWith('PLACEHOLDER')
    ? `\n\n⚠️ Labor cost is a placeholder (${b.costSource}) — log real subcontractor payments or clock hours for a real number.`
    : `\n\n(Cost basis: ${b.costSource || 'unknown'})`;
  return `Revenue: ${fmt(b.revenue)}\n`
    + `Materials: ${fmt(b.materials)}\n`
    + `Labor: ${fmt(b.labor)}\n`
    + `Overhead: ${fmt(b.overhead)}\n`
    + `Marketing: ${fmt(b.marketing)}\n`
    + `Flex: ${fmt(b.flex)}\n`
    + `Taxes: ${fmt(b.taxes)}\n`
    + `Retained Earnings: ${fmt(b.profit)}`
    + placeholderNote;
}

// Owner-only, manual trigger — deliberately NOT wired to a status
// change or automatic event. The existing proposal-signature ->
// PlannerXD bridge is flagged elsewhere in this file as unreliable and
// "being diagnosed" — stacking another automatic trigger on the same
// shaky mechanism would just add a second unreliable path. A button
// Travis presses himself is slower but actually trustworthy.
async function generateCOOBudgetBreakdown() {
  if (currentUserRole !== 'Owner') { alert('Only the Owner can generate a COO budget breakdown.'); return; }
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (!job) return;

  try {
    const breakdown = await computeCOOBudgetBreakdown(job);
    if (!breakdown.revenue) { alert('No estimate line items or contract value found on this job yet.'); return; }

    await coll('jobs').doc(job.id).update({ cooBudgetBreakdown: breakdown });
    job.cooBudgetBreakdown = breakdown;
    renderCOOBudgetBreakdown();

    // Push to PlannerXD — same bridge/collection already used for
    // to-do notifications, already scoped to the Owner's account
    // specifically (settings/company.ownerUid), so "only I see it"
    // is inherent to this destination, not something extra to build.
    const settDoc = await coll('settings').doc('company').get();
    const ownerUid = settDoc?.exists ? settDoc.data().ownerUid : null;
    if (!ownerUid) {
      alert('Budget breakdown saved on the job, but could not push to PlannerXD — no PlannerXD account (ownerUid) is linked in Company Settings.');
      return;
    }
    await conDb.collection('plannerxd_notifications').doc(ownerUid).collection('items').add({
      type: 'coo_budget_breakdown',
      title: 'COO Budget — ' + (job.address || job.name || 'Job'),
      body: formatCOOBudgetBody(breakdown),
      jobId: job.id,
      companyId: currentCompanyId,
      actionLabel: 'Open Job',
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      createdMs: Date.now(),
      read: false
    });
    alert('✅ COO budget breakdown generated and sent to PlannerXD.');
  } catch (e) {
    alert('Error generating breakdown: ' + e.message);
  }
}
window.generateCOOBudgetBreakdown = generateCOOBudgetBreakdown;

// Renders the saved breakdown (if any) in the Financials Hub —
// Owner-only, so it persists and is reviewable in JOBSMETRIX itself,
// not just as a PlannerXD notification that gets dismissed and lost.
function renderCOOBudgetBreakdown() {
  const wrap = document.getElementById('fhCooBudgetWrap');
  if (!wrap) return;
  if (currentUserRole !== 'Owner') { wrap.style.display = 'none'; return; }
  wrap.style.display = '';
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const b = job?.cooBudgetBreakdown;
  const genBtn = `<button class="btn" onclick="generateCOOBudgetBreakdown()" style="padding:4px 10px;font-size:.72rem">${b ? '↻ Regenerate' : '📊 Generate Breakdown'}</button>`;
  if (!b) {
    wrap.innerHTML = `<div class="finhub-sec-head" style="cursor:default"><span>📊 COO Budget Breakdown <span class="small muted">(Owner only)</span></span>${genBtn}</div>
      <div class="finhub-sec-body"><div class="finhub-empty">Not generated yet for this job.</div></div>`;
    return;
  }
  const fmt = v => '$' + v.toLocaleString(undefined, {minimumFractionDigits:0, maximumFractionDigits:0});
  const costFlag = b.costSource && b.costSource.startsWith('PLACEHOLDER') ? ' ⚠️ placeholder labor cost' : '';
  const rows = [
    ['Materials', b.materials, '#fb923c'],
    ['Labor', b.labor, '#60a5fa'],
    ['Overhead', b.overhead, '#a3a3a3'],
    ['Retained Earnings', b.profit, '#1dbb87'],
    ['Marketing', b.marketing, '#c084fc'],
  ];
  wrap.innerHTML = `<div class="finhub-sec-head" style="cursor:default"><span>📊 COO Budget Breakdown <span class="small muted">(Owner only) — Revenue ${fmt(b.revenue)}${costFlag}</span></span>${genBtn}</div>
    <div class="finhub-sec-body">
      ${rows.map(([label, val, color]) => `<div class="finhub-line"><div class="finhub-line-title" style="color:${color}">${label}</div><div class="finhub-line-amt">${fmt(val)}</div></div>`).join('')}
      <div class="finhub-line" style="border-top:1px solid rgba(110,145,210,.15);padding-top:8px;margin-top:4px"><div class="finhub-line-title" style="font-style:italic">Taxes (from Retained Earnings)</div><div class="finhub-line-amt" style="font-style:italic">${fmt(b.taxes)}</div></div>
    </div>`;
}
window.renderCOOBudgetBreakdown = renderCOOBudgetBreakdown;

function walkEstimateLaborItems() {
  // Returns [{ item, groupId, subgroupId, subSubgroupId }] for every
  // Labor cost-type line item across the whole tree (direct group
  // items, subgroup items, and sub-subgroup items).
  const out = [];
  estGroups.forEach(g => {
    (g.directItems || []).forEach(item => {
      if (item.costType === 'Labor') out.push({ item, groupId: g.id, subgroupId: null, subSubgroupId: null });
    });
    (g.subgroups || []).forEach(sub => {
      (sub.items || []).forEach(item => {
        if (item.costType === 'Labor') out.push({ item, groupId: g.id, subgroupId: sub.id, subSubgroupId: null });
      });
      (sub.subgroups || []).forEach(subsub => {
        (subsub.items || []).forEach(item => {
          if (item.costType === 'Labor') out.push({ item, groupId: g.id, subgroupId: sub.id, subSubgroupId: subsub.id });
        });
      });
    });
  });
  return out;
}

function laborItemRef(jobId, groupId, subgroupId, subSubgroupId, itemId) {
  const jobRef = coll('jobs').doc(jobId);
  if (subSubgroupId) {
    return jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId)
      .collection('subgroups').doc(subSubgroupId).collection('items').doc(itemId);
  }
  if (subgroupId) {
    return jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId).collection('items').doc(itemId);
  }
  return jobRef.collection('estimateGroups').doc(groupId).collection('items').doc(itemId);
}

async function applyLaborDiscount() {
  const input = document.getElementById('ffDiscountPct');
  const pct = parseFloat(input?.value);
  if (!pct || pct <= 0 || pct >= 100) { alert('Enter a discount percentage between 1 and 99.'); return; }

  const laborItems = walkEstimateLaborItems();
  if (!laborItems.length) { alert('No labor line items found on this estimate yet.'); return; }

  const currentTotal = laborItems.reduce((s, li) => s + (li.item.unitPrice || 0) * (li.item.qty || 1), 0);
  const newTotal = currentTotal * (1 - pct / 100);
  if (!confirm(`Apply a ${pct}% friends & family discount to ${laborItems.length} labor line item${laborItems.length===1?'':'s'}?\n\nLabor total: $${Math.round(currentTotal).toLocaleString()} → $${Math.round(newTotal).toLocaleString()}\n\nThis changes the actual price on each labor line (not just a display total), so it carries through to the Proposal and to any invoice you later import from this estimate. Your real labor cost/margin tracking is untouched — only the customer-facing price drops. Reversible with "Remove Discount."`)) return;

  try {
    // Snapshot originals BEFORE touching anything, so this is
    // reversible even if applied more than once (each apply overwrites
    // the backup with what was live at that moment, which is correct —
    // "remove" should undo the CURRENT discount, not stack backups).
    const backup = laborItems.map(li => ({
      groupId: li.groupId, subgroupId: li.subgroupId, subSubgroupId: li.subSubgroupId, itemId: li.item.id,
      unitCost: li.item.unitCost, markup: li.item.markup, unitPrice: li.item.unitPrice,
    }));

    for (const li of laborItems) {
      const oldPrice = li.item.unitPrice || 0;
      const unitCost = li.item.unitCost || 0;
      const newPrice = Math.round(oldPrice * (1 - pct / 100) * 100) / 100;
      const newMarkup = unitCost > 0 ? Math.round((newPrice / unitCost - 1) * 100) : li.item.markup;
      await laborItemRef(conCurrentJobId, li.groupId, li.subgroupId, li.subSubgroupId, li.item.id)
        .update({ unitPrice: newPrice, markup: newMarkup });
    }

    await coll('jobs').doc(conCurrentJobId).update({
      laborDiscount: { pct, appliedAt: new Date().toISOString(), backup }
    });
    const job = conJobs.find(j => j.id === conCurrentJobId);
    if (job) job.laborDiscount = { pct, appliedAt: new Date().toISOString(), backup };

    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
  } catch (e) {
    alert('Error applying discount: ' + e.message);
  }
}
window.applyLaborDiscount = applyLaborDiscount;

async function removeLaborDiscount() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const backup = job?.laborDiscount?.backup;
  if (!backup || !backup.length) {
    // No backup to restore from (e.g. loaded fresh from a doc missing
    // it) — just clear the flag rather than leave a broken "applied"
    // state with nothing to undo.
    await coll('jobs').doc(conCurrentJobId).update({ laborDiscount: firebase.firestore.FieldValue.delete() });
    if (job) delete job.laborDiscount;
    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
    return;
  }
  if (!confirm('Restore original labor pricing on ' + backup.length + ' line item' + (backup.length===1?'':'s') + '?')) return;

  try {
    for (const b of backup) {
      await laborItemRef(conCurrentJobId, b.groupId, b.subgroupId, b.subSubgroupId, b.itemId)
        .update({ unitCost: b.unitCost, markup: b.markup, unitPrice: b.unitPrice })
        .catch(() => {}); // item may have been deleted since — skip rather than fail the whole restore
    }
    await coll('jobs').doc(conCurrentJobId).update({ laborDiscount: firebase.firestore.FieldValue.delete() });
    if (job) delete job.laborDiscount;
    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
  } catch (e) {
    alert('Error removing discount: ' + e.message);
  }
}
window.removeLaborDiscount = removeLaborDiscount;

function renderFFDiscountControl(jobId) {
  const wrap = document.getElementById('ffDiscountWrap');
  if (!wrap) return;
  const job = conJobs.find(j => j.id === (jobId || conCurrentJobId));
  const discount = job?.laborDiscount;
  if (discount) {
    wrap.innerHTML = `<span class="small" style="color:#a3f2d2;font-weight:700">🎁 ${discount.pct}% F&amp;F discount applied</span>
      <button class="btn" onclick="removeLaborDiscount()" style="padding:6px 10px;font-size:.78rem">Remove Discount</button>`;
  } else {
    wrap.innerHTML = `<span class="small muted">🎁 F&amp;F Discount</span>
      <input id="ffDiscountPct" type="number" min="1" max="99" placeholder="%" style="width:56px;padding:3px 6px;font-size:.8rem" />
      <button class="btn" onclick="applyLaborDiscount()" style="padding:6px 10px;font-size:.78rem" title="Reduces every labor line's price by this %. Real labor cost stays the same -- only the customer price drops.">Apply to Labor</button>`;
  }
}

function updateEstimateSummary() {
  let totalCost = 0, totalPrice = 0, totalItems = 0;
  estGroups.forEach(g => {
    const items = getAllItemsInGroup(g);
    totalItems += items.length;
    const t = calcGroupTotals(items);
    totalCost += t.cost;
    totalPrice += t.price;
  });
  const profit = totalPrice - totalCost;
  const margin = totalPrice > 0 ? profit/totalPrice*100 : 0;
  const marginColor = margin >= 20 ? '#1dbb87' : margin >= 10 ? '#f59e0b' : '#ef5350';

  const setEl = (id, v, color) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = v;
    if (color) el.style.color = color;
  };
  setEl('estKpiCost', '$'+Math.round(totalCost).toLocaleString());
  setEl('estKpiPrice', '$'+Math.round(totalPrice).toLocaleString());
  setEl('estKpiProfit', '$'+Math.round(profit).toLocaleString(), profit>=0?'#1dbb87':'#ef5350');
  setEl('estKpiMargin', Math.round(margin)+'%', marginColor);
  setEl('estKpiItems', totalItems);

  // Sync estCost from the estimate. Do NOT overwrite contractValue —
  // the contract/approved price is set on the job and only moves via change orders.
  if (conCurrentJobId && conDb && totalItems > 0) {
    const rounded = Math.round(totalCost);
    coll('jobs').doc(conCurrentJobId).update({
      estCost: rounded, estCostSyncedAt: firebase.firestore.FieldValue.serverTimestamp()
    }).catch(()=>{});
    const job = conJobs.find(j => j.id === conCurrentJobId);
    if (job) { job.estCost = rounded; refreshJobFinancials(job); }
  }
}

