window.deleteSubSubgroup = deleteSubSubgroup;

// Clones a subgroup (all its line items, and any nested sub-subgroups
// with THEIR items too) into a new subgroup in the same group. Built
// for the exact case of "Bathroom 1" and "Bathroom 2" needing the same
// scope of work — duplicate once, then just rename and tweak the
// specifics instead of rebuilding line-by-line.
async function duplicateSubgroup(groupId, subId) {
  const group = estGroups.find(g => g.id === groupId);
  const sub = group?.subgroups?.find(s => s.id === subId);
  if (!sub) return;

  const newName = prompt('Name for the duplicate:', sub.name + ' (Copy)');
  if (!newName || !newName.trim()) return;

  try {
    const baseRef = coll('jobs').doc(conCurrentJobId).collection('estimateGroups').doc(groupId);
    const newSubRef = await baseRef.collection('subgroups').add({
      name: newName.trim(),
      order: group.subgroups.length,
      visibleToCustomer: sub.visibleToCustomer !== false,
      scopeNotes: sub.scopeNotes || '',
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    });
    const newSubId = newSubRef.id;

    // Copy this subgroup's own line items
    const itemFields = it => ({
      desc: it.desc || '', qty: it.qty || 1, unit: it.unit || 'ea',
      costType: it.costType || 'Labor', unitCost: it.unitCost || 0,
      markup: it.markup || 0, unitPrice: it.unitPrice || 0,
      notes: it.notes || '', phase: it.phase || '',
      order: it.order || 0, createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    });
    for (const it of (sub.items || [])) {
      await baseRef.collection('subgroups').doc(newSubId).collection('items').add(itemFields(it));
    }

    // Copy any nested sub-subgroups and their items too
    for (const ss of (sub.subgroups || [])) {
      const newSsRef = await baseRef.collection('subgroups').doc(newSubId)
        .collection('subgroups').add({
          name: ss.name, order: ss.order || 0,
          createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        });
      for (const it of (ss.items || [])) {
        await baseRef.collection('subgroups').doc(newSubId)
          .collection('subgroups').doc(newSsRef.id).collection('items').add(itemFields(it));
      }
    }

    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
  } catch (e) {
    alert('Error duplicating subgroup: ' + e.message);
  }
}
window.duplicateSubgroup = duplicateSubgroup;

async function deleteSubgroup(groupId, subId) {
  if (!confirm('Delete this subgroup and all its items?')) return;
  const ref = coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
    .doc(groupId).collection('subgroups').doc(subId);
  const group = estGroups.find(g => g.id === groupId);
  const sub = group?.subgroups?.find(s => s.id === subId);
  try {
    const snapshot = await snapshotSubtree(ref);
    await deleteSubtree(ref);
    if (group) group.subgroups = group.subgroups.filter(s => s.id !== subId);
    renderEstimateTree();
    updateEstimateSummary();
    _pendingUndo = { ref, snapshot };
    showUndoToast('Subgroup "' + (sub?.name || '') + '"');
  } catch (e) {
    alert('Error: ' + e.message);
  }
}

// ── ITEM MODAL ──
// ── Full-catalog search for the Add Item modal ──
// Smart Add's own search (wizardFilterItems) only searches within
// whatever ONE trade the wizard has drilled into — real problem
// reported: "caulk windows" IS in the catalog, just filed under
// Painting trade, invisible while working under Doors & Windows.
// This flattens the entire CATALOG_DATA (every trade) into one
// searchable index, built once and cached, so a search here finds an
// item regardless of which trade it's filed under.
let _flatCatalogIndex = null;
function getFlatCatalogIndex() {
  if (_flatCatalogIndex) return _flatCatalogIndex;
  _flatCatalogIndex = [];
  Object.keys(CATALOG_DATA).forEach(trade => {
    (CATALOG_DATA[trade] || []).forEach(item => {
      _flatCatalogIndex.push({
        name: item.name,
        trade: item.costCodeName || trade,
        materials: item.materials || null,
        labor: item.labor || null,
      });
    });
  });
  return _flatCatalogIndex;
}

// Same multi-word AND matching as wizardFilterItems, just across the
// flattened cross-trade index instead of one trade's item list.
function filterEstItemCatalogSearch() {
  const input = document.getElementById('estItemCatalogSearch');
  const resultsEl = document.getElementById('estItemCatalogResults');
  if (!input || !resultsEl) return;
  const q = input.value.toLowerCase().trim();
  if (!q) { resultsEl.innerHTML = ''; return; }
  const words = q.split(/\s+/).filter(Boolean);
  const index = getFlatCatalogIndex();
  const matches = index.filter(i => {
    const name = i.name.toLowerCase();
    return words.every(w => name.includes(w));
  }).slice(0, 15); // cap — a broad query like "labor" could match hundreds

  if (!matches.length) {
    resultsEl.innerHTML = '<div class="small muted" style="padding:8px;font-style:italic">No matches in the catalog.</div>';
    return;
  }
  resultsEl.innerHTML = matches.map((m, i) => {
    const hasMat = !!m.materials, hasLab = !!m.labor;
    const priceStr = hasMat ? '$' + Number(m.materials.unitCost||0).toFixed(2) : (hasLab ? '$' + Number(m.labor.unitCost||0).toFixed(2) : '');
    return `<div onclick="selectEstItemCatalogResult(${i})" class="est-catalog-result-row" style="padding:10px;border-radius:8px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:8px">
      <div style="min-width:0">
        <div style="font-size:.84rem;font-weight:600;color:#eaf0fb;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(m.name)}</div>
        <div style="font-size:.7rem;color:var(--amber)">${esc(m.trade)}${hasMat&&hasLab?' · materials + labor':hasLab?' · labor':' · materials'}</div>
      </div>
      <div style="font-size:.82rem;color:var(--muted);white-space:nowrap;flex-shrink:0">${priceStr}</div>
    </div>`;
  }).join('');
  // Stash the matches (not just indices) so the click handler doesn't
  // need to re-run the search/filter to know what was clicked.
  window._estItemCatalogMatches = matches;
}
window.filterEstItemCatalogSearch = filterEstItemCatalogSearch;

// Prefills the existing manual-entry fields from the chosen catalog
// entry rather than adding directly — keeps ONE save path (the
// existing Save Item button/validation), search is just a faster way
// to fill the form instead of typing everything by hand. Uses the
// materials side by default when both exist; if the item is
// labor-only (e.g. "Caulk Labor"), uses that instead. Doesn't
// silently drop the other side — flags it in a note so nothing about
// this catalog entry gets lost, just not auto-added as a second line.
function selectEstItemCatalogResult(i) {
  const m = (window._estItemCatalogMatches || [])[i];
  if (!m) return;
  const primary = m.materials || m.labor;
  const isLaborPrimary = !m.materials && !!m.labor;
  const setVal = (id, v) => { const el = document.getElementById(id); if (el) el.value = v; };
  setVal('estItemDesc', primary.desc || m.name);
  setVal('estItemUnit', primary.unit || 'ea');
  setVal('estItemUnitCost', primary.unitCost || '');
  document.getElementById('estItemCostType').value = isLaborPrimary ? 'Labor' : 'Materials';
  onEstItemCostTypeChange();

  const laborWrap = document.getElementById('estItemLaborLineWrap');
  const laborToggle = document.getElementById('estItemLaborLineToggle');
  const laborLabel = document.getElementById('estItemLaborLineLabel');
  if (m.materials && m.labor) {
    // This catalog item bundles a labor price inside the same object —
    // it is NOT a separate searchable entry, so re-searching for it
    // (e.g. "Labor - WM 231...") will never find anything. Stash it and
    // offer a checkbox to add it as a real second line item on Save.
    _pendingCatalogLaborLine = {
      desc: m.labor.desc || m.name,
      unit: m.labor.unit || 'hr',
      unitCost: m.labor.unitCost || 0
    };
    setVal('estItemNotes', 'From catalog: "' + m.name + '"');
    if (laborWrap && laborToggle && laborLabel) {
      laborLabel.textContent = '+ Also add labor line: "' + _pendingCatalogLaborLine.desc + '" — $' + Number(_pendingCatalogLaborLine.unitCost).toFixed(2) + '/' + _pendingCatalogLaborLine.unit;
      laborToggle.checked = true;
      laborWrap.style.display = 'flex';
    }
  } else {
    _pendingCatalogLaborLine = null;
    if (laborWrap) laborWrap.style.display = 'none';
  }

  document.getElementById('estItemCatalogSearch').value = '';
  document.getElementById('estItemCatalogResults').innerHTML = '';
  calcEstItemPreview();
}
window.selectEstItemCatalogResult = selectEstItemCatalogResult;

function openAddEstItemModal(itemId, groupId, subgroupId, subSubgroupId) {
  const catSearchEl = document.getElementById('estItemCatalogSearch');
  const catResultsEl = document.getElementById('estItemCatalogResults');
  if (catSearchEl) catSearchEl.value = '';
  if (catResultsEl) catResultsEl.innerHTML = '';
  // Reset the labor-line-from-catalog checkbox every time the modal is
  // (re)opened, so a leftover pick from a previous item never bleeds
  // into a new one (e.g. editing an existing item afterward).
  _pendingCatalogLaborLine = null;
  const laborWrapReset = document.getElementById('estItemLaborLineWrap');
  if (laborWrapReset) laborWrapReset.style.display = 'none';
  _editingEstItemId = itemId || null;
  _editingGroupId = groupId || null;
  _editingSubgroupId = subgroupId || null;
  _editingSubSubgroupId = subSubgroupId || null;

  const flatToggle = document.getElementById('estItemFlatRateToggle');
  if (flatToggle) flatToggle.checked = false;
  toggleEstItemFlatRate();

  // Find item if editing
  let item = null;
  if (itemId && groupId) {
    const group = estGroups.find(g => g.id === groupId);
    if (subgroupId) {
      const sub = group?.subgroups?.find(s => s.id === subgroupId);
      item = sub?.items?.find(it => it.id === itemId);
    } else {
      item = group?.directItems?.find(it => it.id === itemId);
    }
  }

  const setVal = (id, v) => { const el = document.getElementById(id); if(el) el.value = v||''; };

  // Draft-autosave: protects whatever's mid-typed in THIS specific
  // form from being lost to a crash, accidental tab close, phone lock,
  // etc. — separate from the per-item Firestore save on the Save Item
  // button, which already protects everything already clicked Save on.
  // Scoped per job + item (or 'new' for a brand-new item) so drafts
  // for different items/jobs never collide or leak into each other.
  _estItemDraftKey = 'jm_est_item_draft_' + conCurrentJobId + '_' + (itemId || 'new');
  let restoredDraft = false;
  try {
    const raw = localStorage.getItem(_estItemDraftKey);
    if (raw) {
      const draft = JSON.parse(raw);
      if (draft && draft.desc && confirm('You have an unsaved draft for this item ("' + draft.desc + '") — probably from a crash or accidental close. Restore it?')) {
        setVal('estItemDesc', draft.desc);
        setVal('estItemQty', draft.qty);
        setVal('estItemUnit', draft.unit);
        document.getElementById('estItemCostType').value = draft.costType || 'Labor';
        setVal('estItemUnitCost', draft.unitCost);
        setVal('estItemMarkup', draft.markup);
        setVal('estItemUnitPrice', draft.unitPrice);
        setVal('estItemPhase', draft.phase);
        setVal('estItemNotes', draft.notes);
        restoredDraft = true;
      } else {
        localStorage.removeItem(_estItemDraftKey);
      }
    }
  } catch(e) { console.warn('Draft restore check failed:', e); }

  document.getElementById('estItemModalTitle').textContent = item ? 'Edit Line Item' : 'Add Line Item';
  let markup = item?.markup !== undefined ? item.markup : getDefaultMarkupForCostType(item?.costType || 'Labor');
  if (!restoredDraft) {
    setVal('estItemDesc', item?.desc);
    setVal('estItemQty', item?.qty || 1);
    setVal('estItemUnit', item?.unit || 'ea');
    document.getElementById('estItemCostType').value = item?.costType || 'Labor';
    setVal('estItemUnitCost', item?.unitCost || '');
    setVal('estItemMarkup', markup);
    setVal('estItemNotes', item?.notes || '');
    setVal('estItemPhase', item?.phase || '');
  }

  // Only pre-fill Unit Price if it was manually overridden (differs from
  // cost×markup) — skipped entirely if a draft was restored above, since
  // draft.unitPrice (whatever the user had actually typed) was already
  // set directly and shouldn't be second-guessed by this calculation.
  if (!restoredDraft) {
    const calcedPrice = (item?.unitCost || 0) * (1 + markup/100);
    const storedPrice = item?.unitPrice || 0;
    const isManualOverride = storedPrice > 0 && Math.abs(storedPrice - calcedPrice) > 0.01;
    setVal('estItemUnitPrice', isManualOverride ? storedPrice : '');
  }

  // Populate group dropdown
  const groupSel = document.getElementById('estItemGroupSel');
  if (groupSel) {
    groupSel.innerHTML = '<option value="">— Select Group —</option>' +
      estGroups.map(g => '<option value="'+g.id+'"'+(g.id===groupId?' selected':'')+'>'+esc(g.name)+'</option>').join('') +
      '<option value="__new__">+ Create New Group…</option>';
    if (groupId) groupSel.value = groupId;
  }
  populateEstSubgroupDropdown(groupId, subgroupId);

  calcEstItemPreview();
  kOpen('addEstItemModal');
  setTimeout(() => document.getElementById('estItemDesc')?.focus(), 150);
}

function populateEstSubgroupDropdown(groupId, selectedSubId) {
  const subSel = document.getElementById('estItemSubgroupSel');
  if (!subSel) return;
  const group = estGroups.find(g => g.id === groupId);
  const subs = group?.subgroups || [];
  subSel.innerHTML = '<option value="">No subgroup</option>' +
    subs.map(s => '<option value="'+s.id+'"'+(s.id===selectedSubId?' selected':'')+'>'+esc(s.name)+'</option>').join('');
  if (selectedSubId) subSel.value = selectedSubId;
}

function onEstGroupChange() {
  const sel = document.getElementById('estItemGroupSel');
  const groupId = sel?.value;
  if (groupId === '__new__') {
    createGroupInlineFromItemModal();
    return;
  }
  _editingGroupId = groupId || null;
  populateEstSubgroupDropdown(groupId, null);
}

// Lets a brand-new estimate (zero groups yet) still add a manual line
// item without dead-ending on a required Group dropdown with nothing
// in it — reported by Jason: Smart Add's Custom/One-off Item option
// opens this same modal, and on a fresh estimate estGroups is
// legitimately empty, so there was no way to even create a group from
// here. Mirrors addGroup()'s Firestore write but also re-populates and
// re-selects in this modal's own dropdown instead of just updating the
// (currently hidden) main estimate tree.
function createGroupInlineFromItemModal() {
  const name = prompt('New group name (e.g. "Half Bath"):');
  const sel = document.getElementById('estItemGroupSel');
  if (!name || !name.trim()) { if (sel) sel.value = ''; return; }
  if (!conDb || !conCurrentJobId) { if (sel) sel.value = ''; return; }
  const trimmed = name.trim();
  const order = estGroups.length;
  coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
    name: trimmed, order, createdAt: firebase.firestore.FieldValue.serverTimestamp()
  }).then(ref => {
    const newGroup = { id: ref.id, name: trimmed, order, subgroups: [], directItems: [] };
    estGroups.push(newGroup);
    if (sel) {
      sel.innerHTML = '<option value="">— Select Group —</option>' +
        estGroups.map(g => '<option value="'+g.id+'"'+(g.id===ref.id?' selected':'')+'>'+esc(g.name)+'</option>').join('') +
        '<option value="__new__">+ Create New Group…</option>';
      sel.value = ref.id;
    }
    _editingGroupId = ref.id;
    populateEstSubgroupDropdown(ref.id, null);
  }).catch(e => { alert('Error creating group: ' + e.message); if (sel) sel.value = ''; });
}

function onEstSubgroupChange() {
  _editingSubgroupId = document.getElementById('estItemSubgroupSel')?.value || null;
}

// Configurable Supplier Cost Adjustment: company-wide default markup %,
// set in Settings > Supplier Cost Adjustment (defaultMaterialsMarkup /
// defaultLaborMarkup on companyProfile). Originally hardcoded per Jason's
// QuickBooks/JobTread cost-types export (Labor 15%, Materials &
// Subcontractor 25%, Other & Permit 15%) — now those numbers are just the
// fallback defaults if no company setting has been saved yet.
// Cost-type bucketing: Materials & Subcontractor use the materials rate;
// Labor, Permits & Fees, Equipment, Overhead, and Other all use the labor
// rate (no separately-confirmed real rate exists for Equipment/Overhead).
const MATERIALS_RATE_COST_TYPES = new Set(['Materials', 'Subcontractor']);
function getDefaultMarkupForCostType(costType) {
  const materialsRate = companyProfile.defaultMaterialsMarkup !== undefined ? companyProfile.defaultMaterialsMarkup : 25;
  const laborRate = companyProfile.defaultLaborMarkup !== undefined ? companyProfile.defaultLaborMarkup : 15;
  return MATERIALS_RATE_COST_TYPES.has(costType) ? materialsRate : laborRate;
}
function onEstItemCostTypeChange() {
  const costType = document.getElementById('estItemCostType')?.value;
  const markupEl = document.getElementById('estItemMarkup');
  if (markupEl) {
    markupEl.value = getDefaultMarkupForCostType(costType);
  }
  calcEstItemPreview();
}
window.onEstItemCostTypeChange = onEstItemCostTypeChange;

function clearUnitPriceOverride() {
  // When cost or markup changes, clear any manual Unit Price override
  // so the field recalculates from unitCost × markup instead of staying
  // stuck — EXCEPT in flat-rate mode, where cost and price are both
  // independently known (e.g. Jason quoted a flat $1,600 for labor he
  // costs out separately) and typing one shouldn't wipe the other.
  if (document.getElementById('estItemFlatRateToggle')?.checked) return;
  const priceEl = document.getElementById('estItemUnitPrice');
  if (priceEl) priceEl.value = '';
}
window.clearUnitPriceOverride = clearUnitPriceOverride;

function toggleEstItemFlatRate() {
  const on = document.getElementById('estItemFlatRateToggle')?.checked;
  const markupWrap = document.getElementById('estItemMarkupWrap');
  const priceLabel = document.getElementById('estItemUnitPriceLabel');
  const priceInput = document.getElementById('estItemUnitPrice');
  if (markupWrap) markupWrap.style.display = on ? 'none' : '';
  if (priceLabel) {
    priceLabel.innerHTML = on
      ? 'Unit Price ($) <span style="color:var(--muted);font-weight:400">(your negotiated price)</span>'
      : 'Unit Price ($) <span style="color:var(--muted);font-weight:400">(optional override)</span>';
  }
  if (priceInput) priceInput.placeholder = on ? 'e.g. 1600.00' : 'Auto from markup';
  calcEstItemPreview();
}
window.toggleEstItemFlatRate = toggleEstItemFlatRate;

function calcEstItemPreview() {
  const qty = parseFloat(document.getElementById('estItemQty')?.value) || 1;
  const unitCost = parseFloat(document.getElementById('estItemUnitCost')?.value) || 0;
  const markup = parseFloat(document.getElementById('estItemMarkup')?.value) || 0;
  const manualPrice = parseFloat(document.getElementById('estItemUnitPrice')?.value);

  const unitPrice = isNaN(manualPrice) || document.getElementById('estItemUnitPrice')?.value === ''
    ? unitCost * (1 + markup/100)
    : manualPrice;

  const extCost = qty * unitCost;
  const extPrice = qty * unitPrice;
  const profit = extPrice - extCost;
  const margin = extPrice > 0 ? profit/extPrice*100 : 0;

  const setEl = (id, v) => { const el = document.getElementById(id); if(el) el.textContent = v; };
  setEl('estPreviewExtCost', '$' + extCost.toFixed(2));
  setEl('estPreviewExtPrice', '$' + extPrice.toFixed(2));
  setEl('estPreviewProfit', '$' + profit.toFixed(2));
  setEl('estPreviewMargin', margin.toFixed(1) + '%');

  // Write calculated price into the Unit Price field as placeholder
  // so user can see what it will be, and can override if needed
  const priceEl = document.getElementById('estItemUnitPrice');
  if (priceEl && priceEl.value === '') {
    priceEl.placeholder = '$' + unitPrice.toFixed(2);
  }
}

function saveEstItem() {
  const desc = document.getElementById('estItemDesc')?.value.trim();
  if (!desc) { alert('Description is required.'); return; }

  // Read group/subgroup from dropdowns
  const groupIdFromSel = document.getElementById('estItemGroupSel')?.value;
  const subgroupIdFromSel = document.getElementById('estItemSubgroupSel')?.value || null;
  if (!groupIdFromSel) { alert('Please select a group.'); return; }
  _editingGroupId = groupIdFromSel;
  _editingSubgroupId = subgroupIdFromSel;

  const qty = parseFloat(document.getElementById('estItemQty')?.value) || 1;
  const unitCost = parseFloat(document.getElementById('estItemUnitCost')?.value) || 0;
  const markup = parseFloat(document.getElementById('estItemMarkup')?.value) || 0;
  const manualPrice = parseFloat(document.getElementById('estItemUnitPrice')?.value);
  const unitPrice = manualPrice || unitCost * (1 + markup/100);

  const data = {
    desc,
    qty,
    unit: document.getElementById('estItemUnit')?.value || 'ea',
    costType: document.getElementById('estItemCostType')?.value || 'Labor',
    unitCost,
    markup,
    unitPrice,
    phase: document.getElementById('estItemPhase')?.value || '',
    notes: document.getElementById('estItemNotes')?.value.trim() || '',
    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
  };

  const groupId = _editingGroupId;
  const subgroupId = _editingSubgroupId;
  const subSubgroupId = _editingSubSubgroupId;
  const jobRef = coll('jobs').doc(conCurrentJobId);
  let colRef;

  if (subSubgroupId && subgroupId) {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId).collection('subgroups').doc(subSubgroupId).collection('items');
  } else if (subgroupId) {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId).collection('items');
  } else {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('items');
  }

  const promise = _editingEstItemId
    ? colRef.doc(_editingEstItemId).update(data)
    : colRef.add({ ...data, order: 0, createdAt: firebase.firestore.FieldValue.serverTimestamp() });

  // If this item was picked from a catalog entry that bundles both a
  // materials AND a labor price, and the "also add labor line"
  // checkbox is checked, write the labor side as its own second line
  // item in the same group/subgroup — using the exact catalog labor
  // price, not re-derived from anything on this form.
  const laborToggle = document.getElementById('estItemLaborLineToggle');
  const laborWrap = document.getElementById('estItemLaborLineWrap');
  const shouldAddLaborLine = laborWrap && laborWrap.style.display !== 'none' && laborToggle && laborToggle.checked && _pendingCatalogLaborLine && !_editingEstItemId;
  const laborLineData = shouldAddLaborLine ? { ..._pendingCatalogLaborLine } : null;

  promise.then(() => {
    if (laborLineData) {
      const laborMarkup = getDefaultMarkupForCostType('Labor');
      return colRef.add({
        desc: laborLineData.desc,
        qty: 1,
        unit: laborLineData.unit,
        costType: 'Labor',
        unitCost: laborLineData.unitCost,
        markup: laborMarkup,
        unitPrice: laborLineData.unitCost * (1 + laborMarkup / 100),
        phase: data.phase,
        notes: 'From catalog: labor line for "' + desc + '"',
        order: 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    }
  }).then(() => {
    _pendingCatalogLaborLine = null;
    clearEstItemDraft();
    kClose('addEstItemModal');
    loadEstimate(conCurrentJobId);
  }).catch(e => alert('Error: ' + e.message));
}

function deleteEstItem(itemId, groupId, subgroupId, subSubgroupId) {
  if (!confirm('Delete this line item?')) return;
  const jobRef = coll('jobs').doc(conCurrentJobId);
  let colRef;
  if (subSubgroupId && subgroupId) {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId).collection('subgroups').doc(subSubgroupId).collection('items');
  } else if (subgroupId) {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('subgroups').doc(subgroupId).collection('items');
  } else {
    colRef = jobRef.collection('estimateGroups').doc(groupId).collection('items');
  }
  const ref = colRef.doc(itemId);
  ref.get().then(doc => {
    const itemData = doc.exists ? doc.data() : null;
    return ref.delete().then(() => {
      loadEstimate(conCurrentJobId);
      if (itemData) {
        _pendingUndo = { ref, snapshot: { id: itemId, data: itemData, items: [], subgroups: [] } };
        showUndoToast('Line item "' + (itemData.desc || '') + '"');
      }
    });
  }).catch(e => alert('Error: ' + e.message));
}

function importFromCatalogModal() {
  if (!conCatalogItems?.length) { alert('No catalog items yet. Add items to the Cost Catalog first.'); return; }
  if (!estGroups.length) { alert('Add a group first before importing from catalog.'); return; }

  const groupId = estGroups.length === 1 ? estGroups[0].id : null;
  if (!groupId) {
    const names = estGroups.map((g,i) => (i+1)+'. '+g.name).join('\n');
    const choice = prompt('Import to which group? ' + names + ' -- Enter number:');
    const idx = parseInt(choice) - 1;
    if (isNaN(idx) || idx < 0 || idx >= estGroups.length) return;
    const selectedGroupId = estGroups[idx].id;
    showCatalogPicker(selectedGroupId);
  } else {
    showCatalogPicker(groupId);
  }
}

function showCatalogPicker(groupId) {
  const items = conCatalogItems || [];
  const cats = [...new Set(items.map(i => i.category||'Other'))].sort();
  const choice = prompt('Select category: ' + cats.map((c,i) => (i+1)+'. '+c).join(', ') + ' -- Enter number:');



  if (!choice) return;
  const idx = parseInt(choice) - 1;
  const cat = cats[idx];
  if (!cat) return;

  const catItems = items.filter(i => (i.category||'Other') === cat);
  catItems.forEach((item, i) => {
    const jobRef = coll('jobs').doc(conCurrentJobId);
    const costType = item.category || 'Materials';
    const markup = item.markup !== undefined && item.markup !== null && item.markup !== ''
      ? item.markup
      : getDefaultMarkupForCostType(costType);
    const unitCost = item.cost || 0;
    jobRef.collection('estimateGroups').doc(groupId).collection('items').add({
      desc: item.description || item.name || '',
      qty: 1,
      unit: item.unit || 'ea',
      costType,
      unitCost,
      markup,
      unitPrice: item.sellPrice || unitCost * (1 + markup / 100),
      order: i,
      notes: '',
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
  });

  setTimeout(() => loadEstimate(conCurrentJobId), 500);
  alert(`Imported ${catItems.length} items from ${cat}.`);
}

// ── PRINT ESTIMATE ──
// ── PRINT PROPOSAL (Customer-facing — totals only, no itemized costs, no scope notes) ──
// Static legal boilerplate — not sourced from any specific document.
// Original draft language; flagged for attorney review before being
// treated as binding on real customers.
const TERMS_AND_CONDITIONS = [
  ['Scope of Work &amp; Pricing', `This Proposal reflects the scope of work and pricing based on site conditions and information available at the time of preparation. All pricing is based on current material and labor costs. Work not expressly described in this Proposal is excluded. If unforeseen conditions are discovered during the course of work — including but not limited to hidden damage, code deficiencies, hazardous materials, or conditions not visible during initial assessment — Contractor will stop affected work, notify Customer promptly, and issue a written Change Order before proceeding. Customer acknowledges that final costs may differ from this Proposal if site conditions differ materially from those observed.`],
  ['Customer Responsibilities', `Customer is responsible for providing accurate site access, disclosing all known conditions affecting the work, securing any required HOA approvals, and ensuring that the work area is clear and accessible on scheduled work days. Delays caused by Customer's failure to meet these responsibilities may result in rescheduling fees or revised pricing. Customer is responsible for protecting or removing personal property from work areas prior to commencement. Contractor is not liable for damage to items not disclosed or not removed.`],
  ['Payment Terms', `Payment is due according to the Payment Schedule outlined above. A deposit is required before materials are ordered or work is scheduled. Progress payments are due upon completion of each designated phase. Final payment is due upon substantial completion, prior to final walkthrough. Invoices unpaid beyond their due date accrue interest at 1.5% per month (18% annually). Contractor reserves the right to suspend work without penalty if any payment is more than seven (7) days past due. Customer remains liable for all work completed to the point of suspension, plus reasonable costs incurred due to the stoppage.`],
  ['Warranty', `Contractor warrants all labor performed under this Proposal against defects in workmanship for a period of one (1) year from the date of substantial completion, provided the work is used and maintained as intended. This warranty does not cover damage resulting from misuse, neglect, acts of third parties, or natural events. Manufacturer warranties on materials and fixtures are passed through to Customer and are governed by each manufacturer's terms. Contractor makes no warranty, express or implied, beyond what is stated herein.`],
  ['Alterations &amp; Change Orders', `Any changes, additions, or deletions to the scope of work must be documented in a written Change Order signed by both parties before the work begins. Verbal agreements are not binding. Change Orders will reflect any adjustment to price, materials, and/or schedule. Contractor is not obligated to perform out-of-scope work without an executed Change Order, and Customer is not obligated to pay for unauthorized work. Emergency conditions requiring immediate action will be documented and presented to Customer at the earliest opportunity.`],
  ['Delay &amp; Force Majeure', `Contractor will make reasonable efforts to meet any estimated schedule. Contractor is not liable for delays caused by weather, material shortages, supply chain disruptions, labor unavailability, Customer-requested changes, permit delays, or any other condition beyond Contractor's reasonable control. If a delay extends the project beyond the original estimated completion date through no fault of Contractor, Contractor reserves the right to re-price materials affected by market changes.`],
  ['Dispute Resolution', `In the event of a dispute, the parties agree to first attempt resolution through good-faith negotiation. If unresolved within thirty (30) days, either party may pursue mediation before initiating legal proceedings. The prevailing party in any legal action arising from this agreement shall be entitled to recover reasonable attorney's fees and costs. This agreement shall be governed by the laws of the State of Missouri.`],
  ['Acceptance of Proposal', `This Proposal is not a binding contract until signed by the Customer below. By signing, Customer accepts the full scope of work, pricing, payment schedule, and all Terms &amp; Conditions stated herein. Customer certifies they have read and understood this Proposal in its entirety and have had the opportunity to ask questions before signing. Electronic signatures are accepted and carry the same legal weight as physical signatures.`],
  ['Proposal Validity', `This Proposal is valid for thirty (30) days from the date shown above. Contractor reserves the right to revise pricing if this Proposal is not accepted within that window, if material costs change significantly, or if the scope of work is altered after signing. Scheduling is subject to availability at the time of signed acceptance.`]
];

// Gathers everything the Proposal print needs into a plain, serializable
// data object — no HTML, just structured facts (room/category/price/notes,
// grand total, payment schedule). This is what gets frozen into a
// versioned proposal snapshot in Firestore, AND what renderProposalDocumentHtml
// turns into the printable page. Keeping these separate means a stored
// snapshot can be reprinted byte-for-byte later even if the live estimate
// has since changed.
function computeProposalData(job, itemized) {
  let grandTotal = 0;
  const rooms = [];

  estGroups.forEach(group => {
    const allItems = getAllItemsInGroup(group);
    const totals = calcGroupTotals(allItems);
    if (totals.price <= 0) return;
    // Price always counts toward the total, whether or not this scope is
    // shown to the customer — hiding a room/category only hides its
    // description, it doesn't mean the work (and its cost) isn't happening.
    grandTotal += totals.price;
    if (group.visibleToCustomer === false) return;

    const catBlocks = (group.subgroups || []).map(sub => {
      if (sub.visibleToCustomer === false) return null;
      const st = calcGroupTotals(sub.items || []);
      // Include subgroups that have scope notes even if they have no items/price
      // — these are description-only room sections for the proposal and punch list
      if (st.price <= 0 && !sub.scopeNotes) return null;
      // Individual line items inside the subgroup, shown indented beneath the
      // subgroup name so the customer can see what the price actually covers.
      // Prices stay off these lines unless the Itemized toggle is on.
      const subItems = (sub.items || []).map(item => {
        if (item.visibleToCustomer === false) return null;
        const price = (item.qty || 1) * (item.unitPrice || item.unitCost || 0);
        if (price <= 0) return null;
        return { label: itemDescriptionText(item.desc || item.name), price, notes: item.notes || '' };
      }).filter(Boolean);

      return {
        label: proposalSafeLabel(sub),
        price: st.price,
        items: subItems,
        scopeNotes: sub.scopeNotes || '',
        pendingBid: !!sub.pendingBid,
        pendingBidNote: sub.pendingBidNote || '',
        descriptionOnly: st.price <= 0
      };
    }).filter(Boolean);

    const directBlocks = (group.directItems || []).map(item => {
      if (item.visibleToCustomer === false) return null;
      const price = (item.qty || 1) * (item.unitPrice || item.unitCost || 0);
      if (price <= 0) return null;
      const label = itemDescriptionText(item.desc);
      return { label, price, notes: item.notes || '' };
    }).filter(Boolean);

    if (!catBlocks.length && !directBlocks.length) return;
    // Only skip the group if it has no pricing AND no scope notes at all
    const hasContent = catBlocks.some(c => c.price > 0 || c.scopeNotes) || directBlocks.length;
    if (!hasContent) return;
    rooms.push({ name: group.name, catBlocks, directBlocks });
  });

  return {
    itemized: !!itemized,
    grandTotal,
    rooms,
    jobDescription: job?.notes || '',
    paymentSchedule: job?.paymentSchedule || null
  };
}

// Turns a computeProposalData() result into the full printable HTML page.
// Used both for a fresh live print and for reprinting a frozen historical
// version — same renderer, different data source.
function renderProposalDocumentHtml(data, job, co, autoPrint) {
  const itemized = data.itemized;

  const roomSections = data.rooms.map(room => {
    const catHtml = room.catBlocks.map(c => {
      const priceHtml = (itemized && !c.descriptionOnly) ? `<span style="float:right;font-weight:700;color:#1f2937">$${c.price.toFixed(2)}</span>` : '';
      const bidCaveat = c.pendingBid
        ? `<div class="cat-bid-caveat">⚠ ${esc(c.pendingBidNote || 'Pricing for this item is preliminary and may be adjusted once final vendor bids are in.')}</div>`
        : '';
      const itemsHtml = (itemized && (c.items || []).length)
        ? `<div class="cat-items">${c.items.map(it => {
            const itPrice = `<span style="float:right;font-weight:600;color:#374151">$${it.price.toFixed(2)}</span>`;
            return `<div class="cat-item">
              <div class="cat-item-name">${esc(it.label)}${itPrice}</div>
              ${it.notes ? `<div class="cat-item-note">${esc(it.notes)}</div>` : ''}
            </div>`;
          }).join('')}</div>`
        : '';
      return `<div class="cat-block">
        <div class="cat-name">${esc(c.label)}${priceHtml}</div>
        ${c.scopeNotes ? `<div class="cat-scope">${esc(c.scopeNotes)}</div>` : ''}
        ${itemsHtml}
        ${bidCaveat}
      </div>`;
    }).join('');
    const directHtml = room.directBlocks.map(d => {
      const priceHtml = itemized ? `<span style="float:right;font-weight:700;color:#1f2937">$${d.price.toFixed(2)}</span>` : '';
      return `<div class="cat-block">
        <div class="cat-name">${esc(d.label)}${priceHtml}</div>
        ${d.notes ? `<div class="cat-scope">${esc(d.notes)}</div>` : ''}
      </div>`;
    }).join('');
    return `<div class="room-section">
      <div class="room-heading">${esc(room.name)}</div>
      ${catHtml}${directHtml}
    </div>`;
  }).join('');

  const termsHtml = `
  <div class="terms-block">
    <div class="payment-heading">Terms &amp; Conditions</div>
    ${TERMS_AND_CONDITIONS.map(([title, text]) => `
      <div class="term-item">
        <div class="term-title">${title}</div>
        <div class="term-text">${text}</div>
      </div>`).join('')}
  </div>`;

  const paymentRows = getPaymentScheduleRows(data.paymentSchedule, data.grandTotal);
  const paymentTableHtml = paymentRows.length ? `
  <div class="payment-schedule">
    <div class="payment-heading">Payment Schedule</div>
    <table class="payment-table">
      <thead><tr><th>Stage</th><th style="text-align:center">%</th><th style="text-align:right">Amount</th></tr></thead>
      <tbody>
        ${paymentRows.map(r => `<tr>
          <td>${esc(r.label)}</td>
          <td style="text-align:center">${r.pct}%</td>
          <td style="text-align:right">$${r.amount.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</td>
        </tr>`).join('')}
      </tbody>
    </table>
  </div>` : '';

  return `<!DOCTYPE html><html><head><title>Proposal — ${esc(job?.name||'')}</title>
  <style>
    * { box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; max-width: 820px; margin: 0 auto; padding: 48px 40px; color: #1f2937; line-height: 1.5; }
    .header { display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 24px; margin-bottom: 8px; border-bottom: 4px solid #d97706; }
    .co-name { font-size: 1.25rem; font-weight: 800; color: #111827; }
    .co-contact { color: #6b7280; font-size: .82rem; margin-top: 2px; }
    .doc-title { font-size: 1.7rem; font-weight: 800; color: #d97706; letter-spacing: .03em; text-align: right; }
    .doc-meta { text-align: right; font-size: .85rem; color: #6b7280; margin-top: 4px; }
    .prepared-for { margin: 28px 0 32px; padding: 16px 20px; background: #f9fafb; border-radius: 10px; border: 1px solid #e5e7eb; }
    .prepared-for .label { font-size: .7rem; text-transform: uppercase; letter-spacing: .08em; color: #9ca3af; font-weight: 700; margin-bottom: 4px; }
    .prepared-for .name { font-size: 1.05rem; font-weight: 700; color: #111827; }
    .intro { color: #4b5563; font-size: .92rem; margin-bottom: 32px; }
    .room-section { margin-bottom: 30px; page-break-inside: avoid; }
    .room-heading { font-size: 1.15rem; font-weight: 800; color: #fff; background: #1f2937; padding: 10px 16px; border-radius: 8px 8px 0 0; }
    .cat-block { padding: 14px 16px; border: 1px solid #e5e7eb; border-top: none; }
    .cat-block:last-child { border-radius: 0 0 8px 8px; }
    .cat-name { font-weight: 700; font-size: .98rem; color: #111827; overflow: hidden; }
    .cat-scope { color: #4b5563; font-size: .88rem; margin-top: 6px; line-height: 1.55; white-space: pre-line; }
    .cat-items { margin-top: 8px; padding-left: 14px; border-left: 2px solid #e5e7eb; }
    .cat-item { padding: 3px 0; break-inside: avoid; page-break-inside: avoid; }
    .cat-item-name { color: #374151; font-size: .9rem; font-weight: 500; overflow: hidden; }
    .cat-item-note { color: #6b7280; font-size: .82rem; margin-top: 2px; line-height: 1.5; white-space: pre-line; }
    .cat-bid-caveat { color: #92400e; background: #fffbeb; border: 1px solid #fde68a; border-radius: 6px; padding: 6px 10px; font-size: .82rem; margin-top: 8px; line-height: 1.5; }
    .total-box { margin-top: 36px; padding: 20px 24px; background: #1f2937; color: #fff; border-radius: 10px; display: flex; justify-content: space-between; align-items: center; }
    .total-box .label { font-size: 1rem; font-weight: 700; letter-spacing: .04em; }
    .total-box .amount { font-size: 1.6rem; font-weight: 800; color: #fbbf24; }
    .payment-schedule { margin-top: 28px; page-break-inside: avoid; }
    .payment-heading { font-size: .95rem; font-weight: 800; color: #111827; margin-bottom: 8px; text-transform: uppercase; letter-spacing: .04em; }
    .payment-table { width: 100%; border-collapse: collapse; font-size: .88rem; }
    .payment-table th { text-align: left; background: #f3f4f6; padding: 8px 12px; font-weight: 700; color: #4b5563; border-bottom: 2px solid #e5e7eb; }
    .payment-table td { padding: 8px 12px; border-bottom: 1px solid #e5e7eb; color: #1f2937; }
    .terms-block { margin-top: 32px; padding-top: 20px; border-top: 1px solid #e5e7eb; page-break-inside: avoid; }
    .term-item { margin-bottom: 12px; }
    .term-title { font-weight: 700; font-size: .82rem; color: #374151; margin-bottom: 2px; }
    .term-text { font-size: .76rem; color: #6b7280; line-height: 1.55; }
    .signatures { display: flex; gap: 40px; margin-top: 56px; }
    .sig-block { flex: 1; }
    .sig-line { border-bottom: 1.5px solid #9ca3af; height: 42px; margin-bottom: 6px; }
    .sig-label { font-size: .8rem; color: #6b7280; }
    .footer { margin-top: 48px; padding-top: 18px; border-top: 1px solid #e5e7eb; color: #9ca3af; font-size: .72rem; text-align: center; line-height: 1.6; }
    @media print { body { padding: 20px 30px; } }
  </style></head><body>

  <div class="header">
    <div>
      ${co.logo?`<img src="${co.logo}" style="height:52px;object-fit:contain;margin-bottom:8px"><br>`:''}
      <div class="co-name">${esc(co.companyName||'')}</div>
      <div class="co-contact">${esc(co.phone||'')} · ${esc(co.email||'')}${co.address?' · '+esc(co.address):''}</div>
      ${co.license?`<div class="co-contact">License #${esc(co.license)}</div>`:''}
    </div>
    <div>
      <div class="doc-title">${itemized ? 'ITEMIZED PROPOSAL' : 'PROPOSAL'}</div>
      <div class="doc-meta">${esc(job?.jobNumber||'')}</div>
      <div class="doc-meta">${new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</div>
    </div>
  </div>

  <div class="prepared-for">
    <div class="label">Prepared For</div>
    <div class="name">${esc(job?.client||'')}</div>
    <div class="co-contact">${esc(job?.address||'')}</div>
  </div>

  ${data.jobDescription ? `<div class="intro" style="white-space:pre-line">${esc(data.jobDescription)}</div>` : `<div class="intro">Thank you for the opportunity to work on your project. The following outlines the full scope of work${itemized ? ' with itemized pricing by category' : ''}, organized by category.</div>`}

  ${roomSections}

  <div class="total-box">
    <div class="label">TOTAL PROJECT INVESTMENT</div>
    <div class="amount">$${data.grandTotal.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</div>
  </div>

  ${paymentTableHtml}

  ${termsHtml}

  <div class="signatures">
    <div class="sig-block">
      <div class="sig-line"></div>
      <div class="sig-label">Customer Signature &nbsp;·&nbsp; Date</div>
    </div>
    <div class="sig-block">
      <div class="sig-line"></div>
      <div class="sig-label">${esc(co.companyName||'Company')} Representative &nbsp;·&nbsp; Date</div>
    </div>
  </div>

  <div class="footer">
    ${esc(co.companyName||'')} · ${esc(co.phone||'')} · ${esc(co.email||'')}${co.license?' · License #'+esc(co.license):''}
  </div>

  ${autoPrint !== false ? '<script>window.onload = () => setTimeout(() => window.print(), 250);<\/script>' : ''}</body></html>`;
}

// ── Proposal version history (Draft → Pending → Approved/Declined) ──
// Each print snapshots computeProposalData() into jobs/{jobId}/proposals/{id}.
// While the latest version is still 'draft', reprinting updates that same
// doc in place (no version-spam from routine reprints). Once a version is
// marked Sent (locked to 'pending' or beyond), the NEXT print automatically
// starts a new version — this is how "1250-1", "1250-2" happens naturally.
let conProposals = [];

function loadProposals(jobId) {
  if (!conDb || !jobId) { conProposals = []; renderProposalHistory(); return; }
  coll('jobs').doc(jobId).collection('proposals').orderBy('version', 'desc').get()
    .then(snap => {
      conProposals = [];
      snap.forEach(d => conProposals.push({ id: d.id, ...d.data() }));
      renderProposalHistory();
      // Auto-backfill contractValue from approved proposal if job doesn't have one yet
      const approvedProp = conProposals.find(p => p.status === 'approved');
      if (approvedProp?.snapshot?.grandTotal) {
        const job = conJobs.find(j => j.id === jobId);
        if (job && !job.contractValue) {
          coll('jobs').doc(jobId).update({
            contractValue: approvedProp.snapshot.grandTotal,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
          }).then(() => {
            job.contractValue = approvedProp.snapshot.grandTotal;
            conRenderStats();
          }).catch(() => {});
        }
      }
      // Catches customer signatures made through the anonymous portal
      if (conProposals[0] && conProposals[0].status === 'approved') {
        maybeAdvanceJobStatusForApproval(jobId);
      }
    })
    .catch(e => console.error('Proposal history load error:', e));
}

// Auto-advances a job's pipeline status to "To Be Scheduled" the first
// time one of its proposals is approved — but never regresses a job
// that's already further along the pipeline. Function name kept as-is
// since callers reference it directly; internally now targets To Be
// Scheduled since Approved was removed as a distinct pipeline stage.
// Triggered from the internal "Mark Approved" action (immediate) and from
// loadProposals (catches portal-driven customer signatures).
function maybeAdvanceJobStatusForApproval(jobId) {
  const job = conJobs.find(j => j.id === jobId);
  if (!job) return;
  const TARGET_NAME = 'To Be Scheduled';
  const currentIdx = CON_JOB_STATUSES.indexOf(job.status);
  const targetIdx = CON_JOB_STATUSES.indexOf(TARGET_NAME);
  if (currentIdx === -1 || targetIdx === -1 || currentIdx >= targetIdx) return;

  const prevStatus = job.status;
  coll('jobs').doc(jobId).update({
    status: TARGET_NAME,
    statusDate: new Date().toISOString().split('T')[0],
    updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy: conCurrentUser ? conCurrentUser.email : 'unknown'
  }).then(() => {
    job.status = TARGET_NAME;
    logStatusChangeActivity(jobId, prevStatus, TARGET_NAME, 'Auto-advanced: Proposal was approved/signed');
    if (typeof conRenderBoard === 'function') conRenderBoard();
    if (typeof renderJobsBoard === 'function') renderJobsBoard();
  }).catch(e => console.error('Auto-advance job status error:', e));
}
window.maybeAdvanceJobStatusForApproval = maybeAdvanceJobStatusForApproval;

// Generic version of the same forward-only advance logic above, for any
// target status — used by the 'emailing a proposal moves the job to
// Submitted' automation. Never regresses a job that's already further
// along (e.g. re-sending a revised proposal on an already-Approved job
// won't knock it back down to Submitted).
function advanceJobStatusIfEarlier(jobId, targetStatus, reason) {
  const job = conJobs.find(j => j.id === jobId);
  if (!job) return;
  const curIdx = CON_JOB_STATUSES.indexOf(job.status);
  const targetIdx = CON_JOB_STATUSES.indexOf(targetStatus);
  if (targetIdx === -1 || (curIdx !== -1 && curIdx >= targetIdx)) return;

  const prevStatus = job.status;
  coll('jobs').doc(jobId).update({
    status: targetStatus,
    statusDate: new Date().toISOString().split('T')[0],
    updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
    updatedBy: conCurrentUser ? conCurrentUser.email : 'unknown'
  }).then(() => {
    job.status = targetStatus;
    logStatusChangeActivity(jobId, prevStatus, targetStatus, reason || `Auto-advanced to ${targetStatus}`);
    if (typeof conRenderBoard === 'function') conRenderBoard();
    if (typeof renderJobsBoard === 'function') renderJobsBoard();
  }).catch(e => console.error('Auto-advance job status error:', e));
}
window.advanceJobStatusIfEarlier = advanceJobStatusIfEarlier;

function saveProposalSnapshot(jobId, data) {
  if (!conDb || !jobId) return;
  const latest = conProposals[0];
  if (latest && latest.status === 'draft') {
    coll('jobs').doc(jobId).collection('proposals').doc(latest.id).update({
      snapshot: data,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }).then(() => loadProposals(jobId)).catch(e => console.error('Proposal snapshot update error:', e));
  } else {
    const version = latest ? (latest.version || 1) + 1 : 1;
    coll('jobs').doc(jobId).collection('proposals').add({
      version, status: 'draft', snapshot: data,
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      createdBy: conCurrentUser ? conCurrentUser.email : 'unknown'
    }).then(() => loadProposals(jobId)).catch(e => console.error('Proposal snapshot create error:', e));
  }
}

// Manual status transitions until real e-signature capture wires these
// automatically. 'pending' = marked Sent (locks the snapshot); 'approved'/
// 'declined' = customer response, recorded manually for now.
function markProposalStatus(proposalId, newStatus) {
  if (!conDb || !conCurrentJobId) return;
  const extra = {};
  if (newStatus === 'pending') extra.sentAt = firebase.firestore.FieldValue.serverTimestamp();
  if (newStatus === 'approved' || newStatus === 'declined') extra.respondedAt = firebase.firestore.FieldValue.serverTimestamp();
  const jobIdForThisCall = conCurrentJobId;
  coll('jobs').doc(conCurrentJobId).collection('proposals').doc(proposalId).update({ status: newStatus, ...extra })
    .then(() => {
      loadProposals(jobIdForThisCall);
      if (newStatus === 'approved') {
        maybeAdvanceJobStatusForApproval(jobIdForThisCall);
        // Write contractValue from proposal snapshot so KPIs show correct value
        const prop = conProposals.find(p => p.id === proposalId);
        if (prop?.snapshot?.grandTotal) {
          const patch = {
            contractValue: prop.snapshot.grandTotal,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
          };
          coll('jobs').doc(jobIdForThisCall).update(patch).catch(() => {});
          // Update in-memory so stats refresh immediately
          const job = conJobs.find(j => j.id === jobIdForThisCall);
          if (job) { job.contractValue = prop.snapshot.grandTotal; conRenderStats(); }
        }
      }
    })
    .catch(e => alert('Error updating proposal status: ' + e.message));
}
window.markProposalStatus = markProposalStatus;

// Reprints a frozen historical version exactly as it looked when saved —
// no live recompute against today's estimate.
function reprintProposalVersion(proposalId) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = companyProfile;
  const prop = conProposals.find(p => p.id === proposalId);
  if (!prop) return;
  const win = window.open('', '_blank');
  win.document.write(renderProposalDocumentHtml(prop.snapshot, job, co));
  win.document.close();
}
window.reprintProposalVersion = reprintProposalVersion;

// Resend portal link email for any existing proposal
async function resendProposalEmail(proposalId) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (!job) return;
  if (!job.email) { alert('No customer email on file. Add one in job details first.'); return; }
  if (!conFunctions) { alert('Cloud Functions not available.'); return; }

  const prop = conProposals.find(p => p.id === proposalId);
  const status = prop?.status || 'pending';

  // Get or create portal token
  let portalUrl = '';
  const snap = await conDb.collection('portalTokens').where('jobId','==',conCurrentJobId).limit(1).get();
  if (!snap.empty) {
    portalUrl = window.location.origin + window.location.pathname + '?portal=' + snap.docs[0].id;
  } else {
    const token = conCurrentJobId + '-hash-' + Math.random().toString(36).slice(2,10);
    await conDb.collection('portalTokens').doc(token).set({
      jobId: conCurrentJobId, jobName: job.name||'', companyId: currentCompanyId,
      created: Date.now(), createdBy: conCurrentUser?.email||'', expires: null, shareInvoices: true
    });
    portalUrl = window.location.origin + window.location.pathname + '?portal=' + token;
  }

  const toName = job.client || job.name || 'Valued Customer';
  const co = companyProfile?.companyName || 'JTXD Contracting';
  const jobNum = job.jobNumber || '';
  const isRevised = status === 'draft';
  const subject = isRevised
    ? `Revised Proposal from ${co}${jobNum ? ' — Job ' + jobNum : ''}`
    : `Your Proposal from ${co}${jobNum ? ' — Job ' + jobNum : ''} (Resent)`;
  const bodyHtml = `
    <p>Hi ${toName},</p>
    <p>${isRevised ? `${co} has sent you a <strong>revised proposal</strong>` : `Here is your proposal from ${co} again`}${jobNum ? ' for job <strong>' + jobNum + '</strong>' : ''}.</p>
    ${portalUrl ? `<p style="margin:24px 0"><a href="${portalUrl}" style="background:#d97706;color:#fff;padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:700;font-size:1rem">View & Sign Proposal</a></p>` : ''}
    <p style="color:#888;font-size:.85rem">If the button above doesn't work, copy and paste this link:<br>${portalUrl}</p>
    <p>Thank you for choosing ${co}.</p>`;

  try {
    await conFunctions.httpsCallable('sendJobspanEmail')({
      to: job.email, toName, subject, bodyHtml,
      jobId: conCurrentJobId, docType: 'proposal'
    });
    // Log it
    logProposalEvent(conCurrentJobId, 'proposal_emailed',
      `Proposal ${isRevised ? 're-sent (revised)' : 'resent'} to ${job.email}`, job.name||'');
    // Stamp emailSentAt
    if (prop) {
      coll('jobs').doc(conCurrentJobId).collection('proposals').doc(proposalId)
        .update({ emailSentAt: firebase.firestore.FieldValue.serverTimestamp(),
                  status: prop.status === 'draft' ? 'pending' : prop.status }).catch(()=>{});
    }
    alert(`Proposal resent to ${job.email}.`);
    loadProposals(conCurrentJobId);
  } catch(e) {
    alert('Error resending: ' + e.message);
  }
}
window.resendProposalEmail = resendProposalEmail;

// Revise a signed proposal — clears signature, resets to draft so estimate can be updated
function reviseProposal(proposalId) {
  if (!confirm('This will clear the customer\'s signature and reset this proposal to Draft so you can revise the estimate and send a new version. The original signed document is preserved in the Documents tab.\n\nContinue?')) return;
  coll('jobs').doc(conCurrentJobId).collection('proposals').doc(proposalId).update({
    status: 'draft',
    signedByName: firebase.firestore.FieldValue.delete(),
    signatureDataUrl: firebase.firestore.FieldValue.delete(),
    respondedAt: firebase.firestore.FieldValue.delete(),
    viewedAt: firebase.firestore.FieldValue.delete(),
    revisedAt: firebase.firestore.FieldValue.serverTimestamp(),
    revisedBy: conCurrentUser?.email || ''
  }).then(() => {
    logProposalEvent(conCurrentJobId, 'proposal_emailed',
      'Proposal revised — signature cleared, reset to draft', '');
    alert('Proposal reset to Draft. Update the estimate and use Send via Email to send the revised version.');
    loadProposals(conCurrentJobId);
  }).catch(e => alert('Error: ' + e.message));
}
window.reviseProposal = reviseProposal;

function renderProposalHistory() {
  const el = document.getElementById('proposalHistoryList');
  if (!el) return;
  if (!conProposals.length) {
    el.innerHTML = '<div class="small muted" style="font-style:italic;padding:8px 4px">No proposals printed yet for this job.</div>';
    return;
  }
  const STATUS_COLORS = { draft: '#9ca3af', pending: '#d97706', approved: '#1dbb87', declined: '#ef4444', voided: '#4b5563' };
  const job = conJobs.find(j => j.id === conCurrentJobId);
  el.innerHTML = conProposals.map(p => {
    const color = STATUS_COLORS[p.status] || '#9ca3af';
    const label = (job?.jobNumber || '') + '-' + p.version;
    const actions = [];
    if (p.status === 'draft') actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem" onclick="markProposalStatus('${p.id}','pending')">Mark Sent</button>`);
    if (p.status === 'pending') {
      actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem;color:#1dbb87" onclick="markProposalStatus('${p.id}','approved')">Mark Approved</button>`);
      actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem;color:#ef4444" onclick="markProposalStatus('${p.id}','declined')">Mark Declined</button>`);
    }
    // Resend — any non-voided proposal can be resent
    if (p.status !== 'voided') {
      actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem;color:#60a5fa" onclick="resendProposalEmail('${p.id}')">📧 Resend</button>`);
    }
    // Revise — lets owner revise a signed proposal (new scope change, customer request)
    if (p.status === 'approved') {
      actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem;color:#f59e0b" onclick="reviseProposal('${p.id}')">✏️ Revise</button>`);
    }
    // Void — removes from active consideration without deleting
    if (p.status !== 'voided' && p.status !== 'approved') {
      actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem;color:#6b7280" onclick="markProposalStatus('${p.id}','voided')">Void</button>`);
    }
    actions.push(`<button class="btn" style="padding:3px 10px;font-size:.75rem" onclick="reprintProposalVersion('${p.id}')">🖨 Reprint</button>`);
    const signedBanner = (p.status === 'approved' && p.signedByName)
      ? `<div style="background:rgba(16,185,129,.12);border:1px solid rgba(16,185,129,.3);border-radius:8px;padding:8px 12px;margin:4px 0;font-size:.78rem;color:#1dbb87;display:flex;align-items:center;gap:8px">
          ✅ <strong>Signed by ${esc(p.signedByName)}</strong>${p.respondedAt?.toDate ? ' on ' + p.respondedAt.toDate().toLocaleDateString() : ''}
          ${p.signatureDataUrl ? `<img src="${p.signatureDataUrl}" style="height:32px;background:#fff;border-radius:4px;padding:2px 6px;margin-left:8px">` : ''}
          <span style="margin-left:auto;font-size:.72rem;color:#6ee7b7">✅ To-Do created to schedule</span>
        </div>`
      : '';
    const viewedText = p.viewedAt?.toDate
      ? `<span style="font-size:.72rem;color:#1dbb87" title="Customer opened this proposal in the portal">👁 Viewed ${p.viewedAt.toDate().toLocaleDateString()}</span>`
      : (p.status === 'pending' ? `<span style="font-size:.72rem;color:var(--muted)">Not yet viewed</span>` : '');

    // Real email audit trail (Postmark) — only shows once an email has
    // actually been sent through the "Send via Email" button. The mailto:
    // links elsewhere in the app never populate these, since JOBSMETRIX has
    // no way to track an email it didn't itself send.
    const emailBits = [];
    if (p.emailBounced) {
      emailBits.push(`<span style="font-size:.72rem;color:#ef4444" title="${esc(p.emailBounceReason || 'Delivery failed')}">⚠ Bounced</span>`);
    } else if (p.emailSentAt?.toDate) {
      emailBits.push(`<span style="font-size:.72rem;color:#93c5fd" title="Sent via email">📧 Sent ${p.emailSentAt.toDate().toLocaleDateString()}</span>`);
      if (p.emailLinkClickedAt?.toDate) {
        emailBits.push(`<span style="font-size:.72rem;color:#1dbb87" title="Customer clicked the link in the email">🔗 Clicked ${p.emailLinkClickedAt.toDate().toLocaleDateString()}</span>`);
      } else if (p.emailOpenedAt?.toDate) {
        emailBits.push(`<span style="font-size:.72rem;color:#fbbf24" title="Customer opened the email">✉ Opened ${p.emailOpenedAt.toDate().toLocaleDateString()}</span>`);
      }
    }
    const emailText = emailBits.join(' ');

    return `<div style="padding:8px 10px;border-bottom:1px solid var(--line)">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
        <span style="font-weight:700;color:var(--amber);min-width:90px">${esc(label)}</span>
        <span style="text-transform:uppercase;font-size:.7rem;font-weight:800;color:${color};background:${color}22;padding:2px 8px;border-radius:6px">${esc(p.status)}</span>
        ${emailText}
        ${viewedText}
        <span style="margin-left:auto;display:flex;gap:6px">${actions.join('')}</span>
      </div>
      ${signedBanner}
    </div>`;
  }).join('');
}
window.renderProposalHistory = renderProposalHistory;

function printProposal() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = companyProfile;
  const itemized = !!document.getElementById('proposalItemizedToggle')?.checked;

  // Same mobile popup-blocker fix as viewInvoiceById etc: open
  // synchronously FIRST, before any async/delayed work — the fallback
  // path below used to open the window inside a setTimeout(...,1500),
  // which is exactly the kind of delayed-after-the-tap open mobile
  // browsers silently block. Now the window opens immediately either
  // way; only the CONTENT filling it in is ever delayed.
  const win = window.open('', '_blank');
  if (win) win.document.write('<html><body style="font-family:sans-serif;padding:40px;text-align:center;color:#666">Loading proposal…</body></html>');

  // Ensure estimate is loaded before computing proposal data
  if (!estGroups || !estGroups.length) {
    conLoadEstimate(conCurrentJobId);
    setTimeout(() => {
      const data = computeProposalData(job, itemized);
      saveProposalSnapshot(conCurrentJobId, data);
      if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
      win.document.open();
      win.document.write(renderProposalDocumentHtml(data, job, co));
      win.document.close();
    }, 1500);
    return;
  }

  const data = computeProposalData(job, itemized);
  saveProposalSnapshot(conCurrentJobId, data);
  if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
  win.document.open();
  win.document.write(renderProposalDocumentHtml(data, job, co));
  win.document.close();
}
window.printProposal = printProposal;

// Same document as printProposal, but without the auto-print trigger —
// for actually looking at what you're about to send/print, not printing
// it. Previously the ONLY way to see the proposal at all was to hit
// Print, which immediately threw up the browser's print dialog.
// Shows the proposal in-app instead of a new tab/window -- window.open()
// used to leave mobile users (especially inside a PWA/webview) with no
// back button and no way to close it, forcing them to close the whole
// app. An in-page modal always has a real Close button, period.
function viewProposal() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = companyProfile;
  const itemized = !!document.getElementById('proposalItemizedToggle')?.checked;

  const showInModal = (html) => {
    const titleEl = document.getElementById('viewProposalModalTitle');
    if (titleEl) titleEl.textContent = '👁️ Proposal';
    document.getElementById('viewProposalIframe').srcdoc = html;
    kOpen('viewProposalModal');
  };

  if (!estGroups || !estGroups.length) {
    conLoadEstimate(conCurrentJobId);
    setTimeout(() => {
      const data = computeProposalData(job, itemized);
      showInModal(renderProposalDocumentHtml(data, job, co, false));
    }, 1500);
    return;
  }

  const data = computeProposalData(job, itemized);
  showInModal(renderProposalDocumentHtml(data, job, co, false));
}
window.viewProposal = viewProposal;

// Sends the latest proposal via real email (Postmark), with genuine
// sent/opened/clicked tracking — as opposed to every other "email" action
// in the app, which is just a mailto: link. Requires the Postmark Cloud
// Functions to be deployed (see postmark-functions.js handoff); until
// then this will fail gracefully with a clear message rather than
// silently doing nothing.
// ── Proposal activity logger ──────────────────────────────────────────────
// Writes to jobs/{jobId}/logs so the activity feed picks it up automatically.
// type: proposal_emailed | proposal_viewed | proposal_signed
function logProposalEvent(jobId, type, note, jobName) {
  if (!jobId || !conDb || !currentCompanyId) return;
  const ref = coll('jobs').doc(jobId).collection('logs').doc();
  ref.set({
    type,
    notes: note,
    jobId,
    jobName: jobName || '',
    companyId: currentCompanyId,
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdMs: Date.now(),
    createdBy: conCurrentUser?.email || 'system'
  }).catch(() => {});
}
window.logProposalEvent = logProposalEvent;

let _pendingProposalEmail = null;

function sendProposalViaEmail(btn) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  if (!job) return;
  if (!job.email) { alert('This job has no customer email on file. Add one in the job details first.'); return; }
  if (!conFunctions) { alert("Email sending isn't set up yet — deploy the Cloud Functions first."); return; }

  const proceed = (portalUrl) => {
    const toName = job.client || job.name || 'Valued Customer';
    const jobNum = job.jobNumber || '';
    const prop = conProposals && conProposals[0];
    const total = prop?.snapshot?.grandTotal || 0;
    const co = companyProfile?.companyName || 'JTXD Contracting';
    const subject = `Your Proposal from ${co}${jobNum ? ' — Job ' + jobNum : ''}`;
    const bodyHtml = `
      <p>Hi ${toName},</p>
      <p>${co} has sent you a proposal${jobNum ? ' for job <strong>' + jobNum + '</strong>' : ''}.</p>
      ${total ? `<p><strong>Total: $${Number(total).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</strong></p>` : ''}
      ${portalUrl ? `<p style="margin:24px 0"><a href="${portalUrl}" style="background:#d97706;color:#fff;padding:12px 28px;border-radius:8px;text-decoration:none;font-weight:700;font-size:1rem">View & Sign Proposal</a></p>` : ''}
      <p style="color:#888;font-size:.85rem">If the button above doesn't work, copy and paste this link into your browser:<br>${portalUrl || ''}</p>
      <p>Thank you for choosing ${co}.</p>
    `;

    // Also render the ACTUAL proposal document — the thing the "View &
    // Sign Proposal" link in the email above actually opens — not just
    // the wrapper email text, so this preview reflects what the
    // recipient really sees, not just the notification pointing to it.
    const itemized = !!document.getElementById('proposalItemizedToggle')?.checked;
    const proposalData = computeProposalData(job, itemized);
    const proposalHtml = renderProposalDocumentHtml(proposalData, job, companyProfile, false);
    document.getElementById('emailPreviewProposalFrame').srcdoc = proposalHtml;

    // Stash everything confirmSendProposalEmail() needs, then show the
    // preview instead of sending right away — per feedback, there was
    // no way to see exactly what was about to go out before it went
    // out, risking sending the wrong document/customer. proposalData is
    // included so confirmSendProposalEmail can guarantee a matching
    // Firestore proposal doc exists (see ensureProposalDocForSending) —
    // this is the exact same data just rendered into the preview above,
    // so what gets saved for the customer to sign matches what was shown.
    _pendingProposalEmail = { job, toName, subject, bodyHtml, prop, btn, proposalData };
    document.getElementById('emailPreviewTo').textContent = job.email + (toName ? ' (' + toName + ')' : '');
    document.getElementById('emailPreviewSubject').textContent = subject;
    document.getElementById('emailPreviewBody').innerHTML = bodyHtml;

    kOpen('emailPreviewModal');
  };

  // Reuse an existing portal token for this job if one exists, otherwise
  // create one — same token scheme shareCustomerPortal() already uses.
  conDb.collection('portalTokens').where('jobId', '==', conCurrentJobId).limit(1).get()
    .then(snap => {
      if (!snap.empty) {
        proceed(window.location.origin + window.location.pathname + '?portal=' + snap.docs[0].id);
      } else {
        const token = conCurrentJobId + '-hash-' + Math.random().toString(36).slice(2, 10);
        conDb.collection('portalTokens').doc(token).set({
          jobId: conCurrentJobId, jobName: job.name || '', companyId: currentCompanyId,
          created: Date.now(), createdBy: conCurrentUser?.email || '', expires: null, shareInvoices: true
        }).then(() => proceed(window.location.origin + window.location.pathname + '?portal=' + token))
          .catch(e => alert('Error creating portal link: ' + e.message));
      }
    })
    .catch(e => alert('Error looking up portal link: ' + e.message));
}
window.sendProposalViaEmail = sendProposalViaEmail;

// Guarantees a real proposal document exists in Firestore with a
// customer-visible status before an email actually goes out. Root
// cause of a real incident: sendProposalViaEmail() previously only
// read conProposals[0] (whatever happened to already be loaded) and
// skipped creating/updating anything if it was empty — if nobody had
// separately clicked Print Proposal first, NO document existed at all,
// so the customer portal's proposal query came back empty and showed
// nothing. Now called unconditionally right before sending.
function ensureProposalDocForSending(jobId, data) {
  return coll('jobs').doc(jobId).collection('proposals')
    .orderBy('version', 'desc').limit(1).get()
    .then(snap => {
      if (snap.empty) {
        // Nothing has ever been saved for this job — create it directly
        // as 'pending' since we're sending it right now, no need to
        // pass through an intermediate draft state nobody will see.
        return coll('jobs').doc(jobId).collection('proposals').add({
          version: 1, status: 'pending', snapshot: data,
          createdAt: firebase.firestore.FieldValue.serverTimestamp(),
          sentAt: firebase.firestore.FieldValue.serverTimestamp(),
          createdBy: conCurrentUser ? conCurrentUser.email : 'unknown'
        }).then(ref => ({ id: ref.id, status: 'pending' }));
      }
      const doc = snap.docs[0];
      const existing = doc.data();
      if (existing.status === 'draft') {
        // Existing but never sent — refresh the snapshot to the current
        // estimate and promote it to pending.
        return doc.ref.update({
          snapshot: data, status: 'pending',
          sentAt: firebase.firestore.FieldValue.serverTimestamp(),
          updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        }).then(() => ({ id: doc.id, status: 'pending' }));
      }
      // Already pending/approved/declined — just refresh the snapshot
      // content (estimate may have changed) without touching a
      // customer's existing response/status.
      return doc.ref.update({
        snapshot: data, updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      }).then(() => ({ id: doc.id, status: existing.status }));
    });
}

// Fires only once the user has actually reviewed the preview and
// clicked Confirm & Send — this is where the real Postmark call and
// activity-log/status updates happen, moved out of sendProposalViaEmail
// itself so nothing goes out until explicitly confirmed.
function confirmSendProposalEmail() {
  const pending = _pendingProposalEmail;
  if (!pending) { kClose('emailPreviewModal'); return; }
  const { job, toName, subject, bodyHtml, prop, btn, proposalData } = pending;
  const jobNum = job.jobNumber || '';

  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.textContent = 'Sending…'; }
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }

  const finish = (msg) => {
    if (confirmBtn) { confirmBtn.disabled = false; confirmBtn.textContent = '✅ Confirm & Send'; }
    if (btn) { btn.disabled = false; btn.textContent = '📧 Send via Email'; }
    kClose('emailPreviewModal');
    _pendingProposalEmail = null;
    if (msg) alert(msg);
  };

  // Guaranteed first, and the actual send is gated on it succeeding —
  // never again send a link to a portal with nothing behind it.
  ensureProposalDocForSending(conCurrentJobId, proposalData).then(() => {
    return conFunctions.httpsCallable('sendJobspanEmail')({
      to: job.email,
      toName,
      subject,
      bodyHtml,
      jobId: conCurrentJobId,
      docType: 'proposal'
    });
  }).then(() => {
    finish('Proposal emailed to ' + job.email + '.');
    logProposalEvent(conCurrentJobId, 'proposal_emailed', `Proposal emailed to ${job.email}`, job.name || '');
    const prop2 = conProposals && conProposals[0];
    if (prop2) {
      coll('jobs').doc(conCurrentJobId).collection('proposals').doc(prop2.id)
        .update({ emailSentAt: firebase.firestore.FieldValue.serverTimestamp() }).catch(()=>{});
    }
    // ensureProposalDocForSending() above already created/promoted the
    // proposal doc as needed — just refresh the client-side cache from
    // the source of truth rather than re-deriving status from the
    // stale `prop` captured back when the preview was first opened.
    loadProposals(conCurrentJobId);
    advanceJobStatusIfEarlier(conCurrentJobId, 'Submitted', 'Proposal emailed to customer');
  }).catch(e => finish('Error sending email: ' + e.message));
}
window.confirmSendProposalEmail = confirmSendProposalEmail;

// ═══════════════════════════════════════════════════════════════════════
// Change Order document — View / Print / Email, same pattern as the
// Proposal flow above (renderProposalDocumentHtml / printProposal /
// viewProposal / sendProposalViaEmail). Reuses the same shared modals
// (viewProposalModal, emailPreviewModal) rather than new markup — those
// modals are already generic (the invoice/sub-agreement/lien-waiver
// flows do the same thing), so no HTML duplication needed.
// ═══════════════════════════════════════════════════════════════════════

function renderChangeOrderDocumentHtml(co, job, comp, autoPrint) {
  const amt = Number(co.amount || 0);
  const amtDisplay = (amt < 0 ? '-$' + Math.abs(amt).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})
                               : '$' + amt.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}));

  const items = co.lineItems || [];
  const itemsHtml = items.length ? `
  <table class="payment-table" style="margin-top:20px">
    <thead><tr><th>Description</th><th style="text-align:center">Qty</th><th style="text-align:right">Amount</th></tr></thead>
    <tbody>
      ${items.map(it => {
        const lineTotal = (Number(it.qty)||1) * (Number(it.unitPrice)||0);
        return `<tr>
          <td>${esc(it.desc || '')}</td>
          <td style="text-align:center">${it.qty || 1} ${esc(it.unit||'')}</td>
          <td style="text-align:right">$${lineTotal.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}</td>
        </tr>`;
      }).join('')}
    </tbody>
  </table>` : '';

  const scheduleHtml = co.days ? `<div class="intro" style="margin-bottom:0"><strong>Schedule Impact:</strong> +${co.days} day${co.days!=1?'s':''} added to the project schedule.</div>` : '';

  return `<!DOCTYPE html><html><head><title>Change Order — ${esc(job?.name||'')}</title>
  <style>
    * { box-sizing: border-box; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; max-width: 820px; margin: 0 auto; padding: 48px 40px; color: #1f2937; line-height: 1.5; }
    .header { display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 24px; margin-bottom: 8px; border-bottom: 4px solid #d97706; }
    .co-name { font-size: 1.25rem; font-weight: 800; color: #111827; }
    .co-contact { color: #6b7280; font-size: .82rem; margin-top: 2px; }
    .doc-title { font-size: 1.7rem; font-weight: 800; color: #d97706; letter-spacing: .03em; text-align: right; }
    .doc-meta { text-align: right; font-size: .85rem; color: #6b7280; margin-top: 4px; }
    .prepared-for { margin: 28px 0 24px; padding: 16px 20px; background: #f9fafb; border-radius: 10px; border: 1px solid #e5e7eb; }
    .prepared-for .label { font-size: .7rem; text-transform: uppercase; letter-spacing: .08em; color: #9ca3af; font-weight: 700; margin-bottom: 4px; }
    .prepared-for .name { font-size: 1.05rem; font-weight: 700; color: #111827; }
    .co-title-block { margin: 24px 0; }
    .co-title-block .heading { font-size: 1.1rem; font-weight: 800; color: #111827; margin-bottom: 8px; }
    .intro { color: #4b5563; font-size: .92rem; margin-bottom: 20px; white-space: pre-line; }
    .payment-table { width: 100%; border-collapse: collapse; font-size: .88rem; }
    .payment-table th { text-align: left; background: #f3f4f6; padding: 8px 12px; font-weight: 700; color: #4b5563; border-bottom: 2px solid #e5e7eb; }
    .payment-table td { padding: 8px 12px; border-bottom: 1px solid #e5e7eb; color: #1f2937; }
    .total-box { margin-top: 28px; padding: 20px 24px; background: #1f2937; color: #fff; border-radius: 10px; display: flex; justify-content: space-between; align-items: center; }
    .total-box .label { font-size: 1rem; font-weight: 700; letter-spacing: .04em; }
    .total-box .amount { font-size: 1.6rem; font-weight: 800; color: #fbbf24; }
    .terms-note { margin-top: 24px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: .8rem; color: #6b7280; line-height: 1.55; }
    .signatures { display: flex; gap: 40px; margin-top: 48px; }
    .sig-block { flex: 1; }
    .sig-line { border-bottom: 1.5px solid #9ca3af; height: 42px; margin-bottom: 6px; }
    .sig-label { font-size: .8rem; color: #6b7280; }
    .footer { margin-top: 48px; padding-top: 18px; border-top: 1px solid #e5e7eb; color: #9ca3af; font-size: .72rem; text-align: center; line-height: 1.6; }
    @media print { body { padding: 20px 30px; } }
  </style></head><body>

  <div class="header">
    <div>
      ${comp.logo?`<img src="${comp.logo}" style="height:52px;object-fit:contain;margin-bottom:8px"><br>`:''}
      <div class="co-name">${esc(comp.companyName||'')}</div>
      <div class="co-contact">${esc(comp.phone||'')} · ${esc(comp.email||'')}${comp.address?' · '+esc(comp.address):''}</div>
      ${comp.license?`<div class="co-contact">License #${esc(comp.license)}</div>`:''}
    </div>
    <div>
      <div class="doc-title">CHANGE ORDER</div>
      <div class="doc-meta">${esc(co.coNumber||'')}${job?.jobNumber ? ' · Job ' + esc(job.jobNumber) : ''}</div>
      <div class="doc-meta">${co.date ? new Date(co.date+'T00:00:00').toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'}) : new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</div>
    </div>
  </div>

  <div class="prepared-for">
    <div class="label">Prepared For</div>
    <div class="name">${esc(job?.client||'')}</div>
    <div class="co-contact">${esc(job?.address||'')}</div>
  </div>

  <div class="co-title-block">
    <div class="heading">${esc(co.title || 'Change Order')}</div>
    ${co.reason ? `<div class="intro">${esc(co.reason)}</div>` : ''}
    ${scheduleHtml}
  </div>

  ${itemsHtml}

  <div class="total-box">
    <div class="label">TOTAL CHANGE ORDER AMOUNT</div>
    <div class="amount">${amtDisplay}</div>
  </div>

  <div class="terms-note">
    This Change Order modifies the original signed Proposal/Contract for this project. All other terms and conditions of the original agreement remain in full effect unless explicitly modified above.
  </div>

  <div class="signatures">
    <div class="sig-block">
      <div class="sig-line"></div>
      <div class="sig-label">Customer Signature &nbsp;·&nbsp; Date</div>
    </div>
    <div class="sig-block">
      <div class="sig-line"></div>
      <div class="sig-label">${esc(comp.companyName||'Company')} Representative &nbsp;·&nbsp; Date</div>
    </div>
  </div>

  <div class="footer">
    ${esc(comp.companyName||'')} · ${esc(comp.phone||'')} · ${esc(comp.email||'')}${comp.license?' · License #'+esc(comp.license):''}
  </div>

  ${autoPrint !== false ? '<script>window.onload = () => setTimeout(() => window.print(), 250);<\\/script>' : ''}</body></html>`;
}
window.renderChangeOrderDocumentHtml = renderChangeOrderDocumentHtml;

// Same mobile popup-blocker fix as printProposal: open the window
// synchronously first, fill content in after.
function printChangeOrder(coId) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = conCOs.find(c => c.id === coId);
  if (!co) { alert('Change order not found.'); return; }

  const win = window.open('', '_blank');
  if (win) win.document.write('<html><body style="font-family:sans-serif;padding:40px;text-align:center;color:#666">Loading change order…</body></html>');

  const html = renderChangeOrderDocumentHtml(co, job, companyProfile, true);
  if (!win) { alert('Your browser blocked the popup — check your popup/pop-up blocker settings for this site and try again.'); return; }
  win.document.open();
  win.document.write(html);
  win.document.close();
}
window.printChangeOrder = printChangeOrder;

// Reuses the shared viewProposalModal — that modal is already generic
// (title + iframe + a built-in Print button), so no new markup needed.
function viewChangeOrder(coId) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = conCOs.find(c => c.id === coId);
  if (!co) { alert('Change order not found.'); return; }

  const html = renderChangeOrderDocumentHtml(co, job, companyProfile, false);
  const titleEl = document.getElementById('viewProposalModalTitle');
  if (titleEl) titleEl.textContent = '👁️ ' + (co.title || 'Change Order');
  document.getElementById('viewProposalIframe').srcdoc = html;
  kOpen('viewProposalModal');
}
window.viewChangeOrder = viewChangeOrder;

let _pendingCOEmail = null;

// Reuses the shared emailPreviewModal — same preview-before-send pattern
// as sendProposalViaEmail/emailInvoiceToCustomer: repoint the shared
// Confirm button to this doc type's own confirm function so the other
// email flows are undisturbed.
function emailChangeOrderToCustomer(coId) {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = conCOs.find(c => c.id === coId);
  if (!co) { alert('Change order not found.'); return; }
  if (!job.email) { alert('This job has no customer email on file. Add one in the job details first.'); return; }
  if (!conFunctions) { alert("Email sending isn't set up yet — deploy the Cloud Functions first."); return; }

  const toName = job.client || job.name || 'Valued Customer';
  const jobNum = job.jobNumber || '';
  const amt = Number(co.amount || 0);
  const amtDisplay = (amt < 0 ? '-$' + Math.abs(amt).toLocaleString() : '$' + amt.toLocaleString());
  const subject = `Change Order from ${companyProfile?.companyName || 'JTXD Contracting'}${jobNum ? ' — Job ' + jobNum : ''}`;
  const bodyHtml = `
    <p>Hi ${toName},</p>
    <p>${companyProfile?.companyName || 'JTXD Contracting'} has sent you a Change Order${jobNum ? ' for job <strong>' + jobNum + '</strong>' : ''}: <strong>${esc(co.title||'')}</strong>.</p>
    <p><strong>Amount: ${amtDisplay}</strong>${co.days ? ` &nbsp;·&nbsp; +${co.days} day${co.days!=1?'s':''} to schedule` : ''}</p>
    <p>Please see the attached document for full details.</p>
    <p>Thank you for choosing ${companyProfile?.companyName || 'JTXD Contracting'}.</p>
  `;

  const coHtml = renderChangeOrderDocumentHtml(co, job, companyProfile, false);
  document.getElementById('emailPreviewProposalFrame').srcdoc = coHtml;

  _pendingCOEmail = { job, co, toName, subject, bodyHtml };
  document.getElementById('emailPreviewTo').textContent = job.email + (toName ? ' (' + toName + ')' : '');
  document.getElementById('emailPreviewSubject').textContent = subject;
  document.getElementById('emailPreviewBody').innerHTML = bodyHtml;

  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  if (confirmBtn) confirmBtn.onclick = confirmSendChangeOrderEmail;

  kOpen('emailPreviewModal');
}
window.emailChangeOrderToCustomer = emailChangeOrderToCustomer;

function confirmSendChangeOrderEmail() {
  const pending = _pendingCOEmail;
  if (!pending) { kClose('emailPreviewModal'); return; }
  const { job, co, toName, subject, bodyHtml } = pending;

  const confirmBtn = document.getElementById('emailPreviewConfirmBtn');
  if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.textContent = 'Sending…'; }

  const finish = (msg) => {
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.textContent = '✅ Confirm & Send';
      confirmBtn.onclick = confirmSendProposalEmail; // restore default so the proposal flow is undisturbed
    }
    kClose('emailPreviewModal');
    _pendingCOEmail = null;
    if (msg) alert(msg);
  };

  conFunctions.httpsCallable('sendJobspanEmail')({
    to: job.email,
    toName,
    subject,
    bodyHtml,
    jobId: conCurrentJobId,
    docType: 'changeOrder'
  }).then(() => {
    finish('Change order emailed to ' + job.email + '.');
    if (typeof logActivity === 'function') {
      logActivity(conCurrentJobId, `Change Order "${co.title||''}" emailed to ${job.email}`, job.name || '');
    }
  }).catch(e => finish('Error sending email: ' + e.message));
}
window.confirmSendChangeOrderEmail = confirmSendChangeOrderEmail;

function printEstimate() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = companyProfile;

  let allCost = 0, allPrice = 0;
  const groupRows = estGroups.map(group => {
    const allItems = getAllItemsInGroup(group);
    const totals = calcGroupTotals(allItems);
    allCost += totals.cost;
    allPrice += totals.price;

    const subRows = (group.subgroups||[]).map(sub => {
      const st = calcGroupTotals(sub.items||[]);
      const isDescOnly = st.price <= 0 && sub.scopeNotes;
      const subItemRows = (sub.items||[]).map(item => {
        const qty = item.qty||1;
        const uc = item.unitCost||0;
        const up = item.unitPrice||uc;
        return `<tr style="font-size:.82rem">
          <td style="padding:5px 8px 5px 32px">${esc(item.desc||'')}${item.notes ? `<div style="font-size:.75rem;color:#6b7280;font-style:italic;margin-top:2px">${esc(item.notes)}</div>` : ''}</td>
          <td style="text-align:center">${qty} ${item.unit||''}</td>
          <td style="text-align:right">$${(qty*uc).toFixed(2)}</td>
          <td style="text-align:right;font-weight:600">$${(qty*up).toFixed(2)}</td>
        </tr>`;
      }).join('');

      // Description-only subgroup — show name + scope notes, no price columns
      if (isDescOnly) {
        return `<tr style="background:#f9fafb">
          <td colspan="4" style="padding:6px 8px 2px 20px;font-weight:700;color:#374151">${esc(sub.name)}</td>
        </tr>
        <tr><td colspan="4" style="padding:2px 8px 8px 20px;font-size:.8rem;color:#6b7280;white-space:pre-line">${esc(sub.scopeNotes)}</td></tr>`;
      }

      return `<tr style="background:#f3f4f6">
        <td style="padding:6px 8px 6px 20px;font-weight:700;color:#374151">
          ${esc(sub.name)}
          ${sub.scopeNotes ? `<div style="font-size:.78rem;color:#6b7280;font-weight:400;font-style:italic;white-space:pre-line;margin-top:2px">${esc(sub.scopeNotes)}</div>` : ''}
        </td>
        <td></td>
        <td style="text-align:right;font-weight:600">$${st.cost.toFixed(2)}</td>
        <td style="text-align:right;font-weight:700;color:#d97706">$${st.price.toFixed(2)}</td>
      </tr>${subItemRows}`;
    }).join('');

    const directRows = (group.directItems||[]).map(item => {
      const qty = item.qty||1;
      const uc = item.unitCost||0;
      const up = item.unitPrice||uc;
      return `<tr style="font-size:.82rem">
        <td style="padding:5px 8px 5px 20px">${esc(item.desc||'')}</td>
        <td style="text-align:center">${qty} ${item.unit||''}</td>
        <td style="text-align:right">$${(qty*uc).toFixed(2)}</td>
        <td style="text-align:right;font-weight:600">$${(qty*up).toFixed(2)}</td>
      </tr>`;
    }).join('');

    // Only show group total row if there are multiple pricing subgroups
    // — when there's just one, the subgroup row already shows the total
    const pricingSubCount = (group.subgroups||[]).filter(s => calcGroupTotals(s.items||[]).price > 0).length;
    const showGroupTotal = pricingSubCount !== 1 || (group.directItems||[]).length > 0;

    return `${showGroupTotal ? `<tr style="background:#e5e7eb">
      <td style="padding:8px;font-weight:900;font-size:.95rem">${esc(group.name)}</td>
      <td></td>
      <td style="text-align:right;font-weight:700">$${totals.cost.toFixed(2)}</td>
      <td style="text-align:right;font-weight:700;color:#d97706">$${totals.price.toFixed(2)}</td>
    </tr>` : `<tr style="background:#e5e7eb">
      <td colspan="4" style="padding:8px;font-weight:900;font-size:.95rem">${esc(group.name)}</td>
    </tr>`}${subRows}${directRows}`;
  }).join('');

  const profit = allPrice - allCost;
  const margin = allPrice > 0 ? (profit/allPrice*100).toFixed(1) : '0.0';

  const html = `<!DOCTYPE html><html><head><title>Estimate — ${esc(job?.name||'')}</title>
  <style>body{font-family:Arial,sans-serif;max-width:800px;margin:40px auto;padding:0 20px;color:#111}
  table{width:100%;border-collapse:collapse}td{border-bottom:1px solid #e5e7eb}
  .header{display:flex;justify-content:space-between;border-bottom:3px solid #d97706;padding-bottom:16px;margin-bottom:20px}
  @media print{body{margin:10px}}</style></head><body>
  <div class="header">
    <div>
      ${co.logo?`<img src="${co.logo}" style="height:48px;object-fit:contain;margin-bottom:4px"><br>`:''}
      <strong style="font-size:1.2rem">${esc(co.companyName||'')}</strong><br>
      <span style="color:#6b7280;font-size:.85rem">${esc(co.phone||'')} · ${esc(co.email||'')}</span>
    </div>
    <div style="text-align:right">
      <div style="font-size:1.4rem;font-weight:900;color:#d97706">ESTIMATE</div>
      <div style="font-size:1rem;font-weight:700">${esc(job?.name||'')}</div>
      <div style="color:#6b7280;font-size:.85rem">${esc(job?.address||'')}</div>
      <div style="color:#6b7280;font-size:.85rem">Date: ${new Date().toLocaleDateString()}</div>
    </div>
  </div>
  <table>
    <thead><tr style="background:#1f2937;color:#fff">
      <th style="padding:10px 8px;text-align:left">Description</th>
      <th style="padding:10px 8px;text-align:center">Qty</th>
      <th style="padding:10px 8px;text-align:right">Cost</th>
      <th style="padding:10px 8px;text-align:right">Price</th>
    </tr></thead>
    <tbody>${groupRows}</tbody>
    <tfoot>
      <tr style="background:#1f2937;color:#fff;font-weight:900;font-size:1rem">
        <td style="padding:12px 8px" colspan="2">TOTAL</td>
        <td style="padding:12px 8px;text-align:right">$${allCost.toFixed(2)}</td>
        <td style="padding:12px 8px;text-align:right">$${allPrice.toFixed(2)}</td>
      </tr>
      <tr><td colspan="4" style="padding:8px;text-align:right;color:#6b7280;font-size:.85rem">
        Profit: $${profit.toFixed(2)} · Margin: ${margin}%
      </td></tr>
    </tfoot>
  </table>
  <div style="margin-top:32px;padding-top:16px;border-top:1px solid #e5e7eb;color:#9ca3af;font-size:.75rem;text-align:center">
    ${esc(co.companyName||'')} · ${esc(co.phone||'')} · ${esc(co.email||'')}
    ${co.license?'<br>License #'+esc(co.license):''}
  </div></body></html>`;

  // Was window.open('', '_blank') writing raw HTML into a brand-new
  // browser tab -- on mobile (especially inside a PWA/webview) that
  // produces a stranded tab with no back button and no way to close it,
  // the exact same failure mode already found and fixed for View
  // Proposal. Reusing that same proven in-app modal (iframe + srcdoc,
  // real Close button, already fixed for the notch/safe-area issue)
  // instead of opening a new window. Deliberately does NOT call
  // window.print() automatically on load like the old version did --
  // that's what triggered the OS print dialog immediately in the old
  // popup, which is exactly why there seemed to be "no way to close" on
  // mobile (the print sheet was covering the screen). The modal's own
  // 🖨 Print button covers that instead, only when the person wants it.
  const titleEl = document.getElementById('viewProposalModalTitle');
  if (titleEl) titleEl.textContent = '🖨 Estimate (Internal)';
  document.getElementById('viewProposalIframe').srcdoc = html;
  kOpen('viewProposalModal');
}

// ── PUNCH LIST PRINT ──
// Strips tier/product specifics off a bundle-generated name, leaving a
// generic trade label — "Ceiling Fan Install (High Grade — 52in...) ×1"
// becomes "Ceiling Fan Install". Used anywhere the customer or crew should
// see the task, not the specific product/brand/size (the customer picks
// the actual fixture in Selections).
function toGenericLabel(name) {
  return (name || '').split(' (')[0].replace(/\s*×\d+$/, '').trim() || 'Work';
}

// toGenericLabel() above is deliberately for short catalog/product NAMES
// -- stripping everything after " (" removes trailing brand/model/size
// specs, e.g. "Ceiling Fan Install (Hunter Bay Breeze, 52-inch)" ->
// "Ceiling Fan Install". Real bug found and fixed here: that same
// function was also being used on full freeform item DESCRIPTIONS
// (item.desc) in both the customer proposal and the crew punch list --
// multi-sentence scope text that can legitimately contain a
// parenthetical mid-sentence. "Remove all old roof shingles (both
// layers). Haul away all old roofing shingles..." was silently
// truncated to just "Remove all old roof shingles" on both documents,
// discarding the rest of the actual scope of work, not just visually
// clipping it. This keeps the trailing "×N" quantity-suffix cleanup
// (still useful on a description) without the parenthetical-stripping
// that only makes sense for short names.
function itemDescriptionText(desc) {
  return (desc || '').replace(/\s*×\d+$/, '').trim() || 'Work';
}

// Finds the Low/Medium/High grade word for a subgroup, derived from any
// item inside it tagged with bundleTier (set when added via Smart Add).
function subgroupGradeLabel(sub) {
  const item = (sub.items || []).find(i => i.bundleTier);
  if (!item) return '';
  return { low: 'Low Grade', med: 'Medium Grade', high: 'High Grade' }[item.bundleTier] || '';
}

// Combines the two into the one string customers/crew should see:
// "Ceiling Fan Install — Medium Grade" — no brand, no size, no model.
function customerSafeLabel(sub) {
  const generic = toGenericLabel(sub.name);
  const grade = subgroupGradeLabel(sub);
  return grade ? generic + ' — ' + grade : generic;
}

// Same generic cleanup as customerSafeLabel, but WITHOUT the grade
// word — used only on the customer-facing Proposal document. Jason's
// feedback: customers were nitpicking "Low Grade"/"Medium Grade"
// wording since that's literally the tier they picked at that price
// point; the crew-facing Punch List still needs the grade shown (they
// need to know which tier to actually install), so this is
// deliberately a separate function rather than changing
// customerSafeLabel itself.
function proposalSafeLabel(sub) {
  return toGenericLabel(sub.name);
}

// Turns the crew-facing scope stored on a subgroup into individual punch-list
// tasks. Scope is commonly entered one room/instruction per line, but older
// imported estimates often stored several room instructions as sentences in
// one paragraph, so support both shapes.
// Common measurement/unit abbreviations that end in a period but are NOT
// sentence boundaries -- "60 in. W x 36 in. H Frameless..." must stay one
// task, not fracture into "60 in." / "W x 36 in." / "H Frameless...".
const SCOPE_NOTE_ABBREVIATIONS = new Set([
  'in', 'ft', 'lf', 'sf', 'sqft', 'sq', 'yd', 'ea', 'ct', 'no', 'dia',
  'mm', 'cm', 'hr', 'hrs', 'min', 'sec', 'approx', 'etc', 'vs',
  'w', 'h', 'd', 'l', 'qty', 'oz', 'lb', 'lbs', 'gal'
]);

// Splits a block of scope-note text into sentences, but refuses to split
// right after a known abbreviation (so "in." "ft." "W" "H" "D" etc. don't
// get treated as end-of-sentence just because the next word is capitalized
// or numeric).
function splitScopeNoteSentences(str) {
  const out = [];
  let start = 0;
  const boundaryRe = /([.!?])\s+(?=[A-Z0-9])/g;
  let m;
  while ((m = boundaryRe.exec(str))) {
    const punct = m[1];
    const splitPos = m.index + 1;
    if (punct === '.') {
      const preceding = str.slice(0, m.index);
      const wordMatch = preceding.match(/([A-Za-z]+)$/);
      if (wordMatch && SCOPE_NOTE_ABBREVIATIONS.has(wordMatch[1].toLowerCase())) {
        continue; // not a real sentence boundary -- keep going
      }
    }
    out.push(str.slice(start, splitPos));
    start = splitPos;
  }
  out.push(str.slice(start));
  return out.map(part => part.trim()).filter(Boolean);
}

function punchListScopeTasks(sub) {
  const scopeParts = [sub.scopeNotes, ...(sub.items || []).map(item => item.notes)]
    .filter(Boolean)
    .flatMap(note => String(note)
      .split(/\r?\n+/)
      .flatMap(splitScopeNoteSentences));

  // Keep the printed checklist concise when the same note was copied onto
  // multiple estimate items during an import.
  return [...new Set(scopeParts)];
}

function printPunchList() {
  const job = conJobs.find(j => j.id === conCurrentJobId);
  const co = companyProfile;
  const win = window.open('', '_blank');

  // Strips tier/product specifics off a bundle-generated name, leaving a
  // generic trade label — "Ceiling Fan Install (High Grade — 52in...) ×1"
  // becomes "Ceiling Fan Install". Crew doesn't need the product spec on
  // the punch list, just what the task is. (toGenericLabel is now shared/global.)

  // Job-wide labor hours (used only for the day-estimate footer — never
  // shown per room or per item on the printed sheet itself).
  let totalLaborHours = 0;

  const punchPages = [];

  estGroups.forEach(group => {
    const allItems = getAllItemsInGroup(group);
    const hasSubgroupScope = (group.subgroups || []).some(sub => punchListScopeTasks(sub).length);
    if (!allItems.length && !hasSubgroupScope) return;

    allItems.forEach(item => {
      const isLabor = item.costType === 'Labor' || (item.unit||'').toLowerCase() === 'hr';
      if (isLabor) totalLaborHours += (item.qty || 0);
    });

    // A subgroup is a room. Build one complete printable page for every
    // subgroup instead of combining all rooms beneath the parent group.
    (group.subgroups || []).forEach(sub => {
      const materialItems = (sub.items||[]).filter(i => i.costType !== 'Labor' && (i.unit||'').toLowerCase() !== 'hr');
      const scopeTasks = punchListScopeTasks(sub);
      if (!(sub.items||[]).length && !scopeTasks.length) return;
      const qtyDisplay = materialItems.length === 1 ? `${materialItems[0].qty||1} ${materialItems[0].unit||''}`.trim() : '';

      let rows;
      if (!scopeTasks.length) {
        rows = `<tr>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:24px"><div style="width:18px;height:18px;border:2px solid #374151;border-radius:3px;display:inline-block"></div></td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;font-weight:600">${esc(customerSafeLabel(sub))}</td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;white-space:nowrap;color:#6b7280">${esc(qtyDisplay)}</td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:220px;color:#9ca3af;font-style:italic;font-size:.82rem">Notes: ________________</td>
        </tr>`;
      } else {
        rows = scopeTasks.map((task, taskIndex) => `<tr>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:24px"><div style="width:18px;height:18px;border:2px solid #374151;border-radius:3px;display:inline-block"></div></td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;font-weight:600">${esc(task)}</td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;white-space:nowrap;color:#6b7280">${taskIndex === 0 ? esc(qtyDisplay) : ''}</td>
          <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:220px;color:#9ca3af;font-style:italic;font-size:.82rem">Notes: ________________</td>
        </tr>`).join('');
      }

      punchPages.push({
        title: customerSafeLabel(sub),
        parent: group.name || '',
        rows
      });
    });

    const directRows = (group.directItems||[]).filter(i => i.costType !== 'Labor' && (i.unit||'').toLowerCase() !== 'hr').map(item => {
      const gradeWord = item.bundleTier ? ({ low: 'Low Grade', med: 'Medium Grade', high: 'High Grade' }[item.bundleTier] || '') : '';
      const label = gradeWord ? itemDescriptionText(item.desc) + ' — ' + gradeWord : itemDescriptionText(item.desc);
      return `<tr>
        <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:24px"><div style="width:18px;height:18px;border:2px solid #374151;border-radius:3px;display:inline-block"></div></td>
        <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;font-weight:600">${esc(label)}</td>
        <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;white-space:nowrap;color:#6b7280">${(item.qty||1)} ${item.unit||''}</td>
        <td style="padding:10px 8px;border-bottom:1px solid #e5e7eb;width:200px;color:#9ca3af;font-style:italic;font-size:.82rem">Notes: ________________</td>
      </tr>`;
    }
    ).join('');

    // Legacy estimates can have items directly on a group with no subgroup.
    // Preserve those on their own page rather than dropping them.
    if (directRows) punchPages.push({ title: group.name || 'General', parent: '', rows: directRows });
  });

  const punchPageHeader = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px;padding-bottom:14px;border-bottom:3px solid #d97706">
      <div>
        ${co.logo?`<img src="${co.logo}" style="height:44px;object-fit:contain;margin-bottom:4px"><br>`:''}
        <strong style="font-size:1rem">${esc(co.companyName||'')}</strong>
      </div>
      <div style="text-align:right">
        <div style="font-size:1.3rem;font-weight:900">PUNCH LIST / WORK ORDER</div>
        <div style="font-size:1rem;font-weight:700">${esc(job?.name||'')}</div>
        <div style="color:#6b7280">${esc(job?.address||'')}</div>
        <div style="color:#6b7280;font-size:.85rem">Date: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; Crew: ___________________</div>
      </div>
    </div>`;

  const groupSections = punchPages.map((page, idx) => {
    const isLast = idx === punchPages.length - 1;
    return `<section style="${isLast ? '' : 'page-break-after:always;'}">
      ${punchPageHeader}
      <div style="margin-bottom:28px;border:2px solid #d97706;border-radius:8px;overflow:hidden">
      <div style="background:#d97706;color:#fff;padding:10px 14px">
        <div style="font-size:1.1rem;font-weight:900">${esc(page.title)}</div>
        ${page.parent ? `<div style="font-size:.75rem;font-weight:700;opacity:.85;margin-top:2px">${esc(page.parent)}</div>` : ''}
      </div>
      <table style="width:100%;border-collapse:collapse">
        <thead><tr style="background:#f3f4f6">
          <th style="padding:7px 8px;text-align:left;font-size:.75rem;color:#6b7280;font-weight:700">✓</th>
          <th style="padding:7px 8px;text-align:left;font-size:.75rem;color:#6b7280;font-weight:700">ITEM</th>
          <th style="padding:7px 8px;text-align:left;font-size:.75rem;color:#6b7280;font-weight:700">QTY</th>
          <th style="padding:7px 8px;text-align:left;font-size:.75rem;color:#6b7280;font-weight:700">NOTES</th>
        </tr></thead>
        <tbody>${page.rows}</tbody>
      </table>
      <div style="padding:10px 14px;background:#fffbeb;border-top:1px solid #fde68a">
        <div style="font-size:.78rem;color:#92400e;font-weight:700">Field Notes:</div>
        <div style="height:48px;border-bottom:1px solid #d1d5db;margin-top:4px"></div>
        <div style="height:48px;border-bottom:1px solid #d1d5db;margin-top:8px"></div>
      </div>
      </div>
    </section>`;
  }).join('');

  // Job-wide crew day estimate — the ONLY place labor time appears on this
  // sheet, and only as a whole-job estimate, not per room or per item.
  const days2Man = totalLaborHours > 0 ? Math.ceil(totalLaborHours / (2 * 8)) : 0;
  const days3Man = totalLaborHours > 0 ? Math.ceil(totalLaborHours / (3 * 8)) : 0;
  const dayEstimateBlock = totalLaborHours > 0 ? `
    <div style="margin-top:20px;padding:16px;background:#1a1a1a;color:#fff;border-radius:8px;text-align:center">
      <div style="font-size:.75rem;text-transform:uppercase;letter-spacing:.06em;color:#d97706;font-weight:700;margin-bottom:6px">Estimated Job Duration</div>
      <div style="font-size:1.3rem;font-weight:900">
        2-Man Crew: ~${days2Man} day${days2Man!==1?'s':''} &nbsp;|&nbsp; 3-Man Crew: ~${days3Man} day${days3Man!==1?'s':''}
      </div>
    </div>` : '';

  win.document.write(`<!DOCTYPE html><html><head><title>Punch List — ${esc(job?.name||'')}</title>
  <style>
    body{font-family:Arial,sans-serif;max-width:900px;margin:20px auto;padding:0 16px;color:#111}
    @media print{body{margin:10px} .no-print{display:none} section{break-inside:avoid;page-break-inside:avoid} div{page-break-inside:avoid}}
  </style></head><body>
  ${groupSections}
  ${dayEstimateBlock}
  <div style="margin-top:20px;padding:14px;border:1px solid #e5e7eb;border-radius:8px">
    <div style="font-weight:700;margin-bottom:6px">General Notes:</div>
    <div style="height:60px;border-bottom:1px solid #d1d5db"></div>
    <div style="height:60px;border-bottom:1px solid #d1d5db;margin-top:8px"></div>
  </div>
  <div style="margin-top:16px;text-align:center;color:#9ca3af;font-size:.75rem">
    ${esc(co.companyName||'')} Punch List · ${esc(job?.name||'')} · Printed ${new Date().toLocaleString()}
  </div>
  <script>window.print();<\/script></body></html>`);
  win.document.close();
}

