// Real materials-package SKUs (brush/tape/paper/roller covers) from the
// invoice-history audit catalog — same items JobTread's real template
// itemizes individually, rather than a flat lump-sum line.
const PAINT_MATERIALS_PACKAGE_ITEMS = [
  { desc: "3M ScotchBlue 1.88 in. x 60 yds. Original Multi-Surface Painter's Tape (6-Pack)", unitCost: 39.48, unitPrice: 49.35 },
  { desc: '35 in. x 200 ft. Builders Paper', unitCost: 18.98, unitPrice: 23.725 },
  { desc: '9 in. x 3/8 in. High-Density Polyester Knit Paint Roller Cover (3-Pack)', unitCost: 8.48, unitPrice: 10.6 },
  { desc: 'Premium 2 in. Polyester Trylon Thin Angled Sash Paint Brush', unitCost: 9.33, unitPrice: 11.663 },
];
const PAINT_PACKAGE_COST = PAINT_MATERIALS_PACKAGE_ITEMS.reduce((s, i) => s + i.unitCost, 0);   // 76.27, per package (kept for preview totals)
const PAINT_PACKAGE_PRICE = PAINT_MATERIALS_PACKAGE_ITEMS.reduce((s, i) => s + i.unitPrice, 0); // 95.34
const PAINT_PRODUCT = {
  low:  { cost: 0.60, price: 0.75 },
  med:  { cost: 0.60, price: 0.75 },
  high: { cost: 1.80, price: 2.25 }
};
const PAINT_LABOR = {
  low:  { cost: 3.00, price: 3.45 },
  med:  { cost: 3.00, price: 3.45 },
  high: { cost: 4.50, price: 5.18 }  // 1.5x the low/med rate
};
const PAINT_GRADE_LABELS = { low: 'Low', med: 'Medium', high: 'High' };

function paintPackagesForSqft(sqft) {
  if (sqft <= 0) return 0;
  return Math.ceil(sqft / 1000);
}

let _tplSelectedArea = null;
let _tplSelectedRoom = null;
let _tplSelectedCategory = null;
let _tplSelectedGrade = 'low';

function openTemplatePicker() {
  _tplSelectedArea = null;
  _tplSelectedRoom = null;
  _tplSelectedCategory = null;
  _tplSelectedGrade = 'low';
  tplGoToAreas();
  kOpen('templatePickerModal');
}
window.openTemplatePicker = openTemplatePicker;

function tplUpdateBreadcrumb() {
  const el = document.getElementById('tplBreadcrumb');
  if (!el) return;
  let html = '<span onclick="tplGoToAreas()">Rooms</span>';
  if (_tplSelectedArea) html += ' › <span onclick="tplGoToRooms(\'' + esc(_tplSelectedArea) + '\')">' + esc(_tplSelectedArea) + '</span>';
  if (_tplSelectedRoom) html += ' › <span onclick="tplGoToCategories()">' + esc(_tplSelectedRoom) + '</span>';
  if (_tplSelectedCategory) html += ' › <span onclick="tplGoToItems()">' + esc(_tplSelectedCategory) + '</span>';
  el.innerHTML = html;
}

function tplGoToAreas() {
  _tplSelectedArea = null;
  _tplSelectedRoom = null;
  _tplSelectedCategory = null;
  document.getElementById('tplStepAreas').style.display = 'block';
  document.getElementById('tplStepRooms').style.display = 'none';
  document.getElementById('tplStepCategories').style.display = 'none';
  document.getElementById('tplStepItems').style.display = 'none';
  document.getElementById('tplStepPaintForm').style.display = 'none';
  document.getElementById('tplStepLinearForm').style.display = 'none';
  document.getElementById('tplStepTieredForm').style.display = 'none';
  const grid = document.getElementById('tplAreaGrid');
  const icons = { 'Interior': '🏠', 'Exterior': '🌳', 'Global / Whole-House': '🏗️' };
  grid.innerHTML = Object.keys(TPL_ROOM_GROUPS).map(area =>
    `<div class="wizard-category-card" onclick="tplGoToRooms('${esc(area)}')">${icons[area] || ''} ${esc(area)}</div>`
  ).join('');
  tplUpdateBreadcrumb();
}
window.tplGoToAreas = tplGoToAreas;

function tplGoToRooms(area) {
  _tplSelectedArea = area || _tplSelectedArea;
  _tplSelectedRoom = null;
  _tplSelectedCategory = null;
  document.getElementById('tplStepAreas').style.display = 'none';
  document.getElementById('tplStepRooms').style.display = 'block';
  document.getElementById('tplStepCategories').style.display = 'none';
  document.getElementById('tplStepItems').style.display = 'none';
  document.getElementById('tplStepPaintForm').style.display = 'none';
  document.getElementById('tplStepLinearForm').style.display = 'none';
  document.getElementById('tplStepTieredForm').style.display = 'none';
  const titleEl = document.getElementById('tplRoomAreaTitle');
  if (titleEl) titleEl.textContent = _tplSelectedArea + ' — which room?';
  const grid = document.getElementById('tplRoomGrid');
  const rooms = TPL_ROOM_GROUPS[_tplSelectedArea] || TPL_ROOMS;
  grid.innerHTML = rooms.map(r =>
    `<div class="wizard-category-card" onclick="tplSelectRoom('${esc(r)}')">${esc(r)}</div>`
  ).join('');
  tplUpdateBreadcrumb();
}
window.tplGoToRooms = tplGoToRooms;

function tplSelectRoom(room) {
  _tplSelectedRoom = room;
  tplGoToCategories();
}
window.tplSelectRoom = tplSelectRoom;

function tplGoToCategories() {
  _tplSelectedCategory = null;
  document.getElementById('tplStepRooms').style.display = 'none';
  document.getElementById('tplStepCategories').style.display = 'block';
  document.getElementById('tplStepItems').style.display = 'none';
  document.getElementById('tplStepPaintForm').style.display = 'none';
  document.getElementById('tplStepLinearForm').style.display = 'none';
  document.getElementById('tplStepTieredForm').style.display = 'none';
  document.getElementById('tplCategoryRoomTitle').textContent = _tplSelectedRoom;
  const grid = document.getElementById('tplCategoryGrid');
  grid.innerHTML = TPL_CATEGORIES.map(c =>
    `<div class="wizard-category-card" onclick="tplSelectCategory('${esc(c)}')">${esc(c)}</div>`
  ).join('');
  tplUpdateBreadcrumb();
}
window.tplGoToCategories = tplGoToCategories;

function tplSelectCategory(cat) {
  _tplSelectedCategory = cat;
  tplGoToItems();
}
window.tplSelectCategory = tplSelectCategory;

function tplGoToItems() {
  document.getElementById('tplStepRooms').style.display = 'none';
  document.getElementById('tplStepCategories').style.display = 'none';
  document.getElementById('tplStepItems').style.display = 'block';
  document.getElementById('tplStepPaintForm').style.display = 'none';
  document.getElementById('tplStepLinearForm').style.display = 'none';
  document.getElementById('tplStepTieredForm').style.display = 'none';
  document.getElementById('tplItemCategoryTitle').textContent = _tplSelectedCategory;
  const items = TPL_ITEMS_BY_CATEGORY[_tplSelectedCategory] || [];
  const grid = document.getElementById('tplItemGrid');
  if (!items.length) {
    grid.innerHTML = '<div class="small muted" style="padding:20px;text-align:center;grid-column:1/-1">Coming soon — being built out category by category.</div>';
  } else {
    grid.innerHTML = items.map(it =>
      `<div class="wizard-category-card" onclick="tplSelectItem('${esc(it.key)}')">${esc(it.label)}</div>`
    ).join('');
  }
  tplUpdateBreadcrumb();
}
window.tplGoToItems = tplGoToItems;

function tplSelectItem(key) {
  const itemDef = (TPL_ITEMS_BY_CATEGORY[_tplSelectedCategory] || []).find(it => it.key === key);

  if (key === 'paint') {
    document.getElementById('tplStepRooms').style.display = 'none';
    document.getElementById('tplStepCategories').style.display = 'none';
    document.getElementById('tplStepItems').style.display = 'none';
    document.getElementById('tplStepPaintForm').style.display = 'block';
    document.getElementById('tplPaintSqft').value = '';
    _tplSelectedGrade = 'low';
    tplRefreshGradeButtons();
    tplUpdatePaintPreview();
  } else if (LINEAR_ITEMS[key]) {
    _tplLinearKey = key;
    document.getElementById('tplStepRooms').style.display = 'none';
    document.getElementById('tplStepCategories').style.display = 'none';
    document.getElementById('tplStepItems').style.display = 'none';
    document.getElementById('tplStepLinearForm').style.display = 'block';
    document.getElementById('tplLinearTitle').textContent = LINEAR_ITEMS[key].title;
    document.getElementById('tplLinearLabel').textContent = LINEAR_ITEMS[key].unitLabel || 'Quantity';
    document.getElementById('tplLinearFeet').value = '';
    tplUpdateLinearPreview();
  } else if (itemDef && itemDef.tieredRef) {
    tplOpenTieredForm(itemDef.tieredRef, itemDef.label);
  }
}
window.tplSelectItem = tplSelectItem;

let _tplTieredBundle = null;

// Opens the tier-select form for an existing Smart Add bundle, reused here
// so Doors/Drywall/Flooring items get properly tagged with the Room
// selected in Templates, without duplicating their real catalog data.
function tplOpenTieredForm(tieredRef, label) {
  const bundles = TIERED_BUNDLES[tieredRef.trade] || [];
  _tplTieredBundle = bundles.find(b => b.name === tieredRef.name);
  if (!_tplTieredBundle) { alert('Could not find bundle data for ' + tieredRef.name); return; }

  document.getElementById('tplStepRooms').style.display = 'none';
  document.getElementById('tplStepCategories').style.display = 'none';
  document.getElementById('tplStepItems').style.display = 'none';
  document.getElementById('tplStepTieredForm').style.display = 'block';
  document.getElementById('tplTieredTitle').textContent = label;

  const tierColors = { low: '#34d399', med: '#f59e0b', high: '#ef4444' };
  const tierEmoji = { low: '🟢', med: '🟡', high: '🔴' };
  const grid = document.getElementById('tplTieredTierGrid');
  grid.innerHTML = Object.entries(_tplTieredBundle.tiers).map(([tierKey, tier]) => {
    const total = tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0);
    const color = tierColors[tierKey];
    return `<div onclick="tplSelectTieredTier('${tierKey}')" style="border:2px solid ${color}22;border-radius:14px;padding:14px 16px;margin-bottom:10px;cursor:pointer;background:${color}08">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <div style="font-weight:800;font-size:.95rem">${tierEmoji[tierKey]} ${esc(tier.label)}</div>
        <div style="font-weight:900;color:${color}">$${total.toFixed(0)}</div>
      </div>
      <div style="font-size:.76rem;color:var(--muted)">${esc(tier.priceRange)}</div>
    </div>`;
  }).join('');
}
window.tplOpenTieredForm = tplOpenTieredForm;

async function tplSelectTieredTier(tierKey) {
  if (!conCurrentJobId || !_tplTieredBundle) return;
  const tier = _tplTieredBundle.tiers[tierKey];

  let group = estGroups.find(g => g.name.toLowerCase() === _tplSelectedRoom.toLowerCase());
  if (!group) {
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: _tplSelectedRoom, order: estGroups.length,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: _tplSelectedRoom, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }

  let subgroup = (group.subgroups || []).find(s => s.name.toLowerCase() === _tplSelectedCategory.toLowerCase());
  if (!subgroup) {
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(group.id).collection('subgroups').add({
        name: _tplSelectedCategory, order: group.subgroups?.length || 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    subgroup = { id: subRef.id, name: _tplSelectedCategory, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
  }

  let order = 0;
  for (const line of tier.lines) {
    await coll('jobs').doc(conCurrentJobId)
      .collection('estimateGroups').doc(group.id)
      .collection('subgroups').doc(subgroup.id)
      .collection('items').add({
        desc: line.desc, qty: line.qty, unit: line.unit,
        costType: line.type === 'labor' ? 'Labor' : (line.type === 'subcontractor' ? 'Subcontractor' : 'Materials'),
        unitCost: line.unitCost, unitPrice: line.unitPrice,
        markup: Math.round((line.unitPrice / line.unitCost - 1) * 100),
        bundleTier: tierKey,
        order: order++, createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
  }

  kClose('templatePickerModal');
  if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
}
window.tplSelectTieredTier = tplSelectTieredTier;

let _tplLinearKey = null;

function tplComputeLinear() {
  const feet = parseFloat(document.getElementById('tplLinearFeet')?.value) || 0;
  const item = LINEAR_ITEMS[_tplLinearKey];
  if (!item) return { feet: 0, totalCost: 0, totalPrice: 0 };
  const matCost = item.material ? feet * item.material.unitCost : 0;
  const matPrice = item.material ? feet * item.material.unitPrice : 0;
  const laborCost = feet * item.labor.unitCost;
  const laborPrice = feet * item.labor.unitPrice;
  return { feet, matCost, matPrice, laborCost, laborPrice, totalCost: matCost + laborCost, totalPrice: matPrice + laborPrice };
}

function tplUpdateLinearPreview() {
  const r = tplComputeLinear();
  const item = LINEAR_ITEMS[_tplLinearKey];
  const el = document.getElementById('tplLinearPreview');
  if (!el) return;
  if (r.feet <= 0) { el.innerHTML = '<span class="muted">Enter linear feet to see pricing.</span>'; return; }
  const unitAbbr = item.qtyUnit === 'ea' ? 'ea' : 'lf';
  let html = '';
  if (item.material) {
    html += `<div style="display:flex;justify-content:space-between;margin-bottom:6px"><span>Material (${r.feet} ${unitAbbr} @ $${item.material.unitPrice.toFixed(2)}/${unitAbbr})</span><strong>$${r.matPrice.toFixed(2)}</strong></div>`;
  }
  html += `<div style="display:flex;justify-content:space-between;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid rgba(29,187,135,.25)"><span>Labor (${r.feet} ${unitAbbr} @ $${item.labor.unitPrice.toFixed(2)}/${unitAbbr})</span><strong>$${r.laborPrice.toFixed(2)}</strong></div>`;
  html += `<div style="display:flex;justify-content:space-between;font-size:1rem;font-weight:800"><span>Total</span><span>$${r.totalPrice.toFixed(2)}</span></div>`;
  el.innerHTML = html;
}
window.tplUpdateLinearPreview = tplUpdateLinearPreview;

async function tplAddLinearToEstimate() {
  if (!conCurrentJobId) { alert('Open a job first.'); return; }
  const r = tplComputeLinear();
  if (r.feet <= 0) { alert('Enter a linear footage greater than 0.'); return; }
  const item = LINEAR_ITEMS[_tplLinearKey];

  let group = estGroups.find(g => g.name.toLowerCase() === _tplSelectedRoom.toLowerCase());
  if (!group) {
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: _tplSelectedRoom, order: estGroups.length,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: _tplSelectedRoom, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }

  let subgroup = (group.subgroups || []).find(s => s.name.toLowerCase() === _tplSelectedCategory.toLowerCase());
  if (!subgroup) {
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(group.id).collection('subgroups').add({
        name: _tplSelectedCategory, order: group.subgroups?.length || 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    subgroup = { id: subRef.id, name: _tplSelectedCategory, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
  }

  const itemsToAdd = [];
  if (item.material) {
    itemsToAdd.push({
      desc: item.material.desc, qty: r.feet, unit: item.qtyUnit || 'lf', costType: 'Materials',
      unitCost: item.material.unitCost, unitPrice: item.material.unitPrice,
      markup: Math.round((item.material.unitPrice / item.material.unitCost - 1) * 100)
    });
  }
  itemsToAdd.push({
    desc: item.labor.desc, qty: r.feet, unit: item.qtyUnit || 'lf', costType: 'Labor',
    unitCost: item.labor.unitCost, unitPrice: item.labor.unitPrice,
    markup: Math.round((item.labor.unitPrice / item.labor.unitCost - 1) * 100)
  });

  let order = 0;
  for (const it of itemsToAdd) {
    await coll('jobs').doc(conCurrentJobId)
      .collection('estimateGroups').doc(group.id)
      .collection('subgroups').doc(subgroup.id)
      .collection('items').add({ ...it, order: order++, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
  }

  kClose('templatePickerModal');
  if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
}
window.tplAddLinearToEstimate = tplAddLinearToEstimate;

function tplRefreshGradeButtons() {
  document.querySelectorAll('.tpl-grade-btn').forEach(btn => {
    const active = btn.getAttribute('data-grade') === _tplSelectedGrade;
    btn.style.background = active ? 'linear-gradient(135deg,#1dbb87,#0d9488)' : '';
    btn.style.color = active ? '#fff' : '';
    btn.style.borderColor = active ? '#1dbb87' : '';
  });
}

function tplSelectPaintGrade(grade) {
  _tplSelectedGrade = grade;
  tplRefreshGradeButtons();
  tplUpdatePaintPreview();
}
window.tplSelectPaintGrade = tplSelectPaintGrade;

function tplComputePaint() {
  const sqft = parseFloat(document.getElementById('tplPaintSqft')?.value) || 0;
  const grade = _tplSelectedGrade;
  const numPackages = paintPackagesForSqft(sqft);
  const pkgCost = numPackages * PAINT_PACKAGE_COST;
  const pkgPrice = numPackages * PAINT_PACKAGE_PRICE;
  const paintCost = sqft * PAINT_PRODUCT[grade].cost;
  const paintPrice = sqft * PAINT_PRODUCT[grade].price;
  const laborCost = sqft * PAINT_LABOR[grade].cost;
  const laborPrice = sqft * PAINT_LABOR[grade].price;
  return {
    sqft, grade, numPackages,
    pkgCost, pkgPrice, paintCost, paintPrice, laborCost, laborPrice,
    totalCost: pkgCost + paintCost + laborCost,
    totalPrice: pkgPrice + paintPrice + laborPrice
  };
}

function tplUpdatePaintPreview() {
  const r = tplComputePaint();
  const el = document.getElementById('tplPaintPreview');
  if (!el) return;
  if (r.sqft <= 0) { el.innerHTML = '<span class="muted">Enter square footage to see pricing.</span>'; return; }
  el.innerHTML = `
    <div style="display:flex;justify-content:space-between;margin-bottom:6px"><span>Materials Package × ${r.numPackages} (per 1000 sqft)</span><strong>$${r.pkgPrice.toFixed(2)}</strong></div>
    <div style="display:flex;justify-content:space-between;margin-bottom:6px"><span>Paint (${r.sqft} sqft @ $${PAINT_PRODUCT[r.grade].price.toFixed(2)}/sqft)</span><strong>$${r.paintPrice.toFixed(2)}</strong></div>
    <div style="display:flex;justify-content:space-between;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid rgba(29,187,135,.25)"><span>Labor (${r.sqft} sqft @ $${PAINT_LABOR[r.grade].price.toFixed(2)}/sqft)</span><strong>$${r.laborPrice.toFixed(2)}</strong></div>
    <div style="display:flex;justify-content:space-between;font-size:1rem;font-weight:800"><span>Total (${PAINT_GRADE_LABELS[r.grade]} Grade)</span><span>$${r.totalPrice.toFixed(2)}</span></div>
  `;
}
window.tplUpdatePaintPreview = tplUpdatePaintPreview;

async function tplAddPaintToEstimate() {
  if (!conCurrentJobId) { alert('Open a job first.'); return; }
  const r = tplComputePaint();
  if (r.sqft <= 0) { alert('Enter a square footage greater than 0.'); return; }

  // Find or create the Room (Epic/Group)
  let group = estGroups.find(g => g.name.toLowerCase() === _tplSelectedRoom.toLowerCase());
  if (!group) {
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: _tplSelectedRoom, order: estGroups.length,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: _tplSelectedRoom, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }

  // Find or create the Category (Feature/Subgroup) under that room
  let subgroup = (group.subgroups || []).find(s => s.name.toLowerCase() === _tplSelectedCategory.toLowerCase());
  if (!subgroup) {
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(group.id).collection('subgroups').add({
        name: _tplSelectedCategory, order: group.subgroups?.length || 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    subgroup = { id: subRef.id, name: _tplSelectedCategory, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
  }

  const gradeLabel = PAINT_GRADE_LABELS[r.grade];
  const itemsToAdd = [
    ...PAINT_MATERIALS_PACKAGE_ITEMS.map(pkgItem => ({
      desc: pkgItem.desc,
      qty: r.numPackages, unit: 'ea', costType: 'Materials',
      unitCost: pkgItem.unitCost, unitPrice: pkgItem.unitPrice,
      markup: Math.round((pkgItem.unitPrice / pkgItem.unitCost - 1) * 100)
    })),
    {
      desc: 'Paint — 1 Coat (' + gradeLabel + ' Grade)',
      qty: r.sqft, unit: 'sqft', costType: 'Materials',
      unitCost: PAINT_PRODUCT[r.grade].cost, unitPrice: PAINT_PRODUCT[r.grade].price,
      markup: Math.round((PAINT_PRODUCT[r.grade].price / PAINT_PRODUCT[r.grade].cost - 1) * 100)
    },
    {
      desc: 'Paint Labor — 1 Coat Per Sqft (' + gradeLabel + ' Grade)',
      qty: r.sqft, unit: 'hr', costType: 'Labor',
      unitCost: PAINT_LABOR[r.grade].cost, unitPrice: PAINT_LABOR[r.grade].price,
      markup: Math.round((PAINT_LABOR[r.grade].price / PAINT_LABOR[r.grade].cost - 1) * 100)
    }
  ];

  let order = 0;
  for (const item of itemsToAdd) {
    await coll('jobs').doc(conCurrentJobId)
      .collection('estimateGroups').doc(group.id)
      .collection('subgroups').doc(subgroup.id)
      .collection('items').add({ ...item, order: order++, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
  }

  kClose('templatePickerModal');
  if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
}
window.tplAddPaintToEstimate = tplAddPaintToEstimate;

function openSmartAdd() {
  _launchSmartAdd();
}

function _launchSmartAdd() {
  _wizardStep = 1;
  _wizardCategory = null;
  _wizardRoom = null;
  _wizardTrade = null;
  _wizardPhaseLabel = null;
  _wizardSelectedItems = new Set();
  wizardSelectCategory('Whole House');
  kOpen('smartAddModal');
}

function wizardSelectCategory(cat) {
  _wizardCategory = cat;
  _wizardStep = 2;
  const rooms = ROOM_STRUCTURE[cat]?.rooms || {};
  const grid = document.getElementById('wizardRoomGrid');
  if (!grid) return;

  grid.innerHTML = Object.entries(rooms).map(([room, data]) => {
    const tradeCount = data.phases.length;
    return `<div class="wizard-card" onclick="wizardSelectRoom('${room.replace(/'/g,"\\'")}')">
      <div class="wc-icon">${data.icon}</div>
      <div class="wc-name">${room}</div>
      <div class="wc-count">${tradeCount} trade${tradeCount!==1?'s':''}</div>
    </div>`;
  }).join('');

  wizardSetStep(2);
  updateWizardBreadcrumb();
}

function wizardSelectRoom(room) {
  _wizardRoom = room;
  _wizardStep = 3;
  const phases = ROOM_STRUCTURE[_wizardCategory]?.rooms[room]?.phases || [];
  const grid = document.getElementById('wizardTradeGrid');
  if (!grid) return;

  grid.innerHTML = phases.map(phase => {
    const icon = PHASE_ICONS[phase.label] || '🔨';
    const items = CATALOG_DATA[phase.trade] || [];
    return `<div class="wizard-trade-btn" onclick="wizardSelectPhase('${phase.label.replace(/'/g,"\\'")}','${phase.trade.replace(/'/g,"\\'")}')">
      ${icon} ${esc(phase.label)}<div style="font-size:.68rem;color:var(--muted);font-weight:400;margin-top:2px">${items.length} items</div>
    </div>`;
  }).join('');

  wizardSetStep(3);
  updateWizardBreadcrumb();
}

// Wraps wizardSelectTrade() to also remember the exact phase label
// (e.g. "Electrical: rough" vs "Electrical: final") separately from the
// underlying catalog trade code, since two phases in the same room can
// share a trade code but need distinct breadcrumb/subgroup naming.
function wizardSelectPhase(label, trade) {
  try {
    _wizardPhaseLabel = label;
    wizardSelectTrade(trade);
  } catch (e) {
    console.error('wizardSelectPhase failed:', label, trade, e);
    alert('Smart Add error on "' + label + '": ' + e.message + '\n\nPlease screenshot this and send it over.');
  }
}

function wizardSelectTrade(trade) {
  _wizardTrade = trade;
  _wizardStep = 4;
  _wizardSelectedItems = new Set();
  _wizardCurrentItems = CATALOG_DATA[trade] || [];

  // Check if this trade has tiered bundles
  const bundles = TIERED_BUNDLES[trade] || [];

  if (bundles.length === 1) {
    // Only one bundle exists for this trade — showing a list with a
    // single option to tap is pointless friction. Go straight to it,
    // same principle already used elsewhere (e.g. Toilet Replacement
    // skips the grade question for Round since there's only one real
    // product).
    wizardSelectBundle(bundles[0].name);
  } else if (bundles.length > 1) {
    // Step 4: Show bundle tasks for this trade
    wizardRenderBundleTasks(trade, bundles);
  } else {
    // No bundles — fall through to catalog items with template tab
    wizardSetStep(4);
    updateWizardBreadcrumb();
    document.getElementById('wizardSearchInput').value = '';

    const itemListEl = document.getElementById('wizardItemList');
    if (itemListEl) {
      itemListEl.innerHTML =
        '<div style="display:flex;gap:0;background:rgba(8,18,36,.8);border:1px solid rgba(110,145,210,.15);border-radius:10px;overflow:hidden;margin-bottom:12px">' +
        '<button id="wizTabTemplates" onclick="wizShowTab(\'templates\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:.8rem;font-weight:700;background:linear-gradient(135deg,var(--amber),var(--amber2));color:#fff">⚡ Templates</button>' +
        '<button id="wizTabItems" onclick="wizShowTab(\'items\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:.8rem;font-weight:600;background:transparent;color:var(--muted)">📦 Catalog Items</button>' +
        '</div><div id="wizPanelTemplates"></div><div id="wizPanelItems" style="display:none"></div>';
    }
    wizLoadTemplates(trade);

    const itemsPanel = document.getElementById('wizPanelItems');
    if (itemsPanel) {
      itemsPanel.innerHTML = _wizardCurrentItems.length ? _wizardCurrentItems.map(item => {
        const matPrice = item.materials?.unitPrice || 0;
        const labPrice = item.labor?.unitPrice || 0;
        const totalPrice = matPrice + labPrice;
        return '<div class="wizard-item" onclick="wizardToggleItem(\'' + item.name.replace(/'/g,"\\'") + '\',this)">' +
          '<div class="wizard-item-check"></div>' +
          '<div class="wizard-item-info"><div class="wizard-item-name">' + esc(item.name) + '</div>' +
          '<div class="wizard-item-meta">' + (item.materials ? '📦 Mat: $' + matPrice.toFixed(2) : '') + (item.labor ? ' · 👷 Labor: $' + labPrice.toFixed(2) + '/hr' : '') + '</div></div>' +
          '<div class="wizard-item-price">' + (totalPrice > 0 ? '$' + totalPrice.toFixed(2) : '') + '</div></div>';
      }).join('') : '<div class="small muted" style="text-align:center;padding:20px">No items for this trade</div>';
    }

    const footer = document.getElementById('wizardFooter');
    if (footer) footer.innerHTML =
      '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>' +
      '<button class="btn-amber" onclick="wizardAddToEstimate()" style="min-width:140px">➕ Add to Estimate</button>';
  }
}

// ── Step 4b: Bundle task grid ──
let _wizardBundle = null;
let _wizardTier = null;
let _wizardBundleQty = 1;

function wizardRenderBundleTasks(trade, bundles) {
  wizardSetStep(4);
  updateWizardBreadcrumb();
  document.getElementById('wizardSearchInput').value = '';

  const itemListEl = document.getElementById('wizardItemList');
  if (!itemListEl) return;

  // Hide search row
  const searchRow = document.getElementById('wizardSearchRow');
  if (searchRow) searchRow.style.display = 'none';

  itemListEl.innerHTML =
    '<div style="font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:10px">Select a job bundle:</div>' +
    bundles.map(b =>
      '<div onclick="wizardSelectBundle(\'' + b.name.replace(/'/g,"\\'") + '\')" ' +
      'style="border:1px solid rgba(110,145,210,.15);border-radius:12px;padding:14px;margin-bottom:10px;cursor:pointer;display:flex;align-items:center;gap:14px" ' +
      'onmouseover="this.style.borderColor=\'rgba(217,119,6,.4)\';this.style.background=\'rgba(217,119,6,.05)\'" ' +
      'onmouseout="this.style.borderColor=\'rgba(110,145,210,.15)\';this.style.background=\'\'">' +
      '<div style="font-size:2rem;flex-shrink:0">' + b.icon + '</div>' +
      '<div><div style="font-weight:800;font-size:.95rem;color:#eaf0fb">' + esc(b.name) + '</div>' +
      '<div style="font-size:.76rem;color:var(--muted);margin-top:2px">' + esc(b.desc) + '</div>' +
      '<div style="font-size:.72rem;color:var(--amber);margin-top:4px">' +
      Object.values(b.tiers).map(t => t.label).join(' · ') + '</div></div></div>'
    ).join('') +
    '<button onclick="wizardSelectTradeFallback(\'' + trade.replace(/'/g,"\\'") + '\')" ' +
    'style="width:100%;margin-top:4px;padding:10px;background:transparent;border:1px dashed rgba(110,145,210,.2);border-radius:10px;color:var(--muted);font-size:.82rem;cursor:pointer">' +
    '📦 Browse individual catalog items instead</button>' +
    wizardCustomItemCardHtml();

  const footer = document.getElementById('wizardFooter');
  if (footer) footer.innerHTML = '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>';
}

let _wizardShape = null;

function wizardSelectBundle(bundleName) {
  const bundles = TIERED_BUNDLES[_wizardTrade] || [];
  _wizardBundle = bundles.find(b => b.name === bundleName);
  if (!_wizardBundle) return;
  _wizardTier = null;
  _wizardShape = null;
  _wizardBundleQty = 1;

  // Toilet Replacement has a real shape distinction (Round vs Oblong/
  // Elongated) in the underlying catalog data — ask that first, since
  // it's a separate decision from grade, not a grade itself.
  if (_wizardBundle.name === 'Toilet Replacement') {
    wizardRenderShapeSelect();
  } else {
    wizardRenderTierSelect();
  }
}
window.wizardSelectBundle = wizardSelectBundle;

// Only Toilet Replacement uses this right now. Round only has one real
// product in the catalog (no separate Round-Medium/Round-High SKU), so
// picking Round skips straight to quantity — no pointless grade question
// when there's nothing to choose between.
function wizardRenderShapeSelect() {
  const itemListEl = document.getElementById('wizardItemList');
  if (!itemListEl || !_wizardBundle) return;
  wizardSetStep(4);
  updateWizardBreadcrumb();
  const searchRow = document.getElementById('wizardSearchRow');
  if (searchRow) searchRow.style.display = 'none';

  itemListEl.innerHTML =
    '<div style="text-align:center;margin-bottom:16px">' +
    '<div style="font-size:1.8rem">' + _wizardBundle.icon + '</div>' +
    '<div style="font-weight:800;font-size:1rem;color:#eaf0fb;margin-top:6px">' + esc(_wizardBundle.name) + '</div>' +
    '<div style="font-size:.78rem;color:var(--muted);margin-top:2px">' + esc(_wizardBundle.desc) + '</div></div>' +
    '<div style="font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:10px">Round or Oblong?</div>' +
    '<div onclick="wizardSelectShape(\'round\')" style="border:2px solid rgba(217,119,6,.25);border-radius:14px;padding:16px;margin-bottom:10px;cursor:pointer;text-align:center;font-weight:800;color:#eaf0fb">⭕ Round</div>' +
    '<div onclick="wizardSelectShape(\'oblong\')" style="border:2px solid rgba(217,119,6,.25);border-radius:14px;padding:16px;margin-bottom:10px;cursor:pointer;text-align:center;font-weight:800;color:#eaf0fb">⬭ Oblong (Elongated)</div>' +
    '<button onclick="wizardRenderBundleTasks(_wizardTrade, TIERED_BUNDLES[_wizardTrade]||[])" ' +
    'style="background:none;border:none;color:var(--muted);font-size:.8rem;cursor:pointer;margin-top:6px">← Back to bundles</button>';

  const footer = document.getElementById('wizardFooter');
  if (footer) footer.innerHTML = '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>';
}
window.wizardRenderShapeSelect = wizardRenderShapeSelect;

function wizardSelectShape(shape) {
  _wizardShape = shape;
  if (shape === 'round') {
    // Only one real Round product exists — skip the grade question
    // entirely and go straight to quantity.
    _wizardTier = 'low';
    _wizardBundleQty = 1;
    wizardRenderQtySelect();
  } else {
    wizardRenderTierSelect();
  }
}
window.wizardSelectShape = wizardSelectShape;

function wizardRenderTierSelect() {
  const itemListEl = document.getElementById('wizardItemList');
  if (!itemListEl || !_wizardBundle) return;
  wizardSetStep(4);
  updateWizardBreadcrumb();
  const searchRow = document.getElementById('wizardSearchRow');
  if (searchRow) searchRow.style.display = 'none';

  let tiers = _wizardBundle.tiers;
  // For Toilet Replacement, Oblong only has real Medium/High products —
  // there's no Oblong-Low SKU in the catalog, so don't offer it.
  if (_wizardBundle.name === 'Toilet Replacement' && _wizardShape === 'oblong') {
    tiers = { med: tiers.med, high: tiers.high };
  }
  const tierColors = { low: '#34d399', med: '#f59e0b', high: '#ef4444' };
  const tierEmoji = { low: '🟢', med: '🟡', high: '🔴' };

  // If every tier costs the same, this isn't a real low/medium/high price
  // ladder - it's just a style/color choice at one price point (e.g. LVP
  // Tile-Look: Marble/Slate/Stone all cost the same). Showing green/yellow/
  // red dots in that case falsely implies a price hierarchy that doesn't
  // exist. Detect it and render neutrally instead.
  const tierTotals = Object.entries(tiers).map(([key, tier]) =>
    tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0)
  );
  const allSamePrice = tierTotals.length > 1 && tierTotals.every(t => Math.abs(t - tierTotals[0]) < 0.01);
  const neutralColor = '#94a3b8';

  itemListEl.innerHTML =
    '<div style="text-align:center;margin-bottom:16px">' +
    '<div style="font-size:1.8rem">' + _wizardBundle.icon + '</div>' +
    '<div style="font-weight:800;font-size:1rem;color:#eaf0fb;margin-top:6px">' + esc(_wizardBundle.name) + '</div>' +
    '<div style="font-size:.78rem;color:var(--muted);margin-top:2px">' + esc(_wizardBundle.desc) + '</div></div>' +
    '<div style="font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);margin-bottom:10px">' +
    (allSamePrice ? 'Select option:' : 'Select grade / tier:') + '</div>' +
    Object.entries(tiers).map(([key, tier]) => {
      const total = tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0);
      const color = allSamePrice ? neutralColor : tierColors[key];
      const emoji = allSamePrice ? '' : (tierEmoji[key] + ' ');
      return '<div onclick="wizardSelectTier(\'' + key + '\')" ' +
        'style="border:2px solid ' + color + '22;border-radius:14px;padding:14px 16px;margin-bottom:10px;cursor:pointer;background:' + color + '08" ' +
        'onmouseover="this.style.borderColor=\'' + color + '\'" ' +
        'onmouseout="this.style.borderColor=\'' + color + '22\'">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">' +
        '<div style="font-weight:800;font-size:.95rem;color:#eaf0fb">' + emoji + tier.label + '</div>' +
        '<div style="font-weight:900;color:' + color + ';font-size:1rem">$' + total.toFixed(0) + '</div></div>' +
        '<div style="font-size:.76rem;color:var(--muted);margin-bottom:8px">' + esc(tier.priceRange) + '</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:6px">' +
        tier.lines.map(l =>
          '<span style="background:rgba(255,255,255,.06);border-radius:6px;padding:2px 8px;font-size:.72rem;color:#94a3b8">' +
          esc(l.desc) + (l.qty !== 1 ? ' ×' + l.qty : '') + '</span>'
        ).join('') + '</div></div>';
    }).join('') +
    '<button onclick="wizardRenderBundleTasks(_wizardTrade, TIERED_BUNDLES[_wizardTrade]||[])" ' +
    'style="background:none;border:none;color:var(--muted);font-size:.8rem;cursor:pointer;margin-top:6px">← Back to bundles</button>' +
    wizardCustomItemCardHtml();

  const footer = document.getElementById('wizardFooter');
  if (footer) footer.innerHTML = '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>';
}
window.wizardRenderTierSelect = wizardRenderTierSelect;

function wizardSelectTier(tierKey) {
  _wizardTier = tierKey;
  _wizardBundleQty = 1;
  wizardRenderQtySelect();
}
window.wizardSelectTier = wizardSelectTier;

// Detects whether a tier's pricing is naturally area/length-based (sqft
// or linear ft) rather than a simple per-each count - lets the quantity
// step ask for the real measurement (e.g. "how many square feet?")
// instead of a generic "how many to add" count the person would have to
// do their own math to get right.
function bundleTierAreaInfo(tier) {
  const areaLine = tier.lines.find(l => l.unit === 'sqft' || l.unit === 'lf' || l.unit === 'hr');
  if (!areaLine) return null;
  return { unit: areaLine.unit, baselineQty: areaLine.qty };
}

function wizardRenderQtySelect() {
  if (!_wizardBundle || !_wizardTier) return;
  const itemListEl = document.getElementById('wizardItemList');
  if (!itemListEl) return;
  wizardSetStep(4);
  updateWizardBreadcrumb();

  const tier = _wizardBundle.tiers[_wizardTier];
  const tierColors = { low: '#34d399', med: '#f59e0b', high: '#ef4444' };
  const tierEmoji = { low: '🟢', med: '🟡', high: '🔴' };
  const allTierTotals = Object.values(_wizardBundle.tiers).map(t => t.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0));
  const allSamePriceQty = allTierTotals.length > 1 && allTierTotals.every(t => Math.abs(t - allTierTotals[0]) < 0.01);
  const color = allSamePriceQty ? '#94a3b8' : tierColors[_wizardTier];
  const emojiPrefix = allSamePriceQty ? '' : (tierEmoji[_wizardTier] + ' ');
  const baseTotal = tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0);
  const areaInfo = bundleTierAreaInfo(tier);

  const qtyStepHtml = areaInfo
    ? '<div style="background:rgba(110,145,210,.06);border:1px solid rgba(110,145,210,.15);border-radius:14px;padding:16px;margin-bottom:16px">' +
      '<div style="font-weight:700;font-size:.88rem;color:#eaf0fb;margin-bottom:12px">How many <span style="color:var(--amber)">' + (areaInfo.unit === 'sqft' ? 'square feet' : areaInfo.unit === 'hr' ? 'hours' : 'linear feet') + '</span> for <span style="color:var(--amber)">' + esc(_wizardBundle.name) + '</span>?</div>' +
      '<input type="number" id="wizAreaQtyInput" min="0" step="any" placeholder="e.g. ' + areaInfo.baselineQty + '" ' +
      'oninput="wizUpdateAreaQty(this.value,' + areaInfo.baselineQty + ')" ' +
      'style="font-size:1.3rem;font-weight:800;text-align:center;padding:12px;border-radius:10px;border:2px solid var(--amber-border);background:var(--input-bg);color:var(--text);width:100%" />' +
      '<div style="text-align:center;font-size:.76rem;color:var(--muted);margin-top:8px">Pricing below is baselined on ' + areaInfo.baselineQty + ' ' + areaInfo.unit + ' — entering your real measurement scales it automatically</div></div>'
    : '<div style="background:rgba(110,145,210,.06);border:1px solid rgba(110,145,210,.15);border-radius:14px;padding:16px;margin-bottom:16px">' +
      '<div style="font-weight:700;font-size:.88rem;color:#eaf0fb;margin-bottom:12px">How many <span style="color:var(--amber)">' + esc(_wizardBundle.name) + '</span> to add?</div>' +
      '<div style="display:flex;align-items:center;gap:16px;justify-content:center">' +
      '<button onclick="wizChangeBundleQty(-1)" style="width:44px;height:44px;border-radius:10px;border:2px solid var(--amber-border);background:transparent;color:var(--amber);font-size:1.4rem;cursor:pointer;line-height:1">−</button>' +
      '<div id="wizBundleQtyDisplay" style="font-size:2rem;font-weight:900;color:var(--amber);min-width:48px;text-align:center">1</div>' +
      '<button onclick="wizChangeBundleQty(1)" style="width:44px;height:44px;border-radius:10px;border:2px solid var(--amber-border);background:transparent;color:var(--amber);font-size:1.4rem;cursor:pointer;line-height:1">＋</button>' +
      '</div><div style="text-align:center;font-size:.76rem;color:var(--muted);margin-top:8px">All quantities and prices will multiply by this number</div></div>';

  itemListEl.innerHTML =
    '<div style="background:rgba(217,119,6,.07);border:1px solid rgba(217,119,6,.2);border-radius:14px;padding:16px;margin-bottom:16px">' +
    '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">' +
    '<div style="font-size:1.5rem">' + _wizardBundle.icon + '</div>' +
    '<div><div style="font-weight:800;color:#eaf0fb">' + esc(_wizardBundle.name) + '</div>' +
    '<div style="font-size:.8rem;color:' + color + ';font-weight:700">' + emojiPrefix + tier.label + ' · ' + esc(tier.priceRange) + '</div></div></div>' +
    tier.lines.map(l =>
      '<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid rgba(255,255,255,.06);font-size:.8rem">' +
      '<span style="color:#cbd5e1" id="qtyLine_' + l.desc.replace(/\s/g,'_').replace(/[^a-zA-Z0-9_]/g,'') + '">' + esc(l.desc) + ' ×' + l.qty + '</span>' +
      '<span style="color:var(--muted)">$' + (l.qty * l.unitPrice).toFixed(2) + '</span></div>'
    ).join('') +
    '<div style="display:flex;justify-content:space-between;margin-top:8px;font-weight:900;font-size:.95rem">' +
    '<span style="color:#eaf0fb">Bundle Total</span><span style="color:var(--amber)" id="wizBundleTotalDisplay">$' + baseTotal.toFixed(2) + '</span></div></div>' +
    qtyStepHtml +
    '<button onclick="wizardRenderTierSelect()" style="background:none;border:none;color:var(--muted);font-size:.8rem;cursor:pointer">← Back to tier select</button>' +
    wizardCustomItemCardHtml();

  const footer = document.getElementById('wizardFooter');
  if (footer) footer.innerHTML =
    '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>' +
    '<button class="btn-amber" onclick="wizardAddBundleToEstimate()" style="min-width:180px;font-size:.92rem">➕ Add to Estimate</button>';
}

function wizUpdateAreaQty(value, baselineQty) {
  const entered = parseFloat(value);
  _wizardBundleQty = (entered > 0) ? (entered / baselineQty) : 0.0001; // avoid a hard zero multiplier
  if (_wizardBundle && _wizardTier) {
    const tier = _wizardBundle.tiers[_wizardTier];
    const baseTotal = tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0);
    const totalEl = document.getElementById('wizBundleTotalDisplay');
    if (totalEl) totalEl.textContent = '$' + (baseTotal * _wizardBundleQty).toFixed(2);
  }
}
window.wizUpdateAreaQty = wizUpdateAreaQty;

function wizChangeBundleQty(delta) {
  _wizardBundleQty = Math.max(1, (_wizardBundleQty || 1) + delta);
  const qtyEl = document.getElementById('wizBundleQtyDisplay');
  if (qtyEl) qtyEl.textContent = _wizardBundleQty;
  // Update total
  if (_wizardBundle && _wizardTier) {
    const tier = _wizardBundle.tiers[_wizardTier];
    const baseTotal = tier.lines.reduce((s, l) => s + (l.qty * l.unitPrice), 0);
    const totalEl = document.getElementById('wizBundleTotalDisplay');
    if (totalEl) totalEl.textContent = '$' + (baseTotal * _wizardBundleQty).toFixed(2);
  }
}
window.wizChangeBundleQty = wizChangeBundleQty;

let _wizardAddInProgress = false;
async function wizardAddBundleToEstimate() {
  if (!_wizardBundle || !_wizardTier || !conCurrentJobId) {
    alert('Could not add this — missing bundle/tier/job selection. Please close this and try again from Smart Add.');
    return;
  }
  // Real gap this closes: previously, if the wizard's room/trade context
  // was ever empty for any reason (e.g. a rapid re-tap while a prior add
  // was still in flight, or navigating oddly), this silently fell back to
  // a generic "General" group instead of failing loudly — creating
  // meaningless empty groups that had to be manually cleaned up. Now it
  // refuses instead of guessing.
  if (!_wizardRoom && !_wizardCategory) {
    alert('Lost track of which room/trade this belongs to. Please close Smart Add and start again from the beginning (Start > Interior/Exterior/Systems) rather than retrying from here.');
    return;
  }
  // Guards against rapid double-taps creating duplicate groups/items —
  // the actual mechanism behind the two empty "General" groups found on
  // the James Durbin job.
  if (_wizardAddInProgress) return;
  _wizardAddInProgress = true;

  const tier = _wizardBundle.tiers[_wizardTier];
  const qty = _wizardBundleQty || 1;

  kClose('smartAddModal');

  try {
    // Find or create a group (Epic) based on room context, and a subgroup
    // (Feature) based on trade context — same pattern as wizardAddToEstimate,
    // so bundle-added items land in the same tree the Board/Estimate views read.
    const roomName = _wizardRoom || _wizardCategory;
    const tradeName = _wizardPhaseLabel || (_wizardTrade || '').split(' ').slice(1).join(' ') || 'General';

    let group = estGroups.find(g => g.name.toLowerCase() === roomName.toLowerCase());
    if (!group) {
      const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
        name: roomName, order: estGroups.length,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
      group = { id: ref.id, name: roomName, order: estGroups.length, subgroups: [], directItems: [] };
      estGroups.push(group);
    }
    const groupId = group.id;

    const subgroupName = _wizardBundle.name + (qty > 1 ? ' ×' + qty : '') + ' (' + tier.label + ')';
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(groupId).collection('subgroups').add({
        name: subgroupName, order: group.subgroups?.length || 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    const subgroup = { id: subRef.id, name: subgroupName, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
    const subgroupId = subgroup.id;

    // Add each line × qty
    let order = 0;
    for (const line of tier.lines) {
      const lineQty = parseFloat((line.qty * qty).toFixed(4));
      const data = {
        desc: line.desc,
        qty: lineQty,
        unit: line.unit || 'ea',
        costType: line.type === 'labor' ? 'Labor' : (line.type === 'subcontractor' ? 'Subcontractor' : 'Materials'),
        unitCost: line.unitCost || 0,
        unitPrice: line.unitPrice || 0,
        markup: line.unitCost > 0 ? Math.round((line.unitPrice / line.unitCost - 1) * 100) : 0,
        notes: '',
        order: order++,
        source: 'smartadd-bundle',
        bundleName: _wizardBundle.name,
        bundleTier: _wizardTier,
        createdAt: firebase.firestore.FieldValue.serverTimestamp(),
      };
      await coll('jobs').doc(conCurrentJobId)
        .collection('estimateGroups').doc(groupId)
        .collection('subgroups').doc(subgroupId)
        .collection('items').add(data);
    }

    // Refresh estimate
    if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
  } catch (e) {
    console.error('wizardAddBundleToEstimate error:', e);
    alert('Error adding to estimate: ' + e.message + '\n\nPlease screenshot this and send it over.');
  } finally {
    _wizardAddInProgress = false;
  }
}
window.wizardAddBundleToEstimate = wizardAddBundleToEstimate;

function wizardSelectTradeFallback(trade) {
  // Show catalog items with template tab (bypassing bundle tasks)
  _wizardCurrentItems = CATALOG_DATA[trade] || [];
  document.getElementById('wizardSearchInput').value = '';
  const searchRow = document.getElementById('wizardSearchRow');
  if (searchRow) searchRow.style.display = 'flex';

  const itemListEl = document.getElementById('wizardItemList');
  if (itemListEl) {
    itemListEl.innerHTML =
      '<div style="display:flex;gap:0;background:rgba(8,18,36,.8);border:1px solid rgba(110,145,210,.15);border-radius:10px;overflow:hidden;margin-bottom:12px">' +
      '<button id="wizTabTemplates" onclick="wizShowTab(\'templates\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:.8rem;font-weight:700;background:linear-gradient(135deg,var(--amber),var(--amber2));color:#fff">⚡ Templates</button>' +
      '<button id="wizTabItems" onclick="wizShowTab(\'items\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:.8rem;font-weight:600;background:transparent;color:var(--muted)">📦 Catalog Items</button>' +
      '</div><div id="wizPanelTemplates"></div><div id="wizPanelItems" style="display:none"></div>';
  }
  wizLoadTemplates(trade);

  const itemsPanel = document.getElementById('wizPanelItems');
  if (itemsPanel) {
    itemsPanel.innerHTML = _wizardCurrentItems.length ? _wizardCurrentItems.map(item => {
      const total = (item.materials?.unitPrice || 0) + (item.labor?.unitPrice || 0);
      return '<div class="wizard-item" onclick="wizardToggleItem(\'' + item.name.replace(/'/g,"\\'") + '\',this)">' +
        '<div class="wizard-item-check"></div>' +
        '<div class="wizard-item-info"><div class="wizard-item-name">' + esc(item.name) + '</div></div>' +
        '<div class="wizard-item-price">' + (total > 0 ? '$' + total.toFixed(2) : '') + '</div></div>';
    }).join('') : '<div class="small muted" style="text-align:center;padding:20px">No items for this trade</div>';
  }

  const footer = document.getElementById('wizardFooter');
  if (footer) footer.innerHTML =
    '<button class="btn" onclick="kClose(\'smartAddModal\')">Cancel</button>' +
    '<button class="btn-amber" onclick="wizardAddToEstimate()" style="min-width:140px">➕ Add to Estimate</button>';
}
window.wizardSelectTradeFallback = wizardSelectTradeFallback;

function wizShowTab(tab) {
  const tBtn = document.getElementById('wizTabTemplates');
  const iBtn = document.getElementById('wizTabItems');
  const tPanel = document.getElementById('wizPanelTemplates');
  const iPanel = document.getElementById('wizPanelItems');
  const searchRow = document.getElementById('wizardSearchRow');
  if (tab === 'templates') {
    if (tPanel) tPanel.style.display = 'block';
    if (iPanel) iPanel.style.display = 'none';
    if (tBtn) { tBtn.style.background = 'linear-gradient(135deg,var(--amber),var(--amber2))'; tBtn.style.color='#fff'; }
    if (iBtn) { iBtn.style.background = 'transparent'; iBtn.style.color='var(--muted)'; }
    if (searchRow) searchRow.style.display = 'none';
  } else {
    if (tPanel) tPanel.style.display = 'none';
    if (iPanel) iPanel.style.display = 'block';
    if (iBtn) { iBtn.style.background = 'linear-gradient(135deg,var(--amber),var(--amber2))'; iBtn.style.color='#fff'; }
    if (tBtn) { tBtn.style.background = 'transparent'; tBtn.style.color='var(--muted)'; }
    if (searchRow) searchRow.style.display = 'flex';
  }
}

function wizLoadTemplates(trade) {
  const panel = document.getElementById('wizPanelTemplates');
  if (!panel) return;
  panel.innerHTML = '<div style="color:var(--muted);font-size:.82rem;padding:8px">Loading templates...</div>';

  coll('templates').where('trade','==',trade).orderBy('name').get()
    .then(snap => {
      const templates = [];
      snap.forEach(d => templates.push({ id: d.id, ...d.data() }));
      wizRenderTemplates(templates, trade);
      // Templates is a separate, rarely-populated feature (the user has
      // to manually create one per trade first) — defaulting to this
      // tab meant a trade with real catalog items but zero saved
      // templates (true for most trades most of the time) looked
      // completely empty, with the actual inventory sitting one click
      // away on the Catalog Items tab. Auto-switch so the tab that
      // actually has content is what's shown.
      if (!templates.length) wizShowTab('items');
    })
    .catch(() => { wizRenderTemplates([], trade); wizShowTab('items'); });
}

function wizRenderTemplates(templates, trade) {
  const panel = document.getElementById('wizPanelTemplates');
  if (!panel) return;

  let html = '';

  if (templates.length) {
    html += templates.map(t => {
      const lineCount = (t.lines||[]).length;
      const total = (t.lines||[]).reduce((s,l) => s + (l.qty||1)*(l.unitPrice||0), 0);
      return `<div style="border:1px solid rgba(110,145,210,.15);border-radius:12px;padding:14px;margin-bottom:10px;cursor:pointer"
        onclick="wizSelectTemplate('${t.id}')"
        onmouseover="this.style.borderColor='rgba(217,119,6,.4)';this.style.background='rgba(217,119,6,.05)'"
        onmouseout="this.style.borderColor='rgba(110,145,210,.15)';this.style.background=''">
        <div style="display:flex;justify-content:space-between;align-items:flex-start">
          <div>
            <div style="font-weight:800;font-size:.9rem;color:#eaf0fb">${esc(t.name)}</div>
            <div style="font-size:.74rem;color:var(--muted);margin-top:3px">${lineCount} line${lineCount!==1?'s':''} · ${esc(t.description||'')}</div>
          </div>
          <div style="font-weight:900;color:var(--amber);font-size:.95rem">$${total.toFixed(2)}</div>
        </div>
        <div style="margin-top:8px;font-size:.75rem;color:var(--muted)">
          ${(t.lines||[]).slice(0,3).map(l => `${esc(l.desc||'')} (${l.qty||1})`).join(' · ')}${(t.lines||[]).length>3?' · ...':''}
        </div>
      </div>`;
    }).join('');
  } else {
    html += `<div style="text-align:center;padding:20px 10px;color:var(--muted)">
      <div style="font-size:1.5rem;margin-bottom:8px">⚡</div>
      <div style="font-size:.85rem;font-weight:600;margin-bottom:4px">No templates yet for this trade</div>
      <div style="font-size:.76rem">Create a template to quickly add bundles of items (e.g. "Kitchen Faucet Replacement" with faucet + labor + supply lines)</div>
    </div>`;
  }

  html += `<button onclick="wizOpenCreateTemplate('${trade}')"
    style="width:100%;margin-top:8px;padding:10px;background:transparent;border:1px dashed rgba(217,119,6,.4);border-radius:10px;color:var(--amber);font-size:.83rem;font-weight:700;cursor:pointer">
    ＋ Create New Template
  </button>`;

  panel.innerHTML = html;
}

function wizSelectTemplate(templateId) {
  if (!conCurrentJobId || !conDb) return;
  coll('templates').doc(templateId).get().then(doc => {
    if (!doc.exists) return;
    const t = { id: doc.id, ...doc.data() };

    // Show qty selector overlay
    const overlay = document.createElement('div');
    overlay.id = 'wizTemplateOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,5,14,.8);z-index:999999;display:flex;align-items:center;justify-content:center;padding:20px';

    const lines = t.lines || [];
    const linesHtml = lines.map(l =>
      `<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid rgba(110,145,210,.07);font-size:.82rem">
        <div style="color:#eaf0fb">${esc(l.desc||'')} × <span id="lineQty_${l.id||Math.random().toString(36).slice(2)}" class="tmpl-scaled-qty">${l.qty||1}</span></div>
        <div style="color:var(--amber)">$<span class="tmpl-scaled-price">${((l.qty||1)*(l.unitPrice||0)).toFixed(2)}</span></div>
      </div>`
    ).join('');

    overlay.innerHTML = `
      <div style="background:rgba(6,14,28,.99);border:1px solid rgba(217,119,6,.35);border-radius:18px;padding:26px;max-width:480px;width:100%;max-height:85vh;overflow-y:auto">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
          <div style="font-size:1rem;font-weight:800;color:#eaf0fb">${esc(t.name)}</div>
          <button onclick="document.getElementById('wizTemplateOverlay').remove()" style="background:none;border:none;color:var(--muted);font-size:1.3rem;cursor:pointer">✕</button>
        </div>
        <div style="font-size:.78rem;color:var(--muted);margin-bottom:14px">${esc(t.description||'')}</div>

        <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;background:rgba(217,119,6,.08);border:1px solid rgba(217,119,6,.2);border-radius:10px;padding:12px">
          <div style="font-size:.82rem;font-weight:700;color:#eaf0fb">Quantity:</div>
          <button onclick="wizChangeQty(-1)" style="width:32px;height:32px;border-radius:8px;border:1px solid var(--amber-border);background:transparent;color:var(--amber);font-size:1.2rem;cursor:pointer;line-height:1">−</button>
          <div id="wizTmplQty" style="font-size:1.4rem;font-weight:900;color:var(--amber);min-width:32px;text-align:center">1</div>
          <button onclick="wizChangeQty(1)" style="width:32px;height:32px;border-radius:8px;border:1px solid var(--amber-border);background:transparent;color:var(--amber);font-size:1.2rem;cursor:pointer;line-height:1">＋</button>
          <div style="font-size:.76rem;color:var(--muted);margin-left:4px">× all quantities</div>
        </div>

        <div style="margin-bottom:16px">
          <div style="font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:8px">Notes for this batch (optional)</div>
          <textarea id="wizTmplNotes" placeholder="e.g. Guest bathroom — applies to every line added below" style="width:100%;box-sizing:border-box;min-height:52px;padding:9px 12px;border-radius:8px;border:1px solid var(--line);background:rgba(8,18,36,.6);color:#eaf0fb;font-size:.84rem;font-family:inherit;resize:vertical"></textarea>
          <div style="font-size:.68rem;color:var(--muted);margin-top:4px">Added to every line below — saves editing each one individually afterward.</div>
        </div>

        <div style="margin-bottom:16px">
          <div style="font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:8px">Lines to add:</div>
          ${linesHtml}
        </div>

        <div style="display:flex;gap:8px">
          <button onclick="document.getElementById('wizTemplateOverlay').remove()" style="flex:1;padding:12px;background:transparent;border:1px solid rgba(110,145,210,.2);border-radius:10px;color:var(--muted);font-weight:700;cursor:pointer">Cancel</button>
          <button onclick="wizAddTemplateToEstimate('${templateId}')" style="flex:2;padding:12px;background:#d97706;border:none;border-radius:10px;color:#fff;font-weight:800;cursor:pointer">➕ Add to Estimate</button>
        </div>
      </div>`;

    window._wizTemplateData = t;
    window._wizTemplateQty = 1;
    document.body.appendChild(overlay);
  });
}

function wizChangeQty(delta) {
  const qty = Math.max(1, (window._wizTemplateQty || 1) + delta);
  window._wizTemplateQty = qty;
  document.getElementById('wizTmplQty').textContent = qty;
}

async function wizAddTemplateToEstimate(templateId) {
  const t = window._wizTemplateData;
  const qty = window._wizTemplateQty || 1;
  const sharedNotes = document.getElementById('wizTmplNotes')?.value.trim() || '';
  if (!t || !conCurrentJobId) return;
  if (!_wizardRoom && !_wizardCategory) {
    alert('Lost track of which room/trade this belongs to. Please close Smart Add and start again from the beginning rather than retrying from here.');
    return;
  }

  document.getElementById('wizTemplateOverlay')?.remove();
  kClose('smartAddModal');

  const roomName = _wizardRoom || _wizardCategory;
  const tradeName = t.name || (_wizardTrade || '').split(' ').slice(1).join(' ') || 'General';

  let group = estGroups.find(g => g.name.toLowerCase() === roomName.toLowerCase());
  if (!group) {
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: roomName, order: estGroups.length,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: roomName, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }
  const groupId = group.id;

  const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
    .doc(groupId).collection('subgroups').add({
      name: tradeName, order: group.subgroups?.length || 0,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
  const subgroup = { id: subRef.id, name: tradeName, order: group.subgroups?.length || 0, items: [] };
  if (!group.subgroups) group.subgroups = [];
  group.subgroups.push(subgroup);
  const subgroupId = subgroup.id;

  const lines = t.lines || [];
  let order = 0;
  for (const line of lines) {
    const lineQty = (line.qty || 1) * qty;
    const data = {
      desc: line.desc || '',
      qty: lineQty,
      unit: line.unit || 'ea',
      costType: line.type === 'labor' ? 'Labor' : (line.type === 'subcontractor' ? 'Subcontractor' : 'Materials'),
      unitCost: line.unitCost || 0,
      unitPrice: line.unitPrice || 0,
      markup: line.markup || 0,
      notes: sharedNotes,
      order: order++,
      createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    };
    await coll('jobs').doc(conCurrentJobId)
      .collection('estimateGroups').doc(groupId)
      .collection('subgroups').doc(subgroupId)
      .collection('items').add(data);
  }

  // Refresh estimate
  if (typeof loadEstimate === 'function') loadEstimate(conCurrentJobId);
}

function wizOpenCreateTemplate(trade) {
  const overlay = document.createElement('div');
  overlay.id = 'wizCreateTemplateOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,5,14,.8);z-index:999999;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.innerHTML = `
    <div style="background:rgba(6,14,28,.99);border:1px solid rgba(217,119,6,.35);border-radius:18px;padding:26px;max-width:560px;width:100%;max-height:90vh;overflow-y:auto">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
        <div style="font-size:1rem;font-weight:800;color:#eaf0fb">Create Template — ${esc(trade)}</div>
        <button onclick="document.getElementById('wizCreateTemplateOverlay').remove()" style="background:none;border:none;color:var(--muted);font-size:1.3rem;cursor:pointer">✕</button>
      </div>
      <div style="margin-bottom:12px">
        <label style="font-size:.78rem;color:var(--muted);display:block;margin-bottom:4px">Template Name *</label>
        <input id="tmplName" placeholder="e.g. Kitchen Faucet Replacement" style="width:100%;padding:10px;background:rgba(8,19,37,.8);border:1px solid rgba(217,119,6,.3);border-radius:8px;color:#eaf0fb;font-size:.88rem;box-sizing:border-box" />
      </div>
      <div style="margin-bottom:16px">
        <label style="font-size:.78rem;color:var(--muted);display:block;margin-bottom:4px">Description</label>
        <input id="tmplDesc" placeholder="e.g. Standard kitchen faucet swap with supply lines and shutoffs" style="width:100%;padding:10px;background:rgba(8,19,37,.8);border:1px solid rgba(217,119,6,.3);border-radius:8px;color:#eaf0fb;font-size:.88rem;box-sizing:border-box" />
      </div>
      <div style="font-size:.78rem;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Line Items</div>
      <div id="tmplLines"></div>
      <button onclick="wizAddTemplateLine()" style="width:100%;padding:9px;background:transparent;border:1px dashed rgba(110,145,210,.3);border-radius:8px;color:var(--muted);font-size:.82rem;cursor:pointer;margin-bottom:16px">＋ Add Line Item</button>
      <div style="display:flex;gap:8px">
        <button onclick="document.getElementById('wizCreateTemplateOverlay').remove()" style="flex:1;padding:12px;background:transparent;border:1px solid rgba(110,145,210,.2);border-radius:10px;color:var(--muted);font-weight:700;cursor:pointer">Cancel</button>
        <button onclick="wizSaveTemplate('${trade}')" style="flex:2;padding:12px;background:#d97706;border:none;border-radius:10px;color:#fff;font-weight:800;cursor:pointer">Save Template</button>
      </div>
    </div>`;
  window._tmplLines = [];
  document.body.appendChild(overlay);
  wizAddTemplateLine(); // Start with one line
}

function wizAddTemplateLine() {
  const id = 'tl_' + Date.now();
  window._tmplLines = window._tmplLines || [];
  window._tmplLines.push(id);
  const container = document.getElementById('tmplLines');
  if (!container) return;
  const div = document.createElement('div');
  div.id = id;
  div.style.cssText = 'display:grid;grid-template-columns:2fr 60px 80px 80px 24px;gap:6px;align-items:center;margin-bottom:8px';
  div.innerHTML = `
    <input placeholder="Description" style="padding:8px;background:rgba(8,19,37,.8);border:1px solid rgba(110,145,210,.15);border-radius:6px;color:#eaf0fb;font-size:.8rem" data-field="desc" />
    <input type="number" placeholder="Qty" value="1" min="0.1" step="0.1" style="padding:8px;background:rgba(8,19,37,.8);border:1px solid rgba(110,145,210,.15);border-radius:6px;color:#eaf0fb;font-size:.8rem;text-align:center" data-field="qty" />
    <input type="number" placeholder="Cost $" min="0" step="0.01" style="padding:8px;background:rgba(8,19,37,.8);border:1px solid rgba(110,145,210,.15);border-radius:6px;color:#eaf0fb;font-size:.8rem" data-field="unitCost" />
    <input type="number" placeholder="Price $" min="0" step="0.01" style="padding:8px;background:rgba(8,19,37,.8);border:1px solid rgba(110,145,210,.15);border-radius:6px;color:#eaf0fb;font-size:.8rem" data-field="unitPrice" />
    <button onclick="this.closest('div').remove()" style="background:none;border:none;color:#f87171;font-size:1rem;cursor:pointer;padding:0">✕</button>
  `;
  container.appendChild(div);
}

async function wizSaveTemplate(trade) {
  const name = document.getElementById('tmplName')?.value.trim();
  if (!name) { alert('Template name is required.'); return; }
  const desc = document.getElementById('tmplDesc')?.value.trim() || '';

  const lineEls = document.getElementById('tmplLines')?.children || [];
  const lines = [];
  for (const el of lineEls) {
    const lineDesc = el.querySelector('[data-field="desc"]')?.value.trim();
    const qty = parseFloat(el.querySelector('[data-field="qty"]')?.value) || 1;
    const unitCost = parseFloat(el.querySelector('[data-field="unitCost"]')?.value) || 0;
    const unitPrice = parseFloat(el.querySelector('[data-field="unitPrice"]')?.value) || 0;
    if (lineDesc) lines.push({ id: 'l_'+Date.now()+'_'+Math.random().toString(36).slice(2,6), desc: lineDesc, qty, unitCost, unitPrice, unit: 'ea' });
  }

  if (!lines.length) { alert('Add at least one line item.'); return; }

  await coll('templates').add({
    name, description: desc, trade,
    lines,
    companyId: currentCompanyId,
    createdAt: firebase.firestore.FieldValue.serverTimestamp(),
    createdBy: conCurrentUser?.email || '',
  });

  document.getElementById('wizCreateTemplateOverlay')?.remove();
  // Reload templates
  wizLoadTemplates(trade);
}

window.wizShowTab = wizShowTab;
window.wizLoadTemplates = wizLoadTemplates;
window.wizSelectTemplate = wizSelectTemplate;
window.wizChangeQty = wizChangeQty;
window.wizAddTemplateToEstimate = wizAddTemplateToEstimate;
window.wizOpenCreateTemplate = wizOpenCreateTemplate;
window.wizAddTemplateLine = wizAddTemplateLine;
window.wizSaveTemplate = wizSaveTemplate;

function wizardRenderItems(items) {
  const el = document.getElementById('wizardItemList');
  if (!el) return;

  const customBtn = wizardCustomItemCardHtml();

  if (!items.length) {
    el.innerHTML = '<div class="small muted" style="text-align:center;padding:20px">No items found</div>' + customBtn;
    return;
  }

  el.innerHTML = items.map((item, idx) => {
    const isSelected = _wizardSelectedItems.has(item.name);
    const matPrice = item.materials?.unitPrice || 0;
    const labPrice = item.labor?.unitPrice || 0;
    const totalPrice = matPrice + labPrice;
    return `<div class="wizard-item ${isSelected?'selected':''}" onclick="wizardToggleItem('${item.name.replace(/'/g,"\\'")}',this)">
      <div class="wizard-item-check">${isSelected?'✓':''}</div>
      <div class="wizard-item-info">
        <div class="wizard-item-name">${esc(item.name)}</div>
        <div class="wizard-item-meta">
          ${item.materials?'📦 Mat: $'+item.materials.unitPrice.toFixed(2):''}
          ${item.labor?' · 👷 Labor: $'+item.labor.unitPrice.toFixed(2)+'/hr':''}
        </div>
      </div>
      <div class="wizard-item-price">${totalPrice>0?'$'+totalPrice.toFixed(2):''}</div>
    </div>`;
  }).join('') + customBtn;

  updateWizardSelCount();
}

function wizardToggleItem(name, el) {
  if (_wizardSelectedItems.has(name)) {
    _wizardSelectedItems.delete(name);
    el.classList.remove('selected');
    el.querySelector('.wizard-item-check').textContent = '';
  } else {
    _wizardSelectedItems.add(name);
    el.classList.add('selected');
    el.querySelector('.wizard-item-check').textContent = '✓';
  }
  updateWizardSelCount();
}

function wizardFilterItems() {
  const q = document.getElementById('wizardSearchInput')?.value.toLowerCase() || '';
  const words = q.split(/\s+/).filter(Boolean);
  const filtered = words.length
    ? _wizardCurrentItems.filter(i => {
        const name = i.name.toLowerCase();
        return words.every(w => name.includes(w));
      })
    : _wizardCurrentItems;
  wizardRenderItems(filtered);
}

function wizardSelectAll() {
  _wizardCurrentItems.forEach(i => _wizardSelectedItems.add(i.name));
  wizardRenderItems(_wizardCurrentItems);
}

function wizardClearAll() {
  _wizardSelectedItems.clear();
  wizardRenderItems(_wizardCurrentItems);
}

function updateWizardSelCount() {
  const el = document.getElementById('wizardSelCount');
  if (el) el.textContent = `${_wizardSelectedItems.size} item${_wizardSelectedItems.size!==1?'s':''} selected`;
}

function wizardSetStep(step) {
  for (let i = 1; i <= 4; i++) {
    const el = document.getElementById('wizardStep' + i);
    if (el) el.classList.toggle('active', i === step);
  }
  const backBtn = document.getElementById('wizardBackBtn');
  // Step 2 (room grid) is the effective root now that category selection
  // is skipped (single "Whole House" category) — no back button there.
  if (backBtn) backBtn.style.display = step > 2 ? 'block' : 'none';
  if (step < 4) {
    const footer = document.getElementById('wizardFooter');
    if (footer) { footer.innerHTML = ''; const cb = document.createElement('button'); cb.className='btn'; cb.textContent='Cancel'; cb.onclick=function(){kClose('smartAddModal');}; footer.appendChild(cb); }
  }
}

function wizardBack() {
  if (_wizardStep === 3) wizardSelectCategory(_wizardCategory);
  else if (_wizardStep === 4) wizardSelectRoom(_wizardRoom);
}

function wizardGoTo(step) {
  if (step === 1) wizardSelectCategory('Whole House');
}

function updateWizardBreadcrumb() {
  const el = document.getElementById('wizardBreadcrumb');
  if (!el) return;
  // Category crumb omitted — there's only one category ("Whole House"),
  // so showing it adds noise without a real choice behind it.
  let crumbs = [{ label:'Start', step:1 }];
  if (_wizardRoom) crumbs.push({ label:_wizardRoom, step:2 });
  if (_wizardTrade) {
    const tradeName = _wizardPhaseLabel || _wizardTrade.split(' ').slice(1).join(' ') || _wizardTrade;
    crumbs.push({ label:tradeName, step:3 });
  }
  el.innerHTML = crumbs.map((c, i) =>
    i < crumbs.length - 1
      ? `<span onclick="wizardGoStep(${i})">${c.label}</span> ›`
      : `<span style="color:#eaf0fb;cursor:default">${c.label}</span>`
  ).join(' ');
}

function wizardGoStep(idx) {
  if (idx === 0) wizardSelectCategory('Whole House');
  else if (idx === 1 && _wizardRoom) wizardSelectRoom(_wizardRoom);
}

async function wizardAddToEstimate() {
  if (_wizardSelectedItems.size === 0) { alert('Select at least one item.'); return; }
  if (!conDb || !conCurrentJobId) return;
  if (!_wizardRoom && !_wizardCategory) {
    alert('Lost track of which room/trade this belongs to. Please close Smart Add and start again from the beginning rather than retrying from here.');
    return;
  }

  // Pick or create group based on room
  let groupId = null;
  let subgroupId = null;
  const roomName = _wizardRoom || _wizardCategory;
  const tradeName = _wizardPhaseLabel || (_wizardTrade || '').split(' ').slice(1).join(' ') || 'General';

  // Find existing group matching room name
  let group = estGroups.find(g => g.name.toLowerCase() === roomName.toLowerCase());

  if (!group) {
    // Create new group for this room
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: roomName, order: estGroups.length,
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: roomName, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }
  groupId = group.id;

  // Create subgroup for the trade
  let subgroup = group.subgroups?.find(s => s.name.toLowerCase() === tradeName.toLowerCase());
  if (!subgroup) {
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(groupId).collection('subgroups').add({
        name: tradeName, order: group.subgroups?.length || 0,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    subgroup = { id: subRef.id, name: tradeName, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
  }
  subgroupId = subgroup.id;

  // Add selected items
  const itemsToAdd = _wizardCurrentItems.filter(i => _wizardSelectedItems.has(i.name));
  const addPromises = [];
  let order = subgroup.items?.length || 0;

  for (const item of itemsToAdd) {
    // Add materials item
    if (item.materials) {
      const matUnitCost = item.materials.unitCost || 0;
      const matUnitPrice = item.materials.unitPrice || 0;
      const matData = {
        desc: item.name,
        qty: item.materials.qty || 1,
        unit: item.materials.unit || 'ea',
        costType: 'Materials',
        unitCost: matUnitCost,
        markup: (matUnitCost > 0 && matUnitPrice > 0)
          ? Math.round((matUnitPrice / matUnitCost - 1) * 100)
          : getDefaultMarkupForCostType('Materials'),
        unitPrice: matUnitPrice,
        notes: '',
        order: order++,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      };
      addPromises.push(
        coll('jobs').doc(conCurrentJobId)
          .collection('estimateGroups').doc(groupId)
          .collection('subgroups').doc(subgroupId)
          .collection('items').add(matData)
      );
    }
    // Labor: use the catalog's REAL labor data when it exists (many
    // items genuinely have accurate install-labor pricing baked in —
    // e.g. "Labor to install Deadbolt" at $25/hr). Previously this
    // block ran UNCONDITIONALLY regardless of item.labor, fabricating
    // a blind $100/hr guess on top of every single item added —
    // including subcontractor flat-fee services (e.g. a cleaning
    // company's quote) where that "materials" line already represents
    // the whole job, labor included. Bolting a fake labor line onto
    // those double-counted labor and produced a wrong total. Now: real
    // labor data if the catalog has it, otherwise none at all — no
    // more guessing. If a specific item genuinely needs a separate
    // labor line the catalog doesn't have, add one manually via + Item.
    if (item.labor) {
      const labUnitCost = item.labor.unitCost || 0;
      const labUnitPrice = item.labor.unitPrice || 0;
      const labData = {
        desc: item.labor.desc || ('Labor - ' + item.name),
        qty: item.labor.qty || 1,
        unit: item.labor.unit || 'hr',
        costType: 'Labor',
        unitCost: labUnitCost,
        markup: (labUnitCost > 0 && labUnitPrice > 0)
          ? Math.round((labUnitPrice / labUnitCost - 1) * 100)
          : getDefaultMarkupForCostType('Labor'),
        unitPrice: labUnitPrice,
        notes: '',
        order: order++,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      };
      addPromises.push(
        coll('jobs').doc(conCurrentJobId)
          .collection('estimateGroups').doc(groupId)
          .collection('subgroups').doc(subgroupId)
          .collection('items').add(labData)
      );
    }
  }

  await Promise.all(addPromises);
  kClose('smartAddModal');

  // Switch to estimate tab and reload
  const estTab = document.querySelector('[onclick*="estimate"]');
  if (estTab) estTab.click();
  else loadEstimate(conCurrentJobId);

  const itemCount = itemsToAdd.length;
  const lineCount = itemsToAdd.filter(i=>i.materials).length + itemsToAdd.filter(i=>i.labor).length;
  alert(`✅ Added ${itemCount} item${itemCount!==1?'s':''} (${lineCount} line items) to ${roomName} › ${tradeName}`);
}

// ═══════════════════════════════════════════════════════════════════════
// GUIDED QUESTIONS — "question machine" mode alongside Smart Add's
// "selection machine" browse mode. Walks a trade's yes/no + quantity
// script (GUIDED_SCRIPTS) instead of browsing the catalog, then commits
// to the estimate using the exact same group/subgroup-creation logic as
// wizardAddToEstimate above.
//
// Shared quantities (squares / ridgeLength / eaveLength) are each asked
// only once per session and reused by every later question that needs
// them — this was an explicit design decision, not a default.
//
// Only Roofing is scripted today. Every other trade's phases still show
// in the room/phase pickers (so the flow doesn't feel broken), but
// selecting one explains guided mode isn't built for it yet and points
// back to Smart Add. Add a new trade by adding a GUIDED_SCRIPTS entry —
// the engine below is generic and doesn't change.
// ═══════════════════════════════════════════════════════════════════════

const GUIDED_QTY_LABELS = {
  squares:    'Total roof size, in squares (1 square = 100 sq ft)',
  ridgeLength:'Total ridge length (linear feet)',
  eaveLength: 'Total eave / perimeter length (linear feet)'
};

const GUIDED_SCRIPTS = {
  '0900 Roofing': {
    label: 'Roofing',
    steps: [
      {
        id: 'tearoff', text: 'Is there a tear-off of the existing roof?',
        onYes: { needs: ['squares'],
          items: (ctx) => []   // tear-off is folded into the single consolidated labor line below, no separate charge
        }
      },
      {
        id: 'underlayment', text: 'Install underlayment?',
        onYes: { needs: ['squares'],
          items: (ctx) => [
            { name:'GAF FeltBuster Synthetic Roofing Underlayment (10 sq. roll)', qty: Math.ceil(ctx.squares/10) }
          ]
        }
      },
      {
        id: 'icewater', text: 'Install ice & water shield (eaves/valleys)?',
        onYes: { needs: ['squares'],
          items: (ctx) => [{ name:'GAF WeatherWatch Ice & Water Shield (2 sq. roll)', qty: Math.ceil(ctx.squares/2) }]
        }
      },
      {
        id: 'shingles', text: 'Install shingles?',
        onYes: { needs: ['squares','eaveLength'],
          select: { key:'shingleType', label:'Shingle type', options: [
            'GAF Timberline HDZ 3-Tab Laminated Architectural Shingles (33.3 sq. ft. / bundle)',
            'Owens Corning Duration Architectural Shingles (32.8 sq. ft. / bundle)',
            '3-Tab Asphalt Shingles, Standard (33.3 sq. ft. / bundle)'
          ]},
          items: (ctx) => [
            { name: ctx.shingleType, qty: Math.round(ctx.squares*3) },
            { name:'GAF Pro-Start Starter Strip Shingles (120 lin. ft. / bundle)', qty: Math.ceil(ctx.eaveLength/120) }
          ]
        }
      },
      {
        id: 'ridge', text: 'Install ridge cap & ridge vent?',
        onYes: { needs: ['ridgeLength'],
          items: (ctx) => [
            { name:'GAF Seal-A-Ridge Hip and Ridge Cap Shingles (25 lin. ft. / bundle)', qty: Math.ceil(ctx.ridgeLength/25) },
            { name:'Air Vent Shingle-Over Ridge Vent, 4 ft. (Aluminum)', qty: Math.ceil(ctx.ridgeLength/4) }
          ]
        }
      },
      {
        id: 'vents', text: 'Any additional roof vent penetrations (static vents, pipe boots, etc.)?',
        onYes: { ownQty: { key:'ventCount', label:'How many penetrations?', default:1 },
          items: (ctx) => [{ name:'Galvanized Roof Vent Pipe Boot Flashing (1-1/2 in. - 3 in.)', qty: ctx.ventCount }]
        }
      },
      {
        id: 'dripedge', text: 'Install drip edge flashing along the eaves?',
        onYes: { needs: ['eaveLength'],
          items: (ctx) => [{ name:'Gibraltar Building Products 2-3/8 in. x 1-1/2 in. x 10 ft. Painted Aluminum Drip Edge Flashing in Weathered Wood', qty: Math.ceil(ctx.eaveLength/10) }]
        }
      },
      {
        id: 'gutters', text: 'Replace gutters & downspouts?',
        onYes: { needs: ['eaveLength'], ownQty: { key:'downspoutCount', label:'How many downspouts?', default:2 },
          items: (ctx) => [
            { name:'Amerimax Home Products 5 in. x 10 ft. White Aluminum K-Style Gutter', qty: Math.ceil(ctx.eaveLength/10) },
            { name:'Amerimax Home Products 3 in. x 4 in. x 10 ft. White Aluminum Downspout', qty: ctx.downspoutCount }
          ]
        }
      },
      {
        id: 'decking', text: 'Replace any roof decking / plywood?',
        onYes: { ownQty: { key:'sheetCount', label:'How many sheets?', default:1 },
          items: (ctx) => [{ name:'Roof decking replacement, 1/2 in. CDX plywood (per sheet, material + labor)', qty: ctx.sheetCount }]
        }
      }
    ],
    // Small consumables that scale with roof size, plus the single
    // consolidated labor line — added automatically once squares is
    // known (i.e. at least one squares-dependent step fired "Yes"),
    // no separate question asked. $325/square already includes markup
    // (back-solved to unitCost in the catalog at the standard 15%
    // labor markup) — replaces what used to be 4 separate per-step
    // labor lines (tear-off, underlayment install, shingle install,
    // ridge install).
    // Roofing nails corrected to the 7,200-count box (~22.5 sq
    // coverage at ~320 nails/sq) — the old 5 lb box only covered
    // ~3.3 sq and was both underpriced and under-quantified.
    // Cap nails are a required companion item for synthetic
    // underlayment (plain nails/staples tear it) and were previously
    // missing from the catalog entirely.
    autoItems: (ctx) => ctx.squares ? [
      { name:'Labor - Roofing Installation (per square)', qty: ctx.squares },
      { name:'1-1/4 in. Electro-Galvanized Roofing Nails (7,200-count box)', qty: Math.ceil(ctx.squares/22.5) },
      { name:'1 in. Plastic Cap Roofing Nails, Ring Shank (2,500-count box)', qty: Math.ceil(ctx.squares/20) },
      { name:'10.3 oz. Roofing and Flashing Sealant, Black', qty: Math.ceil(ctx.squares/20) }
    ] : []
  }
};

let _guidedCategory = null, _guidedRoom = null, _guidedTrade = null, _guidedPhaseLabel = null;
let _guidedScript = null, _guidedStepIdx = 0, _guidedCtx = {}, _guidedCart = [];

// Back navigation: a stack of full-state snapshots, one pushed right
// before every forward move. "Back" pops the most recent snapshot and
// re-renders exactly that screen with exactly the ctx/cart it had at
// the time -- so answering a question wrong and hitting Back rewinds
// one question, it doesn't restart the whole flow.
let _guidedHistory = [];

function guidedSnapshot(screen) {
  return {
    screen,
    ctx: { ..._guidedCtx }, cart: [..._guidedCart],
    category: _guidedCategory, room: _guidedRoom, trade: _guidedTrade, phaseLabel: _guidedPhaseLabel,
    script: _guidedScript, stepIdx: _guidedStepIdx
  };
}
function guidedPush(screen) { _guidedHistory.push(guidedSnapshot(screen)); guidedUpdateBackBtn(); }
function guidedUpdateBackBtn() {
  const btn = document.getElementById('guidedBackBtn');
  if (btn) btn.style.display = _guidedHistory.length ? 'inline-block' : 'none';
}

function openGuidedAdd() {
  _guidedCategory = null; _guidedRoom = null; _guidedTrade = null; _guidedPhaseLabel = null;
  _guidedScript = null; _guidedStepIdx = 0; _guidedCtx = {}; _guidedCart = []; _guidedHistory = [];
  guidedRenderCategoryScreen();
  kOpen('guidedAddModal');
}
window.openGuidedAdd = openGuidedAdd;

function guidedRenderCategoryScreen() {
  document.getElementById('guidedBreadcrumb').textContent = 'What are we working on today?';
  const cats = Object.keys(ROOM_STRUCTURE);
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-weight:700;margin-bottom:10px">Where is the work?</div>
    <select id="guidedCatSelect" onchange="guidedPickCategory(this.value)" style="width:100%;padding:10px;font-size:.9rem;margin-bottom:10px">
      <option value="">Select an area…</option>
      ${cats.map(c => `<option value="${esc(c)}" ${c===_guidedCategory?'selected':''}>${esc(c)}</option>`).join('')}
    </select>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
}

function guidedRenderRoomScreen() {
  const rooms = Object.keys(ROOM_STRUCTURE[_guidedCategory]?.rooms || {});
  document.getElementById('guidedBreadcrumb').textContent = _guidedCategory + ' — what are we working on?';
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-weight:700;margin-bottom:10px">Which room or area?</div>
    <select id="guidedRoomSelect" onchange="guidedPickRoom(this.value)" style="width:100%;padding:10px;font-size:.9rem;margin-bottom:10px">
      <option value="">Select a room…</option>
      ${rooms.map(r => `<option value="${esc(r)}" ${r===_guidedRoom?'selected':''}>${esc(r)}</option>`).join('')}
    </select>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
}

function guidedRenderPhaseScreen() {
  const phases = ROOM_STRUCTURE[_guidedCategory]?.rooms[_guidedRoom]?.phases || [];
  document.getElementById('guidedBreadcrumb').textContent = `${_guidedCategory} › ${_guidedRoom}`;
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-weight:700;margin-bottom:10px">${esc(_guidedRoom)}, what are we working on?</div>
    <select id="guidedPhaseSelect" onchange="guidedPickPhase(this.value)" style="width:100%;padding:10px;font-size:.9rem;margin-bottom:10px">
      <option value="">Select a trade…</option>
      ${phases.map(p => `<option value="${esc(p.label)}|||${esc(p.trade)}">${esc(p.label)}${GUIDED_SCRIPTS[p.trade] ? '' : ' (not yet available)'}</option>`).join('')}
    </select>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
}

function guidedPickCategory(cat) {
  if (!cat) return;
  guidedPush({ t: 'category' });
  _guidedCategory = cat;
  guidedRenderRoomScreen();
}
window.guidedPickCategory = guidedPickCategory;

function guidedPickRoom(room) {
  if (!room) return;
  guidedPush({ t: 'room' });
  _guidedRoom = room;
  guidedRenderPhaseScreen();
}
window.guidedPickRoom = guidedPickRoom;

function guidedPickPhase(val) {
  if (!val) return;
  guidedPush({ t: 'phase' });
  const [label, trade] = val.split('|||');
  _guidedPhaseLabel = label; _guidedTrade = trade;
  const script = GUIDED_SCRIPTS[trade];
  if (!script) {
    document.getElementById('guidedBody').innerHTML = `
      <div style="text-align:center;padding:24px;color:var(--muted)">
        Guided Questions isn't built for <strong>${esc(label)}</strong> yet — only Roofing so far.<br><br>
        Use <strong>⚡ Smart Add</strong> to browse that catalog instead.
      </div>`;
    document.getElementById('guidedFooter').innerHTML = '';
    guidedUpdateBackBtn();
    return;
  }
  _guidedScript = script; _guidedStepIdx = 0; _guidedCtx = {}; _guidedCart = [];
  guidedRenderStep();
}
window.guidedPickPhase = guidedPickPhase;

function guidedRenderStep() {
  const steps = _guidedScript.steps;
  if (_guidedStepIdx >= steps.length) { guidedShowReview(); return; }
  const step = steps[_guidedStepIdx];
  document.getElementById('guidedBreadcrumb').textContent = `${_guidedRoom} › ${_guidedPhaseLabel}`;
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-size:1.05rem;font-weight:700;margin-bottom:20px">${esc(step.text)}</div>
    <div style="display:flex;gap:10px">
      <button class="btn-amber" style="flex:1;padding:14px" onclick="guidedAnswer(true)">Yes</button>
      <button class="btn" style="flex:1;padding:14px" onclick="guidedAnswer(false)">No</button>
    </div>`;
  document.getElementById('guidedFooter').innerHTML =
    `<span class="small muted">Step ${_guidedStepIdx+1} of ${steps.length}</span>`;
  guidedUpdateBackBtn();
}

function guidedAnswer(yes) {
  const idx = _guidedStepIdx;
  const step = _guidedScript.steps[idx];
  // Push BEFORE anything changes -- restores to this same yes/no
  // question, with ctx/cart exactly as they were when it was first shown.
  guidedPush({ t: 'yesno', stepIdx: idx });
  if (!yes) { _guidedStepIdx = idx + 1; guidedRenderStep(); return; }
  guidedResolveYes(idx);
}
window.guidedAnswer = guidedAnswer;

// Walks whatever this step's "yes" branch still needs, in order: any
// shared quantities not yet in ctx, then its own one-off quantity
// question, then a select (shingle type etc). Once everything is
// collected, computes this step's items and advances. Does NOT push
// history itself -- each sub-question's submit handler pushes before
// mutating ctx, so Back always rewinds exactly one question.
function guidedResolveYes(idx) {
  const onYes = _guidedScript.steps[idx].onYes;
  const missingShared = (onYes.needs || []).filter(k => _guidedCtx[k] === undefined);
  if (missingShared.length) { guidedRenderSharedQty(idx, missingShared[0]); return; }
  if (onYes.ownQty && _guidedCtx[onYes.ownQty.key] === undefined) { guidedRenderOwnQty(idx); return; }
  if (onYes.select && _guidedCtx[onYes.select.key] === undefined) { guidedRenderSelect(idx); return; }
  const items = onYes.items(_guidedCtx);
  _guidedCart.push(...items);
  _guidedStepIdx = idx + 1;
  guidedRenderStep();
}

function guidedRenderSharedQty(idx, key) {
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-size:1.05rem;font-weight:700;margin-bottom:14px">${esc(GUIDED_QTY_LABELS[key] || key)}</div>
    <input id="guidedQtyInput" type="number" min="0" step="0.1" style="width:100%;padding:12px;font-size:1rem;margin-bottom:14px" />
    <button class="btn-amber" style="width:100%;padding:12px" onclick="guidedSubmitSharedQty(${idx},'${key}')">Next →</button>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
  setTimeout(() => document.getElementById('guidedQtyInput')?.focus(), 50);
}
function guidedSubmitSharedQty(idx, key) {
  const val = parseFloat(document.getElementById('guidedQtyInput').value);
  if (isNaN(val) || val <= 0) { alert('Enter a number greater than 0.'); return; }
  guidedPush({ t: 'sharedQty', stepIdx: idx, key });
  _guidedCtx[key] = val;
  guidedResolveYes(idx);
}
window.guidedSubmitSharedQty = guidedSubmitSharedQty;

function guidedRenderOwnQty(idx) {
  const onYes = _guidedScript.steps[idx].onYes;
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-size:1.05rem;font-weight:700;margin-bottom:14px">${esc(onYes.ownQty.label)}</div>
    <input id="guidedQtyInput2" type="number" min="0" step="1" value="${onYes.ownQty.default}" style="width:100%;padding:12px;font-size:1rem;margin-bottom:14px" />
    <button class="btn-amber" style="width:100%;padding:12px" onclick="guidedSubmitNumber(${idx})">Next →</button>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
  setTimeout(() => document.getElementById('guidedQtyInput2')?.focus(), 50);
}
function guidedSubmitNumber(idx) {
  const onYes = _guidedScript.steps[idx].onYes;
  const val = parseFloat(document.getElementById('guidedQtyInput2').value);
  if (isNaN(val) || val < 0) { alert('Enter a number 0 or greater.'); return; }
  guidedPush({ t: 'ownQty', stepIdx: idx });
  _guidedCtx[onYes.ownQty.key] = val;
  guidedResolveYes(idx);
}
window.guidedSubmitNumber = guidedSubmitNumber;

function guidedRenderSelect(idx) {
  const onYes = _guidedScript.steps[idx].onYes;
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-size:1.05rem;font-weight:700;margin-bottom:14px">${esc(onYes.select.label)}</div>
    <select id="guidedSelectInput" style="width:100%;padding:12px;font-size:.92rem;margin-bottom:14px">
      ${onYes.select.options.map(o => `<option value="${esc(o)}">${esc(o)}</option>`).join('')}
    </select>
    <button class="btn-amber" style="width:100%;padding:12px" onclick="guidedSubmitSelect(${idx})">Next →</button>`;
  document.getElementById('guidedFooter').innerHTML = '';
  guidedUpdateBackBtn();
}
function guidedSubmitSelect(idx) {
  const onYes = _guidedScript.steps[idx].onYes;
  const val = document.getElementById('guidedSelectInput').value;
  guidedPush({ t: 'select', stepIdx: idx });
  _guidedCtx[onYes.select.key] = val;
  guidedResolveYes(idx);
}
window.guidedSubmitSelect = guidedSubmitSelect;

// Pops the last snapshot and re-renders exactly that screen -- restores
// ctx/cart/category/room/trade/phase/script/stepIdx as they were at
// that point, so this always rewinds exactly one question, never the
// whole flow.
function guidedBack() {
  if (!_guidedHistory.length) return;
  const prev = _guidedHistory.pop();
  _guidedCtx = prev.ctx; _guidedCart = prev.cart;
  _guidedCategory = prev.category; _guidedRoom = prev.room;
  _guidedTrade = prev.trade; _guidedPhaseLabel = prev.phaseLabel;
  _guidedScript = prev.script; _guidedStepIdx = prev.stepIdx;

  switch (prev.screen.t) {
    case 'category': guidedRenderCategoryScreen(); break;
    case 'room':     guidedRenderRoomScreen(); break;
    case 'phase':    guidedRenderPhaseScreen(); break;
    case 'yesno':    guidedRenderStep(); break;
    case 'sharedQty':guidedRenderSharedQty(prev.screen.stepIdx, prev.screen.key); break;
    case 'ownQty':   guidedRenderOwnQty(prev.screen.stepIdx); break;
    case 'select':   guidedRenderSelect(prev.screen.stepIdx); break;
    default:         guidedRenderCategoryScreen();
  }
  guidedUpdateBackBtn();
}
window.guidedBack = guidedBack;

function guidedShowReview() {
  const auto = _guidedScript.autoItems ? _guidedScript.autoItems(_guidedCtx) : [];
  const allItems = [..._guidedCart, ...auto];
  const catalog = CATALOG_DATA[_guidedTrade] || [];
  let totalPrice = 0;
  const rows = allItems.map(entry => {
    const cat = catalog.find(i => i.name === entry.name);
    if (!cat) return '';
    let rowHtml = '';
    if (cat.materials) {
      const lineTotal = entry.qty * (cat.materials.unitPrice || 0);
      totalPrice += lineTotal;
      rowHtml += `<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid rgba(110,145,210,.08);font-size:.85rem">
        <span>${esc(cat.name)} <span class="small muted">(${entry.qty} ${esc(cat.materials.unit||'')})</span></span>
        <span>$${lineTotal.toFixed(2)}</span></div>`;
    }
    if (cat.labor) {
      const lineTotal = entry.qty * (cat.labor.unitPrice || 0);
      totalPrice += lineTotal;
      rowHtml += `<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid rgba(110,145,210,.08);font-size:.85rem;color:#4d8dff">
        <span>${esc(cat.labor.desc||('Labor - '+cat.name))} <span class="small muted">(${entry.qty} ${esc(cat.labor.unit||'')})</span></span>
        <span>$${lineTotal.toFixed(2)}</span></div>`;
    }
    return rowHtml;
  }).join('');

  document.getElementById('guidedBreadcrumb').textContent = `${_guidedRoom} › ${_guidedPhaseLabel} — Review`;
  document.getElementById('guidedBody').innerHTML = `
    <div style="font-weight:700;margin-bottom:12px">Here's the estimate built from your answers:</div>
    ${rows || '<div class="small muted" style="padding:12px 0">No items — every question came back No.</div>'}
    <div style="display:flex;justify-content:space-between;font-weight:800;padding:14px 0 0;margin-top:6px;border-top:2px solid rgba(217,119,6,.3)">
      <span>Total</span><span>$${totalPrice.toFixed(2)}</span>
    </div>`;
  document.getElementById('guidedFooter').innerHTML = allItems.length
    ? `<button class="btn-amber" style="padding:10px 18px" onclick="guidedCommit()">✅ Add to Estimate</button>`
    : '';
  guidedUpdateBackBtn();
}

async function guidedCommit() {
  if (!conDb || !conCurrentJobId) return;
  const auto = _guidedScript.autoItems ? _guidedScript.autoItems(_guidedCtx) : [];
  const allItems = [..._guidedCart, ...auto];
  const catalog = CATALOG_DATA[_guidedTrade] || [];
  const roomName = _guidedRoom;
  const tradeName = _guidedPhaseLabel;

  let group = estGroups.find(g => g.name.toLowerCase() === roomName.toLowerCase());
  if (!group) {
    const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
      name: roomName, order: estGroups.length, createdAt: firebase.firestore.FieldValue.serverTimestamp()
    });
    group = { id: ref.id, name: roomName, order: estGroups.length, subgroups: [], directItems: [] };
    estGroups.push(group);
  }
  let subgroup = group.subgroups?.find(s => s.name.toLowerCase() === tradeName.toLowerCase());
  if (!subgroup) {
    const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
      .doc(group.id).collection('subgroups').add({
        name: tradeName, order: group.subgroups?.length || 0, createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    subgroup = { id: subRef.id, name: tradeName, order: group.subgroups?.length || 0, items: [] };
    if (!group.subgroups) group.subgroups = [];
    group.subgroups.push(subgroup);
  }

  const addPromises = [];
  let order = subgroup.items?.length || 0;
  for (const entry of allItems) {
    const cat = catalog.find(i => i.name === entry.name);
    if (!cat) continue;
    if (cat.materials) {
      const uc = cat.materials.unitCost || 0, up = cat.materials.unitPrice || 0;
      addPromises.push(coll('jobs').doc(conCurrentJobId).collection('estimateGroups').doc(group.id)
        .collection('subgroups').doc(subgroup.id).collection('items').add({
          desc: cat.name, qty: entry.qty, unit: cat.materials.unit || 'ea', costType: 'Materials',
          unitCost: uc, markup: (uc>0&&up>0) ? Math.round((up/uc-1)*100) : getDefaultMarkupForCostType('Materials'),
          unitPrice: up, notes: '', order: order++, createdAt: firebase.firestore.FieldValue.serverTimestamp()
        }));
    }
    if (cat.labor) {
      const uc = cat.labor.unitCost || 0, up = cat.labor.unitPrice || 0;
      addPromises.push(coll('jobs').doc(conCurrentJobId).collection('estimateGroups').doc(group.id)
        .collection('subgroups').doc(subgroup.id).collection('items').add({
          desc: cat.labor.desc || ('Labor - '+cat.name), qty: entry.qty, unit: cat.labor.unit || 'hr', costType: 'Labor',
          unitCost: uc, markup: (uc>0&&up>0) ? Math.round((up/uc-1)*100) : getDefaultMarkupForCostType('Labor'),
          unitPrice: up, notes: '', order: order++, createdAt: firebase.firestore.FieldValue.serverTimestamp()
        }));
    }
  }

  await Promise.all(addPromises);
  kClose('guidedAddModal');
  const estTab = document.querySelector('[onclick*="estimate"]');
  if (estTab) estTab.click(); else loadEstimate(conCurrentJobId);
  alert(`✅ Added ${allItems.length} item${allItems.length!==1?'s':''} to ${roomName} › ${tradeName} from your answers.`);
}
window.guidedCommit = guidedCommit;

// Update estimate tab toolbar to include Smart Add
window.openSmartAdd = openSmartAdd;
window.wizardSelectCategory = wizardSelectCategory;
window.wizardSelectRoom = wizardSelectRoom;
window.wizardSelectPhase = wizardSelectPhase;
window.wizardSelectTrade = wizardSelectTrade;
window.wizardToggleItem = wizardToggleItem;
window.wizardFilterItems = wizardFilterItems;
window.wizardSelectAll = wizardSelectAll;
window.wizardClearAll = wizardClearAll;
window.wizardBack = wizardBack;
window.wizardGoTo = wizardGoTo;
window.wizardGoStep = wizardGoStep;
// One-off items that don't fit the catalog (flat fees, vendor bids,
// custom quotes) shouldn't force a fake per-sqft/per-unit catalog rate
// just to be addable from Smart Add. This reuses the existing manual
// Add Line Item modal (same one the Estimate tab's own +Item button
// opens), pre-scoped to whichever room/phase is currently being
// browsed, so the item lands in the right spot in the tree without
// making the user re-navigate the group/subgroup dropdowns by hand.
// Full-sized card for the custom/one-off item option — same visual weight
// as tier/bundle cards (not a small dashed text link) so it reads as a
// real 4th option, not an afterthought easy to miss while scrolling.
function wizardCustomItemCardHtml() {
  return '<div onclick="wizardAddCustomItem()" ' +
    'style="border:2px solid rgba(110,145,210,.35);border-radius:14px;padding:14px 16px;margin-top:10px;margin-bottom:10px;cursor:pointer;background:rgba(110,145,210,.07)" ' +
    'onmouseover="this.style.borderColor=\'rgba(110,145,210,.7)\'" ' +
    'onmouseout="this.style.borderColor=\'rgba(110,145,210,.35)\'">' +
    '<div style="display:flex;align-items:center;gap:10px">' +
    '<div style="font-size:1.4rem">✏️</div>' +
    '<div><div style="font-weight:800;font-size:.95rem;color:#eaf0fb">Custom / One-off Item</div>' +
    '<div style="font-size:.76rem;color:var(--muted);margin-top:2px">Not in the catalog? Add your own — per hour, per job, per sqft, flat fee, anything.</div></div>' +
    '</div></div>';
}

async function wizardAddCustomItem() {
  const roomName = _wizardRoom || _wizardCategory;
  const phaseName = _wizardPhaseLabel || (_wizardTrade || '').split(' ').slice(1).join(' ') || '';
  kClose('smartAddModal');

  let groupId = null, subgroupId = null;
  try {
    let group = estGroups.find(g => g.name.toLowerCase() === (roomName || '').toLowerCase());

    // Smart Add already knows the room (e.g. "Half Bath") — if nothing's
    // been added to this estimate yet, that group genuinely doesn't
    // exist in Firestore. Create it automatically instead of leaving
    // groupId null and making the user hunt for '+ Create New Group'
    // themselves; that option stays available as a fallback for the
    // standalone + Add Item button, which has no room/trade context to
    // work from.
    if (!group && roomName && conDb && conCurrentJobId) {
      const order = estGroups.length;
      const ref = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups').add({
        name: roomName, order, createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
      group = { id: ref.id, name: roomName, order, subgroups: [], directItems: [] };
      estGroups.push(group);
    }

    if (group) {
      groupId = group.id;
      let sub = group.subgroups?.find(s => s.name.toLowerCase() === phaseName.toLowerCase());
      if (!sub && phaseName && conDb && conCurrentJobId) {
        const subOrder = (group.subgroups || []).length;
        const subRef = await coll('jobs').doc(conCurrentJobId).collection('estimateGroups')
          .doc(groupId).collection('subgroups').add({
            name: phaseName, order: subOrder, createdAt: firebase.firestore.FieldValue.serverTimestamp()
          });
        sub = { id: subRef.id, name: phaseName, items: [] };
        if (!group.subgroups) group.subgroups = [];
        group.subgroups.push(sub);
      }
      if (sub) subgroupId = sub.id;
    }
    renderEstimateTree();
  } catch(e) {
    console.error('Auto-create group/subgroup for custom item failed:', e);
    // Fall through and open the modal with whatever we resolved — the
    // '+ Create New Group' option is still there as a manual fallback.
  }

  openAddEstItemModal(null, groupId, subgroupId, null);
}
window.wizardAddCustomItem = wizardAddCustomItem;
window.wizardAddToEstimate = wizardAddToEstimate;

